#if defined(_WIN32)
/* WDDM device allocations also consume host commit for their backing store.
 * Charge the requested bytes before entering CUDA, including pinned/managed
 * allocations. Refuse here, rather than letting CUDA OOM retries hide a host
 * admission failure. The process Job limit also covers allocator internals. */
/* Owner rule: never force-kill this process while it may hold VRAM/DirectStorage.
 * Refusing by exit is kept only before the first GPU allocation (nothing held yet);
 * after it a refusal requests the graceful abort and fails this allocation. */
static bool cuda_host_admit(size_t bytes, const char *kind, int line, bool host_physical = false) {
    if (!(host_physical ? ds4_win32_host_memory_check(bytes, kind) :
                         ds4_win32_host_memory_check_commit(bytes, kind))) {
        fprintf(stderr, "ds4: HOST_MEMORY_ADMISSION_REFUSED CUDA source line=%d kind=%s bytes=%llu\n",
                line, kind, (unsigned long long)bytes);
        fflush(stderr);
        if (!ds4_win32_gpu_resources_live()) ExitProcess(72);
        ds4_win32_request_graceful_abort("host-memory admission refused after GPU resources were live");
        return false;
    }
    if (bytes >= 64u * 1048576u || getenv("DS4_HOST_ALLOCATION_TRACE")) {
        fprintf(stderr, "ds4: HOST_MEMORY_ALLOCATION line=%d kind=%s bytes=%llu\n",
                line, kind, (unsigned long long)bytes);
        ds4_win32_host_memory_snapshot(kind);
    }
    return true;
}
static cudaError_t cuda_host_allocation_result(cudaError_t result, size_t bytes,
        const char *kind, int line) {
    if (getenv("DS4_HOST_ALLOCATION_TRACE")) {
        fprintf(stderr, "ds4: HOST_MEMORY_ALLOCATION_RESULT line=%d kind=%s bytes=%llu code=%d\n",
                line, kind, (unsigned long long)bytes, (int)result);
        ds4_win32_host_memory_snapshot(kind);
    }
    if (result == cudaSuccess && !ds4_win32_host_memory_check_commit(0, kind)) {
        fprintf(stderr, "ds4: HOST_MEMORY_POST_ALLOCATION_REFUSED line=%d kind=%s requested_bytes=%llu\n",
                line, kind, (unsigned long long)bytes);
        fflush(stderr);
        if (!ds4_win32_gpu_resources_live()) ExitProcess(72);
        /* The allocation exists; keep it for the owner's normal release and fail the
         * request gracefully instead of exiting with VRAM/DirectStorage live. */
        ds4_win32_request_graceful_abort("host-memory budget exceeded after an allocation");
    }
    if (result == cudaSuccess) ds4_win32_mark_gpu_resources_live();
    return result;
}
template<class T> static cudaError_t cuda_host_admitted_malloc(T **p, size_t n, int line) {
    if (!cuda_host_admit(n, "cudaMalloc backing store", line)) return cudaErrorMemoryAllocation;
    return cuda_host_allocation_result(cudaMalloc(p, n), n, "cudaMalloc backing store", line);
}
template<class T> static cudaError_t cuda_host_admitted_malloc_host(T **p, size_t n, int line) {
    if (!cuda_host_admit(n, "cudaMallocHost pinned staging", line, true)) return cudaErrorMemoryAllocation;
    return cuda_host_allocation_result(cudaMallocHost(p, n), n, "cudaMallocHost pinned staging", line);
}
template<class T> static cudaError_t cuda_host_admitted_managed(T **p, size_t n, unsigned flags, int line) {
    if (!cuda_host_admit(n, "cudaMallocManaged host commit", line, true)) return cudaErrorMemoryAllocation;
    return cuda_host_allocation_result(cudaMallocManaged(p, n, flags), n, "cudaMallocManaged host commit", line);
}
template<class T> static cudaError_t cuda_host_admitted_host_alloc(T **p, size_t n, unsigned flags, int line) {
    if (!cuda_host_admit(n, "cudaHostAlloc pinned staging", line, true)) return cudaErrorMemoryAllocation;
    return cuda_host_allocation_result(cudaHostAlloc(p, n, flags), n, "cudaHostAlloc pinned staging", line);
}
static cudaError_t cuda_host_admitted_register(void *p, size_t n, unsigned flags, int line) {
    if (!cuda_host_admit(n, "cudaHostRegister locked pages", line, true)) return cudaErrorMemoryAllocation;
    return cuda_host_allocation_result(cudaHostRegister(p, n, flags), n, "cudaHostRegister locked pages", line);
}
#define cudaMalloc(p, n) cuda_host_admitted_malloc(p, n, __LINE__)
#define cudaMallocHost(p, n) cuda_host_admitted_malloc_host(p, n, __LINE__)
#define cudaMallocManaged(p, n) cuda_host_admitted_managed(p, n, cudaMemAttachGlobal, __LINE__)
#define cudaHostAlloc(p, n, flags) cuda_host_admitted_host_alloc(p, n, flags, __LINE__)
#define cudaHostRegister(p, n, flags) cuda_host_admitted_register(p, n, flags, __LINE__)
#endif

/* [merge 2026-08-15] The merge took upstream's "ds4_cuda.cu does not include ds4_gpu.h" convention
 * while KEEPING HEAD code that needs two things from that header, leaving them undefined. The
 * resulting syntax error derails the EDG parser, which then reads function bodies as file scope and
 * emits a storm of bogus "already defined" errors hundreds of lines away from the real cause.
 *
 * I first fixed this by restoring `#include "ds4_gpu.h"` (HEAD's form, which compiled for HEAD).
 * That is WRONG here: upstream locally redeclares much of the header -- ds4_tensor_range,
 * ds4_decode_graph_key, ds4_gpu_stream_expert_table, ds4_gpu_decode_graph_begin/end/abort, ... --
 * which is precisely WHY it dropped the include. Including it produced 7 redefinition/duplicate-C-
 * linkage errors. Declaring only the two missing items locally keeps upstream's convention and
 * changes no behaviour. */
#define DS4_GPU_COMP_KV_FORMAT_F32 0u
#define DS4_GPU_COMP_KV_FORMAT_F16 1u
#define DS4_GPU_COMP_KV_FORMAT_Q8  2u
typedef struct ds4_gpu_decode_profile_snapshot {
    uint64_t command_buffers;
    uint64_t commits;
    uint64_t sync_calls;
    uint64_t wait_calls;
    double   wait_ms;
    uint64_t expert_layers;
    uint64_t clean_layers;
    uint64_t cache_hits;
    uint64_t cache_misses;
    uint64_t ssd_bytes;
    double   expert_plan_ms;
    uint64_t arena_copy_calls;
    uint64_t arena_copy_bytes;
    double   arena_copy_ms;
    uint64_t host_copy_calls;
    uint64_t host_copy_bytes;
    double   host_copy_ms;
    uint64_t resident_copies;
    uint64_t resident_bytes;
    double   resident_ms;
    /* [2026-08-20] The synchronous pread fallback in cuda_model_read_to_host(). Under R4 the DS
     * prepass is skipped wholesale while resident spans are set, the resident lookup then MISSES
     * for the ~65/256 experts R4 never made resident, and the fetch falls through to a blocking
     * per-expert disk read that NO existing counter sees. Suspected to carry the entire
     * 167.7 ms/token R4 decode penalty (2.17 ms per VRAM miss ~= 6.75 MiB in 3 preads at ~3 GB/s). */
    uint64_t pread_calls;
    uint64_t pread_bytes;
    double   pread_ms;
    /* DS prepass staging outcome - see the matching comment in ds4_gpu.h. */
    uint64_t prepass_calls;
    uint64_t prepass_staged;
    uint64_t prepass_skipped;
    uint64_t prepass_gpudest;
    double   prepass_cap_mib;
    double   prepass_fail_reason;  /* last ds4_ds_batch_add_gpu refusal branch, 0 = ok */
    uint64_t ds_batches;
    double   ds_batch_ms;
    uint64_t ds_wait_calls;
    double   ds_wait_ms;
    uint64_t decode_pipeline_depth;
    uint64_t decode_pipeline_batches_ahead;
    uint64_t decode_pipeline_arrival_resident;
    uint64_t decode_pipeline_blocked;
    uint64_t decode_pipeline_prefetched_experts;
    uint64_t decode_pipeline_mispredicted_experts;
    double   decode_pipeline_ds_wait_ms;
    /* Token-wall DirectStorage bandwidth. MUST stay in lockstep with ds4_gpu.h. */
    uint64_t decode_ds_bytes_issued;
    uint64_t decode_ds_bytes_completed;
    double   decode_ds_elapsed_ms;
    uint64_t decode_ds_phase_waves;
    double   decode_ds_phase_setup_ms;
    double   decode_ds_phase_bookkeeping_ms;
    double   decode_ds_phase_sync_ms;
    double   decode_ds_phase_plan_ms;
    double   decode_ds_phase_submit_ms;
    double   decode_ds_phase_wait_ms;
    double   decode_ds_phase_copy_ms;
    double   decode_ds_phase_retire_ms;
    double   decode_ds_phase_teardown_ms;
    double   decode_ds_phase_uncovered_ms;
    /* R9 live route-hotlist maintenance. MUST stay in lockstep with ds4_gpu.h. */
    uint64_t live_hotlist_refreshes;
    double   live_hotlist_refresh_ms;
    uint64_t live_hotlist_ranks_changed;
    uint64_t live_hotlist_decay_passes;
    int      enabled;
} ds4_gpu_decode_profile_snapshot;
