enum {
    /* attention_decode_mixed_kernel stores raw-window scores plus visible
     * compressed scores in shared memory.  The host routes larger unmasked
     * decode calls to the online attention kernel so this fixed buffer never
     * becomes an out-of-bounds write at long context. */
    DS4_CUDA_ATTENTION_SCORE_CAP = 8192u,
    DS4_CUDA_ATTENTION_RAW_SCORE_CAP = 256u,
    DS4_CUDA_TOPK_MERGE_GROUP = 8u,
    /* [merge 2026-08-15] RESTORED from HEAD. The merge dropped these two while KEEPING the code
     * that uses them (streaming expert-cache budget clamp), so they were referenced-but-undefined. */
    DS4_CUDA_STREAM_EXPERT_DEFAULT = 8u * 64u,
    DS4_CUDA_STREAM_EXPERT_MAX = 61u * 384u,
    /* Private fixed bounds for decode DirectStorage pipelines.  The
     * model-facing maxima live in ds4.c, which this standalone CUDA TU does
     * not include; 80 covers the largest supported 79-layer profile. */
    DS4_CUDA_HASH_PIPELINE_MAX_LAYERS = 80u,
    DS4_CUDA_HASH_PIPELINE_MAX_SELECTED = 8u,
    DS4_CUDA_DECODE_PIPELINE_MAX_DEPTH = 8u,
    /* perf-02 split-KV: fixed logical rows per chunk (shared scores = 2KB),
     * grid S = ceil(n_score / CHUNK) clamped, so block count grows with ctx. */
    DS4_CUDA_SPLITKV_CHUNK = 512u,
    DS4_CUDA_SPLITKV_SCORE_CAP = 512u,
    DS4_CUDA_SPLITKV_S_MAX = 16u,
    DS4_CUDA_SPLITKV_S_FLOOR = 4u
};

