static int cuda_decode_profile_enabled(void) {
    static int initialized;
    static int enabled;
    if (!initialized) {
        enabled = getenv("DS4_STREAMING_DECODE_SYNC_PROFILE") != NULL ||
                  getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_PROFILE") != NULL;
        initialized = 1;
    }
    return enabled;
}

static double cuda_decode_profile_now_ms(void) {
    using namespace std::chrono;
    return duration<double, std::milli>(steady_clock::now().time_since_epoch()).count();
}

/* Profile only the two copy populations under investigation.  The opt-in decode profiler is cached,
 * so these helpers add no getenv to the per-expert path.  Wall time is intentional: synchronous
 * cudaMemcpy blocks the calling thread, and that critical-path cost is the quantity this probe needs. */
static cudaError_t cuda_decode_profile_arena_memcpy(
        void *dst, const void *src, size_t bytes, cudaMemcpyKind kind) {
    const int profile = cuda_decode_profile_enabled();
    const double t0 = profile ? cuda_decode_profile_now_ms() : 0.0;
    const cudaError_t err = cudaMemcpy(dst, src, bytes, kind);
    if (profile) {
        g_decode_profile.arena_copy_calls++;
        if (err == cudaSuccess) g_decode_profile.arena_copy_bytes += (uint64_t)bytes;
        g_decode_profile.arena_copy_ms += cuda_decode_profile_now_ms() - t0;
    }
    return err;
}

static cudaError_t cuda_decode_profile_host_memcpy(
        void *dst, const void *src, size_t bytes, cudaMemcpyKind kind) {
    const int profile = cuda_decode_profile_enabled();
    const double t0 = profile ? cuda_decode_profile_now_ms() : 0.0;
    const cudaError_t err = cudaMemcpy(dst, src, bytes, kind);
    if (profile) {
        g_decode_profile.host_copy_calls++;
        if (err == cudaSuccess) g_decode_profile.host_copy_bytes += (uint64_t)bytes;
        g_decode_profile.host_copy_ms += cuda_decode_profile_now_ms() - t0;
    }
    return err;
}

