           g_affinity_decoded>=g_affinity_warmup;
}
static float cuda_affinity_ramp_factor(uint64_t step) {
    if (step<g_affinity_warmup) return 0.0f;
    if (!g_affinity_ramp) return 1.0f;
    return fminf(1.0f,(float)(step-g_affinity_warmup+1u)/(float)g_affinity_ramp);
}
extern "C" int ds4_gpu_cache_affinity_configure(float mean, uint32_t warmup, uint32_t ramp,
        const char *spread_file, const char *calibrate_file, int flat, uint32_t promotion_cap,
        int router_confidence) {
    if (!isfinite(mean) || mean<0 || mean>3 || warmup>1000000 || ramp>256 || promotion_cap>4) return 0;
    if(router_confidence!=0 && router_confidence!=1) return 0;
#if !defined(_WIN32)
    if(promotion_cap) {fprintf(stderr,"ds4: background promotion requires Windows DirectStorage\n");return 0;}
#endif
    if (mean>0 && calibrate_file && *calibrate_file) {
        fprintf(stderr,"ds4: affinity calibration requires mean bias zero\n");return 0;
    }
    if (mean>0 && !flat && (!spread_file || !*spread_file)) {
        fprintf(stderr,"ds4: spread cache affinity requires a per-model calibration file\n");return 0;
    }
    g_affinity_mean=mean;g_affinity_anchor=(spread_file && *spread_file && (!calibrate_file || !*calibrate_file)) ? fmaxf(mean,1.36125f) : mean;g_affinity_warmup=warmup;g_affinity_ramp=ramp;g_affinity_cap=promotion_cap;
    g_affinity_flat=flat!=0;g_affinity_decoded=0;g_affinity_current_biased=false;g_affinity_loaded=false;
    g_affinity_router_confidence=router_confidence!=0;
    g_affinity_verify_active=false;g_affinity_verify_hard=false;g_affinity_verify_mean=-1.0f;
    const char *verify_mean=getenv("DS4_CUDA_DSPARK_VERIFY_BIAS");
    if(verify_mean && *verify_mean) {
        char *end=NULL;float value=strtof(verify_mean,&end);
        if(end==verify_mean || !end || *end || !isfinite(value) || value<0 || value>1.36125f) {
            fprintf(stderr,"ds4: DS4_CUDA_DSPARK_VERIFY_BIAS requires finite0..1.36125\n");return 0;
        }
        g_affinity_verify_mean=value;
    }
    const char *verify_hard=getenv("DS4_CUDA_DSPARK_VERIFY_HARD_RESIDENT");
    if(verify_hard && *verify_hard) {
        if(strcmp(verify_hard,"0") && strcmp(verify_hard,"1")) {
            fprintf(stderr,"ds4: DS4_CUDA_DSPARK_VERIFY_HARD_RESIDENT must be0 or1\n");return 0;
        }
        g_affinity_verify_hard=!strcmp(verify_hard,"1");
    }
    if(g_affinity_verify_mean>=0 && g_affinity_verify_hard) {
        fprintf(stderr,"ds4: choose verify bias or hard resident confidence policy, not both\n");return 0;
    }
    if(g_affinity_verify_mean>=0 || g_affinity_verify_hard)
        fprintf(stderr,"ds4: verify-only routing mean=%.6g hard_resident=%d; decode/drafter unchanged; warm%u/ramp%u\n",g_affinity_verify_mean,(int)g_affinity_verify_hard,warmup,ramp);
    const char *shared=getenv("DS4_CUDA_CACHE_AFFINITY_WARP");
    if(shared && *shared && strcmp(shared,"0") && strcmp(shared,"1")) {
        fprintf(stderr,"ds4: DS4_CUDA_CACHE_AFFINITY_WARP must be 0 or 1\n");return 0;
    }
    g_affinity_warp_topk=!shared || !*shared || !strcmp(shared,"1");
    g_affinity_spread_path=spread_file?spread_file:"";g_affinity_calibrate_path=calibrate_file?calibrate_file:"";
    for (uint32_t l=0;l<128;l++) {g_affinity_factor[l]=1.0f;g_affinity_calibration[l].clear();}
    return 1;
}
extern "C" uint64_t ds4_gpu_cache_affinity_decode_count(void) { return g_affinity_decoded; }
extern "C" void ds4_gpu_cache_affinity_decode_restore(uint64_t count) { g_affinity_decoded=count; }
extern "C" void ds4_gpu_cache_affinity_decode_unbiased(void) {
    if (g_stream_expert_cache_phase_decode) {g_affinity_decoded++; g_affinity_current_biased=false;}
}
extern "C" int ds4_gpu_cache_affinity_set_mean(float mean) {
    if(!isfinite(mean) || mean<0.0f || mean>g_affinity_anchor) return 0;
    g_affinity_mean=mean;return 1;
}
extern "C" int ds4_gpu_cache_affinity_verify_scope(int active) {
    if(active && g_affinity_verify_active)return 0;
    g_affinity_verify_active=active!=0;
    return active && (g_affinity_verify_mean>=0 || g_affinity_verify_hard) ? 2 : 1;
}
static uint64_t cuda_affinity_header_hash(const void *model, uint64_t size) {
    const uint8_t *b=(const uint8_t *)model;uint64_t h=UINT64_C(14695981039346656037);
    for (uint64_t i=0;i<std::min(size,UINT64_C(65536));i++) {h^=b[i];h*=UINT64_C(1099511628211);}
    return h^size;
}
static bool cuda_affinity_model(const void *model, uint64_t size, uint32_t experts, uint32_t layers) {
    if (g_affinity_loaded) return size==g_affinity_model_size && experts==g_affinity_experts && layers==g_affinity_layers;
    g_affinity_model_size=size;g_affinity_model_hash=cuda_affinity_header_hash(model,size);
    g_affinity_experts=experts;g_affinity_layers=layers;
    if ((g_affinity_mean>0 || !g_affinity_spread_path.empty()) && !g_affinity_flat) {
        FILE *f=fopen(g_affinity_spread_path.c_str(),"rb");if (!f) {fprintf(stderr,"ds4: cannot open affinity spread file\n");return false;}
        unsigned long long saved_size=0,saved_hash=0;unsigned saved_e=0,saved_l=0;
        bool ok=fscanf(f,"DS4AFFINITY1 %llu %u %u %llx",&saved_size,&saved_e,&saved_l,&saved_hash)==4 &&
            saved_size==size && saved_hash==g_affinity_model_hash && saved_e==experts && saved_l==layers;
        float mean_spread=0;
        for (uint32_t l=0;ok && l<layers;l++) {
            unsigned layer=0,samples=0;float v=0;
            ok=fscanf(f," %u %f %u",&layer,&v,&samples)==3 && layer==l && samples>=16 && isfinite(v) && v>0;
            if (ok) {g_affinity_factor[l]=v;mean_spread+=v;}
        }
        if (ok) {int c;do {c=fgetc(f);}while(c!=EOF && isspace(c));ok=c==EOF;}
        fclose(f);mean_spread/=layers;
        if (!ok || !isfinite(mean_spread) || mean_spread<=0) {fprintf(stderr,"ds4: invalid or wrong-model affinity calibration\n");return false;}
        for (uint32_t l=0;l<layers;l++) g_affinity_factor[l]/=mean_spread;
        fprintf(stderr,"ds4: cache affinity spread calibration verified layers=%u samples>=16 mean_spread=%.9g\n",layers,mean_spread);
    }
    g_affinity_loaded=true;return true;
}
extern "C" int ds4_gpu_cache_affinity_prepare_model(const void *model,uint64_t size,uint32_t experts,uint32_t layers) {
    return model && size && layers>0 && layers<=128 && cuda_affinity_model(model,size,experts,layers);
}
extern "C" void ds4_gpu_cache_affinity_finish(void) {
    cuda_affinity_background_finish();
    if (g_affinity_calibrate_path.empty()) return;
    bool ok=g_affinity_loaded && g_affinity_layers>0;
    for(uint32_t l=0;ok && l<g_affinity_layers;l++) ok=g_affinity_calibration[l].size()>=16;
    if(!ok) {fprintf(stderr,"ds4: incomplete affinity calibration; no file published\n");g_affinity_calibrate_path.clear();return;}
    FILE *f=fopen(g_affinity_calibrate_path.c_str(),"wb");
    if(!f) {fprintf(stderr,"ds4: cannot write affinity calibration\n");abort();}
    fprintf(f,"DS4AFFINITY1 %llu %u %u %llx\n",(unsigned long long)g_affinity_model_size,g_affinity_experts,g_affinity_layers,(unsigned long long)g_affinity_model_hash);
    for(uint32_t l=0;l<g_affinity_layers;l++) {
        auto values=g_affinity_calibration[l];std::sort(values.begin(),values.end());size_t n=values.size();
        float median=n%2?values[n/2]:(values[n/2-1]+values[n/2])*.5f;
        fprintf(f,"%u %.9g %u\n",l,median,(unsigned)n);
    }
    if(fclose(f)) {fprintf(stderr,"ds4: affinity calibration close failed\n");abort();}
    fprintf(stderr,"ds4: affinity calibration written %s\n",g_affinity_calibrate_path.c_str());g_affinity_calibrate_path.clear();
}


/* [2026-08-18] MECHANISM COUNTER for the prefill-edge work. The two existing lines cannot tell you
 * whether the cache was being populated during prefill:
 *   - "prefill edge evicted expert cache 0.00 GiB" reads 0.00 on EVERY build, because the gate
 *     PREVENTS population rather than evicting an already-built cache.
 *   - "class N allocated ..." prints at cache CREATION, so it is identical across A/B arms.
 * So a config that gains nothing from the gate is indistinguishable from one that gains a lot. That is
 * exactly how an INERT gate passed build, marker and stderr checks earlier today. Count the admissions
 * directly, split by phase, and print them at teardown. */
static unsigned long long g_expert_cache_admits_prefill;
static unsigned long long g_expert_cache_admits_decode;
static unsigned long long g_expert_rank_policy_full_misses;
static unsigned long long g_expert_rank_policy_replacements;
static unsigned long long g_expert_rank_policy_rejects;
static unsigned long long g_expert_rank_policy_eviction_overrides;
static int g_expert_rank_policy_bound;
static int g_route_live_ranks_ready;
static uint64_t g_stream_expert_cache_physical_budget_bytes;
static int g_stream_expert_cache_physical_clamp_notice;
/* One host cache PER ROUTED-EXPERT SIZE CLASS, mirroring g_stream_expert_caches.
 * A single shared host cache cannot serve a mixed-quant model: DSV4-Flash 0731 carries Q4K experts
 * on layers 37-42 and IQ2XXS/Q2K elsewhere, so two shapes alternate within every token. The old
 * singleton had to refuse the second shape outright to avoid reallocating on each flip, which
 * excluded the Q4 experts -- the class the quantizer spent extra bits on, and the one most worth
 * holding resident -- from host RAM entirely. */
static cuda_stream_host_expert_cache
    g_stream_host_expert_caches[DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES];
static uint64_t
    g_stream_host_expert_class_bytes[DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES];
/* A failed pinned allocation falls back to a smaller class. Remember that
 * attainable capacity until teardown; otherwise every following admission
 * frees the working cache and retries the same impossible allocation. */
static uint32_t
    g_stream_host_expert_runtime_cap[DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES];
/* The runtime cap is also used as an allocation-failure backoff latch.  Only
 * caps reached without shrinking the allocation target are safe to reconsider
 * after the transient prefill arena/KV charge goes away. */
static int
    g_stream_host_expert_cap_was_budget_derived[
        DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES];
static int
    g_stream_host_expert_class_notice[DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES];
static uint32_t g_stream_expert_budget_override;
static uint32_t g_stream_host_expert_budget_override;
static uint64_t g_stream_host_expert_budget_bytes_override;
/* While R4 owns its full-layer resources, pinned host-cache pages, the arena,
 * and configured-context KV all compete for the same WDDM residency budget.
 * Charge the latter two before either host-cache class allocates. */
static uint64_t g_prefill_pipeline_host_cache_charge_bytes;
/* R4 is only admitted when the two host expert-cache classes retain at least
 * 2 GiB apiece. The 3.12 GiB aggregate fp165g configuration (1.56 GiB/class)
 * is known to produce invalid routing, while the verified 90 GB path retains
 * 5.77 GiB. Keep the floor between those observed bad/good configurations. */
static const uint64_t DS4_CUDA_PREFILL_MIN_HOST_CACHE_BYTES =
    4ull * 1024ull * 1024ull * 1024ull;
/* g_stream_host_expert_mixed_shape_notice was removed with the code it gated: the singleton host
 * cache used it to warn once that a mixed expert shape was being refused and pushed to GPU/SSD.
 * Per-class host caches no longer refuse anything, so the warning - and the flag - have no meaning. */
static uint64_t g_stream_expert_primary_bytes;
