static const char *cuda_model_range_ptr(const void *model_map, uint64_t offset, uint64_t bytes, const char *what, const char **kind_out = NULL) {
    if (kind_out) *kind_out = NULL;
    if (offset + bytes < offset) return NULL;
#ifdef DS4_EXTERNAL_DECODE
    if (g_ds4x_external_mode) {
        /* Caller-registered device copies only: no host mapping, fd cache or
         * registration of the model file is ever attempted. */
        const uint64_t end = offset + bytes;
        for (const cuda_model_range &r : g_model_ranges)
            if (r.host_base == model_map && r.borrowed && offset >= r.offset && end <= r.offset + r.bytes) {
                if (kind_out) *kind_out = "external";
                return r.device_ptr + (offset - r.offset);
            }
        fprintf(stderr, "LLAMADECODE_DS4X_UNREGISTERED_WEIGHT what=%s offset=%llu bytes=%llu\n",
                what ? what : "weights", (unsigned long long)offset, (unsigned long long)bytes);
        return NULL;
    }
#endif
    if (bytes == 0) {
        if (kind_out) *kind_out = g_model_device_owned ? "resident" : "mmap";
        return cuda_model_ptr(model_map, offset);
    }
    if (model_map == g_model_host_base && (g_model_device_owned || g_model_registered)) {
        if (kind_out) *kind_out = g_model_device_owned ? "resident" : "mmap";
        return cuda_model_ptr(model_map, offset);
    }
    if (model_map == g_model_host_base && g_model_hmm_direct &&
        getenv("DS4_CUDA_WEIGHT_CACHE") == NULL &&
        getenv("DS4_CUDA_WEIGHT_PRELOAD") == NULL) {
        if (kind_out) *kind_out = "mmap";
        return cuda_model_ptr(model_map, offset);
    }
    const char *direct_env = getenv("DS4_CUDA_DIRECT_MODEL");
    if (model_map == g_model_host_base && direct_env && direct_env[0]) {
        if (kind_out) *kind_out = "mmap";
        return cuda_model_ptr(model_map, offset);
    }

    const uint64_t end = offset + bytes;
    auto exact = g_model_range_by_offset.find(offset);
    if (exact != g_model_range_by_offset.end()) {
        const cuda_model_range &r = g_model_ranges[exact->second];
        if (r.host_base == model_map && end >= offset && bytes <= r.bytes) {
            if (kind_out) {
                *kind_out = r.prefill_resident ? "resident" :
                            (r.host_registered ? "mmap" : "arena");
            }
            return r.device_ptr;
        }
    }
    for (const cuda_model_range &r : g_model_ranges) {
        if (r.host_base == model_map && offset >= r.offset && end >= offset && end <= r.offset + r.bytes) {
            if (kind_out) {
                *kind_out = r.prefill_resident ? "resident" :
                            (r.host_registered ? "mmap" : "arena");
            }
            return r.device_ptr + (offset - r.offset);
        }
        if (r.host_base == model_map && r.host_registered && r.registered_base && r.registered_device_base) {
            const uintptr_t h0 = (uintptr_t)((const char *)model_map + offset);
            const uintptr_t h1 = h0 + bytes;
            const uintptr_t r0 = (uintptr_t)r.registered_base;
            const uintptr_t r1 = r0 + r.registered_bytes;
            if (h1 >= h0 && h0 >= r0 && h1 <= r1) {
                if (kind_out) *kind_out = "mmap";
                return r.registered_device_base + (h0 - r0);
            }
        }
    }

    if (getenv("DS4_CUDA_NO_FD_CACHE") == NULL) {
        const char *fd_ptr = cuda_model_range_ptr_from_fd(model_map, offset, bytes, what, kind_out);
        if (fd_ptr || (g_ssd_streaming_mode && g_model_fd >= 0 && model_map == g_model_fd_host_base)) return fd_ptr;
    }

    cudaError_t err = cudaSuccess;
    if (g_model_range_mapping_supported) {
        const long page_sz_l = sysconf(_SC_PAGESIZE);
        const uint64_t page_sz = page_sz_l > 0 ? (uint64_t)page_sz_l : 4096u;
        const uintptr_t host_addr = (uintptr_t)((const char *)model_map + offset);
        const uintptr_t reg_addr = host_addr & ~(uintptr_t)(page_sz - 1u);
        const uint64_t reg_delta = (uint64_t)(host_addr - reg_addr);
        const uint64_t reg_bytes = (reg_delta + bytes + page_sz - 1u) & ~(page_sz - 1u);
        void *reg_dev = NULL;
        err = cudaHostRegister((void *)reg_addr,
                               (size_t)reg_bytes,
                               cudaHostRegisterMapped | cudaHostRegisterReadOnly);
        if (err == cudaSuccess) {
            err = cudaHostGetDevicePointer(&reg_dev, (void *)reg_addr, 0);
            if (err == cudaSuccess && reg_dev) {
                char *dev_ptr = (char *)reg_dev + reg_delta;
                g_model_ranges.push_back({model_map, offset, bytes, dev_ptr, (void *)reg_addr, (char *)reg_dev, reg_bytes, 1, 0, 0});
                g_model_range_by_offset[offset] = g_model_ranges.size() - 1u;
                if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                    fprintf(stderr, "ds4: CUDA mapped %s %.2f MiB\n",
                            what ? what : "weights",
                            (double)bytes / 1048576.0);
                }
                if (kind_out) *kind_out = "mmap";
                return dev_ptr;
            }
            fprintf(stderr, "ds4: CUDA model range map pointer failed for %s: %s\n",
                    what ? what : "weights", cudaGetErrorString(err));
            (void)cudaHostUnregister((void *)reg_addr);
            (void)cudaGetLastError();
        } else {
            if (err == cudaErrorNotSupported || err == cudaErrorInvalidValue) g_model_range_mapping_supported = 0;
            (void)cudaGetLastError();
        }
    }

    void *dev = NULL;
    err = cudaMalloc(&dev, (size_t)bytes);
    if (err != cudaSuccess) {
        (void)cudaGetLastError();
        fprintf(stderr, "ds4: CUDA model range alloc failed for %s (%.2f MiB): %s\n",
                what ? what : "weights", (double)bytes / 1048576.0, cudaGetErrorString(err));
        return NULL;
    }

    const char *src = (const char *)model_map + offset;
    const uint64_t chunk = 64ull * 1024ull * 1024ull;
    for (uint64_t done = 0; done < bytes; done += chunk) {
        uint64_t n = bytes - done < chunk ? bytes - done : chunk;
        err = cudaMemcpy((char *)dev + done, src + done, (size_t)n, cudaMemcpyHostToDevice);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model range copy failed for %s at %.2f/%.2f MiB: %s\n",
                    what ? what : "weights",
                    (double)done / 1048576.0,
                    (double)bytes / 1048576.0,
                    cudaGetErrorString(err));
            (void)cudaFree(dev);
            (void)cudaGetLastError();
            return NULL;
        }
    }
    g_model_ranges.push_back({model_map, offset, bytes, (char *)dev, NULL, NULL, 0, 0, 0, 0});
    g_model_range_by_offset[offset] = g_model_ranges.size() - 1u;
    g_model_range_bytes += bytes;
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA cached %s %.2f MiB (total %.2f GiB)\n",
                what ? what : "weights",
                (double)bytes / 1048576.0,
                (double)g_model_range_bytes / 1073741824.0);
    }
    if (kind_out) *kind_out = "arena";
    return (const char *)dev;
}

/* Per-tier cuBLAS handle. Used by kernel-dispatch wrappers; returns the
 * cuBLAS handle for the logical tier. The wrapper is expected to have
 * cudaSetDevice'd to that tier's physical device already (kernels and
 * cuBLAS calls ride the default stream and are naturally serialized).
 *
 * Added for multi-GPU execution (multi-GPU execution), sub-area 1. */
static inline cublasHandle_t cuda_cublas_for_tier(int logical_tier) {
    if (g_n_gpus <= 1) {
        return (cublasHandle_t)g_gpu[0].cublas;
    }
    /* The executing device is authoritative: GLM per-layer switching runs
     * generic launchers whose out tensors live on device 0 while the layer
     * executes elsewhere. On DS4 paths the current device always equals the
     * requested tier, so this is behavior-preserving there. */
    int cur_dev = -1;
    if (cudaGetDevice(&cur_dev) == cudaSuccess) {
        for (int t = 0; t < g_n_gpus; t++) {
            if (g_gpu[t].device_id == cur_dev) {
                return (cublasHandle_t)g_gpu[t].cublas;
            }
        }
    }
    if (logical_tier < 0 || logical_tier >= g_n_gpus) {
        return (cublasHandle_t)g_gpu[0].cublas;
    }
    return (cublasHandle_t)g_gpu[logical_tier].cublas;
}

/* ------------------------------------------------------------------------
 * Decode-island CUDA graph capture.
 *
 * Design ported from the Entrpi/ds4 batched-serving fork's per-layer
 * decode graph work (fork commits abe26575, 2200c675, 9caaa508; author
 * Entrpi <entrpi@proton.me>), re-implemented against upstream's decode
 * body.  Phase 1 captures the two position-independent islands of each
 * decode layer:
 *   island 0: layer top (hc pre-norm, mixes, QKV projections), ending
 *             before the position-dependent QKV rope.
 *   island 1: attention output projection through the FFN/MoE tail.
 * Network V4.1 TP separates the output projection into island 2 because
 * its attention all-reduce sits before the FFN in island 1.
 * Kernel launches inside the islands ride cuda_decode_stream(): the
 * legacy NULL stream in eager mode (bit-identical behavior to before),
 * or a dedicated blocking stream while capturing/replaying.  The legacy
 * stream cannot be captured; a blocking (default-flags) stream keeps the
 * implicit serialization against NULL-stream work, so the eager middle
 * section of each layer orders correctly around replays.
 *
 * Per-entry state machine: first sight of a key runs eager (warms lazy
 * allocators -- cudaMalloc is forbidden inside capture), second sight
 * captures + instantiates + launches, later sights replay.  Any failure
 * marks the entry dead and the caller re-encodes the island eagerly, so
 * a broken capture can never lose a token's work.  Graphs replay the
 * captured kernels byte-for-byte, so replayed output is bit-identical
 * to the eager encode of the same island.
 *
 * DS4_CUDA_DECODE_GRAPHS=0 (or off/no/false) disables everything. */
#define CUDA_DECODE_GRAPH_LAYERS   64u
#define CUDA_DECODE_GRAPH_ISLANDS   3u
#define CUDA_DECODE_GRAPH_VARIANTS  4u

/* Mirrors the public `struct ds4_decode_graph_key` decl in ds4_gpu.h
 * byte-for-byte (ds4_cuda.cu does not include that header; it carries
 * its own extern "C" signatures inline).  The static_assert catches
 * accidental drift: adding a field means updating both sites. */
struct ds4_decode_graph_key {
    uint32_t il;
    uint32_t island;
    uint32_t variant;
    uint32_t _pad;
    void    *cur_hc;
    void    *after_attn_hc;
    void    *after_ffn_hc;
    void    *attn_norm;
};
typedef struct ds4_decode_graph_key ds4_decode_graph_key;
static_assert(sizeof(ds4_decode_graph_key) == 48u,
              "ds4_decode_graph_key must match the ds4_gpu.h decl");

struct cuda_decode_graph_entry {
    ds4_decode_graph_key key;
    cudaGraphExec_t      exec;
    int                  state;   /* 0 empty, 1 warmed, 2 ready, 3 dead */
    uint64_t             hits;
};

static cuda_decode_graph_entry
    g_decode_graphs[CUDA_DECODE_GRAPH_LAYERS][CUDA_DECODE_GRAPH_ISLANDS]
                   [CUDA_DECODE_GRAPH_VARIANTS];
static cudaStream_t g_decode_graph_stream = NULL;
static int g_decode_graph_capturing = 0;
static uint64_t g_decode_graph_replays = 0;
static uint64_t g_decode_graph_captures = 0;

extern "C" int ds4_gpu_decode_graphs_supported(void) {
    static int init = 0;
    static int enabled = 0;
    if (!init) {
        init = 1;
        const char *s = getenv("DS4_CUDA_DECODE_GRAPHS");
        const int off = s && *s &&
            (s[0] == '0' ||
             strcmp(s, "off") == 0 || strcmp(s, "OFF") == 0 ||
             strcmp(s, "no") == 0 || strcmp(s, "NO") == 0 ||
             strcmp(s, "false") == 0 || strcmp(s, "FALSE") == 0);
        if (off) {
            fprintf(stderr, "ds4: DS4_CUDA_DECODE_GRAPHS=%s - decode graph capture disabled\n", s);
            enabled = 0;
        } else {
            enabled = 1;
        }
    }
    return enabled && g_n_gpus == 1;
}

/* Stream the decode-island kernels launch on.  Legacy NULL stream in
 * eager mode (unchanged behavior); the capture stream while a capture
 * or replay is in flight. */
static inline cudaStream_t cuda_decode_stream(void) {
    if (g_dsv41_shared.active) return g_dsv41_shared.stream;
    return g_decode_graph_capturing ? g_decode_graph_stream : (cudaStream_t)0;
}

static void cuda_dsv41_shared_free(void) {
    if (g_dsv41_shared.stream) (void)cudaStreamDestroy(g_dsv41_shared.stream);
    if (g_dsv41_shared.ready) (void)cudaEventDestroy(g_dsv41_shared.ready);
    if (g_dsv41_shared.done) (void)cudaEventDestroy(g_dsv41_shared.done);
    if (g_dsv41_shared.scratch) (void)cudaFree(g_dsv41_shared.scratch);
    g_dsv41_shared = {};
}

static bool cuda_dsv41_shared_prepare(void) {
    if (g_dsv41_shared.stream) return true;
    if (g_dsv41_shared.disabled || g_decode_graph_capturing) return false;
    if (cuda_ok(cudaStreamCreateWithFlags(&g_dsv41_shared.stream, cudaStreamNonBlocking),
                "shared expert stream") &&
        cuda_ok(cudaEventCreateWithFlags(&g_dsv41_shared.ready, cudaEventDisableTiming),
                "shared expert input event") &&
        cuda_ok(cudaEventCreateWithFlags(&g_dsv41_shared.done, cudaEventDisableTiming),
                "shared expert output event") &&
        cuda_ok(cudaMalloc(&g_dsv41_shared.scratch, CUDA_DSV41_SHARED_SCRATCH),
                "shared expert scratch")) return true;
    cuda_dsv41_shared_free();
    (void)cudaGetLastError();
    g_dsv41_shared.disabled = true;
    return false;
}

static void cuda_decode_graph_entry_kill(cuda_decode_graph_entry *e) {
    if (e->exec) {
        (void)cudaGraphExecDestroy(e->exec);
        e->exec = NULL;
    }
    e->state = 3;
}

extern "C" void ds4_gpu_decode_graphs_invalidate(void) {
    for (uint32_t il = 0; il < CUDA_DECODE_GRAPH_LAYERS; il++) {
        for (uint32_t is = 0; is < CUDA_DECODE_GRAPH_ISLANDS; is++) {
            for (uint32_t v = 0; v < CUDA_DECODE_GRAPH_VARIANTS; v++) {
                cuda_decode_graph_entry *e = &g_decode_graphs[il][is][v];
                if (e->exec) {
                    (void)cudaGraphExecDestroy(e->exec);
                    e->exec = NULL;
                }
                e->state = 0;
                e->hits = 0;
                memset(&e->key, 0, sizeof(e->key));
            }
        }
    }
}

static cuda_decode_graph_entry *cuda_decode_graph_find(
        const ds4_decode_graph_key *key) {
    if (key->il >= CUDA_DECODE_GRAPH_LAYERS ||
        key->island >= CUDA_DECODE_GRAPH_ISLANDS) return NULL;
    cuda_decode_graph_entry *slot = NULL;
    for (uint32_t v = 0; v < CUDA_DECODE_GRAPH_VARIANTS; v++) {
        cuda_decode_graph_entry *e = &g_decode_graphs[key->il][key->island][v];
        if (e->state != 0 &&
            memcmp(&e->key, key, sizeof(*key)) == 0) return e;
        if (e->state == 0 && !slot) slot = e;
    }
    if (slot) {
        memcpy(&slot->key, key, sizeof(*key));
        slot->state = 0;   /* caller advances the state machine */
        return slot;
    }
    return NULL;           /* all variants busy with other keys: stay eager */
}

extern "C" int ds4_gpu_decode_graph_begin(const ds4_decode_graph_key *key) {
    if (!key || !ds4_gpu_decode_graphs_supported()) return -1;
    if (g_decode_graph_capturing) return -1;   /* no nesting */
    cuda_decode_graph_entry *e = cuda_decode_graph_find(key);
    if (!e || e->state == 3) return -1;
    if (e->state == 0) {
        /* Warm pass: run eagerly once so lazy allocators (tmp scratch,
         * cuBLAS workspaces) reach steady-state sizes before capture. */
        e->state = 1;
        return -1;
    }
    if (e->state == 2) {
        cudaError_t err = cudaGraphLaunch(e->exec, g_decode_graph_stream);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: decode graph replay failed (il=%u island=%u): %s\n",
                    key->il, key->island, cudaGetErrorString(err));
            (void)cudaGetLastError();
            cuda_decode_graph_entry_kill(e);
            return -1;     /* caller encodes eagerly; nothing was consumed */
        }
        e->hits++;
        g_decode_graph_replays++;
        return 1;
    }
    /* state == 1: capture this encode. */
    if (!g_decode_graph_stream) {
        if (!cuda_ok(cudaStreamCreate(&g_decode_graph_stream),
                     "decode graph stream create")) {
            g_decode_graph_stream = NULL;
            cuda_decode_graph_entry_kill(e);
            return -1;
        }
    }
    /* cuBLAS rides the legacy NULL stream, which cannot be captured:
     * point the handle at the capture stream for the duration. */
    (void)cublasSetStream(cuda_cublas_for_tier(0), g_decode_graph_stream);
    if (!cuda_ok(cudaStreamBeginCapture(g_decode_graph_stream,
                                        cudaStreamCaptureModeGlobal),
                 "decode graph begin capture")) {
        (void)cublasSetStream(cuda_cublas_for_tier(0), NULL);
        cuda_decode_graph_entry_kill(e);
        return -1;
    }
    g_decode_graph_capturing = 1;
    return 0;
}

extern "C" int ds4_gpu_decode_graph_end(const ds4_decode_graph_key *key) {
    if (!key || !g_decode_graph_capturing) return -1;
    g_decode_graph_capturing = 0;
    cudaGraph_t graph = NULL;
    cudaError_t err = cudaStreamEndCapture(g_decode_graph_stream, &graph);
    (void)cublasSetStream(cuda_cublas_for_tier(0), NULL);
    cuda_decode_graph_entry *e = cuda_decode_graph_find(key);
    if (err != cudaSuccess || graph == NULL) {
        fprintf(stderr, "ds4: decode graph capture failed (il=%u island=%u): %s\n",
                key->il, key->island, cudaGetErrorString(err));
        (void)cudaGetLastError();
        if (graph) (void)cudaGraphDestroy(graph);
        if (e) cuda_decode_graph_entry_kill(e);
        return -1;         /* caller re-encodes the island eagerly */
    }
    if (!e) {              /* cannot happen: begin() found it */
        (void)cudaGraphDestroy(graph);
        return -1;
    }
    cudaGraphExec_t exec = NULL;
    err = cudaGraphInstantiate(&exec, graph, NULL, NULL, 0);
    (void)cudaGraphDestroy(graph);
    if (err != cudaSuccess || exec == NULL) {
        fprintf(stderr, "ds4: decode graph instantiate failed (il=%u island=%u): %s\n",
                key->il, key->island, cudaGetErrorString(err));
        (void)cudaGetLastError();
        cuda_decode_graph_entry_kill(e);
        return -1;
    }
    /* Capture recorded the work without executing it: launch now so this
     * token's island actually runs. */
    err = cudaGraphLaunch(exec, g_decode_graph_stream);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: decode graph first launch failed (il=%u island=%u): %s\n",
                key->il, key->island, cudaGetErrorString(err));
        (void)cudaGetLastError();
        (void)cudaGraphExecDestroy(exec);
        cuda_decode_graph_entry_kill(e);
        return -1;
    }
    e->exec = exec;
    e->state = 2;
    g_decode_graph_captures++;
    if (getenv("DS4_CUDA_DECODE_GRAPH_LOG") != NULL) {
        fprintf(stderr, "ds4: decode graph captured il=%u island=%u (total %llu)\n",
                key->il, key->island,
                (unsigned long long)g_decode_graph_captures);
    }
    return 0;
}

/* ------------------------------------------------------------------------
 * Vendored llama.cpp mmq prefill tier (cuda/mmq/, see cuda/mmq/VENDOR.md).
 *
 * Ported from the Entrpi/ds4 batched-serving fork (fork commits 39d3877c,
 * a56e07a5, 944482d5 and the Phase 5/6 MoE wiring; author Entrpi
 * <entrpi@proton.me>).  Phase 1 takes only the RAW-layout entries: dense
 * Q8_0 GEMMs and the IQ2_XXS gate/up + Q2_K down routed-MoE pipeline for
 * n_tok >= 2 (prefill and batched verify).  The aligned-SoA / D2R /
 * producer-quantized tiers and the weight server are deliberately left
 * behind: they need the repack artifact pipeline for a further ~25% on
 * top of the ~2.5x this tier gives.  Decode (n_tok == 1) is untouched.
 * mmq changes FP32 reduction order vs the cublas+dequant pipeline, so
 * prefill logits drift at ULP scale: validated against the official
 * continuation vectors rather than byte-diffs.  DS4_CUDA_MMQ=0 restores
 * the legacy dispatch. */
/* Producer-fold registry lookup the vendored ds4_mmq.cu entries probe for
 * pre-quantized q8_1 activations (the fork's flat-pool M2-Inc2a fold).
 * The flat-pool producers are not ported, so nothing is ever registered:
 * always miss, and the entries run their own activation quantize. */
extern "C" int ds4_cuda_q8_fold_take_q81(const void *src, uint64_t in_dim,
                                         const void **q81) {
    (void)src; (void)in_dim; (void)q81;
    return 0;
}

static int cuda_use_mmq(void) {
    static int init = 0;
    static int use = 0;
    if (!init) {
        init = 1;
        const char *s = getenv("DS4_CUDA_MMQ");
        const int off = (s && s[0] == '0') || g_quality_mode || g_n_gpus > 1;
        if (off) {
            if (s && s[0] == '0') {
                fprintf(stderr, "ds4: DS4_CUDA_MMQ=0 - mmq prefill tier disabled\n");
            }
        } else if (ds4_mmq_init(0) == 0) {
            use = 1;
        } else {
            fprintf(stderr, "ds4: ds4_mmq_init failed - mmq prefill tier disabled\n");
        }
    }
    return use;
}

/* MXFP4 has no dequant+cublas fallback, so it must retain MMQ on multi-GPU
 * placements where the optional Q8/IQ2 prefill tier stays disabled. MMQ
 * resolves the active CUDA device on every call; initialization only warms
 * its device-info singleton. The experimental global persistent scratch is
 * intentionally rejected because one pointer cannot span CUDA devices. */
static int cuda_use_mxfp4_mmq(void) {
    static int init = 0;
    static int use = 0;
    if (!init) {
        init = 1;
        const char *s = getenv("DS4_CUDA_MMQ");
        if (s && s[0] == '0') {
            fprintf(stderr,
                    "ds4: DS4_CUDA_MMQ=0 - MXFP4 MMQ disabled\n");
        } else if (g_n_gpus > 1 &&
                   getenv("DS4_CUDA_MMQ_Q81_PERSISTENT") != NULL) {
            fprintf(stderr,
                    "ds4: persistent MMQ Q8_1 scratch is unavailable with multi-GPU MXFP4\n");
        } else {
            int device = 0;
            if (cudaGetDevice(&device) == cudaSuccess &&
                ds4_mmq_init(device) == 0) {
                use = 1;
            } else {
                fprintf(stderr,
                        "ds4: ds4_mmq_init failed - MXFP4 unavailable\n");
            }
        }
    }
    return use;
}

/* mmq pipeline helpers, ported from the fork: SwiGLU + clamp + router
 * weight in the (token, slot, feature) layout ds4_mmq_*_moe writes, and
 * the guarded per-token slot sum. */
__global__ static void moe_mmq_swiglu_weighted_clamp_kernel(
        float *mid_out,
        const float *gate_buf, const float *up_buf,
        const float *weights,
        uint32_t expert_mid_dim,
        uint32_t n_tokens,
        uint32_t n_expert_used,
        float clamp) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * n_expert_used * expert_mid_dim;
    if (gid >= n) return;
    uint64_t slot_pair = gid / expert_mid_dim;
    uint32_t tok = (uint32_t)(slot_pair / n_expert_used);
    uint32_t slot = (uint32_t)(slot_pair - (uint64_t)tok * n_expert_used);
    const float w = weights[(uint64_t)tok * n_expert_used + slot];
    /* Unowned assignments have no gate/up output. Never read those slots. */
    if (w == 0.0f) { mid_out[gid] = 0.0f; return; }
    float g = gate_buf[gid];
    float u = up_buf[gid];
    if (!isfinite(g)) g = 0.0f;
    if (!isfinite(u)) u = 0.0f;
    if (clamp > 1.0e-6f) {
        if (g > clamp) g = clamp;
        if (u > clamp) u = clamp;
        if (u < -clamp) u = -clamp;
    }
    const float s = g / (1.0f + expf(-g));
    mid_out[gid] = s * u * w;
}

__global__ static void moe_mmq_sum_kernel(float *out, const float *down,
        const int32_t *selected, uint32_t out_dim, uint32_t n_expert,
        uint32_t n_tokens, uint32_t guard_nonfinite) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * out_dim;
    if (gid >= n) return;
    uint32_t tok = gid / out_dim;
    uint32_t row = gid - (uint64_t)tok * out_dim;
    float acc = 0.0f;
    for (uint32_t e = 0; e < n_expert; e++) {
        if (selected && selected[(uint64_t)tok * n_expert + e] < 0) continue;
        const float v = down[((uint64_t)tok * n_expert + e) * out_dim + row];
        if (!guard_nonfinite || isfinite(v)) acc += v;
    }
    out[gid] = acc;
}

/* Abort an in-flight capture after an encode error inside the island.
 * Nothing was executed; the caller re-encodes eagerly. */
extern "C" void ds4_gpu_decode_graph_abort(const ds4_decode_graph_key *key) {
    if (!g_decode_graph_capturing) return;
    g_decode_graph_capturing = 0;
    cudaGraph_t graph = NULL;
    (void)cudaStreamEndCapture(g_decode_graph_stream, &graph);
    if (graph) (void)cudaGraphDestroy(graph);
    (void)cublasSetStream(cuda_cublas_for_tier(0), NULL);
    (void)cudaGetLastError();
    if (key) {
        cuda_decode_graph_entry *e = cuda_decode_graph_find(key);
        if (e) cuda_decode_graph_entry_kill(e);
    }
}

/* Multi-tier-aware weight pointer resolver.
 *
 * Used by kernel-dispatch wrappers in the per-layer execution path to
 * obtain a device pointer for a weight slice on the layer's logical
 * tier. Behavior:
 *
 *   - When g_n_gpus <= 1 (single-tier engine), delegates to the existing
 *     cuda_model_range_ptr path. This short-circuit guarantees byte-
 *     identical behavior to pre-multi-tier code for the gpu_cfg == NULL
 *     case.
 *
 *   - When g_n_gpus >= 2 (multi-tier engine), translates the logical
 *     tier index to the corresponding physical CUDA device id via
 *     g_gpu[logical_tier].device_id and looks up the slice strictly
 *     in the per-device selective cache via ds4_gpu_lookup_cache_strict.
 *     On miss, logs a diagnostic and returns NULL (no host-pointer
 *     fallback — a miss here is a placement/install bug).
 *
 * The caller is responsible for cudaSetDevice'ing to the right physical
 * device before launching the kernel that consumes the returned pointer.
 * Wrappers in this file thread `int logical_tier` from the dispatch
 * caller; single-tier callers pass 0, which hits the short-circuit.
 *
 * Added for multi-GPU execution (multi-GPU execution), sub-area 3 of the
 * spec. */
/* Optional second (support) model map for speculative decoding. The strict
 * multi-tier cache is keyed by source offset only, so support tensors are
 * installed and resolved with a large disjoint offset bias. */
static const void *g_support_host_base = NULL;
static uint64_t g_support_host_size = 0;
static uint64_t g_support_offset_bias = 0;

extern "C" uint64_t ds4_gpu_tier_free_vram(int logical_tier) {
    if (logical_tier < 0 || logical_tier >= g_n_gpus) return 0;
    int prev = -1;
    if (cudaGetDevice(&prev) != cudaSuccess) prev = -1;
    if (cudaSetDevice(g_gpu[logical_tier].device_id) != cudaSuccess) return 0;
    size_t free_b = 0, total_b = 0;
    uint64_t out = 0;
    if (cudaMemGetInfo(&free_b, &total_b) == cudaSuccess) out = (uint64_t)free_b;
    if (prev >= 0) (void)cudaSetDevice(prev);
    return out;
}

extern "C" int ds4_gpu_register_support_map(const void *map, uint64_t size, uint64_t bias) {
    if (!map || size == 0 || bias == 0) return 0;
    g_support_host_base = map;
    g_support_host_size = size;
    g_support_offset_bias = bias;
    return 1;
}

static const char *cuda_resolve_weight_ptr(const void *model_map,
                                            uint64_t offset,
                                            uint64_t bytes,
                                            int logical_tier,
                                            const char *label,
                                            const char **kind_out = NULL) {
    if (kind_out) *kind_out = NULL;
    /* [2026-08-16 FIX] Resolve SUPPORT-model weights directly against the registered support map.
     *
     * WHY: ds4_gpu_register_support_map() records base/size/bias, but on a single GPU this function
     * took the g_n_gpus <= 1 early return and delegated to cuda_model_range_ptr(), which matches
     * `r.host_base == model_map` against the TARGET model's range table. The support map therefore
     * resolved only where a range happened to exist, giving DISCONTIGUOUS coverage - measured:
     *     offset         5,440 (stage 0 attn_kv)    resolves
     *     offset 2,008,544,064 (stage 1 attn_kv)    NULL   <-- broke the DSpark seed
     *     offset 3,962,015,904 (stage 1 hc_attn_fn) resolves
     * A higher offset working than the failing one is what ruled out every span/truncation theory.
     *
     * The support model is cudaHostRegister'd no-copy, so its host pointer is device-addressable
     * under unified addressing; a bounds-checked base+offset is the correct resolution and needs no
     * range entry. The multi-GPU branch below still applies g_support_offset_bias as before. */
    /* [2026-08-16 REVERTED] A fast path here returned `(const char *)model_map + offset` for the
     * support map. It cleared the resolve NULL (0 instead of 1) but caused
     *     CUDA synchronize failed: an illegal memory access was encountered
     * on the first decode: that is a HOST pointer, and the kernels dereference it on device. The
     * support mapping is not device-addressable as-is.
     *
     * THAT EXPLAINS THE multi_tier DESIGN: engine_install_dspark_support_cache() VRAM-PACKS the
     * support tensors onto the executor tier because the device cannot read the host mapping
     * directly. The packing is not an optimisation, it is a requirement - so DSpark needs the support
     * weights resident in VRAM, competing with the streaming expert cache on a single card. */
    if (g_ssd_streaming_mode && model_map==g_support_host_base &&
        getenv("DS4_CUDA_DSPARK_RESIDENT") && !strcmp(getenv("DS4_CUDA_DSPARK_RESIDENT"),"1")) {
        /* Never fall back to host mapping or a per-tensor upload for the draft. */
        for (const auto &r:g_model_ranges) if(r.host_base==model_map && !r.host_registered &&
            r.offset<=offset && offset-r.offset<=r.bytes && bytes<=r.bytes-(offset-r.offset)) {
            if(kind_out)*kind_out="resident";return r.device_ptr+(offset-r.offset);
        }
        fprintf(stderr,"ds4: resident DSpark weight missing from VRAM: %s\n",label?label:"?");return NULL;
    }
    if (g_n_gpus <= 1) {
        return cuda_model_range_ptr(model_map, offset, bytes, label, kind_out);
    }
    if (g_support_host_base && model_map == g_support_host_base) {
        offset += g_support_offset_bias;
    }
    if (logical_tier < 0 || logical_tier >= g_n_gpus) {
        fprintf(stderr,
            "ds4: cuda_resolve_weight_ptr: bad tier %d (n_gpus=%d, label=%s)\n",
            logical_tier, g_n_gpus, label ? label : "?");
        return NULL;
    }
    const int physical_device = g_gpu[logical_tier].device_id;
    void *dev_ptr = NULL;
    if (ds4_gpu_lookup_cache_strict(offset, bytes, physical_device, &dev_ptr)
        && dev_ptr) {
        if (kind_out) *kind_out = "resident";
        return (const char *)dev_ptr;
    }
    /* GLM multi-tier: generic launchers resolve by the OUT tensor's tier,
     * but the executing device (set per layer) is where the weights were
     * cached. Retry with the current device before declaring a miss;
     * DS4 paths never reach this (out tier == current device). */
    int cur_dev = -1;
    if (cudaGetDevice(&cur_dev) == cudaSuccess &&
        cur_dev != physical_device &&
        ds4_gpu_lookup_cache_strict(offset, bytes, cur_dev, &dev_ptr) &&
        dev_ptr) {
        if (kind_out) *kind_out = "resident";
        return (const char *)dev_ptr;
    }
    fprintf(stderr,
        "ds4: selective-cache miss for offset=%llu bytes=%llu on "
        "logical_tier=%d (physical_device=%d, current_device=%d, "
        "label=%s); this is a placement/cache-install bug\n",
        (unsigned long long)offset, (unsigned long long)bytes,
        logical_tier, physical_device, cur_dev, label ? label : "?");
    return NULL;
}

static int cuda_model_range_is_cached(const void *model_map, uint64_t offset, uint64_t bytes) {
    if (bytes == 0) return 1;
    if (model_map == g_model_host_base &&
        (g_model_device_owned || g_model_registered)) return 1;

    const uint64_t end = offset + bytes;
    if (end < offset) return 0;
    for (const cuda_model_range &r : g_model_ranges) {
        if (r.host_base == model_map &&
            offset >= r.offset &&
            end <= r.offset + r.bytes) {
            return 1;
        }
        if (r.host_base == model_map &&
            r.host_registered &&
            r.registered_base &&
            r.registered_device_base) {
            const uintptr_t h0 = (uintptr_t)((const char *)model_map + offset);
            const uintptr_t h1 = h0 + bytes;
            const uintptr_t r0 = (uintptr_t)r.registered_base;
            const uintptr_t r1 = r0 + r.registered_bytes;
            if (h1 >= h0 && h0 >= r0 && h1 <= r1) return 1;
        }
    }
    return 0;
}

static void cuda_q8_f16_cache_release_all(void) {
    for (const cuda_q8_f16_range &r : g_q8_f16_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f16_ranges.clear();
    g_q8_f16_by_offset.clear();
    g_q8_f16_bytes = 0;
}

static uint64_t cuda_parse_mib_env(const char *name, int *present) {
    const char *env = getenv(name);
    if (present) *present = 0;
    if (!env || !env[0]) return 0;
    char *end = NULL;
    unsigned long long v = strtoull(env, &end, 10);
    if (end == env || *end != '\0') return 0;
    if (present) *present = 1;
    if (v > UINT64_MAX / 1048576ull) return UINT64_MAX;
    return (uint64_t)v * 1048576ull;
}

static uint32_t cuda_parse_u32_env_clamped(const char *name, uint32_t fallback,
                                           uint32_t min_value, uint32_t max_value,
                                           int *present) {
    const char *env = getenv(name);
    if (present) *present = 0;
    if (!env || !env[0]) return fallback;
    errno = 0;
    char *end = NULL;
    unsigned long v = strtoul(env, &end, 10);
    if (errno != 0 || end == env || *end != '\0') return fallback;
    if (present) *present = 1;
    if (v < min_value) return min_value;
    if (v > max_value) return max_value;
    return (uint32_t)v;
}

static int cuda_env_flag_enabled(const char *name, int fallback) {
    const char *env = getenv(name);
    if (!env || !env[0]) return fallback;
    return strcmp(env, "0") != 0;
}

extern "C" int ds4_gpu_set_decode_fast_attention(int enabled) {
    const int old = g_decode_fast_attention;
    g_decode_fast_attention = enabled != 0;
    return old;
}

extern "C" int ds4_gpu_set_decode_score_vec4(int enabled) {
    const int old = g_decode_score_vec4;
    g_decode_score_vec4 = enabled != 0;
    return old;
}

static bool cuda_splitkv_decode_requested(void) {
    if (cuda_env_flag_enabled("DS4_CUDA_NO_SPLITKV_DECODE", 0)) return false;
    return g_decode_fast_attention ||
           cuda_env_flag_enabled("DS4_CUDA_SPLITKV_DECODE", 0);
}

static bool cuda_q8_f16_cache_bounded(void) {
#if defined(_WIN32)
    return g_n_gpus <= 1;
#else
    return false;
#endif
}

static void cuda_q8_f16_cache_required_failure(const char *reason, uint64_t bytes) {
    fprintf(stderr,
            "ds4: Q8_F16_REQUIRED_REFUSED reason=%s requested_bytes=%llu "
            "cached_bytes=%llu; F16 numerical path cannot fit declared residency budget\n",
            reason, (unsigned long long)bytes, (unsigned long long)g_q8_f16_bytes);
    fflush(stderr);
#if defined(_WIN32)
    /* After GPU resources are live: graceful abort (the request fails; the F16 path is
     * never silently replaced, because every cancel check now fails the request). */
    if (ds4_win32_gpu_resources_live()) {
        ds4_win32_request_graceful_abort("required Q8 F16 cache cannot fit");
        return;
    }
    ExitProcess(72);
#else
    exit(72);
#endif
}

static uint64_t cuda_q8_f16_cache_limit_bytes(void) {
    int present = 0;
    const uint64_t limit = cuda_parse_mib_env("DS4_CUDA_Q8_F16_CACHE_MB", &present);
    return present ? limit : cuda_q8_f16_cache_bounded() ? 256ull * 1048576ull : UINT64_MAX;
}

static uint64_t cuda_q8_f16_cache_reserve_bytes(uint64_t total_bytes) {
    int present = 0;
    const uint64_t reserve = cuda_parse_mib_env("DS4_CUDA_Q8_F16_CACHE_RESERVE_MB", &present);
    if (present) return reserve;

    if (total_bytes >= 112ull * 1024ull * 1024ull * 1024ull) {
        return 512ull * 1048576ull;
    }

    /* High-VRAM cards (>= 40 GiB, e.g. 48 GiB RTX 6000 Ada): use a small
     * reserve so the selective Q8->F16 cache can actually engage at tight
     * budgets (e.g. --gpu-vram 47,47, where the 81 GB model leaves only ~1.3
     * GiB free and the old 4 GiB floor rejected every cache allocation,
     * forcing the scalar DP4A prefill kernel).
     *
     * NOTE: this 768 MiB value is a *bounded cache-growth guard*, not a hard
     * guarantee that live free VRAM stays >= 768 MiB.  cuda_q8_f16_cache_has_budget
     * only blocks a *cache* allocation when free - request < reserve at that
     * moment; allocations made outside cache accounting (cuda_tmp_alloc_on
     * activation/prequant buffers, cuBLAS internal workspaces) can still dip
     * below it.  768 MiB is chosen to leave headroom above the ~0.5 GiB
     * memory-safety floor for those out-of-cache allocations; actual minimum
     * free VRAM is verified by measurement, and the disable-after-failure path
     * degrades gracefully if cuBLAS/alloc ever fails under pressure.  Set
     * DS4_CUDA_Q8_F16_CACHE_RESERVE_MB=4096 to restore the prior behavior. */
    if (total_bytes >= 40ull * 1024ull * 1024ull * 1024ull) {
        const uint64_t hi_min_reserve = 768ull * 1048576ull;
        const uint64_t hi_pct_reserve = total_bytes / 100u; /* 1% */
        return hi_pct_reserve > hi_min_reserve ? hi_pct_reserve : hi_min_reserve;
    }

    /* Smaller cards (< 40 GiB): keep the conservative reserve.  The expanded
     * Q8->F16 cache is only an acceleration path; on a small card a sub-GiB
     * reserve would be a large fraction of total VRAM, so keep enough free for
     * cuBLAS workspaces, transient graph buffers, and driver bookkeeping. */
    const uint64_t min_reserve = 4096ull * 1048576ull;
    const uint64_t pct_reserve = total_bytes / 20u; /* 5% */
    return pct_reserve > min_reserve ? pct_reserve : min_reserve;
}

static void cuda_q8_f16_cache_budget_notice(
        const char *reason,
        uint64_t request_bytes,
        uint64_t free_bytes,
        uint64_t total_bytes,
        uint64_t reserve_bytes,
        uint64_t limit_bytes) {
    if (g_q8_f16_budget_notice_printed && getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE") == NULL) return;
    g_q8_f16_budget_notice_printed = 1;
    if (limit_bytes != UINT64_MAX && free_bytes == 0 && total_bytes == 0 && reserve_bytes == 0) {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache %s; using q8 kernels "
                "(request=%.2f MiB cached=%.2f GiB limit=%.2f GiB)\n",
                reason,
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0,
                (double)limit_bytes / 1073741824.0);
    } else if (limit_bytes == UINT64_MAX) {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache %s; using q8 kernels "
                "(request=%.2f MiB cached=%.2f GiB free=%.2f GiB reserve=%.2f GiB total=%.2f GiB)\n",
                reason,
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0,
                (double)free_bytes / 1073741824.0,
                (double)reserve_bytes / 1073741824.0,
                (double)total_bytes / 1073741824.0);
    } else {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache %s; using q8 kernels "
                "(request=%.2f MiB cached=%.2f GiB limit=%.2f GiB free=%.2f GiB reserve=%.2f GiB total=%.2f GiB)\n",
                reason,
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0,
                (double)limit_bytes / 1073741824.0,
                (double)free_bytes / 1073741824.0,
                (double)reserve_bytes / 1073741824.0,
                (double)total_bytes / 1073741824.0);
    }
}

static int cuda_q8_f16_cache_has_budget(uint64_t request_bytes, const char *label) {
    (void)label;
    const uint64_t limit = cuda_q8_f16_cache_limit_bytes();
    if (limit == 0) return 0;
    if (cuda_q8_f16_cache_bounded() && request_bytes > limit)
        cuda_q8_f16_cache_required_failure("tensor exceeds cache cap", request_bytes);
    if (g_q8_f16_bytes > limit || request_bytes > limit - g_q8_f16_bytes) {
        if (cuda_q8_f16_cache_bounded()) {
            /* Prior GEMMs may still read cached weights. Drain all consumers
             * before freeing them; the next miss recreates exactly the same
             * F16 bytes, rather than changing to a Q8 arithmetic path. */
            if (g_decode_graph_capturing ||
                !cuda_ok(cudaDeviceSynchronize(), "drain bounded q8 fp16 cache"))
                cuda_q8_f16_cache_required_failure("cannot drain cache consumers", request_bytes);
            cuda_q8_f16_cache_release_all();
        } else {
            cuda_q8_f16_cache_budget_notice("limit reached", request_bytes, 0, 0, 0, limit);
            return 0;
        }
    }

    size_t free_b = 0;
    size_t total_b = 0;
    cudaError_t err = cudaMemGetInfo(&free_b, &total_b);
    if (err != cudaSuccess) {
        if (cuda_q8_f16_cache_bounded())
            cuda_q8_f16_cache_required_failure("VRAM query failed", request_bytes);
        fprintf(stderr, "ds4: CUDA q8 fp16 cache memory query failed: %s; using q8 kernels\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }

    const uint64_t free_bytes = (uint64_t)free_b;
    const uint64_t total_bytes = (uint64_t)total_b;
    const uint64_t reserve_bytes = cuda_q8_f16_cache_reserve_bytes(total_bytes);
    if (request_bytes > free_bytes ||
        free_bytes - request_bytes < reserve_bytes) {
        if (cuda_q8_f16_cache_bounded())
            cuda_q8_f16_cache_required_failure("VRAM reserve", request_bytes);
        cuda_q8_f16_cache_budget_notice("budget exhausted", request_bytes,
                                        free_bytes, total_bytes,
                                        reserve_bytes, limit);
        return 0;
    }
    return 1;
}

static void cuda_q8_f16_cache_disable_after_failure(const char *what, uint64_t request_bytes) {
    if (cuda_q8_f16_cache_bounded())
        cuda_q8_f16_cache_required_failure(what ? what : "CUDA allocation failure", request_bytes);
    if (!g_q8_f16_disabled_after_oom) {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache disabled after %s "
                "(request=%.2f MiB cached=%.2f GiB); using q8 kernels\n",
                what ? what : "allocation failure",
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0);
    }
    g_q8_f16_disabled_after_oom = 1;
    if (!g_q8_f16_ranges.empty()) {
        (void)cudaDeviceSynchronize();
        cuda_q8_f16_cache_release_all();
    }
    (void)cudaGetLastError();
}

static int cuda_q8_f16_cache_allowed(const char *label, uint64_t in_dim, uint64_t out_dim) {
    if (g_quality_mode) return 0;
    if (g_q8_cache_suppressed) return 0;
    if (g_q8_f16_disabled_after_oom) return 0;
    if (getenv("DS4_CUDA_NO_Q8_F16_CACHE") != NULL) return 0;
    if (cuda_q8_f16_cache_limit_bytes() == 0) return 0;
    if (getenv("DS4_CUDA_Q8_F16_ALL") != NULL) return 1;
    if (!label) return 0;
    if (strstr(label, "attn_output_a") != NULL ||
        strstr(label, "attn_output_b") != NULL ||
        strstr(label, "attention_output_a") != NULL ||
        strstr(label, "attention_output_b") != NULL) {
        return getenv("DS4_CUDA_NO_ATTENTION_OUTPUT_F16_CACHE") == NULL;
    }
    if (strstr(label, "attn_q_b") != NULL) {
        return getenv("DS4_CUDA_NO_ATTN_Q_B_F16_CACHE") == NULL;
    }
    if (strstr(label, "ffn_gate_shexp") != NULL ||
        strstr(label, "ffn_up_shexp") != NULL ||
        strstr(label, "ffn_down_shexp") != NULL) {
        return 1;
    }
    return (in_dim == 4096u && out_dim == 2048u) ||
           (in_dim == 2048u && out_dim == 4096u) ||
           (in_dim == 4096u && out_dim == 1024u) ||
           (in_dim == 4096u && out_dim == 512u) ||
           (getenv("DS4_CUDA_NO_ATTN_Q_B_F16_CACHE") == NULL &&
            in_dim == 1024u && out_dim == 32768u);
}

static int cuda_q8_label_is_attention_output(const char *label) {
    return label &&
           (strstr(label, "attn_output_a") != NULL ||
            strstr(label, "attn_output_b") != NULL ||
            strstr(label, "attention_output_a") != NULL ||
            strstr(label, "attention_output_b") != NULL);
}

static int cuda_q8_use_dp4a(void) {
    return getenv("DS4_CUDA_NO_Q8_DP4A") == NULL;
}

static unsigned cuda_q8_exact_threads(uint64_t blocks) {
    if (blocks <= 64u) return 64u;
    if (blocks <= 128u) return 128u;
    return 256u;
}

static int cuda_q8_f16_preload_allowed(const char *label, uint64_t in_dim, uint64_t out_dim) {
    if (cuda_q8_label_is_attention_output(label) &&
        getenv("DS4_CUDA_ATTENTION_OUTPUT_PRELOAD") == NULL &&
        getenv("DS4_CUDA_Q8_F16_ALL") == NULL) {
        return 0;
    }
    return cuda_q8_f16_cache_allowed(label, in_dim, out_dim);
}

static int cuda_q8_f32_cache_allowed(const char *label, uint64_t in_dim, uint64_t out_dim) {
    if (g_q8_cache_suppressed) return 0;
    if (getenv("DS4_CUDA_NO_Q8_F32_CACHE") != NULL) return 0;
    if (getenv("DS4_CUDA_Q8_F32_ALL") != NULL) return 1;
    if (label && strstr(label, "attn_q_b") != NULL) {
        return getenv("DS4_CUDA_ATTN_Q_B_F32_CACHE") != NULL;
    }
    return getenv("DS4_CUDA_Q8_F32_LARGE") != NULL &&
           in_dim == 1024u && out_dim == 32768u;
}

/* Look up a per-device dequantized fp16 slice of the Q8_0 weight at
 * (model_map, offset, weight_bytes, in_dim, out_dim). expected_device is a
 * PHYSICAL CUDA device id (0 in single-tier; g_gpu[logical_tier].device_id in
 * multi-tier). On hit returns the cached pointer for that device. On miss
 * cudaSetDevice's to expected_device, allocates + dequants there, stamps the
 * new entry with device_id == expected_device, restores the previous device,
 * and returns the new pointer.
 *
 * Single-tier (g_n_gpus <= 1) uses the offset-keyed map for a fast path —
 * legacy entries were stamped device_id=0, so the map remains authoritative.
 * Multi-tier linear-scans the ranges vector filtering on device_id (the same
 * offset may now legitimately map to multiple entries, one per device).
 */
static const __half *cuda_q8_f16_ptr(
        const void *model_map,
        uint64_t offset,
        uint64_t weight_bytes,
        uint64_t in_dim,
        uint64_t out_dim,
        int expected_device,
        const char *label) {
    if (g_n_gpus <= 1) {
        auto exact = g_q8_f16_by_offset.find(offset);
        if (exact != g_q8_f16_by_offset.end()) {
            const cuda_q8_f16_range &r = g_q8_f16_ranges[exact->second];
            if (r.host_base == model_map && r.weight_bytes == weight_bytes &&
                r.in_dim == in_dim && r.out_dim == out_dim) {
                return r.device_ptr;
            }
        }
    } else {
        for (const cuda_q8_f16_range &r : g_q8_f16_ranges) {
            if (r.host_base == model_map &&
                r.offset == offset &&
                r.weight_bytes == weight_bytes &&
                r.in_dim == in_dim &&
                r.out_dim == out_dim &&
                r.device_id == expected_device) {
                return r.device_ptr;
            }
        }
    }
    if (!cuda_q8_f16_cache_allowed(label, in_dim, out_dim)) return NULL;

    /* Source Q8 bytes:
     *  - Single-tier (g_n_gpus <= 1): cuda_model_range_ptr — preserves the
     *    legacy behavior (FD cache, host-register, or cudaMalloc-and-copy).
     *  - Multi-tier (g_n_gpus > 1): the per-device selective cache must
     *    already contain the weight on expected_device. Use the strict
     *    lookup; on miss this is a placement bug and we hard-fail.
     */
    const char *q8;
    if (g_n_gpus <= 1) {
        q8 = cuda_model_range_ptr(model_map, offset, weight_bytes, "q8_0");
    } else {
        void *strict_ptr = NULL;
        if (!ds4_gpu_lookup_cache_strict(offset, weight_bytes, expected_device, &strict_ptr) ||
            !strict_ptr) {
            fprintf(stderr,
                "ds4: q8 fp16 cache miss: source bytes not in selective cache for "
                "offset=%llu bytes=%llu device=%d (label=%s); placement bug\n",
                (unsigned long long)offset, (unsigned long long)weight_bytes,
                expected_device, label ? label : "?");
            return NULL;
        }
        q8 = (const char *)strict_ptr;
    }
    if (!q8) return NULL;

    if (in_dim != 0 && out_dim > UINT64_MAX / in_dim / sizeof(__half)) return NULL;
    const uint64_t out_bytes = in_dim * out_dim * sizeof(__half);
    if (!cuda_q8_f16_cache_has_budget(out_bytes, label)) return NULL;

    int prev = -1;
    if (g_n_gpus > 1) {
        cudaError_t derr = cudaGetDevice(&prev);
        if (derr != cudaSuccess) {
            fprintf(stderr, "ds4: cudaGetDevice failed before q8 fp16 alloc on device %d: %s\n",
                    expected_device, cudaGetErrorString(derr));
            (void)cudaGetLastError();
            return NULL;
        }
        derr = cudaSetDevice(expected_device);
        if (derr != cudaSuccess) {
            fprintf(stderr, "ds4: cudaSetDevice(%d) failed before q8 fp16 alloc: %s\n",
                    expected_device, cudaGetErrorString(derr));
            (void)cudaGetLastError();
            if (prev >= 0) (void)cudaSetDevice(prev);
            return NULL;
        }
    }
    __half *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)out_bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA q8 fp16 cache alloc failed on device %d (%.2f MiB): %s\n",
                expected_device, (double)out_bytes / 1048576.0, cudaGetErrorString(err));
        cuda_q8_f16_cache_disable_after_failure("allocation failure", out_bytes);
        if (g_n_gpus > 1 && prev >= 0) (void)cudaSetDevice(prev);
        return NULL;
    }
    const uint64_t blocks = (in_dim + 31) / 32;
    const uint64_t n = in_dim * out_dim;
    dequant_q8_0_to_f16_kernel<<<(n + 255) / 256, 256>>>(dev,
                                                          (const unsigned char *)q8,
                                                          in_dim,
                                                          out_dim,
                                                          blocks);
    if (!cuda_ok(cudaGetLastError(), "q8 fp16 dequant launch")) {
        (void)cudaFree(dev);
        cuda_q8_f16_cache_disable_after_failure("dequant launch failure", out_bytes);
        if (g_n_gpus > 1 && prev >= 0) (void)cudaSetDevice(prev);
        return NULL;
    }
    g_q8_f16_ranges.push_back({model_map, offset, weight_bytes, in_dim, out_dim, dev, expected_device});
    if (g_n_gpus <= 1) {
        g_q8_f16_by_offset[offset] = g_q8_f16_ranges.size() - 1u;
    }
    g_q8_f16_bytes += out_bytes;
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA cached q8 fp16 %.2f MiB on device %d (total %.2f GiB)\n",
                (double)out_bytes / 1048576.0, expected_device,
                (double)g_q8_f16_bytes / 1073741824.0);
    }
    if (g_n_gpus > 1 && prev >= 0) (void)cudaSetDevice(prev);
    return dev;
}

/* Model-free fixture oracle: exercise the real cache, dequantization and
 * eviction path without replacing any production kernel or launching a model.
 * Disabled unless explicitly enabled in an otherwise idle Windows single-GPU
 * test process initialized with ds4_gpu_init. Never expose pointers in capture. */
static bool cuda_q8_f16_fixture_enabled(void) {
    const char *enabled = getenv("DS4_CUDA_Q8_F16_CACHE_TEST");
    return enabled && !strcmp(enabled, "1") && cuda_q8_f16_cache_bounded() &&
           g_n_gpus == 1 && !g_decode_graph_capturing;
}

extern "C" const void *ds4_gpu_test_q8_f16_cache_ptr(
        const void *model_map, uint64_t offset, uint64_t weight_bytes,
        uint64_t in_dim, uint64_t out_dim, uint64_t *resident_bytes,
        uint64_t *resident_entries) {
    if (!cuda_q8_f16_fixture_enabled()) return NULL;
    const void *ptr = cuda_q8_f16_ptr(model_map, offset, weight_bytes,
                                    in_dim, out_dim, 0, "test:attn_q_b");
    if (resident_bytes) *resident_bytes = g_q8_f16_bytes;
    if (resident_entries) *resident_entries = g_q8_f16_ranges.size();
    return ptr;
}

extern "C" int ds4_gpu_test_q8_f16_cache_clear(void) {
    if (!cuda_q8_f16_fixture_enabled()) return 0;
    if (!cuda_ok(cudaDeviceSynchronize(), "clear q8 fp16 fixture cache")) return 0;
    cuda_q8_f16_cache_release_all();
    return 1;
}

extern "C" int ds4_gpu_test_q8_f16_cache_contains(uint64_t offset) {
    if (!cuda_q8_f16_fixture_enabled()) return 0;
    return g_q8_f16_by_offset.find(offset) != g_q8_f16_by_offset.end();
}

/* Per-device dequantized fp32 cache. Same conventions as cuda_q8_f16_ptr. */
static float *cuda_q8_f32_ptr(
        const void *model_map,
        uint64_t offset,
        uint64_t weight_bytes,
        uint64_t in_dim,
        uint64_t out_dim,
        int expected_device,
        const char *label) {
    if (g_n_gpus <= 1) {
        auto exact = g_q8_f32_by_offset.find(offset);
        if (exact != g_q8_f32_by_offset.end()) {
            const cuda_q8_f32_range &r = g_q8_f32_ranges[exact->second];
            if (r.host_base == model_map && r.weight_bytes == weight_bytes &&
                r.in_dim == in_dim && r.out_dim == out_dim) {
                return r.device_ptr;
            }
        }
    } else {
        for (const cuda_q8_f32_range &r : g_q8_f32_ranges) {
            if (r.host_base == model_map &&
                r.offset == offset &&
                r.weight_bytes == weight_bytes &&
                r.in_dim == in_dim &&
                r.out_dim == out_dim &&
                r.device_id == expected_device) {
                return r.device_ptr;
            }
        }
    }
    if (!cuda_q8_f32_cache_allowed(label, in_dim, out_dim)) return NULL;

    /* Source Q8 bytes: legacy path in single-tier; strict per-device lookup
     * in multi-tier (same rationale as cuda_q8_f16_ptr). */
    const char *q8;
    if (g_n_gpus <= 1) {
        q8 = cuda_model_range_ptr(model_map, offset, weight_bytes, label ? label : "q8_0");
    } else {
        void *strict_ptr = NULL;
        if (!ds4_gpu_lookup_cache_strict(offset, weight_bytes, expected_device, &strict_ptr) ||
            !strict_ptr) {
            fprintf(stderr,
                "ds4: q8 fp32 cache miss: source bytes not in selective cache for "
                "offset=%llu bytes=%llu device=%d (label=%s); placement bug\n",
                (unsigned long long)offset, (unsigned long long)weight_bytes,
                expected_device, label ? label : "?");
            return NULL;
        }
        q8 = (const char *)strict_ptr;
    }
    if (!q8) return NULL;

    const uint64_t out_bytes = in_dim * out_dim * sizeof(float);
    int prev = -1;
    if (g_n_gpus > 1) {
        cudaError_t derr = cudaGetDevice(&prev);
        if (derr != cudaSuccess) {
            fprintf(stderr, "ds4: cudaGetDevice failed before q8 fp32 alloc on device %d: %s\n",
                    expected_device, cudaGetErrorString(derr));
            (void)cudaGetLastError();
            return NULL;
        }
        derr = cudaSetDevice(expected_device);
        if (derr != cudaSuccess) {
            fprintf(stderr, "ds4: cudaSetDevice(%d) failed before q8 fp32 alloc: %s\n",
                    expected_device, cudaGetErrorString(derr));
            (void)cudaGetLastError();
            if (prev >= 0) (void)cudaSetDevice(prev);
            return NULL;
        }
    }
    float *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)out_bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA q8 fp32 cache alloc failed on device %d (%.2f MiB): %s\n",
                expected_device, (double)out_bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        if (g_n_gpus > 1 && prev >= 0) (void)cudaSetDevice(prev);
        return NULL;
    }
    const uint64_t blocks = (in_dim + 31) / 32;
    const uint64_t n = in_dim * out_dim;
    dequant_q8_0_to_f32_kernel<<<(n + 255) / 256, 256>>>(dev,
                                                          (const unsigned char *)q8,
                                                          in_dim,
                                                          out_dim,
                                                          blocks);
    if (!cuda_ok(cudaGetLastError(), "q8 fp32 dequant launch")) {
        (void)cudaFree(dev);
        if (g_n_gpus > 1 && prev >= 0) (void)cudaSetDevice(prev);
        return NULL;
    }
    g_q8_f32_ranges.push_back({model_map, offset, weight_bytes, in_dim, out_dim, dev, expected_device});
    if (g_n_gpus <= 1) {
        g_q8_f32_by_offset[offset] = g_q8_f32_ranges.size() - 1u;
    }
    g_q8_f32_bytes += out_bytes;
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA cached q8 fp32 %.2f MiB on device %d (total %.2f GiB)\n",
                (double)out_bytes / 1048576.0, expected_device,
                (double)g_q8_f32_bytes / 1073741824.0);
    }
    if (g_n_gpus > 1 && prev >= 0) (void)cudaSetDevice(prev);
    return dev;
}

static int cuda_ok(cudaError_t err, const char *what) {
    if (err == cudaSuccess) return 1;
    fprintf(stderr, "ds4: CUDA %s failed: %s (code=%d name=%s)\n", what,
            cudaGetErrorString(err), (int)err, cudaGetErrorName(err));
#if defined(_WIN32)
    ds4_win32_host_memory_snapshot(what);
#endif
    return 0;
}

static double cuda_wall_sec(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec * 1.0e-9;
}

static int cuda_model_load_progress_enabled(void) {
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE") != NULL) return 0;
    return 1;
}

static void cuda_model_load_progress_reset(void) {
    g_model_load_progress_next = 0;
    g_model_load_progress_last = 0.0;
    g_model_load_progress_started = 0;
    g_model_load_progress_tty = 0;
}

static void cuda_model_load_progress_note(uint64_t cached_bytes) {
    if (!cuda_model_load_progress_enabled()) return;

    const double now = cuda_wall_sec();
    if (!g_model_load_progress_started) {
        g_model_load_progress_started = 1;
        g_model_load_progress_tty = isatty(STDERR_FILENO) != 0;
        g_model_load_progress_next = (g_model_load_progress_tty ? 2ull : 16ull) *
                                     1024ull * 1024ull * 1024ull;
        g_model_load_progress_last = now;
        if (g_model_load_progress_tty) {
            fprintf(stderr, "ds4: CUDA loading model tensors into device cache: 0.00 GiB");
        } else {
            fprintf(stderr, "ds4: CUDA loading model tensors into device cache\n");
        }
    }

    if (cached_bytes < g_model_load_progress_next &&
        now - g_model_load_progress_last < (g_model_load_progress_tty ? 2.0 : 10.0)) {
        return;
    }

    if (g_model_load_progress_tty) {
        fprintf(stderr, "\rds4: CUDA loading model tensors into device cache: %.2f GiB",
                (double)cached_bytes / 1073741824.0);
    } else {
        fprintf(stderr, "ds4: CUDA loading model tensors %.2f GiB cached\n",
                (double)cached_bytes / 1073741824.0);
    }
    fflush(stderr);
    g_model_load_progress_last = now;
    const uint64_t step = (g_model_load_progress_tty ? 2ull : 16ull) *
                          1024ull * 1024ull * 1024ull;
    while (g_model_load_progress_next <= cached_bytes) {
        g_model_load_progress_next += step;
    }
}

static int cuda_model_prefetch_range(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size) {
    if (!model_map || map_size == 0 || map_offset > model_size || map_size > model_size - map_offset) return 0;
    if (getenv("DS4_CUDA_NO_MODEL_PREFETCH") != NULL ||
        getenv("DS4_CUDA_COPY_MODEL") != NULL ||
        getenv("DS4_CUDA_WEIGHT_CACHE") != NULL ||
        getenv("DS4_CUDA_WEIGHT_PRELOAD") != NULL) {
        return 0;
    }

    int device = 0;
    if (cudaGetDevice(&device) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }

    int pageable = 0;
    cudaError_t err = cudaDeviceGetAttribute(&pageable, cudaDevAttrPageableMemoryAccess, device);
    if (err != cudaSuccess || !pageable) {
        (void)cudaGetLastError();
        return 0;
    }
#if CUDART_VERSION >= 13000
    cudaMemLocation loc;
    memset(&loc, 0, sizeof(loc));
    loc.type = cudaMemLocationTypeDevice;
    loc.id = device;
#else
    int loc = device;
#endif

    const long page_sz_l = sysconf(_SC_PAGESIZE);
    const uint64_t page_sz = page_sz_l > 0 ? (uint64_t)page_sz_l : 4096u;
    const uintptr_t host_addr = (uintptr_t)((const char *)model_map + map_offset);
    const uintptr_t pre_addr = host_addr & ~(uintptr_t)(page_sz - 1u);
    const uint64_t pre_delta = (uint64_t)(host_addr - pre_addr);
    const uint64_t pre_bytes = (pre_delta + map_size + page_sz - 1u) & ~(page_sz - 1u);
    void *pre_ptr = (void *)pre_addr;

    const double t0 = cuda_wall_sec();
    err = cudaMemAdvise(pre_ptr, (size_t)pre_bytes, cudaMemAdviseSetReadMostly, loc);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model read-mostly advise skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    err = cudaMemAdvise(pre_ptr, (size_t)pre_bytes, cudaMemAdviseSetPreferredLocation, loc);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model preferred-location advise skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }

    if (!g_model_prefetch_stream) {
        err = cudaStreamCreateWithFlags(&g_model_prefetch_stream, cudaStreamNonBlocking);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model prefetch stream creation skipped: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }

#if CUDART_VERSION >= 13000
    err = cudaMemPrefetchAsync(pre_ptr, (size_t)pre_bytes, loc, 0, g_model_prefetch_stream);
#else
    err = cudaMemPrefetchAsync(pre_ptr, (size_t)pre_bytes, loc, g_model_prefetch_stream);
#endif
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model prefetch skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    if (getenv("DS4_CUDA_MODEL_PREFETCH_SYNC") != NULL) {
        err = cudaStreamSynchronize(g_model_prefetch_stream);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model prefetch sync failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }
    const double t1 = cuda_wall_sec();
    fprintf(stderr,
            "ds4: CUDA ATS/HMM prefetch queued %.2f GiB of model tensors in %.3fs\n",
            (double)map_size / 1073741824.0,
            t1 - t0);
    g_model_hmm_direct = 1;
    return 1;
}

static uint64_t cuda_model_copy_chunk_bytes(void) {
    uint64_t mb = 64;
    const char *env = getenv("DS4_CUDA_MODEL_COPY_CHUNK_MB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(env, &end, 10);
        if (end != env && v > 0) mb = (uint64_t)v;
    }
    if (mb < 16) mb = 16;
    if (mb > 4096) mb = 4096;
    return mb * 1048576ull;
}

static void cuda_model_discard_source_pages(const void *model_map, uint64_t model_size, uint64_t offset, uint64_t bytes) {
#if defined(_WIN32)
    if (getenv("DS4_CUDA_KEEP_MODEL_PAGES") != NULL || !model_map || bytes == 0 || offset > model_size) return;
    if (bytes > model_size - offset) bytes = model_size - offset;
    const uintptr_t base = (uintptr_t)model_map;
    if (offset > UINTPTR_MAX - base || bytes > SIZE_MAX) return;
    (void)ds4_win32_trim_mapped_pages((const void *)(base + (uintptr_t)offset), (size_t)bytes);
#elif defined(POSIX_MADV_DONTNEED)
    if (getenv("DS4_CUDA_KEEP_MODEL_PAGES") != NULL || !model_map || bytes == 0 || offset > model_size) return;
    if (bytes > model_size - offset) bytes = model_size - offset;
    const long page_sz_l = sysconf(_SC_PAGESIZE);
    const uint64_t page_sz = page_sz_l > 0 ? (uint64_t)page_sz_l : 4096u;
    const uintptr_t h0 = (uintptr_t)((const char *)model_map + offset);
    const uintptr_t h1 = h0 + bytes;
    const uintptr_t p0 = h0 & ~(uintptr_t)(page_sz - 1u);
    const uintptr_t p1 = (h1 + page_sz - 1u) & ~(uintptr_t)(page_sz - 1u);
    if (p1 > p0) (void)posix_madvise((void *)p0, (size_t)(p1 - p0), POSIX_MADV_DONTNEED);
#else
    (void)model_map;
    (void)model_size;
    (void)offset;
    (void)bytes;
#endif
}

static void cuda_model_drop_file_pages(uint64_t offset, uint64_t bytes) {
#if defined(POSIX_FADV_DONTNEED)
    if (g_model_fd < 0 || getenv("DS4_CUDA_KEEP_MODEL_PAGES") != NULL || bytes == 0) return;
    (void)posix_fadvise(g_model_fd, (off_t)offset, (off_t)bytes, POSIX_FADV_DONTNEED);
#else
    (void)offset;
    (void)bytes;
#endif
}

static uint64_t cuda_round_down(uint64_t v, uint64_t align) {
    if (align <= 1) return v;
    return (v / align) * align;
}

static uint64_t cuda_round_up(uint64_t v, uint64_t align) {
    if (align <= 1) return v;
    const uint64_t rem = v % align;
    return rem == 0 ? v : v + (align - rem);
}

static void *cuda_align_ptr(void *ptr, uint64_t align) {
    if (align <= 1) return ptr;
    uintptr_t p = (uintptr_t)ptr;
    uintptr_t a = (uintptr_t)align;
    return (void *)(((p + a - 1u) / a) * a);
}

static int cuda_model_stage_pool_alloc(uint64_t bytes) {
    if (g_model_stage_bytes >= bytes) return 1;
    for (size_t i = 0; i < 4; i++) {
        if (g_model_stage_event[i]) {
            (void)cudaEventDestroy(g_model_stage_event[i]);
            g_model_stage_event[i] = NULL;
        }
        if (g_model_stage_raw[i]) {
            (void)cudaFreeHost(g_model_stage_raw[i]);
            g_model_stage_raw[i] = NULL;
            g_model_stage[i] = NULL;
        }
    }
    g_model_stage_bytes = 0;
    if (!g_model_upload_stream) {
        cudaError_t err = cudaStreamCreateWithFlags(&g_model_upload_stream, cudaStreamNonBlocking);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model upload stream creation failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }
    for (size_t i = 0; i < 4; i++) {
        cudaError_t err = cudaMallocHost(&g_model_stage_raw[i], (size_t)bytes);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA pinned model staging allocation failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
        g_model_stage[i] = cuda_align_ptr(g_model_stage_raw[i], g_model_direct_align);
        err = cudaEventCreateWithFlags(&g_model_stage_event[i], cudaEventDisableTiming);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model staging event creation failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }
    g_model_stage_bytes = bytes;
    return 1;
}

static int cuda_pread_full(int fd, void *buf, uint64_t bytes, uint64_t offset) {
    uint64_t done = 0;
    while (done < bytes) {
        const size_t n_req = (bytes - done > (uint64_t)SSIZE_MAX) ? (size_t)SSIZE_MAX : (size_t)(bytes - done);
#if defined(_WIN32)
        const int64_t read_offset = (int64_t)(offset + done);
#else
        const off_t read_offset = (off_t)(offset + done);
#endif
        ssize_t n = pread(fd, (char *)buf + done, n_req, read_offset);
        if (n < 0) {
            if (errno == EINTR) continue;
            return 0;
        }
        if (n == 0) { errno = EIO; return 0; }
        done += (uint64_t)n;
    }
    return 1;
}

static int cuda_model_stage_read_from(int fd, int *direct_fd, uint64_t align,
                                     uint64_t file_size, void *stage, uint64_t stage_bytes,
                                     uint64_t offset, uint64_t bytes, const char **payload) {
    *payload = (const char *)stage;
#if defined(__linux__) && defined(O_DIRECT)
    if (*direct_fd >= 0 && align > 1 && file_size != 0) {
        const uint64_t aligned_off = cuda_round_down(offset, align);
        const uint64_t delta = offset - aligned_off;
        uint64_t read_size = cuda_round_up(delta + bytes, align);
        if (aligned_off <= file_size &&
            read_size <= stage_bytes &&
            read_size <= file_size - aligned_off) {
            const int saved_errno = errno;
            errno = 0;
            if (cuda_pread_full(*direct_fd, stage, read_size, aligned_off)) {
                *payload = (const char *)stage + delta;
                errno = saved_errno;
                return 1;
            }
            const int direct_errno = errno;
            if (direct_errno == EINVAL || direct_errno == EFAULT || direct_errno == ENOTSUP || direct_errno == EOPNOTSUPP) {
                if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                    fprintf(stderr, "ds4: CUDA direct model read disabled: %s\n", strerror(direct_errno));
                }
                (void)close(*direct_fd);
                *direct_fd = -1;
            }
            errno = direct_errno;
        }
    }
#else
    (void)stage_bytes;
    (void)direct_fd; (void)align; (void)file_size;
#endif
    return cuda_pread_full(fd, stage, bytes, offset);
}

static int cuda_model_stage_read(void *stage, uint64_t stage_bytes,
                                 uint64_t offset, uint64_t bytes,
                                 const char **payload) {
    return cuda_model_stage_read_from(g_model_fd, &g_model_direct_fd,
        g_model_direct_align, g_model_file_size, stage, stage_bytes, offset, bytes, payload);
}

static void cuda_stream_selected_stage_release(void) {
    for (size_t i = 0; i < 4; i++) {
        if (g_stream_selected_stage_event[i]) {
            (void)cudaEventDestroy(g_stream_selected_stage_event[i]);
            g_stream_selected_stage_event[i] = NULL;
        }
        if (g_stream_selected_stage_raw[i]) {
            (void)cudaFreeHost(g_stream_selected_stage_raw[i]);
            g_stream_selected_stage_raw[i] = NULL;
            g_stream_selected_stage[i] = NULL;
        }
    }
    g_stream_selected_stage_bytes = 0;
    if (g_stream_selected_upload_stream) {
        (void)cudaStreamDestroy(g_stream_selected_upload_stream);
        g_stream_selected_upload_stream = NULL;
    }
}

static int cuda_stream_selected_stage_pool_alloc(uint64_t bytes) {
    if (g_stream_selected_stage_bytes >= bytes) return 1;
    cuda_stream_selected_stage_release();
    cudaError_t err = cudaStreamCreateWithFlags(
            &g_stream_selected_upload_stream, cudaStreamNonBlocking);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: CUDA streaming selected upload stream creation failed: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    for (size_t i = 0; i < 4; i++) {
        err = cudaMallocHost(&g_stream_selected_stage_raw[i], (size_t)bytes);
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: CUDA streaming selected staging allocation failed: %s\n",
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            cuda_stream_selected_stage_release();
            return 0;
        }
        g_stream_selected_stage[i] = cuda_align_ptr(
                g_stream_selected_stage_raw[i], g_model_direct_align);
        err = cudaEventCreateWithFlags(&g_stream_selected_stage_event[i],
                                       cudaEventDisableTiming);
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: CUDA streaming selected staging event creation failed: %s\n",
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            cuda_stream_selected_stage_release();
            return 0;
        }
    }
    g_stream_selected_stage_bytes = bytes;
    return 1;
}

static int cuda_model_copy_to_device_streamed(
        char *dst,
        const void *model_map,
        uint64_t model_size,
        uint64_t offset,
        uint64_t bytes,
        const char *what,
        uint64_t &chunk_idx) {
    if (!dst || !model_map || offset > model_size ||
        bytes > model_size - offset) {
        return 0;
    }
    if (bytes == 0) return 1;
    if (g_prefill_pipeline_resident_spans) {
        const char *resident =
            cuda_model_resident_range_ptr(model_map, offset, bytes);
        if (resident) {
            return cuda_ok(cuda_decode_profile_resident_memcpy(
                                      dst, resident, (size_t)bytes,
                                      cudaMemcpyDeviceToDevice),
                           what ? what : "R4 resident selected expert copy");
        }
        if (!g_prefill_pipeline_partial_resident_spans) {
            fprintf(stderr,
                    "ds4: CUDA R4 selected expert is outside the resident layer spans for %s\n",
                    what ? what : "expert");
            return 0;
        }
    }
    if (g_model_fd < 0 ||
        (g_model_fd_host_base != NULL && model_map != g_model_fd_host_base)) {
        return cuda_ok(cudaMemcpy(dst,
                                  (const char *)model_map + offset,
                                  (size_t)bytes,
                                  cudaMemcpyHostToDevice),
                       what ? what : "stream selected expert copy");
    }

    const uint64_t chunk = cuda_model_copy_chunk_bytes();
    const uint64_t stage_bytes =
        chunk + (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!cuda_stream_selected_stage_pool_alloc(stage_bytes)) return 0;

    uint64_t copied = 0;
    while (copied < bytes) {
        const uint64_t n = bytes - copied < chunk ? bytes - copied : chunk;
        const uint64_t bi = chunk_idx % 4u;
        cudaError_t err;
        if (chunk_idx >= 4u) {
            /* [merge 2026-08-15] restored from HEAD: profiled helper, not raw cudaEventSynchronize.
             * Upstream's rewrite dropped the decode-profile wait accounting; without it the
             * streaming stall time is invisible to the instrumentation this program relies on. */
            if (!cuda_decode_profile_event_synchronize(
                    g_stream_selected_stage_event[bi],
                    what ? what : "expert staging")) {
                fprintf(stderr,
                        "ds4: CUDA streaming selected staging wait failed for %s\n",
                        what ? what : "expert");
                return 0;
            }
        }
        const char *payload = NULL;
        if (!cuda_model_stage_read(g_stream_selected_stage[bi],
                                   g_stream_selected_stage_bytes,
                                   offset + copied, n, &payload)) {
            fprintf(stderr,
                    "ds4: CUDA streaming selected read failed for %s at %.2f MiB: %s\n",
                    what ? what : "expert", (double)copied / 1048576.0,
                    strerror(errno));
            return 0;
        }
        err = cudaMemcpyAsync(dst + copied, payload, (size_t)n,
                              cudaMemcpyHostToDevice,
                              g_stream_selected_upload_stream);
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: CUDA streaming selected copy failed for %s at %.2f MiB: %s\n",
                    what ? what : "expert", (double)copied / 1048576.0,
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
        err = cudaEventRecord(g_stream_selected_stage_event[bi],
                              g_stream_selected_upload_stream);
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: CUDA streaming selected staging record failed for %s: %s\n",
                    what ? what : "expert", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
        cuda_model_drop_file_pages(offset + copied, n);
        cuda_model_discard_source_pages(model_map, model_size,
                                        offset + copied, n);
        copied += n;
        chunk_idx++;
    }

    if (!cuda_decode_profile_stream_synchronize(
            g_stream_selected_upload_stream,
            what ? what : "expert upload")) {
        fprintf(stderr,
                "ds4: CUDA streaming selected upload sync failed for %s\n",
                what ? what : "expert");
        return 0;
    }
    /* [merge 2026-08-15] restored from HEAD. Upstream omits this, so every byte streamed from SSD
     * went UNCOUNTED - g_decode_profile.ssd_bytes would read 0 and the storage instrumentation
     * this whole program depends on would silently report nothing. */
    if (cuda_decode_profile_enabled()) g_decode_profile.ssd_bytes += bytes;
    return 1;
}

static uint64_t cuda_model_cache_limit_bytes(void) {
    uint64_t gb = 0;
    const char *env = getenv("DS4_CUDA_WEIGHT_CACHE_LIMIT_GB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(env, &end, 10);
        if (end != env) gb = (uint64_t)v;
    }
    if (gb == 0) return UINT64_MAX;
    return gb * 1073741824ull;
}

static uint64_t cuda_model_arena_chunk_bytes(uint64_t need) {
    /* Large tensor/shard ranges rarely fit each other's remaining arena tail.
     * Allocate them directly so cached-byte budgets reflect resident memory. */
    if (need >= 256ull * 1048576ull) return need;
#ifdef _WIN32
    /* WDDM also commits backing for unused arena tails. A 1.75 GiB default
     * retained over a GiB of slack on the 32 GiB host; bound small-range
     * granularity while retaining direct exact allocations for large ranges. */
    uint64_t mb = 64;
#else
    uint64_t mb = 1792;
#endif
    const char *env = getenv("DS4_CUDA_WEIGHT_ARENA_CHUNK_MB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long long v = strtoull(env, &end, 10);
        if (end != env && v > 0) mb = (uint64_t)v;
    }
#ifdef _WIN32
    if (mb < 64) mb = 64;
#else
    if (mb < 256) mb = 256;
#endif
    if (mb > 8192) mb = 8192;
    const uint64_t chunk = mb * 1048576ull;
    return chunk < need ? need : chunk;
}

static char *cuda_model_arena_alloc(uint64_t bytes, const char *what) {
    if (bytes == 0) return NULL;
    if (g_model_cache_full) return NULL;
    const uint64_t align = 256u;
    const uint64_t aligned = (bytes + align - 1u) & ~(align - 1u);

    for (cuda_model_arena &a : g_model_arenas) {
        const uint64_t used = (a.used + align - 1u) & ~(align - 1u);
        if (used <= a.bytes && aligned <= a.bytes - used) {
            char *ptr = a.device_ptr + used;
            a.used = used + aligned;
            return ptr;
        }
    }

    const uint64_t limit = cuda_model_cache_limit_bytes();
    if (g_model_range_bytes > limit || aligned > limit - g_model_range_bytes) return NULL;

    const uint64_t chunk = cuda_model_arena_chunk_bytes(aligned);
    void *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)chunk);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model arena alloc failed for %s (%.2f MiB chunk): %s\n",
                what ? what : "weights",
                (double)chunk / 1048576.0,
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        g_model_cache_full = 1;
        return NULL;
    }
    g_model_arenas.push_back({(char *)dev, chunk, aligned});
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        uint64_t arena_bytes = 0;
        for (const cuda_model_arena &a : g_model_arenas) arena_bytes += a.bytes;
        /* Free VRAM is reported alongside the arena total because the arena total ALONE cannot answer the
         * question it is usually asked for. Measured 2026-08-17: the expert cache sizing saw only
         * 9.40 GiB available on a 32.6 GiB card while the logged accounting (model 0.99 + KV 1.59 +
         * context buffers 2.59) came to ~5.2 GiB, leaving ~14 GiB unaccounted. This arena is unbounded by
         * default - cuda_model_cache_limit_bytes() returns UINT64_MAX unless
         * DS4_CUDA_WEIGHT_CACHE_LIMIT_GB is set - so it is the leading suspect, and pairing each chunk
         * with the free-VRAM figure at that moment settles it by observation instead of by arithmetic.
         * Only runs at chunk granularity (order tens of calls), so the cudaMemGetInfo cost is
         * irrelevant here - unlike a getenv in a per-token path, which cost ~35% of decode once. */
        size_t free_b = 0, total_b = 0;
        if (cudaMemGetInfo(&free_b, &total_b) != cudaSuccess) { free_b = 0; total_b = 0; }
        (void)cudaGetLastError();
        fprintf(stderr,
                "ds4: CUDA model arena allocated %.2f MiB (arenas %.2f GiB, chunks %zu, "
                "free %.2f / %.2f GiB)\n",
                (double)chunk / 1048576.0,
                (double)arena_bytes / 1073741824.0,
                g_model_arenas.size(),
                (double)free_b / 1073741824.0,
                (double)total_b / 1073741824.0);
    }
    return (char *)dev;
}

static const char *cuda_model_range_ptr_from_fd(
        const void *model_map,
        uint64_t offset,
        uint64_t bytes,
        const char *what,
        const char **kind_out) {
    if (g_model_fd < 0 || bytes == 0) return NULL;
    if (g_model_fd_host_base != NULL && model_map != g_model_fd_host_base) return NULL;
    const uint64_t limit = cuda_model_cache_limit_bytes();
    if (g_model_range_bytes > limit || bytes > limit - g_model_range_bytes) {
        if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
            fprintf(stderr, "ds4: CUDA direct %s %.2f MiB (cache budget %.2f GiB exhausted)\n",
                    what ? what : "weights",
                    (double)bytes / 1048576.0,
                    (double)limit / 1073741824.0);
        }
        if (kind_out) *kind_out = "mmap";
        return g_ssd_streaming_mode ? NULL : cuda_model_ptr(model_map, offset);
    }

    char *dev = cuda_model_arena_alloc(bytes, what);
    if (!dev) {
        if (g_ssd_streaming_mode || getenv("DS4_CUDA_STRICT_WEIGHT_CACHE") != NULL) return NULL;
        if (kind_out) *kind_out = "mmap";
        return cuda_model_ptr(model_map, offset);
    }
    cudaError_t err = cudaSuccess;

    const uint64_t chunk = cuda_model_copy_chunk_bytes();
    const uint64_t stage_bytes = chunk + (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!cuda_model_stage_pool_alloc(stage_bytes)) return NULL;

    uint64_t copied = 0;
    uint64_t chunk_idx = 0;
    while (copied < bytes) {
        const uint64_t n = (bytes - copied < chunk) ? (bytes - copied) : chunk;
        const uint64_t bi = chunk_idx % 4u;
        if (chunk_idx >= 4u) {
            err = cudaEventSynchronize(g_model_stage_event[bi]);
            if (err != cudaSuccess) {
                fprintf(stderr, "ds4: CUDA model staging wait failed for %s: %s\n",
                        what ? what : "weights", cudaGetErrorString(err));
                (void)cudaGetLastError();
                return NULL;
            }
        }
        const char *payload = NULL;
        if (!cuda_model_stage_read(g_model_stage[bi], g_model_stage_bytes,
                                   offset + copied, n, &payload)) {
            fprintf(stderr, "ds4: CUDA model range read failed for %s at %.2f MiB: %s\n",
                    what ? what : "weights",
                    (double)copied / 1048576.0,
                    strerror(errno));
            return NULL;
        }
        err = cudaMemcpyAsync(dev + copied, payload, (size_t)n,
                              cudaMemcpyHostToDevice, g_model_upload_stream);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model range copy failed for %s at %.2f MiB: %s\n",
                    what ? what : "weights",
                    (double)copied / 1048576.0,
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            return NULL;
        }
        err = cudaEventRecord(g_model_stage_event[bi], g_model_upload_stream);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model staging record failed for %s: %s\n",
                    what ? what : "weights", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return NULL;
        }
        cuda_model_drop_file_pages(offset + copied, n);
        cuda_model_discard_source_pages(model_map, g_model_registered_size, offset + copied, n);
        copied += n;
        cuda_model_load_progress_note(g_model_range_bytes + copied);
        chunk_idx++;
    }
    err = cudaStreamSynchronize(g_model_upload_stream);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model range upload sync failed for %s: %s\n",
                what ? what : "weights", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return NULL;
    }

    g_model_ranges.push_back({model_map, offset, bytes, dev, NULL, NULL, 0, 0, 1, 0});
    g_model_range_by_offset[offset] = g_model_ranges.size() - 1u;
    g_model_range_bytes += bytes;
    cuda_model_load_progress_note(g_model_range_bytes);
    if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
        fprintf(stderr, "ds4: CUDA fd-cached %s %.2f MiB (total %.2f GiB)\n",
                what ? what : "weights",
                (double)bytes / 1048576.0,
                (double)g_model_range_bytes / 1073741824.0);
    }
    if (kind_out) *kind_out = "fd";
    return (const char *)dev;
}

static int cuda_model_copy_chunked(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size) {
    if (!model_map || model_size == 0 || map_offset > model_size || map_size > model_size - map_offset) return 0;
    if (getenv("DS4_CUDA_NO_MODEL_COPY") != NULL ||
        getenv("DS4_CUDA_DIRECT_MODEL") != NULL ||
        getenv("DS4_CUDA_WEIGHT_CACHE") != NULL ||
        getenv("DS4_CUDA_WEIGHT_PRELOAD") != NULL) {
        return 0;
    }
    if (g_model_device_owned || g_model_registered) return 1;

    void *dev = NULL;
    const double t0 = cuda_wall_sec();
    cudaError_t err = cudaMalloc(&dev, (size_t)model_size);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model allocation skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }

    fprintf(stderr, "ds4: CUDA chunk-copying %.2f GiB model image\n",
            (double)model_size / 1073741824.0);

    const uint64_t chunk = cuda_model_copy_chunk_bytes();
    void *stage = NULL;
    err = cudaMallocHost(&stage, (size_t)chunk);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA pinned model staging allocation failed: %s\n", cudaGetErrorString(err));
        (void)cudaFree(dev);
        (void)cudaGetLastError();
        return 0;
    }

    if (map_offset > 0) {
        uint64_t copied_header = 0;
        while (copied_header < map_offset) {
            const uint64_t n = (map_offset - copied_header < chunk) ? (map_offset - copied_header) : chunk;
            memcpy(stage, (const char *)model_map + copied_header, (size_t)n);
            err = cudaMemcpy((char *)dev + copied_header, stage, (size_t)n, cudaMemcpyHostToDevice);
            if (err != cudaSuccess) {
                fprintf(stderr, "ds4: CUDA model header copy failed: %s\n", cudaGetErrorString(err));
                (void)cudaFreeHost(stage);
                (void)cudaFree(dev);
                (void)cudaGetLastError();
                return 0;
            }
            copied_header += n;
        }
    }

    uint64_t copied = 0;
    double last_report = t0;
    while (copied < map_size) {
        const uint64_t n = (map_size - copied < chunk) ? (map_size - copied) : chunk;
        const uint64_t off = map_offset + copied;
        memcpy(stage, (const char *)model_map + off, (size_t)n);
        err = cudaMemcpy((char *)dev + off, stage, (size_t)n, cudaMemcpyHostToDevice);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model chunk copy failed at %.2f GiB: %s\n",
                    (double)copied / 1073741824.0, cudaGetErrorString(err));
            (void)cudaFreeHost(stage);
            (void)cudaFree(dev);
            (void)cudaGetLastError();
            return 0;
        }
        cuda_model_discard_source_pages(model_map, model_size, off, n);
        copied += n;
        const double now = cuda_wall_sec();
        if (getenv("DS4_CUDA_MODEL_COPY_VERBOSE") != NULL && now - last_report >= 2.0) {
            fprintf(stderr, "ds4: CUDA model chunk copy %.2f/%.2f GiB\n",
                    (double)copied / 1073741824.0,
                    (double)map_size / 1073741824.0);
            last_report = now;
        }
    }

    (void)cudaFreeHost(stage);
    g_model_device_base = (const char *)dev;
    g_model_device_owned = 1;
    g_model_hmm_direct = 0;
    const double t1 = cuda_wall_sec();
    fprintf(stderr,
            "ds4: CUDA model chunk copy complete in %.3fs (%.2f GiB tensors)\n",
            t1 - t0,
            (double)map_size / 1073741824.0);
    return 1;
}

typedef struct {
    uint64_t arena_bytes;
    uint64_t standalone_bytes;
    int cache_full_before;
} cuda_model_range_release_stats;

/* Release the transient model-weight cache and report only allocations whose
 * cudaFree actually succeeded.  Clearing g_model_cache_full is part of the
 * cache lifecycle: an arena OOM means "full for this decode phase", not "never
 * try to cache weights again for the lifetime of the server". */
static cuda_model_range_release_stats cuda_model_range_release_all(bool keep_support = true) {
    cuda_model_range_release_stats stats = {};
    stats.cache_full_before = g_model_cache_full;
    std::vector<cuda_model_range> retained;
    const char *resident=getenv("DS4_CUDA_DSPARK_RESIDENT");
    for (const cuda_model_range &r : g_model_ranges) {
        if (keep_support && resident && !strcmp(resident,"1") &&
            g_support_host_base && r.host_base==g_support_host_base && !r.arena_allocated) {
            retained.push_back(r);continue;
        }
        if (r.host_registered && r.registered_base) {
            (void)cudaHostUnregister(r.registered_base);
        } else if (r.device_ptr && !r.arena_allocated && !r.borrowed) {
            int previous=-1;auto aux=g_dspark_aux_allocations.find(r.device_ptr);
            if(aux!=g_dspark_aux_allocations.end()){(void)cudaGetDevice(&previous);(void)cudaSetDevice(aux->second);}
            cudaError_t released=cudaFree(r.device_ptr);
            if(previous>=0)(void)cudaSetDevice(previous);
            if(aux!=g_dspark_aux_allocations.end())g_dspark_aux_allocations.erase(aux);
            if (released == cudaSuccess) {
                stats.standalone_bytes += r.bytes;
            } else {
                (void)cudaGetLastError();
            }
        }
    }
    for (const cuda_model_arena &a : g_model_arenas) {
        if (a.device_ptr) {
            if (cudaFree(a.device_ptr) == cudaSuccess) {
                stats.arena_bytes += a.bytes;
            } else {
                (void)cudaGetLastError();
            }
        }
    }
    g_model_arenas.clear();
    g_model_ranges.clear();
    g_model_range_by_offset.clear();
    g_model_range_bytes = 0;
    for (const cuda_model_range &r:retained) {
        g_model_range_by_offset[r.offset]=g_model_ranges.size();
        g_model_ranges.push_back(r);if(!g_dspark_aux_allocations.count(r.device_ptr))g_model_range_bytes+=r.bytes;
    }
    g_model_cache_full = 0;
    cuda_model_load_progress_reset();
    return stats;
}

static void cuda_derived_range_release_all(void) {
    ds4_mmq_set_aligned_q81_scratch(NULL, 0);
    if (g_aligned_q81_scratch) {
        (void)cudaFree(g_aligned_q81_scratch);
        g_aligned_q81_scratch = NULL;
    }
    for (const cuda_derived_range &r : g_derived_ranges) {
        if (r.device_ptr) (void)cudaFree(r.device_ptr);
    }
    g_derived_ranges.clear();
    g_derived_replace_map = NULL;
    g_derived_artifact_bytes = 0;
    g_derived_artifact_build_secs = 0.0;
    g_derived_replaces_complete = 0;
}

/* Kept from this port: upstream dropped cuda_model_load_progress_finish() when it reworked the
 * loader-progress helpers, but every path in this port that finishes -- or aborts -- a weight-cache
 * fill still calls it to terminate the in-place TTY progress line. Without it the streaming loader,
 * the derived-artifact builder and the SSD streaming entry points all leave a dangling line (and the
 * translation unit does not link). It only touches progress state that upstream's helpers still
 * declare, so it slots in beside upstream's reset()/note() unchanged. */
static void cuda_model_load_progress_finish(void) {
    if (!g_model_load_progress_started) return;
    if (g_model_load_progress_tty) {
        fputc('\n', stderr);
        fflush(stderr);
    }
    g_model_load_progress_started = 0;
}

static void cuda_stream_expert_cache_release(cuda_stream_expert_cache *cache) {
    if (!cache) return;
    if (cache->vmm) {
        (void)cudaDeviceSynchronize();
        for (int i = 0; i < 3; i++) cuda_vmm_free(&cache->vm[i]);
        cache->vmm = 0;
        cache->gate_ptr = cache->up_ptr = cache->down_ptr = NULL;
    }
    if (cache->gate_ptr) {
        (void)cudaFree(cache->gate_ptr);
    }
    if (cache->up_ptr) {
        (void)cudaFree(cache->up_ptr);
    }
    if (cache->down_ptr) {
        (void)cudaFree(cache->down_ptr);
    }
    cache->slots.clear();
    cache->valid = 0;
    cache->capacity = 0;
    cache->count = 0;
    cache->tick = 0;
    cache->gate_expert_bytes = 0;
    cache->down_expert_bytes = 0;
    cache->gate_ptr = NULL;
    cache->up_ptr = NULL;
    cache->down_ptr = NULL;
    cache->gate_capacity = 0;
    cache->up_capacity = 0;
    cache->down_capacity = 0;
    cache->rank_worst_valid = 0;
    cache->rank_worst_slot = 0;
    cache->rank_worst_value = 0;
}

static void cuda_stream_expert_cache_release_all(void) {
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        cuda_stream_expert_cache_release(&g_stream_expert_caches[i]);
        g_stream_expert_caches[i].runtime_cap = 0;
        g_stream_expert_caches[i].memory_cap_notice = 0;
    }
}

static void cuda_stream_expert_cache_invalidate(
        cuda_stream_expert_cache *cache) {
    cuda_stream_expert_cache_release(cache);
}

static uint32_t cuda_stream_expert_cache_requested_budget(void) {
    uint32_t cap = g_stream_expert_budget_override != 0 ?
        g_stream_expert_budget_override : DS4_CUDA_STREAM_EXPERT_DEFAULT;
    const char *env = getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_N");
    if (env && env[0]) {
        char *end = NULL;
        errno = 0;
        unsigned long v = strtoul(env, &end, 10);
        while (end && (*end == ' ' || *end == '\t')) end++;
        if (end != env && errno == 0 && end && *end == '\0') {
            cap = v > DS4_CUDA_STREAM_EXPERT_MAX ?
                DS4_CUDA_STREAM_EXPERT_MAX : (uint32_t)v;
        }
    }
    if (cap > DS4_CUDA_STREAM_EXPERT_MAX) {
        cap = DS4_CUDA_STREAM_EXPERT_MAX;
    }
    return cap;
}

static uint32_t cuda_stream_expert_cache_configured_budget(void) {
    return cuda_stream_expert_cache_requested_budget();
}

static int cuda_stream_expert_cache_budget_visible_to_shared(void) {
    if (!g_ssd_streaming_mode) return 0;
    if (g_stream_expert_budget_override != 0) return 1;
    const char *env = getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_N");
    if (env && env[0]) return 1;
    env = getenv("DS4_CUDA_ENABLE_STREAMING_EXPERT_HOTLIST");
    if (!env || !env[0]) {
        env = getenv("DS4_CUDA_STREAMING_EXPERT_HOTLIST");
    }
    return env && env[0] && strcmp(env, "0") != 0;
}

/* [2026-08-18] The denominator of the primary/tail expert-cache class split: the tail class gets
 * 1/denom of the aggregate byte budget and the primary gets the rest. Read in TWO places that must
 * agree - the class budget (what the tail may claim) and the live-budget holdback (what the primary
 * must leave) - so it lives here rather than being parsed twice. Default 8 is the historical value
 * and is byte-for-byte unchanged. */
static uint64_t cuda_stream_expert_cache_class_denom(void) {
    static uint64_t cached = 0;
    if (cached != 0) return cached;
    cached = 8ull;
    const char *env = getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_CLASS_DENOM");
    if (env && env[0]) {
        char *end = NULL;
        errno = 0;
        unsigned long long v = strtoull(env, &end, 10);
        while (end && (*end == ' ' || *end == '\t')) end++;
        if (end != env && errno == 0 && end && *end == '\0' && v >= 2ull && v <= 64ull) {
            cached = (uint64_t)v;
        } else {
            fprintf(stderr,
                    "ds4: ignoring DS4_CUDA_STREAMING_EXPERT_CACHE_CLASS_DENOM='%s' "
                    "(want an integer 2..64); using 8\n",
                    env);
        }
    }
    return cached;
}

static uint64_t cuda_stream_expert_cache_reserve_bytes(void) {
    /* 8 GiB, not 16.
     *
     * Swept on a clean 5090 (32607 MiB free before AND after every run) with per-class caches and the
     * batched prefetch in place, DSV4-Flash 0731, identical prompt and -n:
     *     reserve 16 GiB (old default) -> 4.21 t/s
     *     reserve 12 GiB               -> 4.66
     *     reserve  8 GiB               -> 4.76   <-- best
     *     reserve  4 GiB               -> 4.28
     *
     * The curve has an interior optimum, and the logs say why: at 8 GiB the primary class's 7/8 share
     * is small enough to leave the Q4 tail class room (it allocates 216 experts against 3.36 GiB
     * available), while at 4 GiB the LARGER usable pool makes the primary's share bigger, it swallows
     * the card, and the tail reports "available 0.00 GiB" and runs off SSD. A parallel tail-share
     * sweep peaks at the same 4.76 (reserve 4 + tail 1/4), confirming the mechanism is expert-class
     * residency rather than the reserve number itself.
     *
     * The old 16 GiB default predates per-size-class caches, when a bigger cache thrashed and a large
     * reserve looked protective. That is no longer true. */
    uint64_t gb = 8;
    const char *env = getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_RESERVE_GB");
    if (env && env[0]) {
        char *end = NULL;
        errno = 0;
        unsigned long long v = strtoull(env, &end, 10);
        while (end && (*end == ' ' || *end == '\t')) end++;
        if (end != env && errno == 0 && end && *end == '\0') {
            gb = (uint64_t)v;
        }
    }
    if (gb > UINT64_MAX / 1073741824ull) return UINT64_MAX;
    return gb * 1073741824ull;
}

/* Defined below, next to the class-index logic it belongs with. */
static int cuda_stream_expert_cache_class_isolation_enabled(void);

static uint32_t cuda_stream_expert_cache_live_budget(
        cuda_stream_expert_cache *cache,
        uint32_t requested,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        uint64_t reclaim_bytes,
        int report) {
    if (requested == 0 ||
        gate_expert_bytes == 0 ||
        down_expert_bytes == 0 ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        return 0;
    }
    const uint64_t per_expert_bytes =
        gate_expert_bytes * 2ull + down_expert_bytes;
    if (per_expert_bytes == 0) return 0;

    size_t free_b = 0;
    size_t total_b = 0;
    cudaError_t err = cudaMemGetInfo(&free_b, &total_b);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: CUDA streaming expert cache memory query failed: %s; "
                "using direct selected loads\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }

    uint64_t free_bytes = (uint64_t)free_b;
    if (reclaim_bytes > UINT64_MAX - free_bytes) {
        free_bytes = UINT64_MAX;
    } else {
        free_bytes += reclaim_bytes;
    }
    uint64_t reserve = cuda_stream_expert_cache_reserve_bytes();
    const uint64_t total_bytes = (uint64_t)total_b;
    if (total_bytes != 0 && reserve > total_bytes / 2ull) {
        reserve = total_bytes / 2ull;
    }

    /* Charge the reserve ONCE, not once per size class.
     *
     * The reserve protects non-cache VRAM (context buffers, activations) from the expert cache. The
     * primary class already honours it in full and additionally holds back the tail share below, so
     * by the time a secondary class asks, the reserve is already physically protected. Charging the
     * full reserve a second time made the tail class fail its own gate on the leftovers and fall
     * back to SSD entirely -- measured as
     *     tail 1/8 -> "available 0.00 GiB <= reserve 4.00 GiB"
     *     tail 1/4 -> "available 2.71 GiB <= reserve 4.00 GiB"
     * i.e. the hold-back was working (0.00 -> 2.71 GiB survived) yet the doubled reserve still
     * rejected it. A secondary class only needs a small floor of its own. */
    if (cuda_stream_expert_cache_class_isolation_enabled() &&
        cache != &g_stream_expert_caches[0] &&
        g_stream_expert_caches[0].valid) {
        const uint64_t tail_floor = 512ull * 1048576ull;
        if (reserve > tail_floor) reserve = tail_floor;
    }
    if (free_bytes <= reserve) {
        if (report && cache && cache->memory_cap_notice != requested) {
            cuda_model_load_progress_finish();
            fprintf(stderr,
                    "ds4: CUDA streaming expert cache disabled: available %.2f GiB <= reserve %.2f GiB\n",
                    (double)free_bytes / 1073741824.0,
                    (double)reserve / 1073741824.0);
            cache->memory_cap_notice = requested;
        }
        return 0;
    }

    uint64_t usable = free_bytes - reserve;

    /* Hold back room for the OTHER size class.
     *
     * The class budget below already splits the aggregate byte budget 7/8 to the dominant class and
     * 1/8 to the boosted/Q4 tail, but that split is advisory: whichever class allocates FIRST calls
     * cudaMemGetInfo and can physically consume everything the reserve does not protect. Measured on
     * DSV4-Flash 0731 with isolation on, the secondary class then reported
     *     "streaming expert cache disabled: available 0.00 GiB <= reserve 4.00 GiB"
     * and ran entirely off SSD -- so the class the quantizer spent extra bits on got no VRAM at all.
     *
     * Reserving the tail share here makes the split real. Tunable because the ideal share depends on
     * how hot the boosted class actually is; 1/8 matches the existing budget split. */
    if (cuda_stream_expert_cache_class_isolation_enabled() &&
        cache == &g_stream_expert_caches[0] &&
        !g_stream_expert_caches[1].valid) {
        /* [2026-08-18] DEFAULT TO THE CLASS SPLIT, not a second independent 8. These two denominators
         * describe the same intent from opposite sides: the class budget decides how many bytes the
         * tail class may CLAIM, and this holdback decides how many bytes the primary class must LEAVE.
         * When they disagree the tail claim is unfunded, and because a secondary class only carries a
         * 512 MiB floor (see above) rather than the full reserve, it spends the model arena's
         * protection instead.
         *
         * MEASURED: CLASS_DENOM=4 with this hardcoded at 8 grew class 1 exactly as intended,
         * 233 -> 466 experts / 3.07 -> 6.14 GiB, while class 0 did NOT shrink (10.09 GiB, unchanged -
         * it is capped by free VRAM, well under its own 3/4 share). The extra ~3 GiB came out of the
         * reserve and the run died the same way reserve=5 does:
         *     ds4: CUDA model arena alloc failed for q8_0 (1792.00 MiB chunk): out of memory
         *     ds4: CUDA rope_tail launch failed: an illegal memory access was encountered
         * Tracking the class split makes the tail's claim funded by construction. */
        uint64_t denom = cuda_stream_expert_cache_class_denom();
        const char *env = getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_TAIL_DENOM");
        if (env && env[0]) {
            char *end = NULL;
            errno = 0;
            unsigned long long v = strtoull(env, &end, 10);
            while (end && (*end == ' ' || *end == '\t')) end++;
            if (end != env && errno == 0 && end && *end == '\0' && v >= 2ull) {
                denom = (uint64_t)v;
            }
        }
        const uint64_t holdback = usable / denom;
        usable -= holdback;
    }

    uint64_t max_slots64 = usable / per_expert_bytes;
    if (max_slots64 > UINT32_MAX) max_slots64 = UINT32_MAX;
    uint32_t capped = requested;
    if ((uint64_t)capped > max_slots64) capped = (uint32_t)max_slots64;
    if (report && capped != requested && cache &&
        cache->memory_cap_notice != capped) {
        cuda_model_load_progress_finish();
        fprintf(stderr,
                "ds4: CUDA streaming expert cache capped from %u to %u experts "
                "(available %.2f GiB, reserve %.2f GiB, %.2f MiB/expert)\n",
                requested,
                capped,
                (double)free_bytes / 1073741824.0,
                (double)reserve / 1073741824.0,
                (double)per_expert_bytes / 1048576.0);
        cache->memory_cap_notice = capped;
    }
    return capped;
}

static uint64_t cuda_stream_expert_cache_expert_bytes(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (gate_expert_bytes == 0 ||
        down_expert_bytes == 0 ||
        gate_expert_bytes > (UINT64_MAX - down_expert_bytes) / 2ull) {
        return 0;
    }
    return gate_expert_bytes * 2ull + down_expert_bytes;
}

/* Per-size-class expert caches are ON by default.
 *
 * Measured on DSV4-Flash 0731 (mixed quant: Q4K experts on layers 37-42, IQ2XXS/Q2K elsewhere, so
 * two shapes at 13.50 and 6.75 MiB/expert) on a 5090 streaming from D:, 64-token runs:
 *
 *     isolation off -> 1.05 t/s decode, 125 whole-cache re-caps in one run
 *     isolation on  -> 2.47 t/s decode, 0 re-caps                      == 2.35x
 *
 * With one shared cache the two shapes alternate within every token and ds4_cuda.cu's !same_dims
 * path frees the entire cache and refills it from disk each flip -- which is also why decode got
 * monotonically SLOWER as the cache grew (1.51 t/s at 3.9 GiB down to 1.06 t/s at 15.8 GiB).
 * Defaulting this off meant the shipped configuration could not satisfy the residency invariant
 * asserted a few lines below. Set DS4_CUDA_STREAMING_EXPERT_CACHE_CLASS_ISOLATION=0 to restore the
 * old shared-cache behaviour. */
static int cuda_stream_expert_cache_class_isolation_enabled(void) {
    const char *env =
        getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_CLASS_ISOLATION");
    if (env && env[0]) return strcmp(env, "0") != 0;
    return 1;
}

static uint32_t cuda_stream_expert_cache_class_index(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    const int isolated = cuda_stream_expert_cache_class_isolation_enabled();
    if (!isolated || g_stream_expert_primary_bytes == 0) return 0u;
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        const cuda_stream_expert_cache *cache = &g_stream_expert_caches[i];
        if (cache->valid &&
            cache->gate_expert_bytes == gate_expert_bytes &&
            cache->down_expert_bytes == down_expert_bytes) {
            return i;
        }
    }
    const uint64_t expert_bytes =
        cuda_stream_expert_cache_expert_bytes(gate_expert_bytes,
                                              down_expert_bytes);
    if (g_stream_expert_primary_bytes != 0 &&
        expert_bytes != g_stream_expert_primary_bytes) {
        return 1u;
    }
    /* Equal aggregate bytes are not sufficient proof of equal layout. Keep a
     * different gate/down signature out of an already-resident primary slab. */
    const cuda_stream_expert_cache *primary = &g_stream_expert_caches[0];
    return primary->valid &&
           (primary->gate_expert_bytes != gate_expert_bytes ||
            primary->down_expert_bytes != down_expert_bytes) ? 1u : 0u;
}

/* DS4COMBO growable context: byte ceiling on the whole VRAM expert tier,
 * lowered as context VRAM is mapped and raised as it is unmapped.
 * UINT64_MAX = no ceiling (fixed-context behaviour). */
static uint64_t g_stream_expert_ctx_ceiling_bytes = UINT64_MAX;
static int g_stream_expert_ctx_vmm;
/* Tier bytes the fixed full-ctx plan holds: the live free-VRAM reserve may
 * not cap the primary class below this (the fixed build is never capped). */
static uint64_t g_stream_expert_ctx_floor_bytes;

static uint32_t cuda_stream_expert_cache_class_budget(
        uint32_t class_index,
        uint64_t expert_bytes,
        bool apply_ctx_ceiling = true) {
    const uint32_t requested = cuda_stream_expert_cache_requested_budget();
    if (requested == 0 || expert_bytes == 0) return 0;
    const uint64_t primary_bytes =
        g_stream_expert_primary_bytes != 0 ?
            g_stream_expert_primary_bytes : expert_bytes;
    if ((uint64_t)requested > UINT64_MAX / primary_bytes) return 0;
    uint64_t total_bytes = (uint64_t)requested * primary_bytes;
    const int ceiling_on = apply_ctx_ceiling && g_stream_expert_ctx_ceiling_bytes != UINT64_MAX;
    if (g_stream_expert_cache_edge_vram_enabled &&
        g_stream_expert_cache_phase_decode &&
        g_stream_expert_cache_physical_budget_bytes != 0 &&
        total_bytes > g_stream_expert_cache_physical_budget_bytes) {
        if (!g_stream_expert_cache_physical_clamp_notice) {
            fprintf(stderr,
                    "ds4: CUDA expert cache request physically clamped from %.2f to %.2f GiB "
                    "at decode edge\n",
                    (double)total_bytes / 1073741824.0,
                    (double)g_stream_expert_cache_physical_budget_bytes / 1073741824.0);
            g_stream_expert_cache_physical_clamp_notice = 1;
        }
        total_bytes = g_stream_expert_cache_physical_budget_bytes;
    }
    const int isolated = cuda_stream_expert_cache_class_isolation_enabled();
    if (!isolated || g_stream_expert_primary_bytes == 0) {
        if (ceiling_on && total_bytes > g_stream_expert_ctx_ceiling_bytes)
            total_bytes = g_stream_expert_ctx_ceiling_bytes;
        uint64_t slots = total_bytes / expert_bytes;
        if (slots > requested) slots = requested;
        if (slots > DS4_CUDA_STREAM_EXPERT_MAX) {
            slots = DS4_CUDA_STREAM_EXPERT_MAX;
        }
        return (uint32_t)slots;
    }
    /* Keep the dominant low-bit class resident while reserving enough room
     * for the larger boosted/Q4 tail. Both shares remain inside the original
     * aggregate byte budget derived by ds4.c from --ssd-streaming-cache-gb.
     *
     * [2026-08-18] THE 1/8 IS THE THING THAT PINS THE Q4 TAIL, and it had no knob. Measured: class 1
     * allocates exactly 233 experts / 3.07 GiB in every configuration tried today - reserves 6/7/8/
     * 9/10/12, a 2 GB DirectStorage arena, both cache modes, and every TAIL_DENOM value. It is 15%
     * residency over the 1536 Q4 experts while the primary class runs at 43%.
     *
     * DS4_CUDA_STREAMING_EXPERT_CACHE_TAIL_DENOM does NOT move it - that one only sizes the
     * free-VRAM holdback in the live-budget path. Measured at denom 4 and 3: class 0 shrinks
     * 10.09 -> 8.67 -> 8.50 GiB while class 1 stays at 3.07, i.e. the holdback takes VRAM from the
     * primary class and hands it to nobody, costing 12.23 -> 12.19 -> 11.80 t/s. Two separate
     * eighths, and only this one caps the tail.
     *
     * Default 8 keeps existing behaviour byte-for-byte. */
    const uint64_t class_denom = cuda_stream_expert_cache_class_denom();
    uint64_t class_bytes = class_index == 0 ?
        total_bytes - total_bytes / class_denom : total_bytes / class_denom;
    if (ceiling_on) {
        /* The ceiling bounds the whole tier: this class gets what the other
         * classes do not hold, after (not before) the class split. */
        uint64_t other = 0;
        for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
            const cuda_stream_expert_cache &c = g_stream_expert_caches[i];
            if (i != class_index && c.valid)
                other += (uint64_t)c.capacity * (2u * c.gate_expert_bytes + c.down_expert_bytes);
        }
        const uint64_t avail = g_stream_expert_ctx_ceiling_bytes > other ?
            g_stream_expert_ctx_ceiling_bytes - other : 0;
        if (class_bytes > avail) class_bytes = avail;
    }
    uint64_t slots = class_bytes / expert_bytes;
    if (slots > DS4_CUDA_STREAM_EXPERT_MAX) slots = DS4_CUDA_STREAM_EXPERT_MAX;
    return (uint32_t)slots;
}

static uint32_t cuda_stream_expert_cache_shrunken_cap(uint32_t cap) {
    if (cap == 0) return 0;
    const uint32_t release = (cap + 9u) / 10u;
    return cap > release ? cap - release : 0;
}

static void cuda_stream_expert_cache_note_oom_cap(
        cuda_stream_expert_cache *cache,
        uint32_t failed_cap,
        uint32_t new_cap,
        uint64_t expert_bytes,
        const char *errstr) {
    if (!cache) return;
    if (cache->runtime_cap != 0 && cache->runtime_cap <= new_cap) {
        return;
    }
    cache->runtime_cap = new_cap;
    const uint32_t released =
        failed_cap > new_cap ? failed_cap - new_cap : 0;
    cuda_model_load_progress_finish();
    fprintf(stderr,
            "ds4: CUDA streaming expert cache allocation failed at %u experts "
            "/ %.2f GiB%s%s\n",
            failed_cap,
            expert_bytes != 0 ?
                (double)((uint64_t)failed_cap * expert_bytes) / 1073741824.0 :
                0.0,
            errstr && errstr[0] ? ": " : "",
            errstr && errstr[0] ? errstr : "");
    if (new_cap != 0) {
        fprintf(stderr,
                "ds4:   shrinking resident cache margin by %u experts / %.2f GiB; "
                "runtime cache cap now %u experts\n",
                released,
                expert_bytes != 0 ?
                    (double)((uint64_t)released * expert_bytes) / 1073741824.0 :
                    0.0,
                new_cap);
    } else {
        fprintf(stderr,
                "ds4:   disabling resident expert cache after OOM; using direct selected loads\n");
    }
}

static int cuda_stream_expert_cache_try_alloc(
        uint32_t cap,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        char **gate_ptr,
        char **up_ptr,
        char **down_ptr,
        const char **errstr) {
    *gate_ptr = NULL;
    *up_ptr = NULL;
    *down_ptr = NULL;
    if (errstr) *errstr = NULL;
    if (cap == 0 ||
        (uint64_t)cap > UINT64_MAX / gate_expert_bytes ||
        (uint64_t)cap > UINT64_MAX / down_expert_bytes) {
        return 0;
    }
    const uint64_t gate_bytes = (uint64_t)cap * gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)cap * down_expert_bytes;

    void *gate = NULL;
    void *up = NULL;
    void *down = NULL;
    cudaError_t err = cudaMalloc(&gate, (size_t)gate_bytes);
    if (err != cudaSuccess) goto fail;
    err = cudaMalloc(&up, (size_t)gate_bytes);
    if (err != cudaSuccess) goto fail;
    err = cudaMalloc(&down, (size_t)down_bytes);
    if (err != cudaSuccess) goto fail;

    *gate_ptr = (char *)gate;
    *up_ptr = (char *)up;
    *down_ptr = (char *)down;
    return 1;

fail:
    if (errstr) *errstr = cudaGetErrorString(err);
    (void)cudaGetLastError();
    if (gate) (void)cudaFree(gate);
    if (up) (void)cudaFree(up);
    if (down) (void)cudaFree(down);
    return 0;
}

/* cuda_stream_selected_stage_release(), cuda_stream_selected_stage_pool_alloc() and
 * cuda_stream_selected_ensure_bytes() used to be defined here. Upstream now carries its own copies
 * -- the first two just above this block, cuda_stream_selected_ensure_bytes() further down with the
 * selected-expert table -- so the duplicates were dropped rather than merged. Only this forward
 * declaration survives, because the streaming selected-expert cache below calls
 * cuda_stream_selected_ensure_bytes() long before upstream's definition appears. */
static int cuda_stream_selected_ensure_bytes(
        char **ptr, uint64_t *capacity, uint64_t bytes, const char *label);

static int cuda_stream_selected_ensure_i32(
        int32_t **ptr,
        uint64_t *capacity,
        uint64_t count,
        const char *what) {
    if (count == 0 || count > UINT64_MAX / sizeof(int32_t)) return 0;
    const uint64_t bytes = count * sizeof(int32_t);
    if (*ptr && *capacity >= bytes) return 1;
    if (*ptr) {
        (void)cudaFree(*ptr);
        *ptr = NULL;
        *capacity = 0;
    }
    void *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)bytes);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: CUDA streaming selected cache allocation failed for %s (%u entries): %s\n",
                what ? what : "selected slots",
                (unsigned)count,
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    *ptr = (int32_t *)dev;
    *capacity = bytes;
    return 1;
}

static uint32_t cuda_stream_expert_cache_vmm_grow(cuda_stream_expert_cache *c, uint32_t cap);

/* DS4COMBO growable context: reserve the tier's uncapped budget as virtual
 * space and back only `cap` slots, so later ceiling changes resize in place. */
static int cuda_stream_expert_cache_vmm_alloc(
        cuda_stream_expert_cache *cache,
        uint32_t cap,
        uint32_t reserve_cap,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        char **gate_ptr,
        char **up_ptr,
        char **down_ptr,
        const char **errstr) {
    *gate_ptr = *up_ptr = *down_ptr = NULL;
    if (errstr) *errstr = NULL;
    if (reserve_cap < cap) reserve_cap = cap;
    const uint64_t per[3] = {gate_expert_bytes, gate_expert_bytes, down_expert_bytes};
    int ok = cap != 0;
    for (int i = 0; ok && i < 3; i++) {
        ok = cuda_vmm_reserve(&cache->vm[i], (uint64_t)reserve_cap * per[i], 16ull << 20) &&
             cuda_vmm_resize(&cache->vm[i], (uint64_t)cap * per[i], 0);
    }
    if (!ok) {
        (void)cudaDeviceSynchronize();
        for (int i = 0; i < 3; i++) cuda_vmm_free(&cache->vm[i]);
        if (errstr) *errstr = "VMM map failed (out of memory)";
        return 0;
    }
    cache->vmm = 1;
    *gate_ptr = (char *)(uintptr_t)cache->vm[0].base;
    *up_ptr = (char *)(uintptr_t)cache->vm[1].base;
    *down_ptr = (char *)(uintptr_t)cache->vm[2].base;
    return 1;
}

static cuda_stream_expert_cache *cuda_stream_expert_cache_prepare(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        uint32_t target_cap) {
    if (g_stream_prefill_borrow_slots) {
        /* The borrow holds this memory; the tier comes back after
         * ds4_gpu_stream_prefill_borrow_end(). Refuse (logged once) instead of
         * allocating past the live reserve (the fixed-plan floor would); every
         * caller treats NULL as no VRAM tier for this request. */
        if (!g_stream_prefill_borrow_notice) {
            g_stream_prefill_borrow_notice = 1;
            fprintf(stderr, "DS4COMBO_PREFILL_BORROW_REFUSED decode expert tier requested while a layer "
                            "sweep borrows its memory (loader slots %u); not allocated, the caller proceeds uncached\n",
                    g_stream_prefill_borrow_slots);
        }
        return NULL;
    }
    /* R1: prefill streams full layers and cannot consume per-token residency.
     * Do not immediately recreate a cache that the prefill edge just evicted. */
    if (g_stream_expert_cache_edge_vram_enabled &&
        !g_stream_expert_cache_phase_decode) {
        return NULL;
    }
    const uint64_t expert_bytes =
        cuda_stream_expert_cache_expert_bytes(gate_expert_bytes,
                                              down_expert_bytes);
    if (expert_bytes == 0) return NULL;
    const uint32_t class_index =
        cuda_stream_expert_cache_class_index(gate_expert_bytes,
                                             down_expert_bytes);
    cuda_stream_expert_cache *cache = &g_stream_expert_caches[class_index];
    uint32_t requested_cap =
        cuda_stream_expert_cache_class_budget(class_index, expert_bytes);
    if (cache->runtime_cap != 0 && requested_cap > cache->runtime_cap) {
        requested_cap = cache->runtime_cap;
    }
    if (requested_cap == 0) return NULL;
    if (target_cap == 0 || target_cap > requested_cap) target_cap = requested_cap;
    if (target_cap == 0) return NULL;
    const int same_dims =
        cache->valid &&
        cache->gate_expert_bytes == gate_expert_bytes &&
        cache->down_expert_bytes == down_expert_bytes;
    if (!same_dims && cache->valid) {
        /* A secondary shape may replace another secondary shape, but it must
         * never invalidate the primary IQ2/Q2 residency class (or vice versa). */
        cuda_stream_expert_cache_release(cache);
        cache->runtime_cap = 0;
        cache->memory_cap_notice = 0;
    }
    if (same_dims &&
        cache->capacity != 0 &&
        cache->capacity >= target_cap &&
        cache->slots.size() == cache->capacity) {
        return cache;
    }

    uint64_t reclaim_bytes = 0;
    if (same_dims &&
        cache->capacity != 0 &&
        (uint64_t)cache->capacity <= UINT64_MAX / expert_bytes) {
        reclaim_bytes = (uint64_t)cache->capacity * expert_bytes;
    }
    uint32_t cap =
        cuda_stream_expert_cache_live_budget(cache,
                                             target_cap,
                                             gate_expert_bytes,
                                             down_expert_bytes,
                                             reclaim_bytes,
                                             reclaim_bytes == 0);
    if (g_stream_expert_ctx_floor_bytes != 0 && cache == &g_stream_expert_caches[0]) {
        uint64_t floor_n = g_stream_expert_ctx_floor_bytes / expert_bytes;
        if (floor_n > target_cap) floor_n = target_cap;
        if (cap < floor_n) {
            fprintf(stderr, "ds4: CUDA expert cache class 0 kept at the fixed-plan floor of %u experts "
                            "(live reserve would cap it at %u)\n", (unsigned)floor_n, cap);
            cap = (uint32_t)floor_n;
        }
    }
    if (cap == 0) {
        /* [2026-08-18] KEEP WHAT WE ALREADY HAVE. A zero live budget means the cache cannot GROW; it
         * has never meant the existing allocation became unusable. Returning NULL here threw that
         * allocation away and made the caller bypass VRAM for every expert, for the rest of the run.
         *
         * MEASURED: at RESERVE_GB=10 the primary class had already allocated 1266 experts / 8.35 GiB
         * when this fired. All 8.35 GiB stayed resident and went completely unused - decode 7.19 t/s
         * against 12.23 with the cache live, and DirectStorage re-read 217.7 GiB against 110.7 to
         * fetch experts that were already sitting in VRAM.
         *
         * This is what made decode BIMODAL rather than degrading. Three runs that reach the zero
         * budget by unrelated routes (a 2 GB DirectStorage arena; reserves of 10 and 12) land within
         * 1.8% of each other at 7.08-7.21 t/s, while every run whose cache survived sits at
         * 11.02-12.23. An all-or-nothing gate on a cache that was already 80% built turns a shortfall
         * into a cliff. Degrade instead: serve from the capacity we hold. */
        if (same_dims &&
            cache->valid &&
            cache->capacity != 0 &&
            cache->slots.size() == cache->capacity) {
            if (cache->budget_zero_notice != target_cap) {
                cache->budget_zero_notice = target_cap;
                size_t free_b = 0, total_b = 0;
                cudaMemGetInfo(&free_b, &total_b);
                fprintf(stderr,
                        "ds4: CUDA expert cache class %d cannot grow to %u experts "
                        "(free %.2f GiB <= reserve %.2f GiB) - KEEPING the %u experts it holds. "
                        "Lookups continue against the existing cache.\n",
                        (int)(cache - &g_stream_expert_caches[0]),
                        target_cap,
                        (double)free_b / 1073741824.0,
                        (double)cuda_stream_expert_cache_reserve_bytes() / 1073741824.0,
                        cache->capacity);
            }
            return cache;
        }
        /* Nothing allocated yet - this one really is a disable, and it is the case worth shouting
         * about, because the caller will bypass VRAM entirely.
         *
         * SAY SO. This return is how the expert cache SWITCHES ITSELF OFF, and until now
         * it did it in silence: the live-budget call above suppresses reporting whenever an existing
         * allocation is reclaimable (reclaim_bytes != 0), so a zero result produced no "capped" or
         * "disabled" line anywhere in the log. The caller then sets expert_cache_disabled and every
         * subsequent expert access skips the VRAM lookup entirely.
         *
         * MEASURED CONSEQUENCE, and it cost a day to find: with a 2048 MiB DirectStorage arena, or at
         * ctx 262144, free VRAM falls to the 8 GiB reserve, this fires, and decode drops 11.4 -> 6.8
         * t/s while the LOOKUP COUNT COLLAPSES from ~281k to ~40k. The 40k survivors are the 6 Q4_K
         * layers in cache class 1 (512 MiB floor, vs the primary's 8 GiB), so the REPORTED hit rate
         * even goes UP - a smaller, easier population - and every log line still says the budget was
         * granted in full. Nothing visible said the cache had stopped being used.
         *
         * Once per (class, reason) so it cannot spam a decode loop. */
        static int warned[8] = {0};
        const int idx = (int)(cache - &g_stream_expert_caches[0]);
        if (idx >= 0 && idx < 8 && !warned[idx]) {
            warned[idx] = 1;
            size_t free_b = 0, total_b = 0;
            cudaMemGetInfo(&free_b, &total_b);
            fprintf(stderr,
                    "ds4: CUDA expert cache class %d DISABLED - live budget is zero "
                    "(free %.2f GiB, reserve %.2f GiB, wanted %u experts). Expert lookups will BYPASS "
                    "VRAM. Free VRAM, not the requested budget, is what this gate tests: lower "
                    "--ssd-streaming-cache-experts or DS4_CUDA_DS_DIRECT_MB, or raise ctx headroom.\n",
                    idx,
                    (double)free_b / 1073741824.0,
                    (double)cuda_stream_expert_cache_reserve_bytes() / 1073741824.0,
                    target_cap);
        }
        return NULL;
    }
    if (same_dims &&
        cache->capacity != 0 &&
        cache->capacity >= cap &&
        cache->slots.size() == cache->capacity) {
        return cache;
    }

    if (same_dims && cache->vmm && cache->capacity != 0 &&
        cuda_stream_expert_cache_vmm_grow(cache, cap) >= cap) {
        return cache;  /* DS4COMBO: grown in place, residents kept */
    }
    cuda_stream_expert_cache_release(cache);
    while (cap != 0) {
        if ((uint64_t)cap > UINT64_MAX / gate_expert_bytes ||
            (uint64_t)cap > UINT64_MAX / down_expert_bytes) {
            fprintf(stderr, "ds4: CUDA streaming expert cache size overflow\n");
            return NULL;
        }

        char *gate_ptr = NULL;
        char *up_ptr = NULL;
        char *down_ptr = NULL;
        const char *alloc_error = NULL;
        if (!(g_stream_expert_ctx_vmm ?
              cuda_stream_expert_cache_vmm_alloc(cache,
                  cap,
                  cuda_stream_expert_cache_class_budget(class_index, expert_bytes, false),
                  gate_expert_bytes,
                  down_expert_bytes,
                  &gate_ptr,
                  &up_ptr,
                  &down_ptr,
                  &alloc_error) :
              cuda_stream_expert_cache_try_alloc(cap,
                                                gate_expert_bytes,
                                                down_expert_bytes,
                                                &gate_ptr,
                                                &up_ptr,
                                                &down_ptr,
                                                &alloc_error))) {
            const uint32_t new_cap =
                cuda_stream_expert_cache_shrunken_cap(cap);
            cuda_stream_expert_cache_note_oom_cap(cache,
                                                  cap,
                                                  new_cap,
                                                  expert_bytes,
                                                  alloc_error);
            cap = new_cap;
            if (cap != 0) {
                cap = cuda_stream_expert_cache_live_budget(cache,
                                                           cap,
                                                           gate_expert_bytes,
                                                           down_expert_bytes,
                                                           0,
                                                           1);
            }
            continue;
        }

        try {
            cache->slots.resize(cap);
        } catch (...) {
            fprintf(stderr, "ds4: CUDA streaming expert cache metadata allocation failed\n");
            if (!cache->vmm) {
                (void)cudaFree(gate_ptr);
                (void)cudaFree(up_ptr);
                (void)cudaFree(down_ptr);
            }
            cuda_stream_expert_cache_release(cache);
            return NULL;
        }

        cache->valid = 1;
        cache->capacity = cap;
        cache->count = 0;
        cache->tick = 0;
        cache->rank_worst_valid = 0;
        cache->rank_worst_slot = 0;
        cache->rank_worst_value = 0;
        cache->gate_expert_bytes = gate_expert_bytes;
        cache->down_expert_bytes = down_expert_bytes;
        cache->gate_ptr = gate_ptr;
        cache->up_ptr = up_ptr;
        cache->down_ptr = down_ptr;
        cache->gate_capacity =
            (uint64_t)cap * gate_expert_bytes;
        cache->up_capacity =
            (uint64_t)cap * gate_expert_bytes;
        cache->down_capacity =
            (uint64_t)cap * down_expert_bytes;
        /* [2026-08-18] ALWAYS-ON, was behind DS4_CUDA_STREAMING_EXPERT_CACHE_VERBOSE. The VRAM expert
         * cache was the only major allocation in this engine that landed silently - the RAM cache
         * announces itself (see the "CUDA RAM expert cache class %u allocated" line below), the DS
         * arena announces itself, this did not. That gap cost a wrong conclusion in DS4_NOW.md: a
         * missing allocation line was read as "the class never allocated", when no such line had ever
         * existed. An absence can only be evidence if the presence was possible.
         *
         * Cheap to leave on: prepare() early-returns whenever the existing allocation already covers
         * the target, so this fires on real capacity CHANGES, not per token. The guard below makes
         * that explicit anyway. Paired with the DISABLED warning above, the two lines now cover both
         * outcomes of every prepare - which is what makes "no DISABLED line" mean something. */
        if (cache->last_reported_cap != cap) {
            cache->last_reported_cap = cap;
            fprintf(stderr,
                    "ds4: CUDA expert cache class %u allocated %u experts / %.2f GiB "
                    "(%.2f MiB/expert)\n",
                    class_index,
                    cap,
                    (double)((uint64_t)cap * expert_bytes) / 1073741824.0,
                    (double)expert_bytes / 1048576.0);
#if defined(_WIN32)
            /* DS4COMBO: the VMM tier maps 16 MiB chunks, each under the 64 MiB
             * per-allocation trace threshold, so its WDDM commit never showed
             * in HOST_MEMORY traces. One line for the whole tier. */
            fprintf(stderr, "ds4: HOST_MEMORY_ALLOCATION line=%d kind=VRAM expert tier class %u (%s) bytes=%llu\n",
                    __LINE__, class_index, cache->vmm ? "cuMemCreate" : "cudaMalloc",
                    (unsigned long long)((uint64_t)cap * expert_bytes));
            ds4_win32_host_memory_snapshot("VRAM expert tier");
#endif
            ds4_t1_mark("vram_tier_allocated");
        }
        return cache;
    }
    return NULL;
}

/* EXPERT CACHE HIT-RATE COUNTERS.
 *
 * WHY: decode is fetch-bound, and the arithmetic says how much that costs. A decoded token touches
 * 6 experts x 42 MoE layers = 1.90 GiB of expert weights, so 10 t/s demands ~19 GiB/s of expert traffic
 * while the measured 4.5 t/s demands ~8.5 GiB/s. Whether the >10 t/s goal is reachable therefore turns on
 * what fraction of that traffic the caches actually serve - and RESIDENCY IS NOT HIT RATE. Routing has
 * locality, so the achieved rate can be far above the 8.1%-of-experts currently resident, or below it if
 * routing is flat. That was the single largest unknown in the sizing table, and it is cheap to just count.
 *
 * Deliberately NOT env-gated and always on: a getenv in a per-expert path cost ~35% of decode once
 * (feedback), whereas two unsynchronised integer increments are free. The counters are intentionally
 * racy - they are diagnostics, and a lost increment under contention cannot change a percentage that is
 * only ever read to one decimal place. */
/* DS4COMBO expert hotlist: routed lookups per (layer, expert) over this process's decode
 * (one per expert per layer per token), with that layer's expert sizes. Racy like the
 * counters below; used only to rank experts for the next decoder's pre-seed. */
#define DS4_COMBO_FREQ_LAYERS 64u
#define DS4_COMBO_FREQ_EXPERTS 1024u
static uint32_t g_combo_expert_freq[DS4_COMBO_FREQ_LAYERS][DS4_COMBO_FREQ_EXPERTS];
static uint64_t g_combo_expert_freq_gate[DS4_COMBO_FREQ_LAYERS], g_combo_expert_freq_down[DS4_COMBO_FREQ_LAYERS];
static inline void ds4_combo_expert_freq_count(uint32_t layer, uint32_t expert, uint64_t gate, uint64_t down) {
    if (layer >= DS4_COMBO_FREQ_LAYERS || expert >= DS4_COMBO_FREQ_EXPERTS) return;
    g_combo_expert_freq[layer][expert]++;
    g_combo_expert_freq_gate[layer] = gate; g_combo_expert_freq_down[layer] = down;
}
static uint64_t g_expert_vram_hits = 0;
static uint64_t g_expert_vram_misses = 0;
static uint64_t g_expert_host_hits = 0;
static uint64_t g_expert_host_misses = 0;

static void cuda_expert_cache_stats_dump(void) {
    const uint64_t v_tot = g_expert_vram_hits + g_expert_vram_misses;
    const uint64_t h_tot = g_expert_host_hits + g_expert_host_misses;
    const char *rank_env = getenv("DS4_CUDA_LEARNED_CACHE_POLICY");
    const int rank_requested =
        rank_env && rank_env[0] && strcmp(rank_env, "0") != 0;
    /* R9 phase-B MECHANISM LINE. This is deliberately before the zero-lookup
     * return and is identical in both A/B arms. `rejects` proves that a cold
     * miss was served without displacing a hotter resident; `eviction_overrides`
     * proves that the learned rank chose a different victim from the shipped
     * protect/LRU policy. The hit rate on the same line is the resulting VRAM
     * outcome rather than a treatment-only activity counter. */
    fprintf(stderr,
            "ds4: R9 learned cache mechanism [R9_LEARNED_CACHE_ADMISSION_V1]: "
            "flag=%s rank-bound=%s full-misses=%llu replacements=%llu "
            "admission-rejects=%llu eviction-overrides=%llu VRAM %.1f%% (%llu/%llu)\n",
            rank_requested ? "on" : "off",
            g_expert_rank_policy_bound ? "yes" : "no",
            g_expert_rank_policy_full_misses,
            g_expert_rank_policy_replacements,
            g_expert_rank_policy_rejects,
            g_expert_rank_policy_eviction_overrides,
            v_tot ? 100.0 * (double)g_expert_vram_hits / (double)v_tot : 0.0,
            (unsigned long long)g_expert_vram_hits,
            (unsigned long long)v_tot);
    /* R9 LIVE MECHANISM LINE. Keep this, the hit-rate line below, and the RAM
     * promotion exit line in both arms and above every zero-lookup return. */
    fprintf(stderr,
            "ds4: R9 live hotlist mechanism [R9_LIVE_HOTLIST_V1]: "
            "flag=%s ready=%s refreshes=%llu refresh_ms=%.3f "
            "ranks_changed=%llu decay_passes=%llu\n",
            cuda_env_flag_enabled("DS4_CUDA_LIVE_ROUTE_HOTLIST", 0) ?
                "on" : "off",
            g_route_live_ranks_ready ? "yes" : "no",
            (unsigned long long)g_decode_profile.live_hotlist_refreshes,
            g_decode_profile.live_hotlist_refresh_ms,
            (unsigned long long)g_decode_profile.live_hotlist_ranks_changed,
            (unsigned long long)g_decode_profile.live_hotlist_decay_passes);
    /* "served" = VRAM hits + host hits, against total VRAM lookups, which is one per expert per layer per
     * token. What is left went to disk. */
    const uint64_t served = g_expert_vram_hits + g_expert_host_hits;
    fprintf(stderr,
            "ds4: expert cache hit rate: VRAM %.1f%% (%llu/%llu), host %.1f%% (%llu/%llu), "
            "served-from-memory %.1f%% of %llu lookups\n",
            v_tot ? 100.0 * (double)g_expert_vram_hits / (double)v_tot : 0.0,
            (unsigned long long)g_expert_vram_hits, (unsigned long long)v_tot,
            h_tot ? 100.0 * (double)g_expert_host_hits / (double)h_tot : 0.0,
            (unsigned long long)g_expert_host_hits, (unsigned long long)h_tot,
            v_tot ? 100.0 * (double)served / (double)v_tot : 0.0,
             (unsigned long long)v_tot);
    if (v_tot == 0 && h_tot == 0) return;
}

static void cuda_expert_cache_stats_register(void) {
    static int stats_registered = 0;
    if (!stats_registered) {
        stats_registered = 1;
        atexit(cuda_expert_cache_stats_dump);
    }
}

/* Residency probe WITHOUT touching the hit/miss counters.
 *
 * Needed because the two-pass copy loop must know hit-or-miss to decide which pass an expert belongs to,
 * and it would otherwise scan twice per expert - double-counting every lookup and silently corrupting the
 * very hit-rate measurement that drove this whole line of work. Same scan, no side effects. */
static int cuda_stream_expert_cache_probe(
        cuda_stream_expert_cache *cache,
        const void *model_map,
        uint64_t model_size,
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t expert,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (!cache || !cache->valid) return -1;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_stream_expert_cache_slot &slot = cache->slots[i];
        if (slot.valid &&
            slot.model_map == model_map &&
            slot.model_size == model_size &&
            slot.layer == layer &&
            slot.n_total_expert == n_total_expert &&
            slot.expert == expert &&
            slot.gate_offset == gate_offset &&
            slot.up_offset == up_offset &&
            slot.down_offset == down_offset &&
            slot.gate_expert_bytes == gate_expert_bytes &&
            slot.down_expert_bytes == down_expert_bytes) {
            return (int)i;
        }
    }
    return -1;
}

/* Shared exact residency predicate for point lookups and router snapshots. */
template <typename Slot>
static bool cuda_stream_expert_slot_matches(const Slot &slot,
        const void *model_map, uint64_t model_size, uint32_t layer,
        uint32_t n_total_expert, uint32_t expert, uint64_t gate_offset,
        uint64_t up_offset, uint64_t down_offset,
        uint64_t gate_expert_bytes, uint64_t down_expert_bytes) {
    return slot.valid && slot.model_map == model_map && slot.model_size == model_size &&
        slot.layer == layer && slot.n_total_expert == n_total_expert && slot.expert == expert &&
        slot.gate_offset == gate_offset && slot.up_offset == up_offset && slot.down_offset == down_offset &&
        slot.gate_expert_bytes == gate_expert_bytes && slot.down_expert_bytes == down_expert_bytes;
}

static int cuda_stream_expert_cache_find(
        cuda_stream_expert_cache *cache,
        const void *model_map,
        uint64_t model_size,
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t expert,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes, bool record_stats = true) {
    /* Register the dump once, here rather than at init, so a run that never touches the streaming path
     * prints nothing at all. */
    cuda_expert_cache_stats_register();
    if (record_stats) ds4_combo_expert_freq_count(layer, expert, gate_expert_bytes, down_expert_bytes);
    /* No cache at all counts as a miss: functionally the expert is not resident, which is the quantity
     * the sizing analysis needs. */
    if (!cache || !cache->valid) { if (record_stats) g_expert_vram_misses++; return -1; }
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_stream_expert_cache_slot &slot = cache->slots[i];
        if (cuda_stream_expert_slot_matches(slot, model_map, model_size, layer,
                n_total_expert, expert, gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes)) {
            if (record_stats) g_expert_vram_hits++;
            return (int)i;
        }
    }
    if (record_stats) g_expert_vram_misses++;
    return -1;
}

/* How much of the cache is PROTECTED from eviction, as a divisor of capacity (1/N). 0 disables. */
static uint32_t cuda_stream_expert_cache_protect_divisor(void) {
    uint32_t d = 4;                       /* protect the first quarter by default */
    const char *env = getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_PROTECT_DIV");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long v = strtoul(env, &end, 10);
        if (end != env && end && *end == '\0' && v <= 64) d = (uint32_t)v;
    }
    return d;
}

static uint32_t cuda_stream_cache_frequency(uint32_t layer, uint32_t expert);
/* Background candidates retain the same displacement value under foreground
 * eviction. During warm-up/off, the original retention policy is unchanged. */
static uint64_t cuda_affinity_cache_priority(uint32_t layer, uint32_t expert) {
    uint64_t value=cuda_stream_cache_frequency(layer,expert);
#if defined(_WIN32)
    if(g_affinity_cap && g_affinity_current_biased && layer<128u && expert<384u)
        value+=g_affinity_displaced[layer][expert];
#endif
    return value;
}

static int cuda_stream_cache_lfu_enabled(void) {
    static const int enabled = cuda_env_flag_enabled("DS4_CUDA_STREAMING_CACHE_LFU", 0);
    return enabled;
}

static bool cuda_stream_cache_older_or_colder(
        uint32_t layer, uint32_t expert, uint64_t age,
        uint32_t other_layer, uint32_t other_expert, uint64_t other_age) {
    if (cuda_stream_cache_lfu_enabled() || (g_affinity_cap && g_affinity_current_biased)) {
        const uint64_t count = cuda_affinity_cache_priority(layer, expert);
        const uint64_t other = cuda_affinity_cache_priority(other_layer, other_expert);
        if (count != other) return count < other;
    }
    return age < other_age;
}

static uint32_t cuda_stream_expert_cache_lru_slot(
        cuda_stream_expert_cache *cache) {
    for (uint32_t i = 0; i < cache->capacity; i++) {
        if (!cache->slots[i].valid) return i;
    }

    /* Protect a popularity prefix from eviction, rather than letting pure recency rule.
     *
     * The low slots are filled first by the startup popularity preload
     * (`--ssd-streaming-preload-experts` / `DS4_CUDA_STREAMING_EXPERT_HOTLIST`), so slot index is a
     * usable proxy for "ranked hot". Under pure LRU a burst of cold experts walks the whole cache and
     * evicts exactly those hot entries - and this model punishes that hard: the tail-share sweep
     * measured **4.76 -> 4.28 t/s** purely on whether the Q4 class kept its residency.
     *
     * This is the one portable idea from krasis, whose HCS "protects the high-ranked heatmap prefix
     * and reserves a recency tail". Unlike its RAM->GPU streaming (which needs ~154 GB for this
     * model), a protected prefix costs no extra memory and works on a 31.4 GB box.
     *
     * Composes with the per-size-class caches: each class protects its own prefix independently.
     * Set DS4_CUDA_STREAMING_EXPERT_CACHE_PROTECT_DIV=0 to restore pure LRU. */
    uint32_t first = 0;
    const uint32_t div = cuda_stream_expert_cache_protect_divisor();
    if (!cuda_stream_cache_lfu_enabled() && div >= 2 && cache->capacity >= 8) {
        first = cache->capacity / div;
        /* Never protect everything: leave at least half the cache evictable, or the cache cannot
         * adapt at all once the protected region fills. */
        if (first > cache->capacity / 2) first = cache->capacity / 2;
    }

    uint32_t slot = first;
    uint64_t best_age = cache->slots[first].age;
    for (uint32_t i = first + 1; i < cache->capacity; i++) {
        if (cuda_stream_cache_older_or_colder(
                cache->slots[i].layer, cache->slots[i].expert, cache->slots[i].age,
                cache->slots[slot].layer, cache->slots[slot].expert, best_age)) {
            best_age = cache->slots[i].age;
            slot = i;
        }
    }
    return slot;
}

static void cuda_stream_expert_cache_refresh_worst_rank(
        cuda_stream_expert_cache *cache) {
    if (!cache) return;
    cache->rank_worst_valid = 0;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_stream_expert_cache_slot &entry = cache->slots[i];
        if (!entry.valid) continue;
        if (!cache->rank_worst_valid ||
            entry.route_rank > cache->rank_worst_value ||
            (entry.route_rank == cache->rank_worst_value &&
             entry.age < cache->slots[cache->rank_worst_slot].age)) {
            cache->rank_worst_valid = 1;
            cache->rank_worst_slot = i;
            cache->rank_worst_value = entry.route_rank;
        }
    }
}

/* MEASURED AND REFUTED TWICE. Keep this default OFF; do not re-roll it without a NEW mechanism.
 *
 * 90 GB build, ctx 262144, 28 GB SSD + 16 GB RAM cache, n=3 alternating pairs, md5 identical on
 * every arm (so this is a performance verdict, not a correctness one):
 *
 *   attempt 1, reject on (incoming_rank >= rank_worst_value):
 *       VRAM hit 61.1% -> 51.8%, decode 9.527 -> 8.700 t/s   (rejects 58924 vs 2132 replacements)
 *   attempt 2, THIS code (unknown ranks admitted, protected-LRU baseline, 8x band):
 *       VRAM hit 61.1% -> 58.2%, decode 9.510 -> 9.323 t/s   (rejects 49153 vs 3527 replacements)
 *
 * Attempt 2 recovered most of attempt 1's damage but still lost to plain protected-LRU on BOTH
 * columns. The reading: a hotlist is a GLOBAL STATIC ranking, and it discards the temporal locality
 * that LRU already captures. Ranking experts by lifetime hotness cannot beat recency when the
 * working set moves. (Weak corroboration only, different engine and hardware: the flash-moe project
 * independently measured temporal expert prediction at -18% and an MLP routing predictor at 31%
 * accuracy, "worse than temporal baseline".)
 *
 * A rank is only ordinal, so small numerical differences are not evidence
 * that one expert is materially hotter than another. Require an eightfold
 * separation before treating two known ranks as clearly different. +1 keeps
 * rank zero meaningful and the uint64_t arithmetic avoids overflow. Missing
 * hotlist entries use UINT32_MAX and deliberately compare as unknown. */
static int cuda_stream_expert_rank_clearly_worse(
        uint32_t candidate_rank,
        uint32_t reference_rank) {
    const uint64_t rank_ratio = 8;
    if (candidate_rank == UINT32_MAX || reference_rank == UINT32_MAX) return 0;
    return (uint64_t)candidate_rank + 1 >
           rank_ratio * ((uint64_t)reference_rank + 1);
}

/* Rank-aware admission for R9 phase B. Keep the shipped protected-LRU choice
 * as the baseline because it supplies the recency tail that decode needs.
 * Learned rank may intervene only with strong evidence:
 *   - an incoming expert more than 8x colder than the actual LRU incumbent is
 *     rejected;
 *   - an incoming expert more than 8x hotter than the cache's coldest known
 *     resident evicts that resident instead.
 * Everything else, including either side having no learned rank, is admitted
 * through the shipped path. Thus ordinary/nearby ranks retain cache churn and
 * rejection is the exception rather than the steady-state default. */
static uint32_t cuda_stream_expert_cache_admission_slot(
        cuda_stream_expert_cache *cache,
        uint32_t incoming_rank,
        int rank_policy,
        uint32_t layer,
        uint32_t expert) {
    if (cuda_stream_cache_lfu_enabled() || (g_affinity_cap && g_affinity_current_biased)) {
        const uint32_t slot = cuda_stream_expert_cache_lru_slot(cache);
        const auto &resident = cache->slots[slot];
        if (resident.valid && cuda_affinity_cache_priority(layer, expert) <
                              cuda_affinity_cache_priority(resident.layer, resident.expert))
            return UINT32_MAX;
        return slot;
    }
    if (!rank_policy) return cuda_stream_expert_cache_lru_slot(cache);
    g_expert_rank_policy_bound = 1;

    if (cache->count < cache->capacity) {
        for (uint32_t i = 0; i < cache->capacity; i++) {
            if (!cache->slots[i].valid) return i;
        }
    }

    g_expert_rank_policy_full_misses++;
    const uint32_t legacy_slot = cuda_stream_expert_cache_lru_slot(cache);
    if (!cache->rank_worst_valid) {
        cuda_stream_expert_cache_refresh_worst_rank(cache);
    }

    uint32_t slot = legacy_slot;
    if (cache->rank_worst_valid &&
        cuda_stream_expert_rank_clearly_worse(cache->rank_worst_value,
                                              incoming_rank)) {
        slot = cache->rank_worst_slot;
    } else if (cache->slots[legacy_slot].valid &&
               cuda_stream_expert_rank_clearly_worse(
                   incoming_rank,
                   cache->slots[legacy_slot].route_rank)) {
        g_expert_rank_policy_rejects++;
        return UINT32_MAX;
    }

    g_expert_rank_policy_replacements++;
    if (slot != legacy_slot) g_expert_rank_policy_eviction_overrides++;
    cache->rank_worst_valid = 0;
    return slot;
}

static int cuda_stream_expert_cache_copy_to_compact(
        cuda_stream_expert_cache *cache,
        uint32_t cache_slot,
        uint32_t compact_slot,
        char *compact_gate,
        char *compact_up,
        char *compact_down) {
    const uint64_t gate_src = (uint64_t)cache_slot * cache->gate_expert_bytes;
    const uint64_t down_src = (uint64_t)cache_slot * cache->down_expert_bytes;
    const uint64_t gate_dst = (uint64_t)compact_slot * cache->gate_expert_bytes;
    const uint64_t down_dst = (uint64_t)compact_slot * cache->down_expert_bytes;
    return cuda_ok(cudaMemcpy(compact_gate + gate_dst,
                              cache->gate_ptr + gate_src,
                              (size_t)cache->gate_expert_bytes,
                              cudaMemcpyDeviceToDevice),
                   "streaming selected gate cache copy") &&
           cuda_ok(cudaMemcpy(compact_up + gate_dst,
                              cache->up_ptr + gate_src,
                              (size_t)cache->gate_expert_bytes,
                              cudaMemcpyDeviceToDevice),
                   "streaming selected up cache copy") &&
           cuda_ok(cudaMemcpy(compact_down + down_dst,
                              cache->down_ptr + down_src,
                              (size_t)cache->down_expert_bytes,
                              cudaMemcpyDeviceToDevice),
                   "streaming selected down cache copy");
}

/* Which allocator the host expert cache used; the free path MUST match or it is heap corruption. */
static int g_host_cache_pinned = 1;

static void cuda_stream_host_expert_cache_free_buffers(
        char *gate_ptr,
        char *up_ptr,
        char *down_ptr, int pinned = g_host_cache_pinned) {
    if (pinned) {
        if (gate_ptr) cudaFreeHost(gate_ptr);
        if (up_ptr)   cudaFreeHost(up_ptr);
        if (down_ptr) cudaFreeHost(down_ptr);
    } else {
        free(gate_ptr);
        free(up_ptr);
        free(down_ptr);
    }
}

static uint64_t cuda_stream_host_expert_cache_allocated_bytes(
        const cuda_stream_host_expert_cache *cache) {
    if (!cache) return 0;
    return cache->gate_capacity +
           cache->up_capacity +
           cache->down_capacity;
}

static uint64_t cuda_stream_host_expert_cache_total_allocated_bytes(void) {
    uint64_t total = 0;
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        const uint64_t class_bytes = cuda_stream_host_expert_cache_allocated_bytes(
            &g_stream_host_expert_caches[i]);
        if (class_bytes > UINT64_MAX - total) return UINT64_MAX;
        total += class_bytes;
    }
    return total;
}

static void cuda_stream_host_expert_cache_update_peak(
        uint64_t other_class_bytes,
        uint64_t allocation_peak_bytes,
        uint64_t *peak_bytes) {
    if (!peak_bytes) return;
    const uint64_t candidate = allocation_peak_bytes >
            UINT64_MAX - other_class_bytes ?
        UINT64_MAX : other_class_bytes + allocation_peak_bytes;
    if (candidate > *peak_bytes) *peak_bytes = candidate;
}

static void cuda_stream_host_expert_cache_release(
        cuda_stream_host_expert_cache *cache, int pinned = g_host_cache_pinned) {
    if (!cache) return;
    /* [2026-08-16] cudaFreeHost: these are cudaMallocHost'd (pinned) now. free() here would be
     * heap corruption. */
    cuda_stream_host_expert_cache_free_buffers(
        cache->gate_ptr, cache->up_ptr, cache->down_ptr, pinned);
    cache->slots.clear();
    cache->slots.shrink_to_fit();
    /* memset would blow away the std::vector header; clear the POD fields by hand. */
    cache->valid = 0;
    cache->capacity = 0;
    cache->count = 0;
    cache->tick = 0;
    cache->gate_expert_bytes = 0;
    cache->down_expert_bytes = 0;
    cache->gate_ptr = NULL;
    cache->up_ptr = NULL;
    cache->down_ptr = NULL;
    cache->gate_capacity = 0;
    cache->up_capacity = 0;
    cache->down_capacity = 0;
}

static void cuda_stream_host_expert_cache_release_all(void) {
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        cuda_stream_host_expert_cache_release(&g_stream_host_expert_caches[i]);
        g_stream_host_expert_class_bytes[i] = 0;
        g_stream_host_expert_runtime_cap[i] = 0;
        g_stream_host_expert_cap_was_budget_derived[i] = 0;
        /* Reset the once-per-class log gate too. Without this the per-class budget line prints only
         * once per PROCESS, so after a teardown and re-setup -- a model reload, or the MTP/DSpark
         * model swapping in -- the operator silently loses the line telling them what budget the new
         * configuration actually got. */
        g_stream_host_expert_class_notice[i] = 0;
    }
}

static void cuda_stream_host_expert_cache_invalidate(void) {
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        cuda_stream_host_expert_cache *cache = &g_stream_host_expert_caches[i];
        for (cuda_stream_host_expert_cache_slot &slot : cache->slots) {
            slot.valid = 0;
        }
        cache->valid = 0;
        cache->count = 0;
        cache->tick = 0;
    }
}

/* Which per-class host cache owns this expert shape. Always on: unlike the GPU-side isolation this
 * has no opt-out, because the singleton it replaces could not hold a mixed-quant model at all. */
static uint32_t cuda_stream_host_expert_cache_class_index(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        const cuda_stream_host_expert_cache *cache = &g_stream_host_expert_caches[i];
        if (cache->valid &&
            cache->gate_expert_bytes == gate_expert_bytes &&
            cache->down_expert_bytes == down_expert_bytes) {
            return i;
        }
    }
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        if (!g_stream_host_expert_caches[i].valid) return i;
    }
    /* More distinct shapes than classes: keep class 0 (first seen, the dominant population) intact
     * and let the newcomer contend for the last class rather than evicting the primary. */
    return DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES - 1u;
}

static uint32_t cuda_stream_host_expert_cache_requested_budget(void) {
    uint32_t cap = g_stream_host_expert_budget_override;
    const char *env = getenv("DS4_CUDA_STREAMING_HOST_CACHE_N");
    if (env && env[0]) {
        char *end = NULL;
        errno = 0;
        unsigned long v = strtoul(env, &end, 10);
        while (end && (*end == ' ' || *end == '\t')) end++;
        if (end != env && errno == 0 && end && *end == '\0') {
            cap = v > DS4_CUDA_STREAM_EXPERT_MAX ?
                DS4_CUDA_STREAM_EXPERT_MAX : (uint32_t)v;
        }
    }
    if (cap > DS4_CUDA_STREAM_EXPERT_MAX) cap = DS4_CUDA_STREAM_EXPERT_MAX;
    return cap;
}

static int cuda_stream_host_expert_cache_enabled(void) {
    return g_ssd_streaming_mode &&
           (cuda_stream_host_expert_cache_requested_budget() != 0 ||
            g_stream_host_expert_budget_bytes_override != 0);
}

static uint32_t cuda_stream_host_expert_cache_budget_cap_for_classes(
        uint64_t expert_bytes,
        uint64_t competing_charge_bytes,
        uint32_t class_count) {
    uint32_t cap = cuda_stream_host_expert_cache_requested_budget();
    if (expert_bytes == 0 ||
        g_stream_host_expert_budget_bytes_override == 0) {
        return cap;
    }
    if (class_count == 0 ||
        class_count > DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES) {
        class_count = DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES;
    }
    const uint64_t effective_budget_bytes =
        g_stream_host_expert_budget_bytes_override > competing_charge_bytes ?
            g_stream_host_expert_budget_bytes_override - competing_charge_bytes : 0;
    const uint64_t class_budget_bytes =
        effective_budget_bytes / class_count;
    const uint64_t byte_cap64 = class_budget_bytes / expert_bytes;
    const uint32_t byte_cap = byte_cap64 > DS4_CUDA_STREAM_EXPERT_MAX ?
        DS4_CUDA_STREAM_EXPERT_MAX : (uint32_t)byte_cap64;
    if (cap == 0 || cap > byte_cap) cap = byte_cap;
    return cap;
}

static uint32_t cuda_stream_host_expert_cache_budget_cap(
        uint64_t expert_bytes,
        uint64_t competing_charge_bytes) {
    /* Before every model shape has been observed, reserve an equal share for
     * each supported class. The decode edge can safely redistribute this
     * aggregate byte budget across only the classes prefill actually used. */
    return cuda_stream_host_expert_cache_budget_cap_for_classes(
        expert_bytes,
        competing_charge_bytes,
        DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES);
}

#define DS4_CUDA_HOST_CACHE_DECODE_REFILL_MIN_RESERVE_BYTES (512ull * 1048576ull)

struct cuda_stream_host_expert_cache_decode_feasibility {
    int measured;
    uint32_t selected_cap;
    uint64_t available_bytes;
    uint64_t reserve_bytes;
    uint64_t other_class_bytes;
};

/* GlobalMemoryStatusEx reports physical bytes immediately available to this
 * process. Keep the larger of 512 MiB and 10% of that reading uncommitted: a
 * target that consumes the final available page is not a credible pinned
 * allocation while the model streamer and CUDA runtime remain live. Re-read
 * this for every class so a class already grown at this edge is visible both
 * in ullAvailPhys and in other_class_bytes. */
static cuda_stream_host_expert_cache_decode_feasibility
cuda_stream_host_expert_cache_decode_feasible_cap(
        uint32_t class_index,
        uint32_t requested_cap,
        uint64_t expert_bytes) {
    cuda_stream_host_expert_cache_decode_feasibility result = {};
    if (class_index >= DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES ||
        requested_cap == 0 || expert_bytes == 0) {
        return result;
    }
#if defined(_WIN32)
    MEMORYSTATUSEX state = {};
    state.dwLength = sizeof(state);
    if (!GlobalMemoryStatusEx(&state)) return result;

    result.measured = 1;
    result.available_bytes = (uint64_t)state.ullAvailPhys;
    result.reserve_bytes = result.available_bytes / 10u;
    if (result.reserve_bytes <
        DS4_CUDA_HOST_CACHE_DECODE_REFILL_MIN_RESERVE_BYTES) {
        result.reserve_bytes =
            DS4_CUDA_HOST_CACHE_DECODE_REFILL_MIN_RESERVE_BYTES;
    }

    const uint64_t total_allocated_bytes =
        cuda_stream_host_expert_cache_total_allocated_bytes();
    const uint64_t class_allocated_bytes =
        cuda_stream_host_expert_cache_allocated_bytes(
            &g_stream_host_expert_caches[class_index]);
    result.other_class_bytes =
        total_allocated_bytes >= class_allocated_bytes ?
            total_allocated_bytes - class_allocated_bytes : 0;
    const uint64_t usable_available_bytes =
        result.available_bytes > result.reserve_bytes ?
            result.available_bytes - result.reserve_bytes : 0;
    const uint64_t aggregate_attainable_bytes =
        total_allocated_bytes > UINT64_MAX - usable_available_bytes ?
            UINT64_MAX : total_allocated_bytes + usable_available_bytes;
    const uint64_t class_attainable_bytes =
        aggregate_attainable_bytes > result.other_class_bytes ?
            aggregate_attainable_bytes - result.other_class_bytes : 0;
    const uint64_t cap64 = class_attainable_bytes / expert_bytes;
    result.selected_cap = cap64 > requested_cap ?
        requested_cap : (uint32_t)cap64;
#endif
    return result;
}

/* Default-on shipping behavior.  A zero value keeps the prefill-sized runtime
 * cap latched at the decode edge so the latch release can be measured in the
 * same binary without changing R4 itself. */
static int cuda_stream_host_expert_cache_latch_release_enabled(void) {
    static int enabled = -1;
    if (enabled < 0) {
        const char *e = getenv("DS4_CUDA_HOST_CACHE_LATCH_RELEASE");
        enabled = (e && *e && *e == '0') ? 0 : 1;
    }
    return enabled;
}

static void cuda_stream_host_expert_cache_report_decode_refill(
        uint32_t class_index,
        uint32_t active_classes,
        int eligible,
        int enabled,
        int attempted,
        uint32_t cap_before,
        uint32_t cap_after,
        uint32_t target_cap,
        uint32_t selected_cap,
        int feasibility_measured,
        uint64_t available_bytes,
        uint64_t reserve_bytes,
        uint64_t other_class_bytes,
        uint64_t allocated_before,
        uint64_t allocated_after,
        uint64_t transient_peak_bytes,
        uint32_t experts_discarded,
        int realloc_succeeded,
        int fallback_taken,
        const char *status) {
    fprintf(stderr,
            "ds4: [DS4_HOST_CACHE_DECODE_REFILL_V1] class=%u active_classes=%u eligible=%d "
            "enabled=%d attempted=%d cap=%u->%u target_cap=%u "
            "selected_cap=%u feasibility_measured=%d available_bytes=%llu "
            "reserve_bytes=%llu other_class_bytes=%llu "
            "allocated_bytes=%llu->%llu experts_discarded=%u "
            "transient_peak_bytes=%llu realloc_succeeded=%d "
            "fallback_taken=%d status=%s\n",
            class_index,
            active_classes,
            eligible,
            enabled,
            attempted,
            cap_before,
            cap_after,
            target_cap,
            selected_cap,
            feasibility_measured,
            (unsigned long long)available_bytes,
            (unsigned long long)reserve_bytes,
            (unsigned long long)other_class_bytes,
            (unsigned long long)allocated_before,
            (unsigned long long)allocated_after,
            experts_discarded,
            (unsigned long long)transient_peak_bytes,
            realloc_succeeded,
            fallback_taken,
            status ? status : "unknown");
}

static uint32_t cuda_stream_host_expert_cache_shrunken_cap(uint32_t cap) {
    if (cap == 0) return 0;
    const uint32_t release = (cap + 9u) / 10u;
    return cap > release ? cap - release : 0;
}

static int cuda_stream_host_expert_cache_pinned_enabled(void) {
    static const int host_cache_pin = []() {
        const char *e = getenv("DS4_CUDA_HOST_EXPERT_CACHE_PINNED");
        const int on = !(e && e[0] == '0');
        if (!on) fprintf(stderr, "ds4: DS4_CUDA_HOST_EXPERT_CACHE_PINNED=0 - host expert cache is PAGEABLE"
                                 " (expect ~2.7 GB/s H2D instead of pinned rates)\n");
        return on;
    }();
    return host_cache_pin;
}

static int cuda_stream_host_expert_cache_try_alloc(
        uint32_t cap,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        int host_cache_pin,
        char **gate_ptr,
        char **up_ptr,
        char **down_ptr,
        uint64_t *peak_bytes) {
    *gate_ptr = NULL;
    *up_ptr = NULL;
    *down_ptr = NULL;
    if (peak_bytes) *peak_bytes = 0;
    const uint64_t expert_bytes = cuda_stream_expert_cache_expert_bytes(
        gate_expert_bytes, down_expert_bytes);
    if (cap == 0 ||
        expert_bytes == 0 ||
        (uint64_t)cap > UINT64_MAX / expert_bytes ||
        (uint64_t)cap > UINT64_MAX / gate_expert_bytes ||
        (uint64_t)cap > UINT64_MAX / down_expert_bytes) {
        return 0;
    }
    const uint64_t gate_bytes = (uint64_t)cap * gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)cap * down_expert_bytes;
    if (gate_bytes > (uint64_t)SIZE_MAX ||
        down_bytes > (uint64_t)SIZE_MAX) {
        return 0;
    }

    /* [2026-08-16] PINNED, not malloc. This cache is the source of every host->device expert copy on
     * the decode path -- ~206 copies/token -- and pageable memory forces the driver to stage each one
     * through an internal bounce buffer. Measured on the pageable version: 464 MiB/token at 2.68 GB/s
     * = 10.7% of PCIe 4.0 x16, ~0.82 ms for a ~2.25 MiB copy, i.e. latency-bound, and `plan` (the
     * whole staging function) was ~95% of the decode token. cudaMallocHost is already the pattern
     * elsewhere in this file (:2241, :2348, :2662, :5027, :5106).
     * NOTE: this pins up to the host-cache budget (6 GB at current settings) on a 31.4 GB box; pinned
     * pages cannot be swapped. Failure is handled the same as a malloc failure -- the caller retries
     * at a smaller capacity -- so an over-large request degrades rather than aborting. */
    /* DS4_CUDA_HOST_EXPERT_CACHE_PINNED=0 reverts to pageable malloc. Documented escape hatch, not a
     * hidden default: pinning is ON because it is worth +98% prefill / +23% decode here, but it makes
     * up to the host-cache budget (6 GB at current settings) unswappable, which is a real cost on a
     * 31.4 GB box under heavy multitasking. The allocator choice is recorded in g_host_cache_pinned so
     * the matching free path cannot diverge. */
    char *gate = NULL, *up = NULL, *down = NULL;
    if (host_cache_pin) {
        if (cudaMallocHost((void **)&gate, (size_t)gate_bytes) != cudaSuccess) gate = NULL;
        if (gate &&
            cudaMallocHost((void **)&up, (size_t)gate_bytes) != cudaSuccess) {
            up = NULL;
        }
        if (gate && up &&
            cudaMallocHost((void **)&down, (size_t)down_bytes) != cudaSuccess) {
            down = NULL;
        }
    } else {
        gate = (char *)malloc((size_t)gate_bytes);
        if (gate) up = (char *)malloc((size_t)gate_bytes);
        if (up) down = (char *)malloc((size_t)down_bytes);
    }
    g_host_cache_pinned = host_cache_pin;
    if (peak_bytes) {
        if (gate) *peak_bytes += gate_bytes;
        if (up)   *peak_bytes += gate_bytes;
        if (down) *peak_bytes += down_bytes;
    }
    if (!gate || !up || !down) {
        (void)cudaGetLastError();
        if (host_cache_pin) {
            if (gate) cudaFreeHost(gate);
            if (up)   cudaFreeHost(up);
            if (down) cudaFreeHost(down);
        } else {
            free(gate); free(up); free(down);
        }
        return 0;
    }

    *gate_ptr = gate;
    *up_ptr = up;
    *down_ptr = down;
    return 1;
}

enum cuda_stream_host_expert_cache_decode_refill_result {
    DS4_HOST_CACHE_DECODE_REFILL_RETAINED = 0,
    DS4_HOST_CACHE_DECODE_REFILL_SUCCEEDED = 1,
    DS4_HOST_CACHE_DECODE_REFILL_REBUILT_OLD_CAP = 2,
    DS4_HOST_CACHE_DECODE_REFILL_EMERGENCY_INVALID = 3,
};

/* The refill deliberately discards residency, so the old buffers do not need
 * to coexist with the decode-sized generation. Free them first to keep the
 * class-local pinned-buffer peak at max(old, target), then rebuild an empty
 * old-capacity generation if the target cannot be allocated. */
static cuda_stream_host_expert_cache_decode_refill_result
cuda_stream_host_expert_cache_decode_refill(
        uint32_t class_index,
        uint32_t requested_cap,
        cuda_stream_host_expert_cache_decode_feasibility *feasibility_out,
        uint32_t *selected_cap_out,
        const char **failure_reason,
        uint64_t *transient_peak_bytes) {
    if (feasibility_out) *feasibility_out = {};
    if (selected_cap_out) *selected_cap_out = requested_cap;
    if (failure_reason) *failure_reason = NULL;
    if (transient_peak_bytes) {
        *transient_peak_bytes =
            cuda_stream_host_expert_cache_total_allocated_bytes();
    }
    if (class_index >= DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES ||
        requested_cap == 0) {
        if (failure_reason) *failure_reason = "invalid target";
        return DS4_HOST_CACHE_DECODE_REFILL_RETAINED;
    }
    cuda_stream_host_expert_cache *cache =
        &g_stream_host_expert_caches[class_index];
    if (!cache->valid ||
        cache->capacity == 0 ||
        cache->count > cache->capacity ||
        cache->slots.size() != cache->capacity ||
        cache->gate_expert_bytes == 0 ||
        cache->down_expert_bytes == 0 ||
        !cache->gate_ptr ||
        !cache->up_ptr ||
        !cache->down_ptr) {
        if (failure_reason) *failure_reason = "existing cache state is not refillable";
        return DS4_HOST_CACHE_DECODE_REFILL_RETAINED;
    }

    const uint32_t old_cap = cache->capacity;
    const uint64_t gate_expert_bytes = cache->gate_expert_bytes;
    const uint64_t down_expert_bytes = cache->down_expert_bytes;
    const uint64_t old_allocated_bytes =
        cuda_stream_host_expert_cache_allocated_bytes(cache);
    const uint64_t total_allocated_bytes =
        cuda_stream_host_expert_cache_total_allocated_bytes();
    const uint64_t other_class_bytes =
        total_allocated_bytes >= old_allocated_bytes ?
            total_allocated_bytes - old_allocated_bytes : 0;
    const int allocator_was_pinned = g_host_cache_pinned;
    char *old_gate_ptr = cache->gate_ptr;
    char *old_up_ptr = cache->up_ptr;
    char *old_down_ptr = cache->down_ptr;

    /* No resident slots are copied by design. Release the large resources
     * before allocating any part of the replacement generation. */
    fprintf(stderr,
            "ds4: CUDA decode edge released RAM expert cache class %u "
            "%u experts / %.2f GiB before host cache refill "
            "[DS4_HOST_CACHE_DECODE_REFILL_V1]\n",
            class_index,
            old_cap,
            (double)old_allocated_bytes / 1073741824.0);
    cuda_stream_host_expert_cache_free_buffers(
        old_gate_ptr, old_up_ptr, old_down_ptr);
    for (cuda_stream_host_expert_cache_slot &slot : cache->slots) {
        slot.valid = 0;
    }
    cache->valid = 0;
    cache->capacity = 0;
    cache->count = 0;
    cache->tick = 0;
    cache->gate_ptr = NULL;
    cache->up_ptr = NULL;
    cache->down_ptr = NULL;
    cache->gate_capacity = 0;
    cache->up_capacity = 0;
    cache->down_capacity = 0;
    g_stream_host_expert_class_bytes[class_index] = 0;

    const cuda_stream_host_expert_cache_decode_feasibility feasibility =
        cuda_stream_host_expert_cache_decode_feasible_cap(
            class_index, requested_cap,
            cuda_stream_expert_cache_expert_bytes(
                gate_expert_bytes, down_expert_bytes));
    if (feasibility_out) *feasibility_out = feasibility;
    uint32_t target_cap = feasibility.measured ?
        feasibility.selected_cap : 0;
    if (selected_cap_out) *selected_cap_out = target_cap;
    if (feasibility.measured) {
        const uint64_t expert_bytes =
            cuda_stream_expert_cache_expert_bytes(
                gate_expert_bytes, down_expert_bytes);
        fprintf(stderr,
                "ds4: CUDA decode edge measured RAM host cache class %u "
                "after release: available %.2f GiB reserve %.2f GiB other "
                "classes %.2f GiB; requested %u experts / %.2f GiB, "
                "selected %u experts / %.2f GiB "
                "[DS4_HOST_CACHE_DECODE_REFILL_V1]\n",
                class_index,
                (double)feasibility.available_bytes / 1073741824.0,
                (double)feasibility.reserve_bytes / 1073741824.0,
                (double)feasibility.other_class_bytes / 1073741824.0,
                requested_cap,
                (double)((uint64_t)requested_cap * expert_bytes) /
                    1073741824.0,
                target_cap,
                (double)((uint64_t)target_cap * expert_bytes) /
                    1073741824.0);
        if (target_cap != requested_cap) {
            fprintf(stderr,
                    "ds4: CUDA RAM expert cache request physically clamped "
                    "from %.2f to %.2f GiB at decode edge for host class %u "
                    "[DS4_HOST_CACHE_DECODE_REFILL_V1]\n",
                    (double)((uint64_t)requested_cap * expert_bytes) /
                        1073741824.0,
                    (double)((uint64_t)target_cap * expert_bytes) /
                        1073741824.0,
                    class_index);
        }
    }

    std::vector<cuda_stream_host_expert_cache_slot> new_slots;
    const char *target_failure = !feasibility.measured ?
        "available-memory query failed after release" :
        (target_cap == 0 ? "physical clamp selected zero experts" : NULL);
    int target_metadata_failed = 0;
    if (!target_failure) {
        try {
            new_slots.resize(target_cap);
        } catch (...) {
            target_metadata_failed = 1;
            target_failure = "target metadata allocation failed";
        }
    }

    /* [2026-08-23] DESCENDING RETRY - DS4_HOST_CACHE_DECODE_STEPDOWN_V1.
     *
     * This used to be a single attempt at target_cap that fell straight back to old_cap, and
     * MEASURED on fp165g that is a REGRESSION against the pre-fix build. Pre-fix, the budget latch
     * reaches 455 experts / 6.00 GiB and keeps them. Post-fix, this path asked for 910 / 12.00 GiB,
     * the allocation failed on a 31.4 GiB box, and it rebuilt EMPTY at the 152-expert startup
     * capacity - 2.00 GiB, a THIRD of what the old code got, with 152 warm experts discarded on the
     * way down. Removing the class divisor was right; treating the first failure as a cliff was not.
     *
     * The feasibility check cannot prevent this. It measured available 13.99 GiB, reserve 1.40 GiB
     * and selected 910 / 12.00 GiB, and that still would not allocate - because this is THREE large
     * contiguous buffers (gate, up, down), not one pool of free bytes. A byte count that fits says
     * nothing about whether the address space has three runs that fit.
     *
     * So step DOWN in 1 GiB increments until one fits. The descent stops ABOVE old_cap so the
     * known-good fallback below keeps its exact previous behaviour when nothing larger fits, and it
     * is bounded so a pathological expert size cannot spin. Every failed attempt is reported: a
     * silent descent would make a 12.00 GiB request that quietly served 3.00 GiB indistinguishable
     * from one that served 12.00.
     */
    char *gate_ptr = NULL;
    char *up_ptr = NULL;
    char *down_ptr = NULL;
    uint64_t allocation_peak_bytes = 0;
    uint32_t settled_cap = 0;
    if (!target_failure) {
        const uint64_t expert_bytes_each =
            cuda_stream_expert_cache_expert_bytes(
                gate_expert_bytes, down_expert_bytes);
        uint32_t step = expert_bytes_each ?
            (uint32_t)(1073741824ULL / expert_bytes_each) : 1u;
        if (step == 0) step = 1u;
        uint32_t candidate = target_cap;
        unsigned attempts = 0;
        for (;;) {
            gate_ptr = NULL;
            up_ptr = NULL;
            down_ptr = NULL;
            allocation_peak_bytes = 0;
            if (cuda_stream_host_expert_cache_try_alloc(
                    candidate,
                    gate_expert_bytes,
                    down_expert_bytes,
                    allocator_was_pinned,
                    &gate_ptr,
                    &up_ptr,
                    &down_ptr,
                    &allocation_peak_bytes)) {
                settled_cap = candidate;
                break;
            }
            attempts++;
            fprintf(stderr,
                    "ds4: CUDA RAM host cache class %u step-down attempt %u "
                    "failed at %u experts / %.2f GiB; stepping to %.2f GiB "
                    "(floor is the existing %u experts / %.2f GiB) "
                    "[DS4_HOST_CACHE_DECODE_STEPDOWN_V1]\n",
                    class_index,
                    attempts,
                    candidate,
                    (double)((uint64_t)candidate * expert_bytes_each) /
                        1073741824.0,
                    (double)((uint64_t)(candidate > step ? candidate - step : 0) *
                        expert_bytes_each) / 1073741824.0,
                    old_cap,
                    (double)((uint64_t)old_cap * expert_bytes_each) /
                        1073741824.0);
            if (attempts >= 64u || candidate <= step ||
                candidate - step <= old_cap) {
                target_failure = "target buffer allocation failed";
                break;
            }
            candidate -= step;
        }
    }
    if (!target_failure && settled_cap != target_cap) {
        /* Shrinking a vector never allocates, so this cannot throw here. */
        new_slots.resize(settled_cap);
        if (selected_cap_out) *selected_cap_out = settled_cap;
        fprintf(stderr,
                "ds4: CUDA RAM host cache class %u settled at %u experts / "
                "%.2f GiB by stepping down from the %u-expert / %.2f GiB "
                "target (existing capacity was %u experts / %.2f GiB) "
                "[DS4_HOST_CACHE_DECODE_STEPDOWN_V1]\n",
                class_index,
                settled_cap,
                (double)((uint64_t)settled_cap *
                    cuda_stream_expert_cache_expert_bytes(
                        gate_expert_bytes, down_expert_bytes)) / 1073741824.0,
                target_cap,
                (double)((uint64_t)target_cap *
                    cuda_stream_expert_cache_expert_bytes(
                        gate_expert_bytes, down_expert_bytes)) / 1073741824.0,
                old_cap,
                (double)((uint64_t)old_cap *
                    cuda_stream_expert_cache_expert_bytes(
                        gate_expert_bytes, down_expert_bytes)) / 1073741824.0);
    }
    cuda_stream_host_expert_cache_update_peak(
        other_class_bytes, allocation_peak_bytes, transient_peak_bytes);

    if (!target_failure) {
        /* settled_cap, NOT target_cap: after a step-down these differ, and committing target_cap
         * here would publish a capacity larger than the buffers actually allocated. */
        cache->slots.swap(new_slots);
        cache->valid = 1;
        cache->capacity = settled_cap;
        cache->gate_ptr = gate_ptr;
        cache->up_ptr = up_ptr;
        cache->down_ptr = down_ptr;
        cache->gate_capacity = (uint64_t)settled_cap * gate_expert_bytes;
        cache->up_capacity = (uint64_t)settled_cap * gate_expert_bytes;
        cache->down_capacity = (uint64_t)settled_cap * down_expert_bytes;
        g_stream_host_expert_class_bytes[class_index] =
            cuda_stream_host_expert_cache_allocated_bytes(cache);
        return DS4_HOST_CACHE_DECODE_REFILL_SUCCEEDED;
    }

    /* Do not let decode-target metadata compete with the known-good fallback. */
    {
        std::vector<cuda_stream_host_expert_cache_slot> empty_slots;
        new_slots.swap(empty_slots);
    }
    gate_ptr = NULL;
    up_ptr = NULL;
    down_ptr = NULL;
    allocation_peak_bytes = 0;
    if (cuda_stream_host_expert_cache_try_alloc(
            old_cap,
            gate_expert_bytes,
            down_expert_bytes,
            allocator_was_pinned,
            &gate_ptr,
            &up_ptr,
            &down_ptr,
            &allocation_peak_bytes)) {
        cuda_stream_host_expert_cache_update_peak(
            other_class_bytes, allocation_peak_bytes, transient_peak_bytes);
        cache->valid = 1;
        cache->capacity = old_cap;
        cache->gate_ptr = gate_ptr;
        cache->up_ptr = up_ptr;
        cache->down_ptr = down_ptr;
        cache->gate_capacity = (uint64_t)old_cap * gate_expert_bytes;
        cache->up_capacity = (uint64_t)old_cap * gate_expert_bytes;
        cache->down_capacity = (uint64_t)old_cap * down_expert_bytes;
        g_stream_host_expert_class_bytes[class_index] =
            cuda_stream_host_expert_cache_allocated_bytes(cache);
        g_stream_host_expert_runtime_cap[class_index] = old_cap;
        g_stream_host_expert_cap_was_budget_derived[class_index] = 0;
        if (failure_reason) *failure_reason = target_failure;
        return DS4_HOST_CACHE_DECODE_REFILL_REBUILT_OLD_CAP;
    }

    cuda_stream_host_expert_cache_update_peak(
        other_class_bytes, allocation_peak_bytes, transient_peak_bytes);
    /* Preserve the physical-failure latch even though there are no usable
     * buffers. A later admission may rebuild at old_cap, but this decode edge
     * must never retry the failed budget-derived target. */
    g_stream_host_expert_runtime_cap[class_index] = old_cap;
    g_stream_host_expert_cap_was_budget_derived[class_index] = 0;
    if (failure_reason) {
        *failure_reason = target_metadata_failed ?
            "target metadata and old-capacity buffer allocations failed" :
            (!feasibility.measured ?
                "available-memory query and old-capacity buffer allocation failed" :
                (target_cap == 0 ?
                    "physical clamp selected zero and old-capacity buffer allocation failed" :
                    "target and old-capacity buffer allocations failed"));
    }
    return DS4_HOST_CACHE_DECODE_REFILL_EMERGENCY_INVALID;
}

static cuda_stream_host_expert_cache *cuda_stream_host_expert_cache_prepare(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        uint32_t target_cap) {
    const uint64_t expert_bytes =
        cuda_stream_expert_cache_expert_bytes(gate_expert_bytes,
                                              down_expert_bytes);
    if (expert_bytes == 0 || !cuda_stream_host_expert_cache_enabled()) {
        return NULL;
    }

    /* Route this shape to its own class cache. Mixed IQ2/Q2 + Q4 models (notably Flash 0731) cross
     * the shape boundary on every token; with a single cache the only safe policy was to refuse the
     * minority shape, which locked the Q4 experts out of host RAM. Per-class caches let both stay
     * resident, so neither can evict the other. */
    const uint32_t class_index =
        cuda_stream_host_expert_cache_class_index(gate_expert_bytes,
                                                  down_expert_bytes);
    cuda_stream_host_expert_cache *cache =
        &g_stream_host_expert_caches[class_index];

    const uint32_t configured_cap =
        cuda_stream_host_expert_cache_requested_budget();
    uint32_t requested_cap = cuda_stream_host_expert_cache_budget_cap(
        expert_bytes, g_prefill_pipeline_host_cache_charge_bytes);
    if (g_stream_host_expert_budget_bytes_override != 0) {
        /* The budget the user asked for is a TOTAL across classes, not per class -- on a 31 GB box
         * handing each class the full figure would double the host footprint. Split it evenly so
         * --ram-streaming-cache-experts NGB still means NGB of RAM in aggregate. */
        if (requested_cap == 0) return NULL;
        if (configured_cap == 0 || configured_cap > requested_cap) {
            if (!g_stream_host_expert_class_notice[class_index]) {
                g_stream_host_expert_class_notice[class_index] = 1;
                fprintf(stderr,
                        "ds4: CUDA RAM host cache class %u (%.2f MiB/expert) budget "
                        "%u experts / %.2f GiB\n",
                        class_index,
                        (double)expert_bytes / 1048576.0,
                        requested_cap,
                        (double)((uint64_t)requested_cap * expert_bytes) / 1073741824.0);
            }
        }
    }
    if (target_cap == 0 || target_cap > requested_cap) target_cap = requested_cap;
    int target_was_runtime_clamped = 0;
    if (g_stream_host_expert_runtime_cap[class_index] != 0 &&
        target_cap > g_stream_host_expert_runtime_cap[class_index]) {
        target_cap = g_stream_host_expert_runtime_cap[class_index];
        target_was_runtime_clamped = 1;
    }
    if (target_cap == 0) return NULL;

    const int same_dims =
        cache->valid &&
        cache->gate_expert_bytes == gate_expert_bytes &&
        cache->down_expert_bytes == down_expert_bytes;
    if (same_dims &&
        cache->capacity != 0 &&
        cache->capacity >= target_cap &&
        cache->slots.size() == cache->capacity) {
        return cache;
    }

    const int preserve_residency =
        same_dims &&
        cache->capacity != 0 &&
        cache->slots.size() == cache->capacity &&
        cache->gate_ptr && cache->up_ptr && cache->down_ptr;
    if (same_dims && !preserve_residency) {
        /* A malformed live cache cannot be copied safely.  The decode edge must
         * never turn that into a destructive reallocation. */
        fprintf(stderr,
                "ds4: CUDA RAM host cache class %u cannot grow in place; "
                "retaining %u experts and existing residency\n",
                class_index, cache->capacity);
        g_stream_host_expert_runtime_cap[class_index] = cache->capacity;
        g_stream_host_expert_cap_was_budget_derived[class_index] = 0;
        return cache;
    }
    const uint32_t old_capacity = preserve_residency ? cache->capacity : 0;
    uint32_t cap = target_cap;
    while (cap != 0) {
        if (preserve_residency && cap <= old_capacity) {
            /* Growing requires both generations to coexist until the copy is
             * complete.  If no larger candidate fits, retain the warm cache
             * and make the failure latch durable. */
            g_stream_host_expert_runtime_cap[class_index] = old_capacity;
            g_stream_host_expert_cap_was_budget_derived[class_index] = 0;
            fprintf(stderr,
                    "ds4: CUDA RAM host cache class %u growth retained at %u "
                    "experts / %.2f GiB preserved=%u (physically bounded)\n",
                    class_index,
                    old_capacity,
                    (double)((uint64_t)old_capacity * expert_bytes) / 1073741824.0,
                    cache->count);
            return cache;
        }
        if ((uint64_t)cap > UINT64_MAX / gate_expert_bytes ||
            (uint64_t)cap > UINT64_MAX / down_expert_bytes) {
            if (preserve_residency) return cache;
            return NULL;
        }

        std::vector<cuda_stream_host_expert_cache_slot> new_slots;
        try {
            new_slots.resize(cap);
        } catch (...) {
            const uint32_t new_cap =
                cuda_stream_host_expert_cache_shrunken_cap(cap);
            fprintf(stderr,
                    "ds4: CUDA RAM expert cache metadata allocation failed at "
                    "%u experts; retrying with %u experts\n",
                    cap, new_cap);
            cap = new_cap;
            continue;
        }
        char *gate_ptr = NULL;
        char *up_ptr = NULL;
        char *down_ptr = NULL;
        ds4_t1_mark("host_tier_pinned_alloc_start");
        if (!cuda_stream_host_expert_cache_try_alloc(cap,
                                                     gate_expert_bytes,
                                                     down_expert_bytes,
                                                     cuda_stream_host_expert_cache_pinned_enabled(),
                                                     &gate_ptr,
                                                     &up_ptr,
                                                     &down_ptr,
                                                     NULL)) {
            const uint32_t new_cap =
                cuda_stream_host_expert_cache_shrunken_cap(cap);
            cuda_model_load_progress_finish();
            fprintf(stderr,
                    "ds4: CUDA RAM expert cache allocation failed at %u experts "
                    "/ %.2f GiB; retrying with %u experts\n",
                    cap,
                    (double)((uint64_t)cap * expert_bytes) / 1073741824.0,
                    new_cap);
            cap = new_cap;
            continue;
        }

        ds4_t1_mark("host_tier_pinned_alloc_end");
        uint32_t preserved = 0;
        if (preserve_residency) {
            for (uint32_t i = 0; i < old_capacity; i++) {
                new_slots[i] = cache->slots[i];
                if (!cache->slots[i].valid) continue;
                const uint64_t gate_offset =
                    (uint64_t)i * gate_expert_bytes;
                const uint64_t down_offset =
                    (uint64_t)i * down_expert_bytes;
                memcpy(gate_ptr + gate_offset,
                       cache->gate_ptr + gate_offset,
                       (size_t)gate_expert_bytes);
                memcpy(up_ptr + gate_offset,
                       cache->up_ptr + gate_offset,
                       (size_t)gate_expert_bytes);
                memcpy(down_ptr + down_offset,
                       cache->down_ptr + down_offset,
                       (size_t)down_expert_bytes);
                preserved++;
            }
        }

        char *old_gate_ptr = cache->gate_ptr;
        char *old_up_ptr = cache->up_ptr;
        char *old_down_ptr = cache->down_ptr;
        cache->slots.swap(new_slots);
        cache->valid = 1;
        cache->capacity = cap;
        cache->count = preserve_residency ? preserved : 0;
        if (!preserve_residency) cache->tick = 0;
        cache->gate_expert_bytes = gate_expert_bytes;
        cache->down_expert_bytes = down_expert_bytes;
        cache->gate_ptr = gate_ptr;
        cache->up_ptr = up_ptr;
        cache->down_ptr = down_ptr;
        cache->gate_capacity =
            (uint64_t)cap * gate_expert_bytes;
        cache->up_capacity =
            (uint64_t)cap * gate_expert_bytes;
        cache->down_capacity =
            (uint64_t)cap * down_expert_bytes;
        /* Only after the new buffers and all resident slots are committed is it
         * safe to free the old generation. */
        cuda_stream_host_expert_cache_free_buffers(
            old_gate_ptr, old_up_ptr, old_down_ptr);
        g_stream_host_expert_runtime_cap[class_index] = cap;
        g_stream_host_expert_cap_was_budget_derived[class_index] =
            !target_was_runtime_clamped && cap == target_cap;
        g_stream_host_expert_class_bytes[class_index] =
            (uint64_t)cap * expert_bytes;
        cuda_model_load_progress_finish();
        {
            uint64_t total_bytes = 0;
            for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
                total_bytes += g_stream_host_expert_class_bytes[i];
            }
            if (preserve_residency) {
                fprintf(stderr,
                        "ds4: CUDA RAM expert cache class %u grew %u -> %u "
                        "experts / %.2f GiB preserved=%u "
                        "(%.2f MiB/expert; all classes %.2f GiB)\n",
                        class_index,
                        old_capacity,
                        cap,
                        (double)((uint64_t)cap * expert_bytes) / 1073741824.0,
                        preserved,
                        (double)expert_bytes / 1048576.0,
                        (double)total_bytes / 1073741824.0);
            } else {
                fprintf(stderr,
                        "ds4: CUDA RAM expert cache class %u allocated %u experts / %.2f GiB "
                        "(%.2f MiB/expert; all classes %.2f GiB)\n",
                        class_index,
                        cap,
                        (double)((uint64_t)cap * expert_bytes) / 1073741824.0,
                        (double)expert_bytes / 1048576.0,
                        (double)total_bytes / 1073741824.0);
            }
        }
        return cache;
    }
    return NULL;
}

static int cuda_stream_host_expert_cache_find(
        cuda_stream_host_expert_cache *cache,
        const void *model_map,
        uint64_t model_size,
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t expert,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (!cache || !cache->valid) return -1;
    for (uint32_t i = 0; i < cache->capacity; i++) {
        const cuda_stream_host_expert_cache_slot &slot = cache->slots[i];
        if (cuda_stream_expert_slot_matches(slot, model_map, model_size, layer,
                n_total_expert, expert, gate_offset, up_offset, down_offset,
                gate_expert_bytes, down_expert_bytes)) {
            return (int)i;
        }
    }
    return -1;
}

static uint32_t cuda_stream_host_expert_cache_lru_slot(
        cuda_stream_host_expert_cache *cache) {
    /* [2026-08-24] Ranking this by route hotness without a lifetime barrier was unsafe.
     * See .planning/HOTNESS_EVICT_REVIEW.md. The host cache has no slot-lifetime protection:
     * get_slot() can return a slot whose H2D copy is DEFERRED into a merged run, and a later miss
     * in the same run could evict and overwrite it before the copy reads it (ds4_cuda.cu run-flush
     * path). LRU's protection is incidental but real - a returned slot is stamped NEWEST, so LRU
     * does not reuse it during the unconsumed interval. Any hotness ordering discards that.
     * The opt-in LFU path now flushes deferred runs before either cache can
     * admit the next expert; synchronous cache uploads consume their source
     * immediately. The shipped LRU path keeps its existing run merging. */
    for (uint32_t i = 0; i < cache->capacity; i++) {
        if (!cache->slots[i].valid) return i;
    }
    uint32_t slot = 0;
    uint64_t best_age = cache->slots[0].age;
    for (uint32_t i = 1; i < cache->capacity; i++) {
        if (cuda_stream_cache_older_or_colder(
                cache->slots[i].layer, cache->slots[i].expert, cache->slots[i].age,
                cache->slots[slot].layer, cache->slots[slot].expert, best_age)) {
            best_age = cache->slots[i].age;
            slot = i;
        }
    }
    return slot;
}

#if defined(_WIN32)
/* ---- Batched expert prefetch -------------------------------------------------------------------
 *
 * The router picks every expert for a layer at once, so all of that layer's disk reads are known
 * before the first one is issued -- yet they were issued one blocking pread at a time, three per
 * missed expert. Measured on this box: the array sat at 93.8% duty cycle while delivering 7.5% of
 * its 24 GB/s, the signature of a single outstanding request.
 *
 * This prefetches a layer's misses as ONE DirectStorage batch into a bounded arena, then lets the
 * existing serial loop run untouched -- cuda_model_read_to_host() finds each span already in the
 * arena and memcpy's it instead of going to disk.
 *
 * Injecting here rather than restructuring the loop is deliberate. A three-pass planner would have
 * to reserve cache victims before any load completes, and cuda_stream_expert_cache_lru_slot() bumps
 * `age` only on COMPLETION -- so it would hand out the same victim slot repeatedly and silently
 * overwrite experts. It would also have to stop a miss from evicting a slot that is a hit for the
 * same batch but not yet copied out. The arena touches neither cache's LRU, so neither hazard can
 * occur, and the disk win is the same.
 *
 * Measured, scattered 8 MiB reads, median of 6: pread 3.05 GB/s, DS QD1 4.45, DS batch-64 7.2. */
struct cuda_ds_prefetch_span {
    const void *model_map;   /* which model these bytes came from -- see the guard in find() */
    uint64_t offset;
    uint64_t bytes;
    uint64_t arena_off;
    int gpu_destination;
    int decode_pipeline_slot; /* -1 for legacy/token-transient ownership */
};
static char                                   *g_ds_prefetch_arena     = NULL;
static uint64_t                                g_ds_prefetch_capacity  = 0;
static char                                   *g_ds_gpu_prefetch_arena = NULL;
static uint64_t                                g_ds_gpu_prefetch_capacity = 0;
static uint64_t                                g_ds_prefetch_used      = 0;
static std::vector<cuda_ds_prefetch_span>      g_ds_prefetch_spans;
static uint64_t                                g_ds_prefetch_hits      = 0;
static uint64_t                                g_ds_prefetch_batches   = 0;
static uint64_t                                g_ds_prefetch_bytes     = 0;
static double                                  g_ds_prefetch_ms        = 0.0;
static int                                     g_ds_prefetch_disabled  = 0;
static int                                     g_ds_gpu_prefetch_disabled = 0;

/* R4: two compute-owned full-expert-table slots. Each layer publishes the
 * exact D3D fence value for its own DirectStorage wave, and the consuming CUDA
 * stream waits on that external fence directly. Slot reuse is gated by the
 * prior layer's own compute_done event; the polling happens on the scheduler
 * thread, never on the layer-driving host thread. Two slots are sufficient for
 * the only overlap we need: loading layer N+1 while layer N computes. */
#define DS4_CUDA_PREFILL_PIPELINE_SLOTS 2u
static_assert(DS4_CUDA_PREFILL_PIPELINE_SLOTS >= 2u,
              "prefill pipeline requires alternating compute slots");
