static cuda_ds_decode_pipeline_state g_ds_decode_pipeline = {};

/* Effective decode transport bandwidth is measured over the union wall
 * interval from the token's first DirectStorage submit through its final
 * completion. Summing submit-to-completion latency double-counts overlap. */
struct cuda_ds_decode_bandwidth_state {
    int active;
    uint64_t token;
    uint64_t issued;
    uint64_t completed;
    double first_submit_ms;
    uint64_t phase_waves;
    double phase_setup_ms;
    double phase_bookkeeping_ms;
    double phase_sync_ms;
    double phase_plan_ms;
    double phase_submit_ms;
    double phase_wait_ms;
    double phase_copy_ms;
    double phase_retire_ms;
    double phase_teardown_ms;

    int interval_open() const {
        return active && issued != 0;
    }

    double phase_accounted_ms() const {
        return phase_setup_ms + phase_bookkeeping_ms + phase_sync_ms +
               phase_plan_ms + phase_submit_ms + phase_wait_ms +
               phase_copy_ms + phase_retire_ms + phase_teardown_ms;
    }

    /* Attribute only the part of an outer scope not already claimed by a
     * nested phase. A scope entered before the first successful submit starts
     * at first_submit_ms, keeping pre-submit token planning outside the union. */
    void phase_end_exclusive(
            double start_ms,
            double accounted_before_ms,
            double *phase_ms) {
        if (!phase_ms || !interval_open()) return;
        if (start_ms == 0.0) start_ms = first_submit_ms;
        const double elapsed_ms = cuda_decode_profile_now_ms() - start_ms;
        double nested_ms = phase_accounted_ms() - accounted_before_ms;
        if (nested_ms < 0.0) nested_ms = 0.0;
        if (elapsed_ms > nested_ms) *phase_ms += elapsed_ms - nested_ms;
    }

    void begin(uint64_t token_index) {
        if (active) {
            fprintf(stderr,
                    "ds4: decode DirectStorage bandwidth token %llu was not retired "
                    "before token %llu began (issued=%llu completed=%llu)\n",
                    (unsigned long long)token,
                    (unsigned long long)token_index,
                    (unsigned long long)issued,
                    (unsigned long long)completed);
        }
        *this = {};
        active = 1;
        token = token_index;
    }

    void note_issued(uint64_t bytes, double submit_t0_ms) {
        if (!active || bytes == 0) return;
        if (issued == 0) first_submit_ms = submit_t0_ms;
        issued += bytes;
        g_decode_profile.decode_ds_bytes_issued += bytes;
    }

    void note_completed(uint64_t bytes) {
        if (!active || bytes == 0) return;
        completed += bytes;
        g_decode_profile.decode_ds_bytes_completed += bytes;
    }

    int batch_submit() {
        const uint64_t bytes = ds4_ds_batch_bytes();
        const double submit_t0_ms = active && bytes != 0 ?
            cuda_decode_profile_now_ms() : 0.0;
        const int ok = ds4_ds_batch_submit();
        if (ok && bytes != 0) {
            const double submit_ms =
                cuda_decode_profile_now_ms() - submit_t0_ms;
            note_issued(bytes, submit_t0_ms);
            if (submit_ms > 0.0) phase_submit_ms += submit_ms;
            phase_waves++;
        }
        return ok;
    }

    int batch_wait(
            uint64_t *out_bytes,
            double *out_ms,
            double *out_wait_ms) {
        const double wait_t0_ms = interval_open() ?
            cuda_decode_profile_now_ms() : 0.0;
        double measured_wait_ms = 0.0;
        const int ok = ds4_ds_batch_wait(
            out_bytes, out_ms, &measured_wait_ms);
        if (out_wait_ms) *out_wait_ms = measured_wait_ms;
        if (ok && wait_t0_ms != 0.0) {
            const double call_ms =
                cuda_decode_profile_now_ms() - wait_t0_ms;
            const double wait_ms = measured_wait_ms > 0.0 ?
                std::min(measured_wait_ms, call_ms) : 0.0;
            phase_wait_ms += wait_ms;
            if (call_ms > wait_ms) phase_retire_ms += call_ms - wait_ms;
            if (out_bytes) note_completed(*out_bytes);
        }
        return ok;
    }

    int batch_submit_wait(
            uint64_t *out_bytes,
            double *out_ms,
            double *out_wait_ms) {
        const uint64_t bytes = ds4_ds_batch_bytes();
        const double submit_t0_ms = active && bytes != 0 ?
            cuda_decode_profile_now_ms() : 0.0;
        double measured_wait_ms = 0.0;
        const int ok = ds4_ds_batch_submit_wait(
            out_bytes, out_ms, &measured_wait_ms);
        if (out_wait_ms) *out_wait_ms = measured_wait_ms;
        if (ok && bytes != 0) {
            const double call_ms =
                cuda_decode_profile_now_ms() - submit_t0_ms;
            const double wait_ms = measured_wait_ms > 0.0 ?
                std::min(measured_wait_ms, call_ms) : 0.0;
            note_issued(bytes, submit_t0_ms);
            note_completed(bytes);
            phase_wait_ms += wait_ms;
            if (call_ms > wait_ms) phase_submit_ms += call_ms - wait_ms;
            phase_waves++;
        }
        return ok;
    }

    void end() {
        if (!active) return;
        if (issued != 0) {
            const double elapsed_ms =
                cuda_decode_profile_now_ms() - first_submit_ms;
            if (elapsed_ms > 0.0) {
                const double phase_sum_ms = phase_accounted_ms();
                g_decode_profile.decode_ds_elapsed_ms += elapsed_ms;
                g_decode_profile.decode_ds_phase_waves += phase_waves;
                g_decode_profile.decode_ds_phase_setup_ms += phase_setup_ms;
                g_decode_profile.decode_ds_phase_bookkeeping_ms +=
                    phase_bookkeeping_ms;
                g_decode_profile.decode_ds_phase_sync_ms += phase_sync_ms;
                g_decode_profile.decode_ds_phase_plan_ms += phase_plan_ms;
                g_decode_profile.decode_ds_phase_submit_ms += phase_submit_ms;
                g_decode_profile.decode_ds_phase_wait_ms += phase_wait_ms;
                g_decode_profile.decode_ds_phase_copy_ms += phase_copy_ms;
                g_decode_profile.decode_ds_phase_retire_ms += phase_retire_ms;
                g_decode_profile.decode_ds_phase_teardown_ms +=
                    phase_teardown_ms;
                g_decode_profile.decode_ds_phase_uncovered_ms +=
                    elapsed_ms > phase_sum_ms ? elapsed_ms - phase_sum_ms : 0.0;
            }
        }
        active = 0;
    }
};
static cuda_ds_decode_bandwidth_state g_ds_decode_bandwidth = {};

/* One steady-clock read on entry and exit, never per expert. Nested scopes
 * are made disjoint by subtracting phases that completed inside the scope. */
struct cuda_ds_phase_scope {
    double *phase_ms;
    double start_ms;
    double accounted_before_ms;

    explicit cuda_ds_phase_scope(double *phase)
        : phase_ms(phase),
          start_ms(g_ds_decode_bandwidth.interval_open() ?
                       cuda_decode_profile_now_ms() : 0.0),
          accounted_before_ms(g_ds_decode_bandwidth.phase_accounted_ms()) {}

    ~cuda_ds_phase_scope() {
        g_ds_decode_bandwidth.phase_end_exclusive(
            start_ms, accounted_before_ms, phase_ms);
    }
};

/* Exact tid2eid routes let the token-wide hot-prefetch batch become a true
 * layer pipeline.  Keep private copies because the caller's tables and rows
 * are stack storage.  `current` names the one submitted layer; advancing it
 * happens only after that layer's selected weights have been copied out of
 * the DirectStorage arena. */
struct cuda_ds_hash_pipeline_state {
    int                         active;
    uint32_t                    count;
    uint32_t                    current;
    uint32_t                    next_submit;
    int                         current_drained;
    uint8_t                     submitted[DS4_CUDA_HASH_PIPELINE_MAX_LAYERS];
    ds4_gpu_stream_expert_table tables[DS4_CUDA_HASH_PIPELINE_MAX_LAYERS];
    int32_t                     selected[DS4_CUDA_HASH_PIPELINE_MAX_LAYERS]
                                                [DS4_CUDA_HASH_PIPELINE_MAX_SELECTED];
};
static cuda_ds_hash_pipeline_state g_ds_hash_pipeline = {};
struct cuda_ds_hash_pipeline_stats {
    uint64_t tokens;
    uint64_t waits[DS4_CUDA_HASH_PIPELINE_MAX_LAYERS];
    double   batch_ms[DS4_CUDA_HASH_PIPELINE_MAX_LAYERS];
    double   wait_ms[DS4_CUDA_HASH_PIPELINE_MAX_LAYERS];
    uint32_t layer[DS4_CUDA_HASH_PIPELINE_MAX_LAYERS];
};
static cuda_ds_hash_pipeline_stats g_ds_hash_pipeline_stats = {};

static void cuda_ds_hash_pipeline_stats_dump(void) {
    if (g_ds_hash_pipeline_stats.tokens == 0) return;
    fprintf(stderr,
            "ds4: CUDA hash-layer pipeline totals: tokens=%llu\n",
            (unsigned long long)g_ds_hash_pipeline_stats.tokens);
    for (uint32_t i = 0; i < DS4_CUDA_HASH_PIPELINE_MAX_LAYERS; i++) {
        const uint64_t waits = g_ds_hash_pipeline_stats.waits[i];
        if (waits == 0) continue;
        const double batch_ms = g_ds_hash_pipeline_stats.batch_ms[i];
        const double wait_ms = g_ds_hash_pipeline_stats.wait_ms[i];
        fprintf(stderr,
                "ds4: CUDA hash-layer pipeline layer=%u waits=%llu "
                "batch_ms=%.3f wait_ms=%.3f blocked=%.1f%%\n",
                g_ds_hash_pipeline_stats.layer[i],
                (unsigned long long)waits,
                batch_ms,
                wait_ms,
                batch_ms > 0.0 ? 100.0 * wait_ms / batch_ms : 0.0);
    }
}
