/* Optional next-layer RAM -> VRAM promotion.  It occupies a disjoint tail of
 * the DirectStorage GPU arena, so pinned-H2D and SSD->GPU can run together
 * without allocating a second transient VRAM slab or overwriting each other. */
/* [2026-08-18] RAISED 16 -> 256, i.e. a WHOLE LAYER.
 *
 * 16 experts is ~6% of a 256-expert layer, which cannot move the hit rate no matter how accurate the
 * prediction is - the promotion has to cover a large FRACTION of the layer to matter. At 6.75 MiB an
 * expert, a full layer is 1.7 GiB; the old ceiling was 16 experts = 108 MiB, and it was consistent
 * with the other two caps below it (the MB knob stopped at 192 and the arena it lives in was 256 MiB),
 * so all three had to move together or the request is silently clamped.
 *
 * This only sizes an index array; the memory that matters is the arena, which is capped separately. */
#define DS4_CUDA_RAM_HOT_PREFETCH_MAX 256u
struct cuda_ram_hot_prefetch_state {
    int active;
    int ready_waited;
    const void *model_map;
    uint64_t model_size;
    uint32_t layer;
    uint32_t n_total_expert;
    uint64_t gate_offset;
    uint64_t up_offset;
    uint64_t down_offset;
    uint64_t gate_expert_bytes;
    uint64_t down_expert_bytes;
    uint32_t count;
    int32_t experts[DS4_CUDA_RAM_HOT_PREFETCH_MAX];
    cudaStream_t stream;
    cudaEvent_t ready;
};
static cuda_ram_hot_prefetch_state g_ram_hot_prefetch = {};
static uint64_t g_ram_hot_prefetch_launched = 0;
static uint64_t g_ram_hot_prefetch_hits = 0;

static uint32_t cuda_ram_hot_prefetch_k(void) {
    static int initialized = 0;
    static uint32_t value = 0;
    if (!initialized) {
        const char *env = getenv("DS4_CUDA_RAM_PREFETCH_K");
        if (env && env[0]) {
            char *end = NULL;
            const unsigned long parsed = strtoul(env, &end, 10);
            if (end != env && end && *end == '\0') {
                value = parsed > DS4_CUDA_RAM_HOT_PREFETCH_MAX ?
                    DS4_CUDA_RAM_HOT_PREFETCH_MAX : (uint32_t)parsed;
            }
        }
        initialized = 1;
        if (value != 0) {
            fprintf(stderr,
                    "ds4: CUDA next-layer RAM hot prefetch K=%u\n",
                    value);
        }
    }
    return value;
}

static uint64_t cuda_ram_hot_prefetch_reserve_bytes(void) {
    if (cuda_ram_hot_prefetch_k() == 0) return 0;
    uint64_t mb = 64;
    const char *env = getenv("DS4_CUDA_RAM_PREFETCH_MB");
    if (env && env[0]) {
        char *end = NULL;
        const unsigned long parsed = strtoul(env, &end, 10);
        /* Upper bound raised 192 -> 3072 alongside DS4_CUDA_RAM_HOT_PREFETCH_MAX, so a large fraction
         * of a layer can actually be promoted: 256 experts x 6.75 MiB = 1728 MiB for a whole layer on
         * the IQ2 class, more on the Q4_K tail. The bound must stay <= the DirectStorage GPU arena this
         * reserve is carved from (DS4_CUDA_DS_DIRECT_MB), or the promotion silently gets nothing.
         *
         * NOTE the rejection is SILENT: a value outside the range falls back to the 64 MiB default with
         * no warning, which cost this project a void run when 256 was passed against the old 192 cap.
         * Warn instead of failing quietly. */
        if (end != env && end && *end == '\0' && parsed >= 16 && parsed <= 3072) {
            mb = (uint64_t)parsed;
        } else {
            fprintf(stderr,
                    "ds4: DS4_CUDA_RAM_PREFETCH_MB=%s ignored (accepted range 16..3072 MiB); "
                    "using %llu MiB\n",
                    env, (unsigned long long)mb);
        }
    }
    return mb * 1048576ull;
}

static uint64_t cuda_ds_gpu_ssd_capacity(void) {
    const uint64_t reserve = cuda_ram_hot_prefetch_reserve_bytes();
    return g_ds_gpu_prefetch_capacity > reserve ?
        g_ds_gpu_prefetch_capacity - reserve : 0;
}

static uint64_t cuda_ds_prefetch_capacity_bytes(void) {
    /* Default sized to hold a WHOLE layer's misses.
     *
     * Measured on DSV4-Flash 0731, clean GPU, identical prompt and -n:
     *     256 MiB  (37 experts, truncates)  decode 4.09 / 4.17 / 4.06 / 3.99  prefill 1.07
     *     512 MiB  (75 experts, truncates)  decode 3.69                       prefill 1.20
     *    1024 MiB  (whole layer, no trunc)  decode 4.22 / 4.33                prefill 1.21
     *
     * The dip at 512 is the tell: PARTIAL batching is worse than either extreme, because the layer
     * pays the synchronous batch stall AND still issues serial preads for whatever did not fit.
     * Covering the layer removes that mixed path entirely.
     *
     * Host-RAM budget on the 31.4 GB box: 1 GiB arena + 256 MiB DirectStorage staging + the host
     * expert cache (6 GB at the settings used) ~= 7.3 GB, all explicitly bounded and none of it
     * scaling with model size. Free RAM measured flat at 21.7 GB across these runs.
     *
     * [2026-08-15] RAISED 1024 -> 1792 MiB. The 1024 figure above was tuned on DECODE, where one
     * token activates few experts and 1024 MiB really did cover them. PREFILL activates close to the
     * whole 256-expert union of a layer (GGUF: deepseek4.expert_count=256), so at 1024 MiB the engine
     * logged "held 151 experts of this layer; the remainder use serial reads" -- i.e. prefill sat in
     * exactly the PARTIAL-batching regime the note above identifies as the worst case. A full normal
     * layer is 256 x 6.75 MiB = 1728 MiB, so 1792 covers it and the truncation warning disappears.
     *
     * Measured at a 4096-token prompt (on the ~86 t/s plateau, so the fixed first-chunk cost is
     * already amortised), 3 runs each, VRAM 32607 MiB before AND after every run:
     *    1024 MiB   83.91 / 82.94 / 83.31  -> mean 83.39 t/s prefill
     *    1792 MiB   91.44 / 90.15 / 92.24  -> mean 91.28 t/s  (+9.5%)
     *    3584 MiB   97.45 / 91.62 / 90.69  -> mean 93.25 t/s  (+11.8%, spread 90.7-97.5)
     * The third run of each was taken in REVERSED order; 1024 was still slowest running LAST, with
     * the most page-cache warmth, which is what rules out drift rather than the repetition alone.
     *
     * 3584 (a full Q4 layer, 256 x 13.50 MiB) has a slightly higher mean but a much wider spread and
     * costs another 1.75 GB of host RAM on a 31.4 GB box for ~2 points. 1792 is the principled value:
     * it is exactly one full normal layer, it is tight run-to-run, and it removes the mixed path. */
    uint64_t mb = 1792;
    const char *env = getenv("DS4_CUDA_DS_PREFETCH_MB");
    if (env && env[0]) {
        char *end = NULL;
        unsigned long v = strtoul(env, &end, 10);
        if (end != env && end && *end == '\0' && v >= 16 && v <= 4096) mb = (uint64_t)v;
    }
    return mb * 1048576ull;
}

static int cuda_ds_prefetch_enabled(void) {
    if (g_ds_prefetch_disabled) return 0;
    const char *env = getenv("DS4_CUDA_DISK_IO");
    if (env && env[0] && strcmp(env, "pread") == 0) return 0;   /* explicit opt-out, never silent */
    return 1;
}

static int cuda_r4_selective_prepass_enabled(void) {
    /* Default ON: set DS4_CUDA_R4_SELECTIVE_PREPASS=0 only for the old wholesale-gate A/B arm. */
    static const int enabled =
        cuda_env_flag_enabled("DS4_CUDA_R4_SELECTIVE_PREPASS", 1);
    return enabled;
}

static void cuda_ds_prefetch_reset(void) {
    g_ds_prefetch_used = 0;
    g_ds_prefetch_spans.clear();
    g_ds_hot_prefetch_used = 0;
    g_ds_hot_prefetch_spans = 0;
}

static void cuda_ds_prefetch_reset_transient(void) {
    if (g_ds_decode_pipeline.active) {
        /* The current layer still owns its ring region until advance(), and
         * future layers own the other live regions. */
        return;
    }
    if (!g_ds_hot_prefetch_active) {
        cuda_ds_prefetch_reset();
        return;
    }
    g_ds_prefetch_used = g_ds_hot_prefetch_used;
    if (g_ds_prefetch_spans.size() > g_ds_hot_prefetch_spans) {
        g_ds_prefetch_spans.resize(g_ds_hot_prefetch_spans);
    }
}

static void cuda_ds_decode_pipeline_slot_reset(uint32_t slot_index) {
    if (slot_index >= DS4_CUDA_DECODE_PIPELINE_MAX_DEPTH) return;
    cuda_ds_phase_scope retire_scope(&g_ds_decode_bandwidth.phase_retire_ms);
    g_ds_prefetch_spans.erase(
        std::remove_if(g_ds_prefetch_spans.begin(), g_ds_prefetch_spans.end(),
                       [slot_index](const cuda_ds_prefetch_span &span) {
                           return span.decode_pipeline_slot == (int)slot_index;
                       }),
        g_ds_prefetch_spans.end());
    g_ds_decode_pipeline.slots[slot_index].used = 0;
}

/* Linear scan, and the cost is O(spans^2) per layer — sized deliberately, not by accident.
 *
 * ⚠️ This comment previously read "a few dozen spans at most", which was true at the original 256 MiB
 * arena (37 experts x 3 reads = ~111 spans) and became WRONG when the default was raised to 1024 MiB
 * to cover a whole layer: that stages roughly 150 experts x 3 = ~450 spans, and the lookup runs once
 * per read, so ~450 lookups x up to 450 comparisons per layer.
 *
 * Order 10^5 trivial uint64 compares per layer over sequential memory is still small against a layer
 * that is waiting on multi-megabyte disk reads, so a hash map is not obviously a win and has not been
 * measured. Left as-is on purpose.
 *
 * BUT it is quadratic in arena size. If the arena grows well beyond one layer — which the speculative
 * next-layer prefetch design would do — this stops being negligible and should become a hash map or
 * an ordered probe keyed on the staging order (reads follow staging order closely, so a rolling hint
 * index would likely suffice). Measure before changing it. */
static const cuda_ds_prefetch_span *cuda_ds_prefetch_find_span(
        const void *model_map, uint64_t offset, uint64_t bytes) {
    for (size_t i = 0; i < g_ds_prefetch_spans.size(); i++) {
        /* model_map must match. Keying on (offset,bytes) alone would let a read for a DIFFERENT
         * model be served from this arena whenever the pair happened to collide -- silent data
         * corruption. ds4.c loads a second model through ds4_gpu_set_model_fd_for_map() with its own
         * fd and base, and DSpark's support model arrives exactly that way via --mtp, so this is a
         * live path rather than a theoretical one. */
        if (g_ds_prefetch_spans[i].model_map == model_map &&
            g_ds_prefetch_spans[i].offset == offset && g_ds_prefetch_spans[i].bytes == bytes) {
            return &g_ds_prefetch_spans[i];
        }
    }
    return NULL;
}

static const char *cuda_ds_prefetch_find(
        const void *model_map, uint64_t offset, uint64_t bytes) {
    const cuda_ds_prefetch_span *span =
        cuda_ds_prefetch_find_span(model_map, offset, bytes);
    if (!span || span->gpu_destination || !g_ds_prefetch_arena) return NULL;
    return g_ds_prefetch_arena + span->arena_off;
}

static int cuda_ds_prefetch_copy_expert_to_device(
        char *gate_dst,
        char *up_dst,
        char *down_dst,
        const void *model_map,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_bytes,
        uint64_t down_bytes,
        int allow_host_destination = 0) {
    const cuda_ds_prefetch_span *gate =
        cuda_ds_prefetch_find_span(model_map, gate_offset, gate_bytes);
    const cuda_ds_prefetch_span *up =
        cuda_ds_prefetch_find_span(model_map, up_offset, gate_bytes);
    const cuda_ds_prefetch_span *down =
        cuda_ds_prefetch_find_span(model_map, down_offset, down_bytes);
    if (!gate || !up || !down ||
        gate->gpu_destination != up->gpu_destination ||
        gate->gpu_destination != down->gpu_destination) return 0;
    const int gpu = gate->gpu_destination;
    if (!gpu && !allow_host_destination) return 0;
    const char *arena = gpu ? g_ds_gpu_prefetch_arena : g_ds_prefetch_arena;
    if (!arena) return 0;
    const cudaMemcpyKind kind = gpu ? cudaMemcpyDeviceToDevice : cudaMemcpyHostToDevice;
    if (!cuda_ok(cuda_decode_profile_arena_memcpy(
                            gate_dst, arena + gate->arena_off,
                            (size_t)gate_bytes, kind),
                 "DirectStorage GPU gate expert placement") ||
        !cuda_ok(cuda_decode_profile_arena_memcpy(
                            up_dst, arena + up->arena_off,
                            (size_t)gate_bytes, kind),
                 "DirectStorage GPU up expert placement") ||
        !cuda_ok(cuda_decode_profile_arena_memcpy(
                            down_dst, arena + down->arena_off,
                            (size_t)down_bytes, kind),
                 "DirectStorage GPU down expert placement")) {
        return -1;
    }
    g_ds_prefetch_hits += 3;
    if (cuda_decode_profile_enabled()) {
        g_decode_profile.ssd_bytes += gate_bytes * 2ull + down_bytes;
    }
    return 1;
}

static int cuda_ds_prefetch_stage(
        const void *model_map, uint64_t offset, uint64_t bytes, int gpu_destination) {
    const uint64_t capacity = gpu_destination ?
        cuda_ds_gpu_ssd_capacity() : g_ds_prefetch_capacity;
    if (bytes == 0 || bytes > capacity) return 0;
    if (cuda_ds_prefetch_find_span(model_map, offset, bytes) != NULL) return 1;
    uint64_t arena_off = g_ds_prefetch_used;
    int decode_pipeline_slot = -1;
    if (g_ds_decode_pipeline.active &&
        g_ds_decode_pipeline.staging_slot >= 0) {
        decode_pipeline_slot = g_ds_decode_pipeline.staging_slot;
        cuda_ds_decode_pipeline_slot &slot =
            g_ds_decode_pipeline.slots[(uint32_t)decode_pipeline_slot];
        if (bytes > slot.capacity || slot.used > slot.capacity - bytes ||
            slot.arena_offset > capacity ||
            slot.used > capacity - slot.arena_offset ||
            bytes > capacity - slot.arena_offset - slot.used) return 0;
        arena_off = slot.arena_offset + slot.used;
    } else if (g_ds_prefetch_used > capacity - bytes) {
        return 0;
    }
    if (gpu_destination) {
        if (!ds4_ds_batch_add_gpu(offset, (uint32_t)bytes, arena_off)) return 0;
    } else {
        char *dst = g_ds_prefetch_arena + arena_off;
        if (!ds4_ds_batch_add(offset, (uint32_t)bytes, dst)) return 0;
    }
    cuda_ds_prefetch_span span;
    span.model_map = model_map;
    span.offset    = offset;
    span.bytes     = bytes;
    span.arena_off = arena_off;
    span.gpu_destination = gpu_destination;
    span.decode_pipeline_slot = decode_pipeline_slot;
    g_ds_prefetch_spans.push_back(span);
    if (decode_pipeline_slot >= 0) {
        g_ds_decode_pipeline.slots[(uint32_t)decode_pipeline_slot].used += bytes;
    } else {
        g_ds_prefetch_used += bytes;
    }
    return 1;
}

/* Freeze a cache hit into the immutable hot-prefetch arena.  Without this
 * snapshot, planning L+1 before loading L is racy with the cache itself: L can
 * evict an entry that L+1 classified as resident, forcing an unplanned tail
 * batch after the future FIFO slots have already been filled. */
static int cuda_ds_prefetch_snapshot_span(
        const void *model_map,
        uint64_t offset,
        uint64_t bytes,
        const char *source,
        cudaMemcpyKind kind,
        const char *what) {
    const int host_pipeline_destination =
        g_ds_decode_pipeline.active &&
        g_ds_decode_pipeline.staging_slot >= 0 &&
        !g_ds_decode_pipeline.use_gpu_destination;
    const uint64_t capacity = host_pipeline_destination ?
        g_ds_prefetch_capacity : cuda_ds_gpu_ssd_capacity();
    char *arena = host_pipeline_destination ?
        g_ds_prefetch_arena : g_ds_gpu_prefetch_arena;
    if (!arena || !source || bytes == 0 || bytes > capacity) {
        return 0;
    }
    if (cuda_ds_prefetch_find_span(model_map, offset, bytes) != NULL) return 1;
    uint64_t arena_off = g_ds_prefetch_used;
    int decode_pipeline_slot = -1;
    if (g_ds_decode_pipeline.active &&
        g_ds_decode_pipeline.staging_slot >= 0) {
        decode_pipeline_slot = g_ds_decode_pipeline.staging_slot;
        cuda_ds_decode_pipeline_slot &slot =
            g_ds_decode_pipeline.slots[(uint32_t)decode_pipeline_slot];
        if (bytes > slot.capacity || slot.used > slot.capacity - bytes ||
            slot.arena_offset > capacity ||
            slot.used > capacity - slot.arena_offset ||
            bytes > capacity - slot.arena_offset - slot.used) return 0;
        arena_off = slot.arena_offset + slot.used;
    } else if (g_ds_prefetch_used > capacity - bytes) {
        return 0;
    }
    if (host_pipeline_destination) {
        if (kind == cudaMemcpyDeviceToDevice) {
            if (!cuda_ok(cudaMemcpy(arena + arena_off, source, (size_t)bytes,
                                    cudaMemcpyDeviceToHost), what)) {
                return 0;
            }
        } else {
            memcpy(arena + arena_off, source, (size_t)bytes);
        }
    } else {
        if (!cuda_ok(cudaMemcpy(arena + arena_off, source,
                                (size_t)bytes, kind), what)) {
            return 0;
        }
    }
    cuda_ds_prefetch_span span;
    span.model_map = model_map;
    span.offset = offset;
    span.bytes = bytes;
    span.arena_off = arena_off;
    span.gpu_destination = host_pipeline_destination ? 0 : 1;
    span.decode_pipeline_slot = decode_pipeline_slot;
    g_ds_prefetch_spans.push_back(span);
    if (decode_pipeline_slot >= 0) {
        g_ds_decode_pipeline.slots[(uint32_t)decode_pipeline_slot].used += bytes;
    } else {
        g_ds_prefetch_used += bytes;
    }
    return 1;
}
#else
static int cuda_ds_prefetch_copy_expert_to_device(
        char *, char *, char *, const void *,
        uint64_t, uint64_t, uint64_t, uint64_t, uint64_t, int = 0) {
    return 0;
}
#endif  /* _WIN32 */

static int cuda_model_read_to_host(
        char *dst,
        const void *model_map,
        uint64_t model_size,
        uint64_t offset,
        uint64_t bytes,
        const char *what) {
    if (!dst || !model_map || offset > model_size || bytes > model_size - offset) {
        return 0;
    }
    if (bytes == 0) return 1;
#if defined(_WIN32)
    if (g_prefill_pipeline_resident_spans) {
        const char *resident =
            cuda_model_resident_range_ptr(model_map, offset, bytes);
        if (resident) {
            return cuda_ok(cuda_decode_profile_resident_memcpy(
                                      dst, resident, (size_t)bytes,
                                      cudaMemcpyDeviceToHost),
                           what ? what : "R4 resident host expert copy");
        }
        if (!g_prefill_pipeline_partial_resident_spans) {
            fprintf(stderr,
                    "ds4: CUDA R4 host-cache expert is outside the resident layer spans for %s\n",
                    what ? what : "expert");
            return 0;
        }
    }
    /* Already fetched by this layer's batch? Then the disk read has happened. */
    if (g_ds_prefetch_arena != NULL && !g_ds_prefetch_spans.empty()) {
        const char *src = cuda_ds_prefetch_find(model_map, offset, bytes);
        if (src != NULL) {
            memcpy(dst, src, (size_t)bytes);
            g_ds_prefetch_hits++;
            return 1;
        }
    }
#endif
    if (g_model_fd >= 0 &&
        (g_model_fd_host_base == NULL || model_map == g_model_fd_host_base)) {
        /* [2026-08-20] Timed: this blocking read is the last fall-through of this function and was
         * invisible to every counter. Marker: DS4_PREAD_FALLBACK_PROFILE_V1 */
        const int pread_profile = cuda_decode_profile_enabled();
        const double pread_t0 = pread_profile ? cuda_decode_profile_now_ms() : 0.0;
        const int pread_ok = cuda_pread_full(g_model_fd, dst, bytes, offset);
        if (pread_profile) {
            g_decode_profile.pread_calls++;
            if (pread_ok) g_decode_profile.pread_bytes += (uint64_t)bytes;
            g_decode_profile.pread_ms += cuda_decode_profile_now_ms() - pread_t0;
        }
        if (!pread_ok) {
            fprintf(stderr,
                    "ds4: CUDA RAM expert cache read failed for %s: %s\n",
                    what ? what : "expert",
                    strerror(errno));
            return 0;
        }
        return 1;
    }
    memcpy(dst, (const char *)model_map + offset, (size_t)bytes);
    return 1;
}

static int cuda_stream_host_expert_cache_load_slot(
        cuda_stream_host_expert_cache *cache,
        const void *model_map,
        uint64_t model_size,
        uint32_t slot,
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t expert,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    const uint64_t gate_src =
        gate_offset + (uint64_t)expert * gate_expert_bytes;
    const uint64_t up_src =
        up_offset + (uint64_t)expert * gate_expert_bytes;
    const uint64_t down_src =
        down_offset + (uint64_t)expert * down_expert_bytes;
    const uint64_t gate_dst = (uint64_t)slot * gate_expert_bytes;
    const uint64_t down_dst = (uint64_t)slot * down_expert_bytes;

    if (!cuda_model_read_to_host(cache->gate_ptr + gate_dst,
                                 model_map,
                                 model_size,
                                 gate_src,
                                 gate_expert_bytes,
                                 "RAM cached moe_gate") ||
        !cuda_model_read_to_host(cache->up_ptr + gate_dst,
                                 model_map,
                                 model_size,
                                 up_src,
                                 gate_expert_bytes,
                                 "RAM cached moe_up") ||
        !cuda_model_read_to_host(cache->down_ptr + down_dst,
                                 model_map,
                                 model_size,
                                 down_src,
                                 down_expert_bytes,
                                 "RAM cached moe_down")) {
        return 0;
    }

    cuda_stream_host_expert_cache_slot &entry = cache->slots[slot];
    entry.valid = 1;
    entry.model_map = model_map;
    entry.model_size = model_size;
    entry.layer = layer;
    entry.n_total_expert = n_total_expert;
    entry.expert = expert;
    entry.gate_offset = gate_offset;
    entry.up_offset = up_offset;
    entry.down_offset = down_offset;
    entry.gate_expert_bytes = gate_expert_bytes;
    entry.down_expert_bytes = down_expert_bytes;
    entry.age = ++cache->tick;
    /* [2026-08-18] BOTH admission sites are instrumented - there are two identical ones (this and the
     * other slot-fill path). Counting only one under-reports and would invert the conclusion. */
    if (g_stream_expert_cache_phase_decode) {
        g_expert_cache_admits_decode++;
    } else {
        g_expert_cache_admits_prefill++;
    }
    return 1;
}

static bool cuda_stream_host_expert_cache_admit(const cuda_stream_host_expert_cache_slot &resident,
        uint32_t layer, uint32_t expert) {
    return !((cuda_stream_cache_lfu_enabled() || (g_affinity_cap && g_affinity_current_biased)) && resident.valid &&
        cuda_affinity_cache_priority(layer, expert) < cuda_affinity_cache_priority(resident.layer, resident.expert));
}

static int cuda_stream_host_expert_cache_get_slot(
        cuda_stream_host_expert_cache *cache,
        const void *model_map,
        uint64_t model_size,
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t expert,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        int *was_hit) {
    if (was_hit) *was_hit = 0;
    int slot = cuda_stream_host_expert_cache_find(cache,
                                                  model_map,
                                                  model_size,
                                                  layer,
                                                  n_total_expert,
                                                  expert,
                                                  gate_offset,
                                                  up_offset,
                                                  down_offset,
                                                  gate_expert_bytes,
                                                  down_expert_bytes);
    if (slot >= 0) {
        cache->slots[(uint32_t)slot].age = ++cache->tick;
        if (was_hit) *was_hit = 1;
        g_expert_host_hits++;   /* pinned-host hit: no disk read, but still a H2D copy */
        return slot;
    }
    g_expert_host_misses++;     /* neither VRAM nor host: this one costs a disk read */

    const uint32_t load_slot = cuda_stream_host_expert_cache_lru_slot(cache);
    const auto &resident = cache->slots[load_slot];
    if (!cuda_stream_host_expert_cache_admit(resident, layer, expert)) return -1;
    const int append = !cache->slots[load_slot].valid;
    if (!cuda_stream_host_expert_cache_load_slot(cache,
                                                 model_map,
                                                 model_size,
                                                 load_slot,
                                                 layer,
                                                 n_total_expert,
                                                 expert,
                                                 gate_offset,
                                                 up_offset,
                                                 down_offset,
                                                 gate_expert_bytes,
                                                 down_expert_bytes)) {
        return -1;
    }
    if (append && cache->count < cache->capacity) cache->count++;
    return (int)load_slot;
}

static int cuda_stream_host_expert_cache_copy_to_device(
        cuda_stream_host_expert_cache *cache,
        uint32_t cache_slot,
        char *gate_dst_ptr,
        char *up_dst_ptr,
        char *down_dst_ptr) {
    const uint64_t gate_src = (uint64_t)cache_slot * cache->gate_expert_bytes;
    const uint64_t down_src = (uint64_t)cache_slot * cache->down_expert_bytes;
    return cuda_ok(cuda_decode_profile_host_memcpy(gate_dst_ptr,
                              cache->gate_ptr + gate_src,
                              (size_t)cache->gate_expert_bytes,
                              cudaMemcpyHostToDevice),
                   "RAM cached gate expert upload") &&
           cuda_ok(cuda_decode_profile_host_memcpy(up_dst_ptr,
                              cache->up_ptr + gate_src,
                              (size_t)cache->gate_expert_bytes,
                              cudaMemcpyHostToDevice),
                   "RAM cached up expert upload") &&
           cuda_ok(cuda_decode_profile_host_memcpy(down_dst_ptr,
                              cache->down_ptr + down_src,
                              (size_t)cache->down_expert_bytes,
                              cudaMemcpyHostToDevice),
                   "RAM cached down expert upload");
}

#include "ds4_external_host_cache.inc"

/* [2026-08-16] Merged-run variant of the copy above.
 *
 * WHY: the per-expert version issues THREE SYNCHRONOUS cudaMemcpy calls, and a 16K prefill makes
 * 24,000 such calls = 72,000 blocking transfers, measured at 10.87 GiB/s against 25-50 GB/s of
 * pinned-H2D link speed. The cost is per-call, not per-byte (a VRAM sweep moved the hit rate
 * 43.6% -> 55.3% and changed prefill throughput by zero).
 *
 * Both ends of a run are contiguous:
 *     src = cache->gate_ptr + cache_slot   * gate_expert_bytes
 *     dst = selected.gate_ptr + compact_slot * gate_expert_bytes
 * and consecutive copies were MEASURED to hold consecutive host slots 99.4% of the time, in runs
 * averaging 156. So a run collapses to three transfers total instead of three per expert.
 *
 * The caller must guarantee the run is contiguous on BOTH sides; it falls back to the per-expert
 * path at a break. */
static int cuda_stream_host_expert_cache_copy_run_to_device(
        cuda_stream_host_expert_cache *cache,
        uint32_t first_cache_slot,
        uint32_t count,
        char *gate_dst_ptr,
        char *up_dst_ptr,
        char *down_dst_ptr) {
    if (count == 0) return 1;
    const uint64_t gate_src = (uint64_t)first_cache_slot * cache->gate_expert_bytes;
    const uint64_t down_src = (uint64_t)first_cache_slot * cache->down_expert_bytes;
    const size_t   gate_len = (size_t)cache->gate_expert_bytes * (size_t)count;
    const size_t   down_len = (size_t)cache->down_expert_bytes * (size_t)count;
    return cuda_ok(cuda_decode_profile_host_memcpy(
                              gate_dst_ptr, cache->gate_ptr + gate_src, gate_len,
                              cudaMemcpyHostToDevice),
                   "RAM cached gate expert run upload") &&
           cuda_ok(cuda_decode_profile_host_memcpy(
                              up_dst_ptr, cache->up_ptr + gate_src, gate_len,
                              cudaMemcpyHostToDevice),
                   "RAM cached up expert run upload") &&
           cuda_ok(cuda_decode_profile_host_memcpy(
                              down_dst_ptr, cache->down_ptr + down_src, down_len,
                              cudaMemcpyHostToDevice),
                   "RAM cached down expert run upload");
}

#if defined(_WIN32)
static int cuda_ram_hot_prefetch_find(
        const void *model_map,
        uint64_t model_size,
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t expert,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    const cuda_ram_hot_prefetch_state &s = g_ram_hot_prefetch;
    if (!s.active || s.model_map != model_map || s.model_size != model_size ||
        s.layer != layer || s.n_total_expert != n_total_expert ||
        s.gate_offset != gate_offset || s.up_offset != up_offset ||
        s.down_offset != down_offset ||
        s.gate_expert_bytes != gate_expert_bytes ||
        s.down_expert_bytes != down_expert_bytes) {
        return -1;
    }
    for (uint32_t i = 0; i < s.count; i++) {
        if (s.experts[i] == (int32_t)expert) return (int)i;
    }
    return -1;
}

static int cuda_ram_hot_prefetch_copy_expert_to_device(
        char *gate_dst,
        char *up_dst,
        char *down_dst,
        const void *model_map,
        uint64_t model_size,
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t expert,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    const int staged = cuda_ram_hot_prefetch_find(
        model_map, model_size, layer, n_total_expert, expert,
        gate_offset, up_offset, down_offset,
        gate_expert_bytes, down_expert_bytes);
    if (staged < 0 || !g_ds_gpu_prefetch_arena) return 0;
    if (!g_ram_hot_prefetch.ready_waited) {
        if (!cuda_ok(cudaEventSynchronize(g_ram_hot_prefetch.ready),
                     "next-layer RAM hot prefetch wait")) {
            g_ram_hot_prefetch.active = 0;
            return -1;
        }
        g_ram_hot_prefetch.ready_waited = 1;
    }
    const uint64_t k = cuda_ram_hot_prefetch_k();
    const uint64_t base = cuda_ds_gpu_ssd_capacity();
    const uint64_t gate_src = base + (uint64_t)staged * gate_expert_bytes;
    const uint64_t up_src = base + k * gate_expert_bytes +
                            (uint64_t)staged * gate_expert_bytes;
    const uint64_t down_src = base + 2ull * k * gate_expert_bytes +
                              (uint64_t)staged * down_expert_bytes;
    if (!cuda_ok(cudaMemcpy(gate_dst, g_ds_gpu_prefetch_arena + gate_src,
                            (size_t)gate_expert_bytes, cudaMemcpyDeviceToDevice),
                 "next-layer RAM hot gate placement") ||
        !cuda_ok(cudaMemcpy(up_dst, g_ds_gpu_prefetch_arena + up_src,
                            (size_t)gate_expert_bytes, cudaMemcpyDeviceToDevice),
                 "next-layer RAM hot up placement") ||
        !cuda_ok(cudaMemcpy(down_dst, g_ds_gpu_prefetch_arena + down_src,
                            (size_t)down_expert_bytes, cudaMemcpyDeviceToDevice),
                 "next-layer RAM hot down placement")) {
        g_ram_hot_prefetch.active = 0;
        return -1;
    }
    g_ram_hot_prefetch_hits++;
    return 1;
}
#endif

static int cuda_stream_expert_cache_load_slot(
        cuda_stream_expert_cache *cache,
        const void *model_map,
        uint64_t model_size,
        uint32_t slot,
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t expert,
        uint32_t route_rank,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    const uint64_t gate_src =
        gate_offset + (uint64_t)expert * gate_expert_bytes;
    const uint64_t up_src =
        up_offset + (uint64_t)expert * gate_expert_bytes;
    const uint64_t down_src =
        down_offset + (uint64_t)expert * down_expert_bytes;
    const uint64_t gate_dst = (uint64_t)slot * gate_expert_bytes;
    const uint64_t down_dst = (uint64_t)slot * down_expert_bytes;

    int copied_from_host_cache = 0;
#if defined(_WIN32)
    copied_from_host_cache =
        cuda_ram_hot_prefetch_copy_expert_to_device(
            cache->gate_ptr + gate_dst,
            cache->up_ptr + gate_dst,
            cache->down_ptr + down_dst,
            model_map, model_size, layer, n_total_expert, expert,
            gate_offset, up_offset, down_offset,
            gate_expert_bytes, down_expert_bytes);
    if (copied_from_host_cache < 0) return 0;
#endif
    if (!copied_from_host_cache) copied_from_host_cache =
        cuda_ds_prefetch_copy_expert_to_device(
            cache->gate_ptr + gate_dst,
            cache->up_ptr + gate_dst,
            cache->down_ptr + down_dst,
            model_map, gate_src, up_src, down_src,
            gate_expert_bytes, down_expert_bytes);
    if (copied_from_host_cache < 0) return 0;
    cuda_stream_host_expert_cache *host_cache = NULL;
    if (!copied_from_host_cache) {
        host_cache = cuda_stream_host_expert_cache_prepare(gate_expert_bytes,
                                                           down_expert_bytes,
                                                           0);
    }
    if (!copied_from_host_cache && host_cache) {
        int was_hit = 0;
        const int host_slot =
            cuda_stream_host_expert_cache_get_slot(host_cache,
                                                   model_map,
                                                   model_size,
                                                   layer,
                                                   n_total_expert,
                                                   expert,
                                                   gate_offset,
                                                   up_offset,
                                                   down_offset,
                                                   gate_expert_bytes,
                                                   down_expert_bytes,
                                                   &was_hit);
        if (host_slot >= 0) {
            copied_from_host_cache =
                cuda_stream_host_expert_cache_copy_to_device(
                        host_cache,
                        (uint32_t)host_slot,
                        cache->gate_ptr + gate_dst,
                        cache->up_ptr + gate_dst,
                        cache->down_ptr + down_dst);
            /* Frequency retention keeps the RAM band below the VRAM band.
             * The synchronous upload has consumed this slot; do not retain
             * a duplicate when the same expert is promoted into VRAM. */
            if (copied_from_host_cache && cuda_stream_cache_lfu_enabled()) {
                host_cache->slots[(uint32_t)host_slot].valid = 0;
                host_cache->count--;
            }
            if (getenv("DS4_CUDA_STREAMING_HOST_CACHE_VERBOSE")) {
                fprintf(stderr,
                        "ds4: CUDA RAM expert cache %s layer=%u expert=%u count=%u/%u\n",
                        was_hit ? "hit" : "miss",
                        layer,
                        expert,
                        host_cache->count,
                        host_cache->capacity);
            }
        }
    }

    /* LFU may decline RAM admission. Consume the already-fetched host spans
     * through the same bounded placement helper instead of rereading the file
     * through the large serial staging pool. Ordinary host admission remains
     * first, so accepted misses still populate the RAM tier. */
    if (!copied_from_host_cache) copied_from_host_cache =
        cuda_ds_prefetch_copy_expert_to_device(
            cache->gate_ptr + gate_dst, cache->up_ptr + gate_dst,
            cache->down_ptr + down_dst, model_map, gate_src, up_src, down_src,
            gate_expert_bytes, down_expert_bytes, 1);
    if (copied_from_host_cache < 0) return 0;
    if (!copied_from_host_cache) {
        uint64_t streamed_chunks = 0;
        if (!cuda_model_copy_to_device_streamed(cache->gate_ptr + gate_dst,
                                                model_map,
                                                model_size,
                                                gate_src,
                                                gate_expert_bytes,
                                                "cached moe_gate", streamed_chunks) ||
            !cuda_model_copy_to_device_streamed(cache->up_ptr + gate_dst,
                                                model_map,
                                                model_size,
                                                up_src,
                                                gate_expert_bytes,
                                                "cached moe_up", streamed_chunks) ||
            !cuda_model_copy_to_device_streamed(cache->down_ptr + down_dst,
                                                model_map,
                                                model_size,
                                                down_src,
                                                down_expert_bytes,
                                                "cached moe_down", streamed_chunks)) {
            return 0;
        }
    }
    cuda_stream_expert_cache_slot &entry = cache->slots[slot];
    entry.valid = 1;
    entry.model_map = model_map;
    entry.model_size = model_size;
    entry.layer = layer;
    entry.n_total_expert = n_total_expert;
    entry.expert = expert;
    entry.gate_offset = gate_offset;
    entry.up_offset = up_offset;
    entry.down_offset = down_offset;
    entry.gate_expert_bytes = gate_expert_bytes;
    entry.down_expert_bytes = down_expert_bytes;
    entry.age = ++cache->tick;
    entry.route_rank = route_rank;
    cache->rank_worst_valid = 0;
    /* [2026-08-18] BOTH admission sites are instrumented - there are two identical ones (this and the
     * other slot-fill path). Counting only one under-reports and would invert the conclusion. */
    if (g_stream_expert_cache_phase_decode) {
        g_expert_cache_admits_decode++;
    } else {
        g_expert_cache_admits_prefill++;
    }
    return 1;
}

#if defined(_WIN32)
static int cuda_ds_gpu_destination_enabled(void) {
    static int initialized = 0;
    static int enabled = 0;
    if (!initialized) {
        const char *env = getenv("DS4_CUDA_DS_DIRECT_GPU");
        if (!env || !env[0]) env = getenv("DS4_CUDA_DS_GPU_DEST");
        enabled = env && env[0] && strcmp(env, "0") != 0;
        initialized = 1;
    }
    return enabled && !g_ds_gpu_prefetch_disabled;
}

static int cuda_ds_gpu_prefetch_arena_ensure(void) {
    /* [2026-08-20] REVALIDATE, do not just trust our own pointer. DS4_GPU_ARENA_REVALIDATE_V1.
     *
     * R4's ds4_ds_prefill_arenas_create() calls gpu_arena_release(), destroying the D3D12 resource
     * and the external-memory mapping this pointer refers to. It stays non-NULL and DANGLING, so
     * this function used to report success while every ds4_ds_batch_add_gpu() refused with
     * !g_gpu_arena (measured: prepass_fail_reason=2 on 100% of requests-2+ tokens). The prepass
     * turns that refusal into a silent per-layer `break`, and because the GPU path looked available
     * the HOST arena was never allocated - so there was no fallback and every expert went to a
     * synchronous pread: 206 calls / 499 MiB / 162 ms per token at 3.01 GB/s vs DS at 11.99 GiB/s.
     * That is the whole -59.6% decode regression from request 2 onward.
     *
     * Default ON. DS4_CUDA_GPU_ARENA_REVALIDATE=0 restores the old trust-the-pointer behaviour so
     * an A/B arm exists; there is no reason to set it outside measurement. */
    if (g_ds_gpu_prefetch_arena) {
        if (!cuda_env_flag_enabled("DS4_CUDA_GPU_ARENA_REVALIDATE", 1) ||
            ds4_ds_gpu_arena_alive()) {
            return 1;
        }
        g_ds_gpu_prefetch_arena   = NULL;   /* dangling: the resource behind it is gone */
        g_ds_gpu_prefetch_capacity = 0;
    }
    /* Six boosted experts need 81 MiB. The exact layers 0..2 prefix adds 121.5 MiB, so 256 MiB
     * covers the immutable prefix plus the largest decode-layer transient tail with margin. */
    uint64_t mb = 256;
    const char *env = getenv("DS4_CUDA_DS_DIRECT_MB");
    if (env && env[0]) {
        char *end = NULL;
        const unsigned long value = strtoul(env, &end, 10);
        /* Upper bound raised 1024 -> 4096. The next-layer RAM->VRAM promotion carves its reserve from
         * THIS arena, so the arena bounds how much of a layer can be promoted: a whole 256-expert layer
         * is 1728 MiB on the IQ2 class. At the old 1024 MiB ceiling no setting of DS4_CUDA_RAM_PREFETCH_MB
         * could cover a layer, which made the promotion untestable at the only scale where it could
         * matter. Rejection is warned about rather than silent - the old silent clamp cost a void run. */
        if (end != env && end && *end == '\0' && value >= 96 && value <= 4096) {
            mb = (uint64_t)value;
        } else {
            fprintf(stderr,
                    "ds4: DS4_CUDA_DS_DIRECT_MB=%s ignored (accepted range 96..4096 MiB); "
                    "using %llu MiB\n",
                    env, (unsigned long long)mb);
        }
    }
    g_ds_gpu_prefetch_capacity = mb * 1048576ull;
    void *ptr = NULL;
    if (!ds4_ds_gpu_arena_create(g_ds_gpu_prefetch_capacity, &ptr) || !ptr) {
        fprintf(stderr,
                "ds4: CUDA DirectStorage GPU destination unavailable; retaining MEMORY path\n");
        g_ds_gpu_prefetch_disabled = 1;
        g_ds_gpu_prefetch_capacity = 0;
        return 0;
    }
    g_ds_gpu_prefetch_arena = (char *)ptr;
    if (cuda_ram_hot_prefetch_reserve_bytes() != 0) {
        fprintf(stderr,
                "ds4: CUDA direct arena split %.0f MiB SSD + %.0f MiB RAM-hot\n",
                (double)cuda_ds_gpu_ssd_capacity() / 1048576.0,
                (double)cuda_ram_hot_prefetch_reserve_bytes() / 1048576.0);
    }
    return 1;
}
#endif

static int cuda_stream_expert_cache_seed_one(
        cuda_stream_expert_cache *cache,
        const void *model_map,
        uint64_t model_size,
        uint32_t layer,
        uint32_t n_total_expert,
        uint32_t expert,
        const uint32_t *expert_ranks,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    int cache_slot = cuda_stream_expert_cache_find(cache,
                                                   model_map,
                                                   model_size,
                                                   layer,
                                                   n_total_expert,
                                                   expert,
                                                   gate_offset,
                                                   up_offset,
                                                   down_offset,
                                                   gate_expert_bytes,
                                                   down_expert_bytes);
    if (cache_slot >= 0) {
        cache->slots[(uint32_t)cache_slot].age = ++cache->tick;
        return 1;
    }

    const uint32_t route_rank = expert_ranks ?
        expert_ranks[expert] : UINT32_MAX;
    const uint32_t load_slot = cuda_stream_expert_cache_admission_slot(
        cache, route_rank, expert_ranks != NULL, layer, expert);
    if (load_slot == UINT32_MAX) return 1;
    const int append = !cache->slots[load_slot].valid;
    if (!cuda_stream_expert_cache_load_slot(cache,
                                            model_map,
                                            model_size,
                                            load_slot,
                                            layer,
                                            n_total_expert,
                                            expert,
                                            route_rank,
                                            gate_offset,
                                            up_offset,
                                            down_offset,
                                            gate_expert_bytes,
                                            down_expert_bytes)) {
        return 0;
    }
    if (append && cache->count < cache->capacity) cache->count++;
    return 1;
}

static int cuda_stream_layer_expert_ranges_valid(
        uint64_t model_size,
        uint32_t n_total_expert,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes,
        const char *what) {
    if (n_total_expert == 0 ||
        gate_expert_bytes == 0 ||
        down_expert_bytes == 0 ||
        (uint64_t)n_total_expert > UINT64_MAX / gate_expert_bytes ||
        (uint64_t)n_total_expert > UINT64_MAX / down_expert_bytes) {
        fprintf(stderr,
                "ds4: CUDA streaming %s expert size overflow\n",
                what ? what : "selected");
        return 0;
    }
    const uint64_t full_gate_bytes =
        (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t full_down_bytes =
        (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_offset > model_size || up_offset > model_size ||
        down_offset > model_size ||
        full_gate_bytes > model_size - gate_offset ||
        full_gate_bytes > model_size - up_offset ||
        full_down_bytes > model_size - down_offset) {
        fprintf(stderr,
                "ds4: CUDA streaming %s expert range outside model map\n",
                what ? what : "selected");
        return 0;
    }
    return 1;
}

static int cublas_ok(cublasStatus_t st, const char *what) {
    if (st == CUBLAS_STATUS_SUCCESS) return 1;
    fprintf(stderr, "ds4: cuBLAS %s failed: status %d\n", what, (int)st);
    return 0;
}

extern "C" int ds4_gpu_init_multi(const ds4_gpu_config *cfg) {
    if (!cfg || cfg->n_gpus < 1 || cfg->n_gpus > DS4_MAX_GPUS) return 0;
    cuda_xdev_env_refresh();
    cuda_decode_dispatch_env_refresh();
    g_current_logical_tier = -1;

    /* g_n_gpus is published incrementally so ds4_gpu_cleanup() can unwind
     * partial state on failure. We publish `i + 1` BEFORE allocating any
     * resources for context `i`, so even if (e.g.) stream creation
     * succeeds but event creation fails, cleanup still walks device `i`
     * and destroys the stream. ds4_gpu_cleanup is null-safe per field —
     * partial state is OK. */
    for (int i = 0; i < cfg->n_gpus; i++) {
        ds4_gpu_ctx *c = &g_gpu[i];
        c->device_id = cfg->device_indices[i];
        if (c->device_id < 0) return 0;
        /* Publish the in-progress device id so cleanup can target it on
         * any later failure. cudaSetDevice is also required before
         * cleanup's cudaEventDestroy / cudaStreamDestroy / cublasDestroy
         * calls hit the right context. */
        g_n_gpus = i + 1;
        if (!cuda_ok(cudaSetDevice(c->device_id), "init set device")) return 0;
        cudaDeviceProp prop;
        if (cudaGetDeviceProperties(&prop, c->device_id) == cudaSuccess) {
            if (i == 0) g_device_is_spark =
                prop.integrated && prop.major == 12 && prop.minor == 1;
            fprintf(stderr, "ds4: CUDA backend initialized on %s (sm_%d%d) dev=%d\n",
                    prop.name, prop.major, prop.minor, c->device_id);
        }
        /* Per-device stream. */
        cudaStream_t s = NULL;
        if (!cuda_ok(cudaStreamCreate(&s), "init stream")) return 0;
        c->stream = (void *)s;
        /* Per-device boundary event (reusable, no timing). */
        cudaEvent_t ev = NULL;
        if (!cuda_ok(cudaEventCreateWithFlags(&ev, cudaEventDisableTiming),
                      "init event")) return 0;
        c->boundary_event = (void *)ev;
        /* Per-device cuBLAS handle. */
        cublasHandle_t h = NULL;
        if (!cublas_ok(cublasCreate(&h), "init cublas")) return 0;
        c->cublas = (void *)h;
        const cublasMath_t math_mode =
            (g_quality_mode || getenv("DS4_CUDA_NO_TF32") != NULL)
                ? CUBLAS_DEFAULT_MATH
                : CUBLAS_TF32_TENSOR_OP_MATH;
        (void)cublasSetMathMode(h, math_mode);
        c->cublas_ready = 1;
        c->budget_bytes = cfg->vram_bytes[i];
        c->used_bytes   = 0;
        c->scratch      = NULL;
        c->scratch_bytes = 0;
    }

    /* NxN peer-access matrix.
     *
     * Driver semantics: cudaDeviceCanAccessPeer + cudaDeviceEnablePeerAccess
     * can both succeed even on hardware/drivers where cudaMemcpyPeerAsync
     * silently delivers wrong data (notably RTX 6000 Ada under recent
     * NVIDIA drivers, per the v0 design doc). The corruption is
     * non-deterministic and can affect either or both directions of a
     * pair. To guard against this, we run a multi-size, multi-iteration
     * validation at init (see the loop below): write distinct known
     * patterns, peer-copy them to the destination, read back, and only
     * set peer_ok[i][j] if every probe round-trips byte-perfect. A
     * single small probe is not sufficient — it can pass while realistic
     * activation-sized copies still corrupt. On any failure the entry
     * stays at 0 and cross-device copies fall back to the pinned-host
     * bounce path automatically. */
    for (int i = 0; i < g_n_gpus; i++) {
        for (int j = 0; j < g_n_gpus; j++) {
            if (i == j) { g_gpu_peer_ok[i][j] = 1; continue; }
            int can = 0;
            (void)cudaDeviceCanAccessPeer(&can, g_gpu[i].device_id,
                                          g_gpu[j].device_id);
            if (!can) { g_gpu_peer_ok[i][j] = 0; continue; }
            (void)cudaSetDevice(g_gpu[i].device_id);
            cudaError_t e = cudaDeviceEnablePeerAccess(g_gpu[j].device_id, 0);
            int enabled = (e == cudaSuccess ||
                           e == cudaErrorPeerAccessAlreadyEnabled);
            (void)cudaGetLastError();
            if (!enabled) { g_gpu_peer_ok[i][j] = 0; continue; }

            /* Runtime validation: peer copies on RTX 6000 Ada under recent
             * NVIDIA drivers silently corrupt at realistic sizes even though
             * the API returns success. cudaDeviceCanAccessPeer and
             * cudaDeviceEnablePeerAccess can both report success while
             * cudaMemcpyPeer delivers wrong data non-deterministically.
             * Probe with multiple sizes and iterations; ALL must round-trip
             * byte-perfect or we disable peer for this pair and silently fall
             * back to the pinned-host bounce path. */
            static const size_t kValidateSizes[] = {
                4u * 1024u,
                256u * 1024u,
                1u * 1024u * 1024u,
                16u * 1024u * 1024u,
            };
            const int kValidateIters    = 4;
            const int kNValidateSizes   = (int)(sizeof(kValidateSizes) /
                                                sizeof(kValidateSizes[0]));
            const size_t kMaxValidate   = kValidateSizes[kNValidateSizes - 1];

            unsigned char *vh_src = (unsigned char *)malloc(kMaxValidate);
            unsigned char *vh_dst = (unsigned char *)malloc(kMaxValidate);
            if (!vh_src || !vh_dst) {
                free(vh_src); free(vh_dst);
                g_gpu_peer_ok[i][j] = 0; continue;
            }

            void *src_dev = NULL; void *dst_dev = NULL;
            (void)cudaSetDevice(g_gpu[i].device_id);
            if (cudaMalloc(&src_dev, kMaxValidate) != cudaSuccess) {
                (void)cudaGetLastError();
                free(vh_src); free(vh_dst);
                g_gpu_peer_ok[i][j] = 0; continue;
            }
            (void)cudaSetDevice(g_gpu[j].device_id);
            if (cudaMalloc(&dst_dev, kMaxValidate) != cudaSuccess) {
                (void)cudaGetLastError();
                (void)cudaSetDevice(g_gpu[i].device_id);
                (void)cudaFree(src_dev);
                free(vh_src); free(vh_dst);
                g_gpu_peer_ok[i][j] = 0; continue;
            }

            int    peer_validated = 1;
            size_t failed_bytes   = 0;
            int    failed_iter    = -1;
            for (int s_idx = 0;
                 s_idx < kNValidateSizes && peer_validated;
                 s_idx++) {
                size_t n = kValidateSizes[s_idx];
                for (int it = 0; it < kValidateIters && peer_validated; it++) {
                    for (size_t k = 0; k < n; k++) {
                        vh_src[k] = (unsigned char)
                            ((k * 31u + (size_t)it * 17u +
                              (size_t)s_idx * 53u + 11u) & 0xffu);
                    }
                    (void)cudaSetDevice(g_gpu[i].device_id);
                    if (cudaMemcpy(src_dev, vh_src, n,
                                   cudaMemcpyHostToDevice) != cudaSuccess) {
                        peer_validated = 0; failed_bytes = n; failed_iter = it;
                        break;
                    }
                    cudaError_t pc = cudaMemcpyPeer(
                        dst_dev, g_gpu[j].device_id,
                        src_dev, g_gpu[i].device_id, n);
                    if (pc != cudaSuccess) {
                        peer_validated = 0; failed_bytes = n; failed_iter = it;
                        break;
                    }
                    (void)cudaSetDevice(g_gpu[j].device_id);
                    if (cudaMemcpy(vh_dst, dst_dev, n,
                                   cudaMemcpyDeviceToHost) != cudaSuccess) {
                        peer_validated = 0; failed_bytes = n; failed_iter = it;
                        break;
                    }
                    if (memcmp(vh_src, vh_dst, n) != 0) {
                        peer_validated = 0; failed_bytes = n; failed_iter = it;
                        break;
                    }
                }
            }

            (void)cudaSetDevice(g_gpu[j].device_id);
            (void)cudaFree(dst_dev);
            (void)cudaSetDevice(g_gpu[i].device_id);
            (void)cudaFree(src_dev);
            free(vh_src);
            free(vh_dst);

            g_gpu_peer_ok[i][j] = peer_validated;
            if (peer_validated) {
                fprintf(stderr,
                    "ds4: peer access %d->%d validated across %d sizes x %d"
                    " iterations (max %zu MiB)\n",
                    g_gpu[i].device_id, g_gpu[j].device_id,
                    kNValidateSizes, kValidateIters,
                    kMaxValidate / (1024u * 1024u));
            } else {
                fprintf(stderr,
                    "ds4: peer access %d->%d FAILED validation at"
                    " size=%zu iter=%d; falling back to pinned-host bounce\n",
                    g_gpu[i].device_id, g_gpu[j].device_id,
                    failed_bytes, failed_iter);
            }
        }
    }

    g_cublas_ready = 1;
    return 1;
}

extern "C" int ds4_gpu_init(void) {
    ds4_gpu_config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.device_indices[0] = 0;
    cfg.n_gpus = 1;
    return ds4_gpu_init_multi(&cfg);
}

extern "C" void ds4_gpu_cleanup(void) {
    cuda_dspark_aux_cleanup();
    ds4_gpu_stream_expert_cache_prefetch_finish(true);
    ds4_gpu_tp_shutdown();
    (void)cudaDeviceSynchronize();
    ds4_gpu_decode_graphs_invalidate();
    g_current_logical_tier = -1;

    /* Multi-GPU teardown: events, streams, cublas handles, scratch
     * slabs, per-pair bounce buffers. */
    for (int i = 0; i < g_n_gpus; i++) {
        ds4_gpu_ctx *c = &g_gpu[i];
        (void)cudaSetDevice(c->device_id);
        if (i == 0) cuda_dsv41_shared_free();
        attention_decode_score_split_graph_destroy_one(i);
        routed_moe_decode_graph_destroy_one(i);
        if (c->boundary_event) {
            (void)cudaEventDestroy((cudaEvent_t)c->boundary_event);
            c->boundary_event = NULL;
        }
        if (c->stream) {
            (void)cudaStreamDestroy((cudaStream_t)c->stream);
            c->stream = NULL;
        }
        if (c->cublas) {
            (void)cublasDestroy((cublasHandle_t)c->cublas);
            c->cublas = NULL;
            c->cublas_ready = 0;
        }
        if (c->scratch) {
            (void)cudaFree(c->scratch);
            c->scratch = NULL;
            c->scratch_bytes = 0;
        }
        if (g_tt_scratch && g_tt_scratch_device == c->device_id) {
            (void)cudaFree(g_tt_scratch);
            g_tt_scratch = NULL;
            g_tt_scratch_bytes = 0;
            g_tt_scratch_device = -1;
        }
#ifdef DS4_CUDA_HAVE_MXF4
        if (g_indexer_mxf4_scratch &&
            g_indexer_mxf4_scratch_device == c->device_id) {
            (void)cudaFree(g_indexer_mxf4_scratch);
            g_indexer_mxf4_scratch = NULL;
            g_indexer_mxf4_scratch_bytes = 0;
            g_indexer_mxf4_scratch_device = -1;
        }
#endif
    }
    for (int i = 0; i < DS4_MAX_GPUS; i++) {
        for (int j = 0; j < DS4_MAX_GPUS; j++) {
            if (g_xdev_bounce[i][j]) {
                (void)cudaFreeHost(g_xdev_bounce[i][j]);
                g_xdev_bounce[i][j] = NULL;
                g_xdev_bounce_bytes[i][j] = 0;
            }
        }
    }
    cuda_stream_selected_cache_release();
    cuda_stream_expert_cache_release_all();
    cuda_stream_host_expert_cache_release_all();
    cuda_stream_selected_stage_release();
    g_n_gpus = 0;
    g_device_is_spark = false;
    g_cublas_ready = 0;

    /* Per-device selective cache teardown (selective model cache). */
    for (int d = 0; d < DS4_MAX_GPUS; d++) {
        if (!g_dev_cache[d].present) continue;
        int prev = -1;
        (void)cudaGetDevice(&prev);
        (void)cudaSetDevice(d);
        if (g_dev_cache[d].base) (void)cudaFree(g_dev_cache[d].base);
        g_dev_cache[d].base = NULL;
        g_dev_cache[d].bytes = 0;
        g_dev_cache[d].present = 0;
        if (prev >= 0) (void)cudaSetDevice(prev);
    }
    g_cache_ranges.clear();

    /* Continue with legacy global teardown below. */

    cuda_model_range_release_all(false);
    cuda_derived_range_release_all();
    cuda_q8_f16_cache_release_all();
    g_q8_f16_disabled_after_oom = 0;
    g_q8_f16_budget_notice_printed = 0;
    for (const cuda_q8_f32_range &r : g_q8_f32_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f32_ranges.clear();
    g_q8_f32_by_offset.clear();
    g_q8_f32_bytes = 0;
    if (g_cuda_tmp) {
        (void)cudaFree(g_cuda_tmp);
        g_cuda_tmp = NULL;
        g_cuda_tmp_bytes = 0;
    }
    for (size_t i = 0; i < 4; i++) {
        if (g_model_stage_event[i]) {
            (void)cudaEventDestroy(g_model_stage_event[i]);
            g_model_stage_event[i] = NULL;
        }
        if (g_model_stage_raw[i]) {
            (void)cudaFreeHost(g_model_stage_raw[i]);
            g_model_stage_raw[i] = NULL;
            g_model_stage[i] = NULL;
        }
    }
    g_model_stage_bytes = 0;
    if (g_model_upload_stream) {
        (void)cudaStreamDestroy(g_model_upload_stream);
        g_model_upload_stream = NULL;
    }
    if (g_model_device_owned && g_model_device_base) {
        (void)cudaFree((void *)g_model_device_base);
    }
    if (g_model_registered && g_model_host_base) {
        (void)cudaHostUnregister((void *)g_model_host_base);
    }
    g_model_host_base = NULL;
    g_model_device_base = NULL;
    g_model_registered_size = 0;
    g_model_registered = 0;
    g_model_device_owned = 0;
    g_model_range_mapping_supported = 1;
    g_model_hmm_direct = 0;
    g_model_fd = -1;
    if (g_model_direct_fd >= 0) {
        (void)close(g_model_direct_fd);
        g_model_direct_fd = -1;
    }
    g_model_direct_align = 1;
    g_model_file_size = 0;
    g_model_cache_full = 0;
    g_model_mapping_failure_notice_printed = 0;
    g_ssd_streaming_mode = 0;
    g_stream_host_expert_budget_override = 0;
    g_indexed_f16_kv_notice_printed = 0;
    g_indexed_attention_plan_notice_count = 0;
    g_fp8_raw_store_notice_count = 0;
    if (g_model_prefetch_stream) {
        (void)cudaStreamDestroy(g_model_prefetch_stream);
        g_model_prefetch_stream = NULL;
    }
}

__global__ static void fill_f32_kernel(float *x, uint64_t n, float v);
__global__ static void f32_to_f16_kernel(__half *out, const float *x, uint64_t n);
__global__ static void f32_rows_to_q8_kv_kernel(char *dst, const float *src,
                                                uint32_t rows, uint32_t head_dim,
                                                uint64_t dst_row_bytes);

extern "C" int ds4_gpu_tensor_alloc_on(ds4_gpu_tensor *t, int device_id,
                                       uint64_t bytes) {
    if (!t) return 1;
    if (device_id < 0 || device_id >= g_n_gpus) return 2;
    if (bytes == 0) bytes = 1;
    int ok = 0;
    WITH_DEVICE(g_gpu[device_id].device_id) {
        ok = cuda_ok(cudaMalloc(&t->ptr, (size_t)bytes), "tensor alloc");
    }
    if (!ok) {
        /* R3 retry hygiene: cudaMalloc's OOM is also returned by the next
         * cudaGetLastError().  Leaving it pending made a smaller, successful
         * workspace retry report its first kernel as failed even though that
         * kernel had not caused the OOM. */
        (void)cudaGetLastError();
        return 3;
    }
    t->bytes = bytes;
    t->owner = 1;
    t->device_id = device_id;
    g_gpu[device_id].used_bytes += bytes;
    return 0;
}

/* Async D2D copy queued on the destination device's default stream —
 * ordering against the producer comes from the caller's fence; the CPU
 * does not block (unlike ds4_gpu_tensor_copy's sync cudaMemcpy). */
extern "C" int ds4_gpu_tensor_copy_async(ds4_gpu_tensor *dst,
                                         const ds4_gpu_tensor *src,
                                         uint64_t bytes) {
    if (!dst || !src || bytes > dst->bytes || bytes > src->bytes) return 0;
    if (bytes == 0) return 1;
    return cuda_ok(cudaMemcpyAsync(dst->ptr, src->ptr, (size_t)bytes,
                                   cudaMemcpyDeviceToDevice, 0),
                   "tensor copy async");
}

static bool cuda_vmm_tensor_release(ds4_gpu_tensor *t) {
    if (!t || !t->owner || !t->ptr || g_vmm_tensors.empty()) return false;
    auto it = g_vmm_tensors.find(t->ptr);
    if (it == g_vmm_tensors.end()) return false;
    WITH_DEVICE(it->second.device) {
        (void)cudaDeviceSynchronize();
        cuda_vmm_free(&it->second);
    }
    g_vmm_tensors.erase(it);
    t->ptr = NULL;
    return true;
}

extern "C" void ds4_gpu_tensor_free_in_place(ds4_gpu_tensor *t) {
    if (!t) return;
    int d = ds4_tensor_device_idx(t);
    if (cuda_vmm_tensor_release(t)) {
        t->bytes = 0;
        t->owner = 0;
        return;
    }
    if (t->owner && t->ptr) {
        WITH_DEVICE(g_gpu[d].device_id) {
            (void)cudaFree(t->ptr);
        }
    }
    t->ptr = NULL;
    t->bytes = 0;
    t->owner = 0;
}

extern "C" ds4_gpu_tensor *ds4_gpu_tensor_alloc(uint64_t bytes) {
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    if (ds4_gpu_tensor_alloc_on(t, 0, bytes) != 0) {
        free(t);
        return NULL;
    }
    return t;
}

/* DS4COMBO growable context: a device tensor whose full `bytes` are a fixed
 * virtual range; physical memory is backed by ds4_gpu_tensor_set_mapped().
 * Kernels must only touch the mapped prefix. */
extern "C" ds4_gpu_tensor *ds4_gpu_tensor_alloc_growable(uint64_t bytes) {
    if (bytes == 0) bytes = 1;
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    cuda_vmm_region r;
    int ok = 0;
    WITH_DEVICE(g_gpu[0].device_id) {
        /* At most ~256 chunks per tensor, never below the granularity. */
        ok = cuda_vmm_reserve(&r, bytes, bytes / 256u);
    }
    if (!ok) { free(t); return NULL; }
    t->ptr = (void *)(uintptr_t)r.base;
    t->bytes = bytes;
    t->owner = 1;
    t->device_id = 0;
    try { g_vmm_tensors[t->ptr] = r; } catch (...) {
        cuda_vmm_free(&r); free(t); return NULL;
    }
    return t;
}

/* Back at least `bytes` of a growable tensor (newly backed bytes read as
 * zero), unmapping whole chunks beyond it. Plain tensors are always full. */
extern "C" int ds4_gpu_tensor_set_mapped(ds4_gpu_tensor *t, uint64_t bytes) {
    if (!t || !t->ptr) return 0;
    auto it = g_vmm_tensors.find(t->ptr);
    if (it == g_vmm_tensors.end()) return bytes <= t->bytes;
    int ok = 0;
    WITH_DEVICE(it->second.device) {
        ok = cuda_vmm_resize(&it->second, bytes, 1);
    }
    if (!ok) (void)cudaGetLastError();
    return ok;
}

/* Physical bytes backing `t` if it were mapped to cover `bytes`. */
extern "C" uint64_t ds4_gpu_tensor_map_cost(const ds4_gpu_tensor *t, uint64_t bytes) {
    if (!t || !t->ptr) return 0;
    auto it = g_vmm_tensors.find(t->ptr);
    if (it == g_vmm_tensors.end()) return t->bytes;
    return cuda_vmm_cost(&it->second, bytes);
}

extern "C" uint64_t ds4_gpu_tensor_mapped_bytes(const ds4_gpu_tensor *t) {
    if (!t || !t->ptr) return 0;
    auto it = g_vmm_tensors.find(t->ptr);
    return it == g_vmm_tensors.end() ? t->bytes : it->second.mapped;
}

extern "C" ds4_gpu_tensor *ds4_gpu_tensor_alloc_managed(uint64_t bytes) {
    if (bytes == 0) bytes = 1;
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    int ok = 0;
    /* Managed memory is not device-bound, but we record device 0 so that
     * subsequent ds4_gpu_tensor_free pairs with WITH_DEVICE(0) safely. */
    WITH_DEVICE(g_gpu[0].device_id) {
        ok = cuda_ok(cudaMallocManaged(&t->ptr, (size_t)bytes),
                     "managed tensor alloc");
    }
    if (!ok) { free(t); return NULL; }
    t->bytes = bytes;
    t->owner = 1;
    t->device_id = 0;
    return t;
}

/* Heap-allocated tensor on a specific logical tier.
 *
 * Mirrors the legacy ds4_gpu_tensor_alloc ABI (returns ds4_gpu_tensor *)
 * with an explicit tier argument. Internally calls
 * ds4_gpu_tensor_alloc_on on a freshly malloc'd struct.
 *
 * The legacy ds4_gpu_tensor_alloc(bytes) (above) calls
 * ds4_gpu_tensor_alloc_on(t, 0, bytes); ds4_gpu_tensor_alloc_ptr_on(0,
 * bytes) is byte-equivalent. Single-tier callers MAY remain on the
 * legacy 1-arg helper; new multi-tier callers in ds4.c use _ptr_on. */
extern "C" ds4_gpu_tensor *ds4_gpu_tensor_alloc_ptr_on(int tier, uint64_t bytes) {
    if (tier < 0 || tier >= g_n_gpus) {
        fprintf(stderr,
            "ds4: ds4_gpu_tensor_alloc_ptr_on: bad tier %d (n_gpus=%d)\n",
            tier, g_n_gpus);
        return NULL;
    }
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    if (ds4_gpu_tensor_alloc_on(t, tier, bytes) != 0) {
        free(t);
        return NULL;
    }
    return t;
}

/* Heap-allocated managed-memory tensor on a specific logical tier.
 * Differs from ds4_gpu_tensor_alloc_managed only in stamping
 * tier instead of 0. Used by the per-layer KV cache when tier !=0.
 *
 * Managed-memory paging behavior: cudaMallocManaged pages between
 * devices on first-touch. In a single-tier pipeline the page lives on
 * tier 0; in a multi-tier pipeline the layer's kernels run on the
 * layer's tier so the page lives there after first-touch and stays
 * unless another device touches it. Stamping tier matches the home
 * device for free-time accounting. */
extern "C" ds4_gpu_tensor *ds4_gpu_tensor_alloc_managed_on(int tier, uint64_t bytes) {
    if (tier < 0 || tier >= g_n_gpus) {
        fprintf(stderr,
            "ds4: ds4_gpu_tensor_alloc_managed_on: bad tier %d (n_gpus=%d)\n",
            tier, g_n_gpus);
        return NULL;
    }
    if (bytes == 0) bytes = 1;
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    int ok = 0;
    /* Run the cudaMallocManaged call under the home tier's device so the
     * first-touch home matches the stamped device_id; the page itself can
     * migrate freely under managed-memory semantics. */
    WITH_DEVICE(g_gpu[tier].device_id) {
        ok = cuda_ok(cudaMallocManaged(&t->ptr, (size_t)bytes),
                     "managed tensor alloc (tier)");
    }
    if (!ok) { free(t); return NULL; }
    t->bytes = bytes;
    t->owner = 1;
    t->device_id = tier;
    return t;
}

extern "C" int ds4_gpu_tensor_device(const ds4_gpu_tensor *t) {
    return t ? t->device_id : -1;
}

static uint64_t cuda_managed_kv_reserve_bytes(uint64_t total_bytes) {
    const uint64_t min_reserve = 8ull * 1073741824ull;
    const uint64_t max_reserve = 40ull * 1073741824ull;
    uint64_t reserve = total_bytes / 4u;
    if (reserve < min_reserve) reserve = min_reserve;
    if (reserve > max_reserve) reserve = max_reserve;
    return reserve;
}

extern "C" int ds4_gpu_should_use_managed_kv_cache(uint64_t kv_cache_bytes, uint64_t context_bytes) {
    if (kv_cache_bytes == 0) return 0;

    /* Very large KV caches are where device-only cudaMalloc() can make a
     * unified-memory machine unresponsive.  Managed memory restores the old
     * demand-paged behavior for this one long-lived allocation class only. */
    const uint64_t huge_kv = 8ull * 1073741824ull;
    if (kv_cache_bytes >= huge_kv) return 1;

    const uint64_t large_context = 8ull * 1073741824ull;
    if (context_bytes < large_context) return 0;

    size_t free_b = 0;
    size_t total_b = 0;
    cudaError_t err = cudaMemGetInfo(&free_b, &total_b);
    if (err != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }

    const uint64_t free_bytes = (uint64_t)free_b;
    const uint64_t total_bytes = (uint64_t)total_b;
    const uint64_t reserve_bytes = cuda_managed_kv_reserve_bytes(total_bytes);
    if (context_bytes > free_bytes) return 1;
    return free_bytes - context_bytes < reserve_bytes;
}

extern "C" ds4_gpu_tensor *ds4_gpu_tensor_view(const ds4_gpu_tensor *base, uint64_t offset, uint64_t bytes) {
    if (!base || offset > base->bytes || bytes > base->bytes - offset) return NULL;
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    t->ptr = (char *)base->ptr + offset;
    t->bytes = bytes;
    t->owner = 0;
    t->device_id = base->device_id;  /* inherit owning device */
    return t;
}

extern "C" void ds4_gpu_tensor_free(ds4_gpu_tensor *tensor) {
    if (!tensor) return;
    int d = ds4_tensor_device_idx(tensor);
    if (cuda_vmm_tensor_release(tensor)) {
        free(tensor);
        return;
    }
    if (tensor->owner && tensor->ptr) {
        WITH_DEVICE(g_gpu[d].device_id) {
            (void)cudaFree(tensor->ptr);
        }
    }
    free(tensor);
}

extern "C" uint64_t ds4_gpu_tensor_bytes(const ds4_gpu_tensor *tensor) {
    return tensor ? tensor->bytes : 0;
}

extern "C" void *ds4_gpu_tensor_contents(ds4_gpu_tensor *tensor) {
    if (!tensor) return NULL;
    /* Full-device sync preserves legacy semantics. */
    (void)cudaDeviceSynchronize();
    return tensor->ptr;
}

extern "C" int ds4_gpu_tensor_fill_f32(ds4_gpu_tensor *tensor, float value, uint64_t count) {
    if (!tensor || count > tensor->bytes / sizeof(float)) return 0;
    if (count == 0) return 1;
    int d = ds4_tensor_device_idx(tensor);
    int ok = 0;
    WITH_DEVICE(g_gpu[d].device_id) {
        fill_f32_kernel<<<(count + 255u) / 256u, 256>>>((float *)tensor->ptr, count, value);
        ok = cuda_ok(cudaGetLastError(), "tensor fill f32 launch");
    }
    return ok;
}

extern "C" int ds4_gpu_tensor_write(ds4_gpu_tensor *tensor, uint64_t offset, const void *data, uint64_t bytes) {
    if (!tensor || !data || offset > tensor->bytes || bytes > tensor->bytes - offset) return 0;
    int d = ds4_tensor_device_idx(tensor);
    int ok = 0;
    WITH_DEVICE(g_gpu[d].device_id) {
        ok = cuda_ok(cudaMemcpy((char *)tensor->ptr + offset, data, (size_t)bytes,
                                cudaMemcpyHostToDevice),
                     "tensor write");
    }
    return ok;
}

extern "C" int ds4_gpu_tensor_read(const ds4_gpu_tensor *tensor, uint64_t offset, void *data, uint64_t bytes) {
    if (!tensor || !data || offset > tensor->bytes || bytes > tensor->bytes - offset) return 0;
    int d = ds4_tensor_device_idx(tensor);
    int ok = 0;
    WITH_DEVICE(g_gpu[d].device_id) {
        ok = cuda_ok(cudaMemcpy(data, (const char *)tensor->ptr + offset, (size_t)bytes,
                                cudaMemcpyDeviceToHost),
                     "tensor read");
    }
    return ok;
}

extern "C" int ds4_gpu_tensor_copy(ds4_gpu_tensor *dst, uint64_t dst_offset,
                                     const ds4_gpu_tensor *src, uint64_t src_offset,
                                     uint64_t bytes) {
    if (!dst || !src || dst_offset > dst->bytes || src_offset > src->bytes ||
        bytes > dst->bytes - dst_offset || bytes > src->bytes - src_offset) {
        return 0;
    }
    if (bytes == 0) return 1;
    /* Same-device fast path; for cross-device, callers should use
     * ds4_gpu_tensor_copy_xdev. We still tolerate cross-device callers
     * here by routing to D2D copy on the destination's device. */
    int d = ds4_tensor_device_idx(dst);
    int ok = 0;
    WITH_DEVICE(g_gpu[d].device_id) {
        if (g_decode_graph_capturing) {
            ok = cuda_ok(cudaMemcpyAsync((char *)dst->ptr + dst_offset,
                                         (const char *)src->ptr + src_offset,
                                         (size_t)bytes,
                                         cudaMemcpyDeviceToDevice,
                                         cuda_decode_stream()),
                         "tensor copy");
        } else {
            ok = cuda_ok(cudaMemcpy((char *)dst->ptr + dst_offset,
                                    (const char *)src->ptr + src_offset,
                                    (size_t)bytes,
                                    cudaMemcpyDeviceToDevice),
                         "tensor copy");
        }
    }
    return ok;
}

__global__ static void moe_handoff_pack_kernel(
        unsigned char *packed,
        const float *ffn_norm,
        const int32_t *selected,
        const float *weights,
        uint32_t n_embd,
        uint32_t n_expert) {
    const uint32_t i = blockIdx.x * blockDim.x + threadIdx.x;
    float *packed_norm = (float *)packed;
    int32_t *packed_selected = (int32_t *)(packed + (uint64_t)n_embd * sizeof(float));
    float *packed_weights = (float *)(packed + (uint64_t)n_embd * sizeof(float) +
                                      (uint64_t)n_expert * sizeof(int32_t));
    if (i < n_embd) packed_norm[i] = ffn_norm[i];
    if (i < n_expert) {
        packed_selected[i] = selected[i];
        packed_weights[i] = weights[i];
    }
}

extern "C" int ds4_gpu_moe_handoff_pack_tensor(
        ds4_gpu_tensor       *packed,
        const ds4_gpu_tensor *ffn_norm,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t              n_embd,
        uint32_t              n_expert) {
    if (!packed || !ffn_norm || !selected || !weights ||
        n_embd == 0 || n_expert == 0) {
        return 0;
    }
    const uint64_t bytes = (uint64_t)n_embd * sizeof(float) +
                           (uint64_t)n_expert * sizeof(int32_t) +
                           (uint64_t)n_expert * sizeof(float);
    if (packed->bytes < bytes ||
        ffn_norm->bytes < (uint64_t)n_embd * sizeof(float) ||
        selected->bytes < (uint64_t)n_expert * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_expert * sizeof(float)) {
        return 0;
    }
    const uint32_t n = n_embd > n_expert ? n_embd : n_expert;
    moe_handoff_pack_kernel<<<(n + 255u) / 256u, 256>>>(
            (unsigned char *)packed->ptr,
            (const float *)ffn_norm->ptr,
            (const int32_t *)selected->ptr,
            (const float *)weights->ptr,
            n_embd,
            n_expert);
    return cuda_ok(cudaGetLastError(), "moe handoff pack launch");
}

/* Cross-device copy primitive. Path selection (highest priority first):
 *   DS4_FORCE_HOST_BOUNCE=1  -> always pinned-host bounce
 *   DS4_FORCE_CUDA_PEER=1    -> always cudaMemcpyPeerAsync (manual-testing
 *                               override; bypasses g_gpu_peer_ok)
 *   otherwise                -> peer if validation passed at init, else
 *                               pinned-host bounce. */
static int ds4_gpu_tensor_copy_xdev_impl(ds4_gpu_tensor *dst,
                                         const ds4_gpu_tensor *src,
                                         uint64_t bytes,
                                         bool order_dst_before_write) {
    if (!dst || !src) return 0;
    if (bytes == 0) return 1;
    if (bytes > dst->bytes || bytes > src->bytes) return 0;
    int sd = ds4_tensor_device_idx(src);
    int dd = ds4_tensor_device_idx(dst);

    /* Same-device fast path. */
    if (sd == dd) {
        int ok = 0;
        WITH_DEVICE(g_gpu[sd].device_id) {
            cudaStream_t s = (cudaStream_t)g_gpu[sd].stream;
            ok = cuda_ok(cudaMemcpyAsync(dst->ptr, src->ptr, bytes,
                                         cudaMemcpyDeviceToDevice, s),
                          "xdev same-device copy");
            if (ok && g_xdev_sync_debug) {
                ok = cuda_ok(cudaStreamSynchronize(s), "xdev same-device sync");
            }
        }
        return ok;
    }

    int peer = g_gpu_peer_ok[sd][dd];
    if (g_xdev_force_cuda_peer)   peer = 1;
    if (g_xdev_force_host_bounce) peer = 0;

    if (peer) {
        int ok = 0;
        if (order_dst_before_write) {
            WITH_DEVICE(g_gpu[dd].device_id) {
                cudaStream_t s2 = (cudaStream_t)g_gpu[dd].stream;
                cudaEvent_t  e2 = (cudaEvent_t)g_gpu[dd].boundary_event;
                ok = cuda_ok(cudaEventRecord(e2, s2), "peer dst-ready event record");
            }
            if (!ok) return 0;
        } else {
            ok = 1;
        }
        WITH_DEVICE(g_gpu[sd].device_id) {
            cudaStream_t s = (cudaStream_t)g_gpu[sd].stream;
            cudaEvent_t  e = (cudaEvent_t)g_gpu[sd].boundary_event;
            if (order_dst_before_write) {
                ok = cuda_ok(cudaStreamWaitEvent(s, (cudaEvent_t)g_gpu[dd].boundary_event, 0),
                             "peer src wait dst-ready");
            }
            if (ok) ok = cuda_ok(cudaMemcpyPeerAsync(
                            dst->ptr, g_gpu[dd].device_id,
                            src->ptr, g_gpu[sd].device_id,
                            bytes, s),
                          "peer copy");
            if (ok) ok = cuda_ok(cudaEventRecord(e, s), "peer event record");
        }
        if (!ok) return 0;
        WITH_DEVICE(g_gpu[dd].device_id) {
            cudaStream_t s2 = (cudaStream_t)g_gpu[dd].stream;
            (void)cudaStreamWaitEvent(s2, (cudaEvent_t)g_gpu[sd].boundary_event, 0);
            if (g_xdev_sync_debug) {
                ok = cuda_ok(cudaStreamSynchronize(s2), "peer dst sync");
            }
        }
        return ok;
    }

    /* Per-pair pinned-host bounce buffer. */
    if (g_xdev_bounce_bytes[sd][dd] < bytes) {
        if (g_xdev_bounce[sd][dd]) (void)cudaFreeHost(g_xdev_bounce[sd][dd]);
        if (!cuda_ok(cudaMallocHost(&g_xdev_bounce[sd][dd], (size_t)bytes),
                     "bounce alloc")) return 0;
        g_xdev_bounce_bytes[sd][dd] = bytes;
    }
    int ok = 0;
    WITH_DEVICE(g_gpu[sd].device_id) {
        cudaStream_t s = (cudaStream_t)g_gpu[sd].stream;
        cudaEvent_t  e = (cudaEvent_t)g_gpu[sd].boundary_event;
        ok = cuda_ok(cudaMemcpyAsync(g_xdev_bounce[sd][dd], src->ptr, bytes,
                                     cudaMemcpyDeviceToHost, s),
                      "bounce d2h");
        if (ok) ok = cuda_ok(cudaEventRecord(e, s), "bounce event record");
    }
    if (!ok) return 0;
    WITH_DEVICE(g_gpu[dd].device_id) {
        cudaStream_t s2 = (cudaStream_t)g_gpu[dd].stream;
        (void)cudaStreamWaitEvent(s2, (cudaEvent_t)g_gpu[sd].boundary_event, 0);
        ok = cuda_ok(cudaMemcpyAsync(dst->ptr, g_xdev_bounce[sd][dd], bytes,
                                     cudaMemcpyHostToDevice, s2),
                      "bounce h2d");
        if (ok) ok = cuda_ok(cudaStreamSynchronize(s2), "bounce dst sync");
    }
    return ok;
}

extern "C" int ds4_gpu_tensor_copy_xdev(ds4_gpu_tensor *dst,
                                        const ds4_gpu_tensor *src,
                                        uint64_t bytes) {
    return ds4_gpu_tensor_copy_xdev_impl(dst, src, bytes, false);
}

static int ds4_gpu_tensor_copy_xdev_default_impl(ds4_gpu_tensor *dst,
                                                  const ds4_gpu_tensor *src,
                                                  uint64_t bytes) {
    if (!dst || !src || bytes > dst->bytes || bytes > src->bytes) return 0;
    if (bytes == 0u) return 1;
    const int sd = ds4_tensor_device_idx(src);
    const int dd = ds4_tensor_device_idx(dst);
    if (sd == dd) {
        int ok = 0;
        WITH_DEVICE(g_gpu[sd].device_id) {
            ok = cuda_ok(cudaMemcpyAsync(dst->ptr, src->ptr, (size_t)bytes,
                                         cudaMemcpyDeviceToDevice, 0),
                         "default-stream same-device copy");
        }
        return ok;
    }

    int peer = g_gpu_peer_ok[sd][dd];
    if (g_xdev_force_cuda_peer) peer = 1;
    if (g_xdev_force_host_bounce) peer = 0;
    if (peer) {
        int ok = 0;
        WITH_DEVICE(g_gpu[sd].device_id) {
            ok = cuda_ok(cudaMemcpyPeerAsync(
                             dst->ptr, g_gpu[dd].device_id,
                             src->ptr, g_gpu[sd].device_id,
                             (size_t)bytes, 0),
                         "default-stream peer copy");
            if (ok) {
                ok = cuda_ok(cudaEventRecord(
                                 (cudaEvent_t)g_gpu[sd].boundary_event, 0),
                             "default-stream peer event record");
            }
        }
        if (ok) {
            WITH_DEVICE(g_gpu[dd].device_id) {
                ok = cuda_ok(cudaStreamWaitEvent(
                                 0,
                                 (cudaEvent_t)g_gpu[sd].boundary_event,
                                 0),
                             "default-stream peer destination wait");
            }
        }
        return ok;
    }

    if (g_xdev_bounce_bytes[sd][dd] < bytes) {
        if (g_xdev_bounce[sd][dd]) (void)cudaFreeHost(g_xdev_bounce[sd][dd]);
        if (!cuda_ok(cudaMallocHost(&g_xdev_bounce[sd][dd], (size_t)bytes),
                     "default-stream bounce alloc")) return 0;
        g_xdev_bounce_bytes[sd][dd] = bytes;
    }
    int ok = 0;
    WITH_DEVICE(g_gpu[sd].device_id) {
        ok = cuda_ok(cudaMemcpy(g_xdev_bounce[sd][dd], src->ptr, (size_t)bytes,
                                cudaMemcpyDeviceToHost),
                     "default-stream bounce d2h");
    }
    if (ok) {
        WITH_DEVICE(g_gpu[dd].device_id) {
            ok = cuda_ok(cudaMemcpy(dst->ptr, g_xdev_bounce[sd][dd],
                                    (size_t)bytes, cudaMemcpyHostToDevice),
                         "default-stream bounce h2d");
        }
    }
    return ok;
}

extern "C" int ds4_gpu_tensor_copy_xdev_default(ds4_gpu_tensor *dst,
                                                 const ds4_gpu_tensor *src,
                                                 uint64_t bytes) {
    return ds4_gpu_tensor_copy_xdev_default_impl(dst, src, bytes);
}

extern "C" int ds4_gpu_tensor_copy_xdev3_default_dst(
        ds4_gpu_tensor *dst0,
        const ds4_gpu_tensor *src0,
        uint64_t bytes0,
        ds4_gpu_tensor *dst1,
        const ds4_gpu_tensor *src1,
        uint64_t bytes1,
        ds4_gpu_tensor *dst2,
        const ds4_gpu_tensor *src2,
        uint64_t bytes2) {
    ds4_gpu_tensor *dsts[3] = {dst0, dst1, dst2};
    const ds4_gpu_tensor *srcs[3] = {src0, src1, src2};
    const uint64_t sizes[3] = {bytes0, bytes1, bytes2};
    int sd = -1;
    int dd = -1;
    for (int i = 0; i < 3; i++) {
        if (sizes[i] == 0u) continue;
        if (!dsts[i] || !srcs[i] || sizes[i] > dsts[i]->bytes ||
            sizes[i] > srcs[i]->bytes) {
            return 0;
        }
        const int this_sd = ds4_tensor_device_idx(srcs[i]);
        const int this_dd = ds4_tensor_device_idx(dsts[i]);
        if (sd < 0) {
            sd = this_sd;
            dd = this_dd;
        } else if (sd != this_sd || dd != this_dd) {
            return 0;
        }
    }
    if (sd < 0) return 1;
    if (sd == dd) {
        int ok = 1;
        WITH_DEVICE(g_gpu[sd].device_id) {
            for (int i = 0; ok && i < 3; i++) {
                if (sizes[i] == 0u) continue;
                ok = cuda_ok(cudaMemcpyAsync(
                        dsts[i]->ptr, srcs[i]->ptr, (size_t)sizes[i],
                        cudaMemcpyDeviceToDevice, 0),
                        "grouped default same-device copy");
            }
        }
        return ok;
    }

    int peer = g_gpu_peer_ok[dd][sd];
    if (g_xdev_force_cuda_peer) peer = 1;
    if (g_xdev_force_host_bounce) peer = 0;
    if (!peer) {
        for (int i = 0; i < 3; i++) {
            if (sizes[i] != 0u &&
                !ds4_gpu_tensor_copy_xdev_default_impl(
                        dsts[i], srcs[i], sizes[i])) {
                return 0;
            }
        }
        return 1;
    }

    int ok = 0;
    WITH_DEVICE(g_gpu[sd].device_id) {
        ok = cuda_ok(cudaEventRecord(
                         (cudaEvent_t)g_gpu[sd].boundary_event, 0),
                     "grouped default source-ready record");
    }
    if (!ok) return 0;
    WITH_DEVICE(g_gpu[dd].device_id) {
        ok = cuda_ok(cudaStreamWaitEvent(
                         0, (cudaEvent_t)g_gpu[sd].boundary_event, 0),
                     "grouped default destination wait");
        for (int i = 0; ok && i < 3; i++) {
            if (sizes[i] == 0u) continue;
            ok = cuda_ok(cudaMemcpyPeerAsync(
                             dsts[i]->ptr, g_gpu[dd].device_id,
                             srcs[i]->ptr, g_gpu[sd].device_id,
                             (size_t)sizes[i], 0),
                         "grouped destination-stream peer copy");
        }
    }
    return ok;
}

extern "C" int ds4_gpu_tensor_copy_xdev3(ds4_gpu_tensor       *dst0,
                                         const ds4_gpu_tensor *src0,
                                         uint64_t              bytes0,
                                         ds4_gpu_tensor       *dst1,
                                         const ds4_gpu_tensor *src1,
                                         uint64_t              bytes1,
                                         ds4_gpu_tensor       *dst2,
                                         const ds4_gpu_tensor *src2,
                                         uint64_t              bytes2) {
    ds4_gpu_tensor *dsts[3] = {dst0, dst1, dst2};
    const ds4_gpu_tensor *srcs[3] = {src0, src1, src2};
    uint64_t bytes[3] = {bytes0, bytes1, bytes2};
    int first = -1;
    for (int i = 0; i < 3; i++) {
        if (bytes[i] == 0) continue;
        if (!dsts[i] || !srcs[i] ||
            bytes[i] > dsts[i]->bytes || bytes[i] > srcs[i]->bytes) {
            return 0;
        }
        if (first < 0) first = i;
    }
    if (first < 0) return 1;

    const int sd = ds4_tensor_device_idx(srcs[first]);
    const int dd = ds4_tensor_device_idx(dsts[first]);
    for (int i = first + 1; i < 3; i++) {
        if (bytes[i] == 0) continue;
        if (ds4_tensor_device_idx(srcs[i]) != sd ||
            ds4_tensor_device_idx(dsts[i]) != dd) {
            int ok = 1;
            for (int j = 0; ok && j < 3; j++) {
                if (bytes[j] == 0) continue;
                ok = ds4_gpu_tensor_copy_xdev(dsts[j], srcs[j], bytes[j]);
            }
            return ok;
        }
    }

    if (sd == dd) {
        int ok = 0;
        WITH_DEVICE(g_gpu[sd].device_id) {
            cudaStream_t s = (cudaStream_t)g_gpu[sd].stream;
            ok = 1;
            for (int i = 0; ok && i < 3; i++) {
                if (bytes[i] == 0) continue;
                ok = cuda_ok(cudaMemcpyAsync(dsts[i]->ptr, srcs[i]->ptr, bytes[i],
                                             cudaMemcpyDeviceToDevice, s),
                             "xdev3 same-device copy");
            }
            if (ok && g_xdev_sync_debug) {
                ok = cuda_ok(cudaStreamSynchronize(s), "xdev3 same-device sync");
            }
        }
        return ok;
    }

    int peer = g_gpu_peer_ok[sd][dd];
    if (g_xdev_force_cuda_peer)   peer = 1;
    if (g_xdev_force_host_bounce) peer = 0;
    if (!peer) {
        int ok = 1;
        for (int i = 0; ok && i < 3; i++) {
            if (bytes[i] == 0) continue;
            ok = ds4_gpu_tensor_copy_xdev(dsts[i], srcs[i], bytes[i]);
        }
        return ok;
    }

    int ok = 0;
    WITH_DEVICE(g_gpu[sd].device_id) {
        cudaStream_t s = (cudaStream_t)g_gpu[sd].stream;
        cudaEvent_t  e = (cudaEvent_t)g_gpu[sd].boundary_event;
        ok = 1;
        for (int i = 0; ok && i < 3; i++) {
            if (bytes[i] == 0) continue;
            ok = cuda_ok(cudaMemcpyPeerAsync(
                            dsts[i]->ptr, g_gpu[dd].device_id,
                            srcs[i]->ptr, g_gpu[sd].device_id,
                            bytes[i], s),
                         "peer copy3");
        }
        if (ok) ok = cuda_ok(cudaEventRecord(e, s), "peer copy3 event record");
    }
    if (!ok) return 0;
    WITH_DEVICE(g_gpu[dd].device_id) {
        cudaStream_t s2 = (cudaStream_t)g_gpu[dd].stream;
        ok = cuda_ok(cudaStreamWaitEvent(s2, (cudaEvent_t)g_gpu[sd].boundary_event, 0),
                     "peer copy3 dst wait");
        if (ok && g_xdev_sync_debug) {
            ok = cuda_ok(cudaStreamSynchronize(s2), "peer copy3 dst sync");
        }
    }
    return ok;
}

extern "C" int ds4_gpu_tensor_copy_xdev_ordered(ds4_gpu_tensor *dst,
                                                const ds4_gpu_tensor *src,
                                                uint64_t bytes) {
    return ds4_gpu_tensor_copy_xdev_impl(dst, src, bytes, true);
}

extern "C" int ds4_gpu_tensor_wait_xdev(const ds4_gpu_tensor *src, int dst_tier) {
    if (!src) return 0;
    if (dst_tier < 0 || dst_tier >= g_n_gpus) return 0;
    int sd = ds4_tensor_device_idx(src);
    int dd = dst_tier;
    if (sd == dd) return 1;
    int ok = 0;
    WITH_DEVICE(g_gpu[sd].device_id) {
        cudaStream_t s = (cudaStream_t)g_gpu[sd].stream;
        cudaEvent_t  e = (cudaEvent_t)g_gpu[sd].boundary_event;
        ok = cuda_ok(cudaEventRecord(e, s), "xdev wait source event record");
    }
    if (!ok) return 0;
    WITH_DEVICE(g_gpu[dd].device_id) {
        cudaStream_t s2 = (cudaStream_t)g_gpu[dd].stream;
        ok = cuda_ok(cudaStreamWaitEvent(s2, (cudaEvent_t)g_gpu[sd].boundary_event, 0),
                     "xdev wait destination wait");
        if (ok && g_xdev_sync_debug) {
            ok = cuda_ok(cudaStreamSynchronize(s2), "xdev wait dst sync");
        }
    }
    return ok;
}

extern "C" int ds4_gpu_tensor_wait_xdev_default(
        const ds4_gpu_tensor *src,
        int dst_tier) {
    if (!src || dst_tier < 0 || dst_tier >= g_n_gpus) return 0;
    const int sd = ds4_tensor_device_idx(src);
    const int dd = dst_tier;
    if (sd == dd) return 1;
    int ok = 0;
    WITH_DEVICE(g_gpu[sd].device_id) {
        ok = cuda_ok(cudaEventRecord(
                         (cudaEvent_t)g_gpu[sd].boundary_event, 0),
                     "default xdev wait source event record");
    }
    if (!ok) return 0;
    WITH_DEVICE(g_gpu[dd].device_id) {
        ok = cuda_ok(cudaStreamWaitEvent(
                         0,
                         (cudaEvent_t)g_gpu[sd].boundary_event,
                         0),
                     "default xdev wait destination wait");
    }
    return ok;
}

extern "C" int ds4_gpu_q8_cache_suppressed(void) {
    return g_q8_cache_suppressed;
}

extern "C" void ds4_gpu_set_q8_cache_suppressed(int suppressed) {
    g_q8_cache_suppressed = suppressed ? 1 : 0;
}

__global__ static void pack_slot_rows_f32_kernel(float *out, const float *slots, uint32_t n_rows, uint32_t width, uint32_t n_slots, uint32_t slot_cap);

extern "C" int ds4_gpu_pack_slot_rows_f32_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *slots,
        uint32_t                n_rows,
        uint32_t                width,
        uint32_t                n_slots,
        uint32_t                slot_cap) {
    uint64_t slot_rows = 0;
    uint64_t slot_elems = 0;
    uint64_t out_rows = 0;
    uint64_t out_elems = 0;
    if (!out || !slots || n_rows == 0 || width == 0 || n_slots == 0 ||
        slot_cap == 0 || n_rows > slot_cap ||
        (uint64_t)n_slots > UINT64_MAX / slot_cap ||
        (slot_rows = (uint64_t)n_slots * slot_cap) > UINT64_MAX / width ||
        (slot_elems = slot_rows * width) > UINT64_MAX / sizeof(float) ||
        (uint64_t)n_rows > UINT64_MAX / n_slots ||
        (out_rows = (uint64_t)n_rows * n_slots) > UINT64_MAX / width ||
        (out_elems = out_rows * width) > UINT64_MAX / sizeof(float) ||
        slots->bytes < slot_elems * sizeof(float) ||
        out->bytes < out_elems * sizeof(float)) {
        return 0;
    }
    const uint64_t blocks = (out_elems + 255u) / 256u;
    if (blocks > UINT32_MAX) return 0;
    pack_slot_rows_f32_kernel<<<(unsigned)blocks, 256>>>(
            (float *)out->ptr,
            (const float *)slots->ptr,
            n_rows,
            width,
            n_slots,
            slot_cap);
    return cuda_ok(cudaGetLastError(), "pack_slot_rows_f32 launch");
}

extern "C" int ds4_gpu_tensor_copy_f32_to_q8_kv(ds4_gpu_tensor *dst, uint64_t dst_offset,
                                                const ds4_gpu_tensor *src, uint64_t src_offset,
                                                uint32_t rows, uint32_t head_dim,
                                                uint64_t dst_row_bytes) {
    if (!dst || !src) return 0;
    if (rows == 0) return 1;
    if (head_dim == 0 || dst_row_bytes < sizeof(float) + (uint64_t)head_dim) {
        return 0;
    }
    if ((uint64_t)rows > UINT64_MAX / head_dim ||
        (uint64_t)rows * head_dim > UINT64_MAX / sizeof(float) ||
        (uint64_t)rows > UINT64_MAX / dst_row_bytes) {
        return 0;
    }
    const uint64_t src_bytes = (uint64_t)rows * head_dim * sizeof(float);
    const uint64_t dst_bytes = (uint64_t)rows * dst_row_bytes;
    if (src_offset > src->bytes || src_bytes > src->bytes - src_offset ||
        dst_offset > dst->bytes || dst_bytes > dst->bytes - dst_offset) {
        return 0;
    }
    f32_rows_to_q8_kv_kernel<<<rows, 256>>>(
            (char *)dst->ptr + dst_offset,
            (const float *)((const char *)src->ptr + src_offset),
            rows,
            head_dim,
            dst_row_bytes);
    return cuda_ok(cudaGetLastError(), "tensor copy f32 to q8 kv launch");
}

static void cuda_decode_profile_note_wait(
        double elapsed_ms,
        int profile,
        int ds_phase) {
    if (profile) {
        g_decode_profile.sync_calls++;
        g_decode_profile.wait_calls++;
        g_decode_profile.wait_ms += elapsed_ms;
    }
    if (ds_phase) g_ds_decode_bandwidth.phase_sync_ms += elapsed_ms;
}

static int cuda_decode_profile_event_synchronize(cudaEvent_t event, const char *label) {
    /* Reuse one QPC pair for both the existing profiler and DS phase accounting.
     * The shipped decode path reaches the helpers at command boundaries, never
     * from the per-expert loop. */
    const int profile = cuda_decode_profile_enabled();
    const int ds_phase = g_ds_decode_bandwidth.interval_open();
    const int timed = profile || ds_phase;
    const double t0 = timed ? cuda_decode_profile_now_ms() : 0.0;
    const int ok = cuda_ok(cudaEventSynchronize(event), label);
    if (timed) {
        cuda_decode_profile_note_wait(
            cuda_decode_profile_now_ms() - t0, profile, ds_phase);
    }
    return ok;
}

static int cuda_decode_profile_stream_synchronize(cudaStream_t stream, const char *label) {
    const int profile = cuda_decode_profile_enabled();
    const int ds_phase = g_ds_decode_bandwidth.interval_open();
    const int timed = profile || ds_phase;
    const double t0 = timed ? cuda_decode_profile_now_ms() : 0.0;
    const int ok = cuda_ok(cudaStreamSynchronize(stream), label);
    if (timed) {
        cuda_decode_profile_note_wait(
            cuda_decode_profile_now_ms() - t0, profile, ds_phase);
    }
    return ok;
}

static int cuda_decode_profile_synchronize(const char *label) {
    const int profile = cuda_decode_profile_enabled();
    const int ds_phase = g_ds_decode_bandwidth.interval_open();
    const int timed = profile || ds_phase;
    const double t0 = timed ? cuda_decode_profile_now_ms() : 0.0;
    const int ok = cuda_ok(cudaDeviceSynchronize(), label);
    if (timed) {
        cuda_decode_profile_note_wait(
            cuda_decode_profile_now_ms() - t0, profile, ds_phase);
    }
    return ok;
}

extern "C" int ds4_gpu_begin_commands(void) {
    if (cuda_decode_profile_enabled()) g_decode_profile.command_buffers++;
    return 1;
}
extern "C" int ds4_gpu_flush_commands(void) {
    if (cuda_decode_profile_enabled()) g_decode_profile.commits++;
    return cuda_decode_profile_synchronize("flush");
}
extern "C" int ds4_gpu_signal_selected_readback_ready(uint64_t *event_value) {
    if (event_value) *event_value = 1;
    if (cuda_decode_profile_enabled()) g_decode_profile.commits++;
    return cuda_decode_profile_synchronize("selected readback signal");
}
extern "C" int ds4_gpu_commit_and_wait_selected_readback(uint64_t event_value, const char *label) {
    (void)event_value;
    if (cuda_decode_profile_enabled()) g_decode_profile.commits++;
    return cuda_decode_profile_synchronize(label ? label : "selected readback wait");
}
extern "C" int ds4_gpu_wait_selected_readback_ready(uint64_t event_value, const char *label) {
    (void)event_value;
    (void)label;
    return cuda_decode_profile_synchronize("selected readback wait");
}
extern "C" int ds4_gpu_end_commands(void) {
    cuda_model_load_progress_finish();
    /* R4 layer commands wait on their exact DirectStorage fence and publish a
     * per-layer compute_done event. The pipeline finish supplies the single
     * chunk-boundary synchronization. */
    if (g_prefill_pipeline.active) {
        if (getenv("DS4_CUDA_PREFILL_PIPELINE_SYNC_EACH_LAYER") != NULL) {
            if (cuda_decode_profile_enabled()) g_decode_profile.commits++;
            return cuda_decode_profile_synchronize("R4 diagnostic layer sync");
        }
        return g_prefill_pipeline.failed ? 0 : 1;
    }
    if (cuda_decode_profile_enabled()) g_decode_profile.commits++;
    if (g_cuda_end_stream_sync) {
        return cuda_decode_profile_stream_synchronize((cudaStream_t)0,
                                                      "end commands stream");
    }
    return cuda_decode_profile_synchronize("end commands");
}
extern "C" int ds4_gpu_synchronize(void) {
    cuda_model_load_progress_finish();
    return cuda_decode_profile_synchronize("synchronize");
}

extern "C" void ds4_gpu_decode_profile_get(ds4_gpu_decode_profile_snapshot *snapshot) {
    if (!snapshot) return;
    *snapshot = g_decode_profile;
    snapshot->enabled = cuda_decode_profile_enabled();
}

/* [merge 2026-08-16] RESTORED from the pre-merge tree verbatim. The merge deleted this function
 * and rewired its only production call site (in ds4_gpu_set_model_map_spans) to
 * ds4_gpu_set_model_map(), which does the same teardown PLUS a cudaHostRegister of the entire
 * model mapping -- impossible for 90.9 GiB on a 32 GB card, and the cause of the -22% decode
 * regression. This is bookkeeping/teardown only: no registration, no allocation. */
static int cuda_model_set_host_map(const void *model_map, uint64_t model_size) {
    if (!model_map || model_size == 0) return 0;
    const int same_backing_model =
        g_model_host_base == model_map &&
        g_model_registered_size == model_size;
#if defined(_WIN32)
    if (g_prefill_pipeline.active && same_backing_model) {
        /* Every layer span already names its compute-owned slot. Releasing
         * ranges here would invalidate work still queued on stream zero. */
        return 1;
    }
    if (g_prefill_pipeline.active && !same_backing_model) {
        cuda_prefill_pipeline_release();
    }
#endif
    cuda_stream_selected_cache_invalidate();
    if (!same_backing_model) {
        cuda_stream_expert_cache_release_all();
    }
    cuda_model_range_release_all(same_backing_model);
    if (!same_backing_model) {
        cuda_model_load_progress_reset();
    }
    cuda_q8_f16_cache_release_all();
    g_q8_f16_disabled_after_oom = 0;
    g_q8_f16_budget_notice_printed = 0;
    for (const cuda_q8_f32_range &r : g_q8_f32_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f32_ranges.clear();
    g_q8_f32_by_offset.clear();
    g_q8_f32_bytes = 0;
    if (!same_backing_model) {
        if (g_model_device_owned && g_model_device_base) {
            (void)cudaFree((void *)g_model_device_base);
            g_model_device_owned = 0;
        }
        if (g_model_registered && g_model_host_base) {
            (void)cudaHostUnregister((void *)g_model_host_base);
            g_model_registered = 0;
        }
        g_model_host_base = model_map;
        g_model_device_base = (const char *)model_map;
        g_model_registered_size = model_size;
    } else if (!g_model_device_owned && !g_model_registered) {
        g_model_device_base = (const char *)model_map;
    }
    g_model_range_mapping_supported = 1;
    g_model_hmm_direct = 0;
    g_model_cache_full = 0;
    g_model_mapping_failure_notice_printed = 0;
    g_indexed_attention_plan_notice_count = 0;
    g_fp8_raw_store_notice_count = 0;
    if (g_model_fd >= 0 && g_model_fd_host_base == NULL) {
        g_model_fd_host_base = model_map;
    }
    return 1;
}

extern "C" int ds4_gpu_set_model_map(const void *model_map, uint64_t model_size) {
    if (!model_map || model_size == 0) return 0;
    if (g_model_host_base == model_map && g_model_registered_size == model_size) return 1;
    cuda_stream_selected_cache_release();
    cuda_model_range_release_all();
    cuda_q8_f16_cache_release_all();
    g_q8_f16_disabled_after_oom = 0;
    g_q8_f16_budget_notice_printed = 0;
    for (const cuda_q8_f32_range &r : g_q8_f32_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f32_ranges.clear();
    g_q8_f32_by_offset.clear();
    g_q8_f32_bytes = 0;
    if (g_model_device_owned && g_model_device_base) {
        (void)cudaFree((void *)g_model_device_base);
        g_model_device_owned = 0;
    }
    if (g_model_registered && g_model_host_base) {
        (void)cudaHostUnregister((void *)g_model_host_base);
        g_model_registered = 0;
    }
    g_model_host_base = model_map;
    g_model_device_base = (const char *)model_map;
    g_model_registered_size = model_size;
    g_model_range_mapping_supported = 1;
    g_model_hmm_direct = 0;
    g_model_cache_full = 0;
    g_model_mapping_failure_notice_printed = 0;
    g_indexed_attention_plan_notice_count = 0;
    g_fp8_raw_store_notice_count = 0;
    if (g_model_fd >= 0 && g_model_fd_host_base == NULL) {
        g_model_fd_host_base = model_map;
    }

    /* Never pin or copy the complete model in SSD mode, even on integrated GPUs. */
    if (g_ssd_streaming_mode) return 1;

    const char *copy_env = getenv("DS4_CUDA_COPY_MODEL");
    if (copy_env && copy_env[0]) {
        void *dev = NULL;
        const double t0 = clock() / (double)CLOCKS_PER_SEC;
        cudaError_t err = cudaMalloc(&dev, (size_t)model_size);
        if (err == cudaSuccess) {
            fprintf(stderr, "ds4: CUDA copying %.2f GiB model to device memory\n",
                    (double)model_size / 1073741824.0);
            err = cudaMemcpy(dev, model_map, (size_t)model_size, cudaMemcpyHostToDevice);
            if (err == cudaSuccess) {
                g_model_device_base = (const char *)dev;
                g_model_device_owned = 1;
                const double t1 = clock() / (double)CLOCKS_PER_SEC;
                fprintf(stderr, "ds4: CUDA model copy complete in %.3fs\n", t1 - t0);
                return 1;
            }
            fprintf(stderr, "ds4: CUDA model copy failed: %s\n", cudaGetErrorString(err));
            (void)cudaFree(dev);
            (void)cudaGetLastError();
        } else {
            fprintf(stderr, "ds4: CUDA model allocation skipped: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
        }
    }

    if (cuda_integrated_artifact_map(model_map)) {
        fprintf(stderr,
                "ds4: CUDA aligned artifacts replace expert residency; "
                "leaving the %.2f GiB model mmap unpinned\n",
                (double)model_size / 1073741824.0);
        return 1;
    }

    cudaError_t err = cudaHostRegister((void *)model_map, (size_t)model_size,
                                       cudaHostRegisterMapped | cudaHostRegisterReadOnly);
    if (err == cudaSuccess) {
        void *dev = NULL;
        err = cudaHostGetDevicePointer(&dev, (void *)model_map, 0);
        if (err == cudaSuccess && dev) {
            g_model_device_base = (const char *)dev;
            g_model_registered = 1;
            fprintf(stderr, "ds4: CUDA registered %.2f GiB model mapping for device access\n",
                    (double)model_size / 1073741824.0);
        } else {
            fprintf(stderr, "ds4: CUDA host registration pointer lookup failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
        }
    } else {
        fprintf(stderr, "ds4: CUDA host registration skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
    }
    return 1;
}

extern "C" int ds4_gpu_set_model_map_range(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size, uint64_t max_tensor_bytes) {
    (void)max_tensor_bytes;
    if (!ds4_gpu_register_model_map_no_copy(model_map, model_size)) return 0;
    if (getenv("DS4_CUDA_COPY_MODEL_CHUNKED") != NULL &&
        !cuda_model_copy_chunked(model_map, model_size, map_offset, map_size)) {
        (void)cuda_model_prefetch_range(model_map, model_size, map_offset, map_size);
    }
    return 1;
}

extern "C" int ds4_gpu_set_aux_model_map_range(
        const void *model_map,
        uint64_t model_size,
        uint64_t map_offset,
        uint64_t map_size) {
    if (!model_map || model_size == 0 || map_size == 0 ||
        map_offset > model_size || map_size > model_size - map_offset) {
        return 0;
    }
    if (cuda_model_range_is_cached(model_map, map_offset, map_size)) return 1;

    int current_device = 0;
    int integrated = 0;
    int pageable = 0;
    if (getenv("DS4_CUDA_AUX_FORCE_COPY") == NULL &&
        cudaGetDevice(&current_device) == cudaSuccess &&
        cudaDeviceGetAttribute(&integrated, cudaDevAttrIntegrated,
                               current_device) ==
            cudaSuccess &&
        cudaDeviceGetAttribute(&pageable, cudaDevAttrPageableMemoryAccess,
                               current_device) == cudaSuccess &&
        integrated && pageable) {
        g_model_ranges.push_back({
                model_map, map_offset, map_size,
                (char *)model_map + map_offset,
                NULL, NULL, 0, 0, 0, 1});
        fprintf(stderr,
                "ds4: CUDA directly mapped %.2f GiB auxiliary model\n",
                (double)map_size / 1073741824.0);
        return 1;
    }

    void *device = NULL;
    cudaError_t err = cudaMalloc(&device, (size_t)map_size);
    if (err != cudaSuccess) {
        fprintf(stderr,
                "ds4: CUDA vision map allocation failed (%.2f GiB): %s\n",
                (double)map_size / 1073741824.0,
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    const uint64_t chunk = 64ull * 1024ull * 1024ull;
    const char *source = (const char *)model_map + map_offset;
    for (uint64_t copied = 0; copied < map_size; copied += chunk) {
        const uint64_t bytes = map_size - copied < chunk ?
                               map_size - copied : chunk;
        err = cudaMemcpy((char *)device + copied, source + copied,
                         (size_t)bytes, cudaMemcpyHostToDevice);
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: CUDA vision map copy failed at %.2f/%.2f GiB: %s\n",
                    (double)copied / 1073741824.0,
                    (double)map_size / 1073741824.0,
                    cudaGetErrorString(err));
            (void)cudaFree(device);
            (void)cudaGetLastError();
            return 0;
        }
    }
    g_model_ranges.push_back({model_map, map_offset, map_size,
                              (char *)device, NULL, NULL, 0, 0, 0});
    g_model_range_bytes += map_size;
    fprintf(stderr, "ds4: CUDA mapped %.2f GiB auxiliary model\n",
            (double)map_size / 1073741824.0);
    return 1;
}

/* Register the mmap'd host model pointer for selective-cache lookups WITHOUT
 * triggering any device-side copy. Used by multi-GPU placement scaffolding's
 * multi-tier path so DS4_CUDA_COPY_MODEL cannot reintroduce a full-model
 * copy that defeats the per-device selective cache.
 *
 * This is the no-copy subset of ds4_gpu_set_model_map: same bookkeeping
 * for the host pointer plus cudaHostRegister, but skipping the
 * DS4_CUDA_COPY_MODEL branch that allocates and copies the entire model. */
static int cuda_register_model_map(const void *model_map, uint64_t model_size,
                                   bool register_all) {
    if (!model_map || model_size == 0) return 0;
    if (g_model_host_base == model_map && g_model_registered_size == model_size) return 1;

    cuda_stream_selected_cache_release();
    cuda_model_range_release_all();
    cuda_q8_f16_cache_release_all();
    g_q8_f16_disabled_after_oom = 0;
    g_q8_f16_budget_notice_printed = 0;
    for (const cuda_q8_f32_range &r : g_q8_f32_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f32_ranges.clear();
    g_q8_f32_by_offset.clear();
    g_q8_f32_bytes = 0;
    if (g_model_device_owned && g_model_device_base) {
        (void)cudaFree((void *)g_model_device_base);
        g_model_device_owned = 0;
    }
    if (g_model_registered && g_model_host_base) {
        (void)cudaHostUnregister((void *)g_model_host_base);
        g_model_registered = 0;
    }
    g_model_host_base = model_map;
    g_model_device_base = (const char *)model_map;
    g_model_registered_size = model_size;
    g_model_range_mapping_supported = 1;
    g_model_hmm_direct = 0;
    g_model_cache_full = 0;
    if (g_model_fd >= 0 && g_model_fd_host_base == NULL) {
        g_model_fd_host_base = model_map;
    }

    /* A sharded mapping must never pin the unowned expert ranges. */
    if (!register_all) return 1;

    if (cuda_integrated_artifact_map(model_map)) {
        fprintf(stderr,
                "ds4: CUDA aligned artifacts replace expert residency; "
                "leaving the %.2f GiB model mmap unpinned\n",
                (double)model_size / 1073741824.0);
        return 1;
    }

    cudaError_t err = cudaHostRegister((void *)model_map, (size_t)model_size,
                                       cudaHostRegisterMapped | cudaHostRegisterReadOnly);
    if (err == cudaSuccess) {
        void *dev = NULL;
        err = cudaHostGetDevicePointer(&dev, (void *)model_map, 0);
        if (err == cudaSuccess && dev) {
            g_model_device_base = (const char *)dev;
            g_model_registered = 1;
            fprintf(stderr,
                    "ds4: CUDA (no-copy) registered %.2f GiB model mapping for multi-tier selective cache\n",
                    (double)model_size / 1073741824.0);
        } else {
            fprintf(stderr,
                    "ds4: CUDA (no-copy) host registration pointer lookup failed: %s\n",
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
        }
    } else {
        fprintf(stderr,
                "ds4: CUDA (no-copy) host registration skipped: %s\n",
                cudaGetErrorString(err));
        (void)cudaGetLastError();
    }
    return 1;
}

extern "C" int ds4_gpu_register_model_map_no_copy(const void *model_map, uint64_t model_size) {
    return cuda_register_model_map(model_map, model_size, true);
}

/* Set the current CUDA device by LOGICAL tier index (0..g_n_gpus-1).
 * Maps to the physical CUDA device id stored in g_gpu[].device_id.
 * Added for multi-GPU placement scaffolding (multi-GPU CLI); first executed by
 * multi-GPU execution (follow-up). */
extern "C" int ds4_gpu_set_current_device(int logical_tier) {
    if (logical_tier < 0 || logical_tier >= g_n_gpus) return -1;
    if (!g_cuda_no_setdevice_cache && g_current_logical_tier == logical_tier) {
        return 0;
    }
    if (cudaSetDevice(g_gpu[logical_tier].device_id) == cudaSuccess) {
        g_current_logical_tier = logical_tier;
        return 0;
    }
    g_current_logical_tier = -1;
    return -1;
}

/* Fenced device switch for sequential cross-device pipelines (GLM
 * per-layer placement): work queued on the next device's default stream
 * waits for everything queued so far on the previous device's default
 * stream. Async — no host sync. Falls back to a plain switch when the
 * device does not change. */
extern "C" int ds4_gpu_set_current_device_fenced(int logical_tier) {
    if (logical_tier < 0 || logical_tier >= g_n_gpus) return -1;
    static cudaEvent_t fence_ev[DS4_MAX_GPUS];
    /* Resolve the ACTUAL current device: WITH_DEVICE blocks and direct
     * cudaSetDevice calls can leave g_current_logical_tier stale, and a
     * false "already there" here strands work on the wrong device. */
    int cur_dev = -1;
    (void)cudaGetDevice(&cur_dev);
    int prev = -1;
    for (int t = 0; t < g_n_gpus; t++) {
        if (g_gpu[t].device_id == cur_dev) { prev = t; break; }
    }
    if (getenv("DS4_GLM_FENCE_TRACE")) {
        fprintf(stderr, "ds4: fenced switch %d -> %d\n", prev, logical_tier);
    }
    if (prev == logical_tier) {
        g_current_logical_tier = logical_tier;
        return 0;
    }
    if (prev >= 0 && prev < g_n_gpus && prev != logical_tier) {
        if (cudaSetDevice(g_gpu[prev].device_id) != cudaSuccess) return -1;
        if (!fence_ev[prev] &&
            cudaEventCreateWithFlags(&fence_ev[prev],
                                     cudaEventDisableTiming) != cudaSuccess) {
            fence_ev[prev] = NULL;
        }
        if (fence_ev[prev]) {
            (void)cudaEventRecord(fence_ev[prev], 0);
        }
        if (cudaSetDevice(g_gpu[logical_tier].device_id) != cudaSuccess) {
            g_current_logical_tier = -1;
            return -1;
        }
        g_current_logical_tier = logical_tier;
        if (fence_ev[prev]) {
            (void)cudaStreamWaitEvent(0, fence_ev[prev], 0);
        }
        return 0;
    }
    return ds4_gpu_set_current_device(logical_tier);
}

/* =========================================================================
 * Per-device selective model cache (selective model cache).
 *
 * ds4_gpu_device_cache_tensors copies the listed source ranges from the
 * host mmap onto device_id's selective slab and appends sorted lookup
 * entries. The legacy chunked-copy machinery (cuda_model_range_*) is
 * NOT disturbed — it continues to drive all existing callers. New
 * lookups fall back to it when no selective entry covers the range.
 *
 * Caller-context preference for overlap: when the same source range is
 * cached on multiple devices, ds4_gpu_lookup_cache returns the entry
 * whose device matches cudaGetDevice().
 * ========================================================================= */

extern "C" int ds4_gpu_device_cache_tensors(int device_id,
                                            const ds4_tensor_range *ranges,
                                            int n_ranges) {
    if (device_id < 0 || device_id >= DS4_MAX_GPUS) return 1;
    if (n_ranges < 0 || (!ranges && n_ranges > 0)) return 2;
    if (n_ranges == 0) return 0;

    if (!g_model_host_base || g_model_registered_size == 0) return 3;

    /* Validate ranges against the mmap'd model bounds; reject ranges
     * that overflow or extend past the mapped region. Done in a
     * separate pass before any allocation so a bad input doesn't
     * partially grow the slab. */
    uint64_t want_bytes = 0;
    for (int i = 0; i < n_ranges; i++) {
        if (ranges[i].target_device != device_id) continue;
        const uint64_t off = ranges[i].source_offset;
        const uint64_t nb  = ranges[i].bytes;
        /* Overflow-safe upper bound: off + nb must not exceed model
         * size, and the sum must not wrap. */
        if (nb == 0) continue;
        if (off > g_model_registered_size) return 8;
        if (nb > g_model_registered_size - off) return 9;
        /* Accumulate into want_bytes with overflow check. */
        if (want_bytes > UINT64_MAX - nb) return 10;
        want_bytes += nb;
    }
    if (want_bytes == 0) return 0;

    cuda_device_cache &c = g_dev_cache[device_id];

    int prev_device = -1;
    if (cudaGetDevice(&prev_device) != cudaSuccess) prev_device = -1;
    if (cudaSetDevice(device_id) != cudaSuccess) return 4;

    /* Allocate or grow the slab via cudaMalloc + d2d copy. */
    void *new_base = NULL;
    size_t new_bytes = c.bytes + want_bytes;

    /* Refuse cleanly before cudaMalloc if the device clearly cannot hold
     * the slab. The multi-tier packer reserves per-tier runtime scratch
     * before placing tensors, but it cannot predict the cudaMalloc
     * allocator's overhead (alignment, fragmentation after CUDA context
     * init, default driver-side reservations). On a borderline budget
     * that overhead pushes a "fits-by-packer-math" layout past the actual
     * free pool and the cudaMalloc below OOMs after the engine already
     * committed to the layout — same silent-late-OOM failure mode the
     * upfront refusal path was added to eliminate. Catch it here too. */
    {
        size_t free_b = 0, total_b = 0;
        if (cudaMemGetInfo(&free_b, &total_b) == cudaSuccess) {
            /* free_b already excludes the existing slab (it's still
             * allocated), so the additional cudaMalloc only needs
             * new_bytes free — not new_bytes + c.bytes. The old slab is
             * freed AFTER the d2d copy succeeds. 2 GiB safety covers what
             * the engine will allocate AFTER the cache slab in the same
             * session_create: per-tier graph scratch (the planner can't
             * predict its cumulative cudaMalloc alignment overhead),
             * cuBLAS workspace beyond the 64 MiB the packer already
             * reserves, and driver-side allocator slack. Without this
             * headroom a borderline budget that fits the slab itself can
             * still OOM at the per-tier tensor allocations a few moments
             * later — same silent-late-OOM failure mode, one layer up. */
            const size_t safety = (size_t)2ull * 1024ull * 1024ull * 1024ull;
            const size_t need = new_bytes + safety;
            if (need > free_b) {
                fprintf(stderr,
                        "ds4: device cache slab needs %.2f GiB on device %d "
                        "but only %.2f GiB free (slab=%.2f GiB + %.2f GiB safety). "
                        "Lower --gpu-vram / --ctx-max, or use --gpu-vram auto on "
                        "a host with more free VRAM. Refusing upfront to avoid "
                        "late OOM at cudaMalloc.\n",
                        (double)need / 1073741824.0,
                        device_id,
                        (double)free_b / 1073741824.0,
                        (double)new_bytes / 1073741824.0,
                        (double)safety / 1073741824.0);
                if (prev_device >= 0) (void)cudaSetDevice(prev_device);
                return 5;
            }
        }
        /* If cudaMemGetInfo itself failed, fall through; cudaMalloc's own
         * error path still catches the late case, just with a less helpful
         * message. */
    }

    if (!cuda_ok(cudaMalloc(&new_base, new_bytes), "device cache alloc")) {
        if (prev_device >= 0) (void)cudaSetDevice(prev_device);
        return 5;
    }
    if (c.present && c.bytes > 0) {
        cudaError_t e = cudaMemcpy(new_base, c.base, c.bytes,
                                   cudaMemcpyDeviceToDevice);
        if (e != cudaSuccess) {
            cuda_ok(e, "device cache grow d2d");
            (void)cudaFree(new_base);
            if (prev_device >= 0) (void)cudaSetDevice(prev_device);
            return 6;
        }
        /* Re-base existing entries on this device. */
        char *old_base = (char *)c.base;
        char *grown    = (char *)new_base;
        for (size_t k = 0; k < g_cache_ranges.size(); k++) {
            if (g_cache_ranges[k].device_id == device_id) {
                g_cache_ranges[k].device_ptr =
                    grown + ((char *)g_cache_ranges[k].device_ptr - old_base);
            }
        }
        (void)cudaFree(c.base);
    }
    c.base = new_base;
    c.bytes = new_bytes;
    c.present = 1;

    /* Copy ranges and append entries. */
    const char *host_base = (const char *)g_model_host_base;
    size_t write_off = c.bytes - want_bytes;
    for (int i = 0; i < n_ranges; i++) {
        if (ranges[i].target_device != device_id) continue;
        char *dev_ptr = (char *)c.base + write_off;
        cudaError_t e = cudaMemcpy(dev_ptr,
                                   host_base + ranges[i].source_offset,
                                   (size_t)ranges[i].bytes,
                                   cudaMemcpyHostToDevice);
        if (e != cudaSuccess) {
            cuda_ok(e, "device cache range h2d");
            if (prev_device >= 0) (void)cudaSetDevice(prev_device);
            return 7;
        }
        cache_range_entry ent;
        ent.source_offset = ranges[i].source_offset;
        ent.bytes         = ranges[i].bytes;
        ent.device_id     = device_id;
        ent.device_ptr    = dev_ptr;
        g_cache_ranges.push_back(ent);
        write_off += ranges[i].bytes;
    }

    /* Keep sorted by source_offset for binary-search lookup. */
    std::sort(g_cache_ranges.begin(), g_cache_ranges.end(),
              [](const cache_range_entry &a, const cache_range_entry &b) {
                  if (a.source_offset != b.source_offset)
                      return a.source_offset < b.source_offset;
                  return a.device_id < b.device_id;
              });

    if (prev_device >= 0) (void)cudaSetDevice(prev_device);
    return 0;
}

/* Install support-model tensor ranges into device_id's strict cache,
 * copying from the registered support map and keying entries at
 * source_offset + bias. Standalone slab (does not touch the main cache
 * slab growth path). */
extern "C" int ds4_gpu_device_cache_support_tensors(int device_id,
                                                    int entry_device_id,
                                                    const ds4_tensor_range *ranges,
                                                    int n_ranges,
                                                    int from_main_map) {
    if (device_id < 0 || device_id >= DS4_MAX_GPUS) return 1;
    if (entry_device_id < 0 || entry_device_id >= DS4_MAX_GPUS) return 1;
    if (n_ranges <= 0 || !ranges) return 2;
    const char *src_base;
    uint64_t src_size;
    uint64_t key_bias;
    if (from_main_map) {
        /* Auxiliary main-model ranges (e.g. the embedding bucket for the
         * DSpark executor tier): standalone slab, unbiased offsets. */
        src_base = (const char *)g_model_host_base;
        src_size = g_model_registered_size;
        key_bias = 0;
    } else {
        src_base = (const char *)g_support_host_base;
        src_size = g_support_host_size;
        key_bias = g_support_offset_bias;
        if (key_bias == 0) return 3;
    }
    if (!src_base || src_size == 0) return 3;
    uint64_t want = 0;
    for (int i = 0; i < n_ranges; i++) {
        const uint64_t off = ranges[i].source_offset;
        const uint64_t nb = ranges[i].bytes;
        if (nb == 0) continue;
        if (off > src_size || nb > src_size - off) return 8;
        if (want > UINT64_MAX - nb) return 9;
        want += nb;
    }
    if (want == 0) return 0;
    int prev_device = -1;
    if (cudaGetDevice(&prev_device) != cudaSuccess) prev_device = -1;
    if (cudaSetDevice(device_id) != cudaSuccess) return 4;
    void *base = NULL;
    if (!cuda_ok(cudaMalloc(&base, (size_t)want), "support cache alloc")) {
        if (prev_device >= 0) (void)cudaSetDevice(prev_device);
        return 5;
    }
    const char *host_base = src_base;
    size_t write_off = 0;
    for (int i = 0; i < n_ranges; i++) {
        if (ranges[i].bytes == 0) continue;
        char *dev_ptr = (char *)base + write_off;
        cudaError_t e = cudaMemcpy(dev_ptr,
                                   host_base + ranges[i].source_offset,
                                   (size_t)ranges[i].bytes,
                                   cudaMemcpyHostToDevice);
        if (e != cudaSuccess) {
            cuda_ok(e, "support cache range h2d");
            (void)cudaFree(base);
            if (prev_device >= 0) (void)cudaSetDevice(prev_device);
            return 7;
        }
        cache_range_entry ent;
        ent.source_offset = ranges[i].source_offset + key_bias;
        ent.bytes = ranges[i].bytes;
        /* Entries can claim a different (executor) device than the one the
         * slab physically lives on: strict lookups filter by entry device,
         * and peer access lets the executor's kernels dereference the
         * spilled pointer directly. */
        ent.device_id = entry_device_id;
        ent.device_ptr = dev_ptr;
        g_cache_ranges.push_back(ent);
        write_off += ranges[i].bytes;
    }
    std::sort(g_cache_ranges.begin(), g_cache_ranges.end(),
              [](const cache_range_entry &a, const cache_range_entry &b) {
                  if (a.source_offset != b.source_offset)
                      return a.source_offset < b.source_offset;
                  return a.device_id < b.device_id;
              });
    if (getenv("DS4_DSPARK_VERIFY_CACHE") != NULL) {
        /* Read back every installed range and compare with the host copy. */
        int bad = 0;
        write_off = 0;
        for (int i = 0; i < n_ranges; i++) {
            if (ranges[i].bytes == 0) continue;
            char *dev_ptr = (char *)base + write_off;
            std::vector<char> tmp((size_t)ranges[i].bytes);
            if (cudaMemcpy(tmp.data(), dev_ptr, (size_t)ranges[i].bytes,
                           cudaMemcpyDeviceToHost) != cudaSuccess ||
                memcmp(tmp.data(), host_base + ranges[i].source_offset,
                       (size_t)ranges[i].bytes) != 0) {
                fprintf(stderr,
                        "ds4: support cache VERIFY MISMATCH offset=%llu bytes=%llu dev=%d\n",
                        (unsigned long long)ranges[i].source_offset,
                        (unsigned long long)ranges[i].bytes, device_id);
                bad++;
            }
            write_off += ranges[i].bytes;
        }
        fprintf(stderr, "ds4: support cache verify dev=%d ranges=%d bad=%d\n",
                device_id, n_ranges, bad);
    }
    if (prev_device >= 0) (void)cudaSetDevice(prev_device);
    return 0;
}

extern "C" int ds4_gpu_lookup_cache(uint64_t source_offset, uint64_t bytes,
                                    int *out_device_id, void **out_device_ptr) {
    int active_device = -1;
    (void)cudaGetDevice(&active_device);

    if (!g_cache_ranges.empty()) {
        /* upper_bound: first entry with source_offset > query.
         * Candidates are at strictly earlier positions; scan all of
         * them rather than breaking on the first non-covering entry,
         * because the table allows overlap across devices. */
        auto it = std::upper_bound(
            g_cache_ranges.begin(), g_cache_ranges.end(),
            source_offset,
            [](uint64_t off, const cache_range_entry &e) {
                return off < e.source_offset;
            });
        const cache_range_entry *match_any  = NULL;
        const cache_range_entry *match_pref = NULL;
        while (it != g_cache_ranges.begin()) {
            --it;
            /* Overflow-safe coverage check:
             *   1. source_offset >= it->source_offset
             *   2. bytes <= it->bytes - (source_offset - it->source_offset)
             * The second form computes only the remaining capacity inside
             * the entry, so neither side can overflow even with bytes ==
             * UINT64_MAX. */
            if (source_offset >= it->source_offset) {
                uint64_t into = source_offset - it->source_offset;
                if (into <= it->bytes && bytes <= it->bytes - into) {
                    if (it->device_id == active_device) {
                        match_pref = &*it;
                        break;
                    }
                    if (!match_any) match_any = &*it;
                }
            }
            /* Do NOT break on non-covering: an earlier entry may still
             * cover if its bytes extend far enough. */
        }
        const cache_range_entry *m = match_pref ? match_pref : match_any;
        if (m) {
            if (out_device_id) *out_device_id = m->device_id;
            if (out_device_ptr) {
                *out_device_ptr =
                    (char *)m->device_ptr + (source_offset - m->source_offset);
            }
            return 1;
        }
    }

    /* Legacy chunk-aware fallback (device 0 only). */
    const char *p = cuda_model_range_ptr_from_fd(g_model_host_base,
                                                  source_offset, bytes,
                                                  "lookup_cache");
    if (p) {
        if (out_device_id) *out_device_id = 0;
        if (out_device_ptr) *out_device_ptr = (void *)p;
        return 1;
    }
    return 0;
}

extern "C" int ds4_gpu_lookup_cache_device(uint64_t source_offset, uint64_t bytes) {
    int d = -1;
    if (!ds4_gpu_lookup_cache(source_offset, bytes, &d, NULL)) return -1;
    return d;
}

/* Strict per-device selective-cache lookup.
 *
 * Returns 1 only if a covering entry exists whose device_id matches the
 * caller-supplied expected_device. Otherwise returns 0 with *out_device_ptr
 * untouched. Unlike ds4_gpu_lookup_cache, this variant performs NO host-
 * pointer fallback (no FD-cache, no model_range_ptr_from_fd) and NO
 * different-device fallback. It is the canonical lookup for multi-tier
 * dispatch where consuming a different device's pointer would be a
 * correctness bug. expected_device is a PHYSICAL CUDA device id (the
 * value stored in g_gpu[logical_tier].device_id, not the logical tier
 * index). The caller is expected to have cudaSetDevice'd to
 * expected_device before invoking; the returned pointer is valid to
 * consume from that device's kernel. Added for
 * multi-GPU execution (multi-GPU execution). */
extern "C" int ds4_gpu_lookup_cache_strict(uint64_t source_offset,
                                            uint64_t bytes,
                                            int      expected_device,
                                            void   **out_device_ptr) {
    if (g_cache_ranges.empty()) return 0;

    auto it = std::upper_bound(
        g_cache_ranges.begin(), g_cache_ranges.end(),
        source_offset,
        [](uint64_t off, const cache_range_entry &e) {
            return off < e.source_offset;
        });
    while (it != g_cache_ranges.begin()) {
        --it;
        if (source_offset < it->source_offset) {
            /* Should not happen given upper_bound semantics, but defensive. */
            continue;
        }
        uint64_t into = source_offset - it->source_offset;
        if (into > it->bytes) continue;
        if (bytes > it->bytes - into) continue;
        if (it->device_id != expected_device) continue;
        if (out_device_ptr) {
            *out_device_ptr =
                (char *)it->device_ptr + (source_offset - it->source_offset);
        }
        return 1;
    }
    return 0;
}

extern "C" int ds4_gpu_set_model_fd(int fd) {
    ds4_gpu_stream_expert_cache_prefetch_finish(true);
    g_model_fd = fd;
    g_model_fd_host_base = g_model_host_base;
    g_model_file_size = 0;
    if (g_model_direct_fd >= 0) {
        (void)close(g_model_direct_fd);
        g_model_direct_fd = -1;
    }
    g_model_direct_align = 1;
    if (fd >= 0) {
#if defined(_WIN32)
        struct _stat64 st;
        if (_fstat64(fd, &st) == 0 && st.st_size > 0) {
            g_model_file_size = (uint64_t)st.st_size;
            g_model_direct_align = 4096;
        }
#else
        struct stat st;
        if (fstat(fd, &st) == 0 && st.st_size > 0) {
            g_model_file_size = (uint64_t)st.st_size;
            if (st.st_blksize > 1) g_model_direct_align = (uint64_t)st.st_blksize;
        }
#endif
#if defined(__linux__) && defined(O_DIRECT)
        if (getenv("DS4_CUDA_NO_DIRECT_IO") == NULL) {
            char proc_path[64];
            snprintf(proc_path, sizeof(proc_path), "/proc/self/fd/%d", fd);
            int direct_fd = open(proc_path, O_RDONLY | O_DIRECT);
            if (direct_fd >= 0) {
                g_model_direct_fd = direct_fd;
                if (g_model_direct_align < 512) g_model_direct_align = 512;
                if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                    fprintf(stderr, "ds4: CUDA model direct I/O enabled (align=%llu)\n",
                            (unsigned long long)g_model_direct_align);
                }
            } else if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                fprintf(stderr, "ds4: CUDA model direct I/O unavailable: %s\n", strerror(errno));
            }
        }
#endif
    }
#if defined(_WIN32)
    /* Step 2 proof gate. Reads a span of the real model twice -- once at queue depth 1, once
     * batched -- and byte-compares both against pread. Runs before anything in the decode path
     * depends on DirectStorage, so the premise (that queue depth is what is missing) is confirmed
     * or refuted cheaply. Opt-in: DS4_DS_SELFTEST=<MiB to read>, or 1 for the 512 MiB default. */
    if (fd >= 0) {
        const char *st = getenv("DS4_DS_SELFTEST");
        if (st && st[0]) {
            unsigned long mb = strtoul(st, NULL, 10);
            if (mb <= 1) mb = 512;
            if (mb > 4096) mb = 4096;
            uint64_t span = (uint64_t)mb * 1048576ull;
            /* Read from a third of the way in: past the header, comfortably inside expert data. */
            uint64_t start = g_model_file_size > (span * 3ull) ? (g_model_file_size / 3ull) : 0ull;
            start &= ~4095ull;
            if (g_model_file_size > start + span) {
                /* [2026-08-20] MATRIX SWEEP. chunk and batch used to be hardcoded (8 MiB / 64), so
                 * the two variables that matter most - request SIZE and queue DEPTH - could not be
                 * swept at all, and every other knob was being measured at one arbitrary point in
                 * their plane. Now both take comma-separated lists and the cross product runs in ONE
                 * process, which matters because a process start costs ~40 s while a selftest costs
                 * ~1 s: a 36-point matrix is 40 s instead of 25 minutes.
                 *
                 * Defaults reproduce the previous single point EXACTLY (8 MiB, batch 64), so an
                 * unset environment changes nothing.
                 *   DS4_DS_SELFTEST_CHUNKS_MIB  e.g. "1,4,8,16,32"   (4 ~= the 4.5 MiB decode issues)
                 *   DS4_DS_SELFTEST_BATCHES     e.g. "8,32,64,128,256"
                 * Run-to-run spread on identical settings was measured at 43% (5.38 vs 7.71 GB/s),
                 * so DS4_DS_SELFTEST_REPEATS defaults to 3 - a single point cannot resolve anything
                 * on this path, which is exactly why the 08-17 sweeps read as noise. */
                const char *chunks_env  = getenv("DS4_DS_SELFTEST_CHUNKS_MIB");
                const char *batches_env = getenv("DS4_DS_SELFTEST_BATCHES");
                const char *reps_env    = getenv("DS4_DS_SELFTEST_REPEATS");
                unsigned long reps = reps_env && reps_env[0] ? strtoul(reps_env, NULL, 10) : 3ul;
                if (reps < 1ul) reps = 1ul;
                if (reps > 16ul) reps = 16ul;

                uint32_t chunk_list[16]; uint32_t n_chunk = 0;
                if (chunks_env && chunks_env[0]) {
                    const char *p = chunks_env;
                    while (*p && n_chunk < 16u) {
                        unsigned long v = strtoul(p, NULL, 10);
                        if (v >= 1ul && v <= 256ul) chunk_list[n_chunk++] = (uint32_t)(v * 1048576ul);
                        while (*p && *p != ',') p++;
                        if (*p == ',') p++;
                    }
                }
                if (n_chunk == 0u) { chunk_list[0] = 8u * 1048576u; n_chunk = 1u; }

                uint32_t batch_list[16]; uint32_t n_batch = 0;
                if (batches_env && batches_env[0]) {
                    const char *p = batches_env;
                    while (*p && n_batch < 16u) {
                        unsigned long v = strtoul(p, NULL, 10);
                        if (v >= 1ul && v <= 4096ul) batch_list[n_batch++] = (uint32_t)v;
                        while (*p && *p != ',') p++;
                        if (*p == ',') p++;
                    }
                }
                if (n_batch == 0u) { batch_list[0] = 64u; n_batch = 1u; }

                /* [2026-08-20] EVERY POINT MUST READ A **DIFFERENT** REGION.
                 *
                 * `start` and `span` are computed ONCE, above, outside all three loops. Until now
                 * every point re-read the IDENTICAL bytes: a 36-point matrix at repeats=3 read the
                 * same 1 GiB **108 times**. Only the first read can have come from the drive; the
                 * rest measure whatever the OS/DS path kept resident. That is not a small bias -
                 * it is the difference between measuring a disk and measuring a cache, and it is
                 * why the GPU-dest matrix produced 13 physically impossible values (1 GiB in ~100 ns)
                 * and a 5x spread on identical settings. Those numbers are VOID, not merely noisy.
                 *
                 * Fix: walk each point to its own non-overlapping slot. If the file cannot supply
                 * one slot per point we say so IN THE MARKER rather than silently reusing regions -
                 * a residency confound that is announced can be reasoned about; one that is hidden
                 * has already cost this project one whole matrix. */
                uint32_t total_points = n_chunk * n_batch * (uint32_t)reps;
                uint64_t avail       = g_model_file_size > start ? (g_model_file_size - start) : 0ull;
                uint64_t slots       = span > 0ull ? (avail / span) : 0ull;
                int      unique      = (slots >= (uint64_t)total_points) ? 1 : 0;
                fprintf(stderr,
                        "ds4: [DS4_DS_SELFTEST_MATRIX_V1] chunks=%u batches=%u repeats=%lu "
                        "points=%u span_mib=%llu distinct_slots=%llu unique_regions=%s\n",
                        n_chunk, n_batch, reps, total_points,
                        (unsigned long long)(span / 1048576ull),
                        (unsigned long long)slots,
                        unique ? "yes" : "NO-REGIONS-REUSED-RESULTS-ARE-RESIDENCY-CONFOUNDED");
                uint32_t point_idx = 0;
                for (uint32_t ci = 0; ci < n_chunk; ci++) {
                    for (uint32_t bi = 0; bi < n_batch; bi++) {
                        for (unsigned long r = 0; r < reps; r++) {
                            uint64_t off = slots > 0ull
                                         ? start + ((uint64_t)point_idx % slots) * span
                                         : start;
                            off &= ~4095ull;
                            fprintf(stderr,
                                    "ds4: [DS4_DS_SELFTEST_POINT_V1] chunk_mib=%.2f batch=%u rep=%lu "
                                    "offset_mib=%llu\n",
                                    (double)chunk_list[ci] / 1048576.0, batch_list[bi], r + 1ul,
                                    (unsigned long long)(off / 1048576ull));
                            if(!ds4_ds_selftest(fd,off,span,chunk_list[ci],batch_list[bi])) {
                                fprintf(stderr,"ds4: FATAL requested DirectStorage selftest failed; refusing startup\n");
                                exit(EXIT_FAILURE);
                            }
                            point_idx++;
                        }
                    }
                }
            } else {
                fprintf(stderr, "ds4: DirectStorage selftest skipped: model smaller than the span\n");
            }
        }
    }
#endif
    return 1;
}

static int cuda_build_derived_artifacts(
        const void *model_map,
        uint64_t model_size, uint64_t file_size,
        const char *model_path, uint32_t rank, uint32_t world) {
    if ((world != 1u && world != 2u) || rank >= world) return 0;
    if (!model_map || model_size == 0 || !model_path || !model_path[0]) return 0;
    if (!g_derived_ranges.empty()) return (int)g_derived_ranges.size();
    if (getenv("DS4_CUDA_NO_DERIVED_WEIGHTS") != NULL) return 0;
    const char *build = getenv("DS4_CUDA_BUILD_ARTIFACTS");
    if (build && strcmp(build, "0") == 0) return 0;

    int device = 0;
    int integrated = 0;
    if (cudaGetDevice(&device) != cudaSuccess ||
        cudaDeviceGetAttribute(&integrated, cudaDevAttrIntegrated, device) != cudaSuccess ||
        !integrated) {
        return 0;
    }

    ds4_repack_file mapped;
    if (!ds4_repack_map_file("ds4", model_path, mapped)) return 0;
    if (mapped.size != file_size || model_size > file_size) {
        ds4_repack_unmap_file(mapped);
        fprintf(stderr, "ds4: aligned artifact build skipped: model size changed\n");
        return 0;
    }
    std::vector<ds4_repack_tensor> records;
    const bool catalog_ok =
        ds4_repack_collect_catalog("ds4", mapped, nullptr, &records);
    ds4_repack_unmap_file(mapped);
    if (!catalog_ok) return 0;

    if (world == 2u) {
        /* Repack only the owned half. Dense projections have different slice
         * layouts and keep their existing raw caches in network TP. */
        std::vector<ds4_repack_tensor> owned;
        for (ds4_repack_tensor t : records) {
            if (!ds4_repack_iq2_candidate(t) && !ds4_repack_q2k_candidate(t)) continue;
            if (t.dims[2] % world || t.bytes % world || t.elements % world) return 0;
            t.dims[2] /= world;
            t.bytes /= world;
            t.elements /= world;
            t.off += rank * t.bytes;
            if (t.off > model_size || t.bytes > model_size - t.off) return 0;
            owned.push_back(t);
        }
        records.swap(owned);
    }

    const bool build_moe =
        cuda_aligned_iq2_enabled() && cuda_aligned_q2k_enabled();
    const bool build_q8 = world == 1u && cuda_aligned_q8_enabled();
    if (!build_moe && !build_q8) return 0;

    ds4_repack_build_args args;
    args.log_prefix = "ds4";
    args.model_id = "base";
    args.path = model_path;
    args.records = &records;
    args.device = device;
    args.copy_chunk_bytes = 256ull * 1048576ull;

    const double t0 = cuda_wall_sec();
    std::vector<ds4_repack_artifact> artifacts;
    uint64_t built_bytes = 0;
    uint64_t part_bytes = 0;
    bool ok = true;
    if (build_moe) {
        ok = ds4_repack_build_q2k_aligned(args, artifacts, &part_bytes);
        built_bytes += part_bytes;
    }
    if (ok && build_moe) {
        ok = ds4_repack_build_iq2_aligned(args, artifacts, &part_bytes);
        built_bytes += part_bytes;
    }
    if (ok && build_q8) {
        ok = ds4_repack_build_q8_aligned(args, artifacts, &part_bytes);
        built_bytes += part_bytes;
    }
    if (!ok || artifacts.empty()) {
        for (ds4_repack_artifact &artifact : artifacts) {
            if (artifact.dev) (void)cudaFree(artifact.dev);
        }
        fprintf(stderr, "ds4: aligned artifact build failed; using raw weights\n");
        return 0;
    }

    for (const ds4_repack_artifact &artifact : artifacts) {
        g_derived_ranges.push_back({
            model_map,
            artifact.t->off,
            artifact.t->bytes,
            artifact.kind,
            artifact.in_dim,
            artifact.out_dim,
            artifact.group_count,
            artifact.bytes,
            (char *)artifact.dev,
        });
    }

    int replaces_complete = build_moe ? 1 : 0;
    uint64_t replace_candidates = 0;
    for (const ds4_repack_tensor &tensor : records) {
        if (!ds4_repack_iq2_candidate(tensor) &&
            !ds4_repack_q2k_candidate(tensor)) {
            continue;
        }
        replace_candidates++;
        bool found = false;
        for (const ds4_repack_artifact &artifact : artifacts) {
            if (artifact.t == &tensor) {
                found = true;
                break;
            }
        }
        if (!found) replaces_complete = 0;
    }
    if (replace_candidates == 0) replaces_complete = 0;

    g_derived_replace_map = model_map;
    g_derived_replaces_complete = replaces_complete;
    g_derived_artifact_bytes = built_bytes;
    g_derived_artifact_build_secs = cuda_wall_sec() - t0;
    if (!g_aligned_q81_scratch) {
        const size_t scratch_bytes = 96u * 1024u * 1024u;
        cudaError_t scratch_err = cudaMalloc(&g_aligned_q81_scratch,
                                             scratch_bytes);
        if (scratch_err == cudaSuccess) {
            ds4_mmq_set_aligned_q81_scratch(g_aligned_q81_scratch,
                                             scratch_bytes);
        } else {
            g_aligned_q81_scratch = NULL;
            (void)cudaGetLastError();
            fprintf(stderr,
                    "ds4: aligned decode scratch allocation failed: %s\n",
                    cudaGetErrorString(scratch_err));
        }
    }
    fprintf(stderr,
            "ds4: built %llu aligned CUDA artifacts (%.2f GiB) in %.1fs%s\n",
            (unsigned long long)g_derived_ranges.size(),
            (double)g_derived_artifact_bytes / 1073741824.0,
            g_derived_artifact_build_secs,
            replaces_complete ? "; expert raw residency replaced" : "");
    return (int)g_derived_ranges.size();
}

extern "C" int ds4_gpu_build_derived_artifacts(
        const void *model_map, uint64_t model_size, const char *model_path) {
    return cuda_build_derived_artifacts(model_map, model_size, model_size, model_path, 0, 1);
}

extern "C" int ds4_gpu_build_derived_artifacts_shard(
        const void *model_map, uint64_t model_size, uint64_t file_size,
        const char *model_path, uint32_t rank) {
    return cuda_build_derived_artifacts(model_map, model_size, file_size, model_path, rank, 2);
}

extern "C" int ds4_gpu_model_range_replaced(
        const void *model_map,
        uint64_t offset,
        uint64_t bytes) {
    if (!cuda_model_map_replaces_complete(model_map) || bytes == 0) return 0;
    for (const cuda_derived_range &range : g_derived_ranges) {
        if (range.host_base == model_map &&
            range.source_offset == offset &&
            range.source_bytes == bytes &&
            (range.kind == CUDA_DERIVED_IQ2_XXS_ALIGNED_MOE ||
             range.kind == CUDA_DERIVED_Q2_K_ALIGNED_MOE)) {
            return 1;
        }
    }
    return 0;
}

extern "C" int ds4_gpu_cache_model_range(const void *model_map, uint64_t model_size, uint64_t offset, uint64_t bytes, const char *label) {
    if (!model_map || bytes == 0) return 1;
    if (offset > model_size || bytes > model_size - offset) return 0;
    if (cuda_span_fully_replaced(model_map, offset, bytes)) return 1;
    if (!cuda_model_range_ptr(model_map, offset, bytes, label ? label : "model_tensor")) return 0;
    return cuda_model_range_is_cached(model_map, offset, bytes);
}

extern "C" int ds4_gpu_cache_q8_f16_range(const void *model_map, uint64_t model_size, uint64_t offset, uint64_t bytes, uint64_t in_dim, uint64_t out_dim, const char *label) {
    if (!model_map || bytes == 0) return 1;
    if (offset > model_size || bytes > model_size - offset) return 0;
    static int optional_q8_preload_disabled = 0;
    if (optional_q8_preload_disabled) return 1;
    const char *cache_label = label ? label : "q8_0";
    /* Preload runs before any multi-tier dispatch. The cache entries it creates
     * are device-0 by construction; multi-tier callers in kernel wrappers will
     * miss the linear scan (device_id filter) and allocate fresh per-device
     * copies the first time they're consulted. */
    if (getenv("DS4_CUDA_Q8_F32_PRELOAD") != NULL &&
        cuda_q8_f32_cache_allowed(cache_label, in_dim, out_dim)) {
        if (cuda_q8_f32_ptr(model_map, offset, bytes, in_dim, out_dim, 0, cache_label)) return 1;
        optional_q8_preload_disabled = 1;
        return 1;
    }
    if (!cuda_q8_f16_preload_allowed(cache_label, in_dim, out_dim)) return 1;
    if (cuda_q8_f16_cache_bounded()) {
        const uint64_t cap = cuda_q8_f16_cache_limit_bytes();
        if (in_dim != 0 && out_dim > UINT64_MAX / in_dim / sizeof(__half))
            cuda_q8_f16_cache_required_failure("preload dimensions overflow", UINT64_MAX);
        const uint64_t wanted = in_dim * out_dim * sizeof(__half);
        if (g_q8_f16_bytes > cap || wanted > cap - g_q8_f16_bytes) {
            fprintf(stderr, "ds4: CUDA bounded q8 fp16 preload complete "
                    "cached_bytes=%llu cap_bytes=%llu; runtime eviction preserves F16 numerical path\n",
                    (unsigned long long)g_q8_f16_bytes, (unsigned long long)cap);
            optional_q8_preload_disabled = 1;
            return 1;
        }
    }
    if (cuda_q8_f16_ptr(model_map, offset, bytes, in_dim, out_dim, 0, cache_label)) return 1;
    optional_q8_preload_disabled = 1;
    return 1;
}

extern "C" void ds4_gpu_print_memory_report(const char *label) {
    size_t free_b = 0, total_b = 0;
    (void)cudaMemGetInfo(&free_b, &total_b);
    fprintf(stderr, "ds4: CUDA memory report %s: free %.2f MiB total %.2f MiB\n",
            label ? label : "", (double)free_b / 1048576.0, (double)total_b / 1048576.0);
}

extern "C" void ds4_gpu_set_quality(bool quality) {
    g_quality_mode = quality ? 1 : 0;
    const cublasMath_t math_mode =
        (g_quality_mode || getenv("DS4_CUDA_NO_TF32") != NULL)
            ? CUBLAS_DEFAULT_MATH
            : CUBLAS_TF32_TENSOR_OP_MATH;
    /* Walk every initialized per-tier handle. Single-tier (g_n_gpus == 1)
     * walks exactly one entry. On any device-switch failure,
     * skip the tier and continue — the function is void and the math-mode
     * setting is advisory, but log so misconfiguration is visible. */
    for (int i = 0; i < g_n_gpus; i++) {
        if (!g_gpu[i].cublas_ready || !g_gpu[i].cublas) continue;
        int prev = -1;
        cudaError_t derr = cudaGetDevice(&prev);
        if (derr != cudaSuccess) {
            fprintf(stderr,
                "ds4: ds4_gpu_set_quality: cudaGetDevice failed before tier %d "
                "(dev=%d): %s; skipping\n",
                i, g_gpu[i].device_id, cudaGetErrorString(derr));
            (void)cudaGetLastError();
            continue;
        }
        derr = cudaSetDevice(g_gpu[i].device_id);
        if (derr != cudaSuccess) {
            fprintf(stderr,
                "ds4: ds4_gpu_set_quality: cudaSetDevice(%d) failed for tier %d: "
                "%s; skipping\n",
                g_gpu[i].device_id, i, cudaGetErrorString(derr));
            (void)cudaGetLastError();
            if (prev >= 0) (void)cudaSetDevice(prev);
            continue;
        }
        cublasStatus_t st = cublasSetMathMode((cublasHandle_t)g_gpu[i].cublas, math_mode);
        if (st != CUBLAS_STATUS_SUCCESS) {
            fprintf(stderr,
                "ds4: ds4_gpu_set_quality: cublasSetMathMode failed on tier %d "
                "(dev=%d): status %d\n",
                i, g_gpu[i].device_id, (int)st);
        }
        if (prev >= 0) (void)cudaSetDevice(prev);
    }
}

extern "C" void ds4_gpu_set_ssd_streaming(bool enabled) {
    g_ssd_streaming_mode = enabled ? 1 : 0;
    cuda_stream_selected_cache_invalidate();
    if (!g_ssd_streaming_mode) {
        cuda_stream_selected_cache_release();
        cuda_stream_expert_cache_release_all();
        cuda_stream_host_expert_cache_release_all();
    }
}

