}

extern "C" void ds4_gpu_set_streaming_host_expert_cache_budget_bytes(uint64_t bytes) {
    g_stream_host_expert_budget_bytes_override = bytes;
    cuda_stream_host_expert_cache_release_all();
}

extern "C" void ds4_gpu_set_streaming_expert_cache_expert_bytes(uint64_t bytes) {
    if (g_stream_expert_bytes != bytes) cuda_stream_selected_cache_release();
    g_stream_expert_bytes = bytes;
