extern "C" uint64_t ds4_gpu_recommended_working_set_size(void) {
    /* GLM graph memory guard: on this backend the model weights are
     * distributed across all devices by the multi-tier placement, so the
     * relevant budget is the aggregate VRAM. */
    int n = 0;
    if (cudaGetDeviceCount(&n) != cudaSuccess || n <= 0) return 0;
    size_t free_b = 0, total_b = 0;
    if (cudaMemGetInfo(&free_b, &total_b) != cudaSuccess) return 0;
    return (uint64_t)total_b * (uint64_t)n;
}

extern "C" uint32_t ds4_gpu_stream_expert_cache_configured_count(void) {
    if (!cuda_stream_expert_cache_budget_visible_to_shared()) return 0;
    return cuda_stream_expert_cache_configured_budget();
}

extern "C" uint32_t ds4_gpu_stream_expert_cache_current_count(void) {
    uint64_t count = 0;
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        count += g_stream_expert_caches[i].count;
    }
    return count > UINT32_MAX ? UINT32_MAX : (uint32_t)count;
}

extern "C" uint32_t ds4_gpu_stream_host_expert_cache_configured_count(void) {
    if (!g_ssd_streaming_mode) return 0;
    return cuda_stream_host_expert_cache_requested_budget();
}

/* Host-tier capacity in experts of this size. A byte budget (--ram-streaming-cache-experts
 * NGB) leaves the count budget at 0, so configured_count() reads 0 before the first
 * allocation; restore and the hotlist need the capacity the allocation will get. */
extern "C" uint32_t ds4_gpu_stream_host_expert_cache_capacity_for(uint64_t gate_expert_bytes, uint64_t down_expert_bytes) {
    if (!cuda_stream_host_expert_cache_enabled()) return 0;
    const uint64_t expert_bytes = cuda_stream_expert_cache_expert_bytes(gate_expert_bytes, down_expert_bytes);
    if (!expert_bytes) return 0;
    uint32_t cap = cuda_stream_host_expert_cache_budget_cap(expert_bytes, g_prefill_pipeline_host_cache_charge_bytes);
    const uint32_t configured = cuda_stream_host_expert_cache_requested_budget();
    if (configured && configured < cap) cap = configured;
    const uint32_t cls = cuda_stream_host_expert_cache_class_index(gate_expert_bytes, down_expert_bytes);
    if (g_stream_host_expert_runtime_cap[cls] != 0 && cap > g_stream_host_expert_runtime_cap[cls]) cap = g_stream_host_expert_runtime_cap[cls];
    return cap;
}

extern "C" uint32_t ds4_gpu_stream_host_expert_cache_current_count(void) {
    uint32_t count = 0;
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        count += g_stream_host_expert_caches[i].count;
    }
    return count;
}

/* DS4COMBO expert hotlist: experts with at least one routed lookup in this process, with
 * counts and sizes. Returns the total; fills at most cap entries. */
extern "C" uint32_t ds4_gpu_stream_expert_frequency(
        uint32_t *layers, uint32_t *experts, uint32_t *counts,
        uint64_t *gate_bytes, uint64_t *down_bytes, uint32_t cap) {
    uint32_t n = 0;
    for (uint32_t l = 0; l < DS4_COMBO_FREQ_LAYERS; l++)
        for (uint32_t e = 0; e < DS4_COMBO_FREQ_EXPERTS; e++) {
            const uint32_t c = g_combo_expert_freq[l][e];
            if (!c) continue;
            if (n < cap && layers) {
                layers[n] = l; experts[n] = e; counts[n] = c;
                gate_bytes[n] = g_combo_expert_freq_gate[l]; down_bytes[n] = g_combo_expert_freq_down[l];
            }
            n++;
        }
    return n;
}

/* DS4COMBO expert-cache restore: enumerate resident slots oldest->newest by LRU age
 * (host=0: VRAM caches, host=1: RAM caches).  Returns the total resident count; fills at
 * most cap entries.  Ages are per size-class ticks, so classes are merged by age rank. */
struct ds4_combo_resident_entry { uint64_t age; uint32_t cls, layer, expert; uint64_t gate, down; };
extern "C" uint32_t ds4_gpu_stream_expert_cache_snapshot(
        int host, uint32_t *layers, uint32_t *experts,
        uint64_t *gate_bytes, uint64_t *down_bytes, uint32_t cap) {
    std::vector<ds4_combo_resident_entry> rows;
    for (uint32_t c = 0; c < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; c++) {
        if (host) {
            const cuda_stream_host_expert_cache &h = g_stream_host_expert_caches[c];
            if (!h.valid) continue;
            for (const auto &slot : h.slots) if (slot.valid)
                rows.push_back({slot.age, c, slot.layer, slot.expert, slot.gate_expert_bytes, slot.down_expert_bytes});
        } else {
            const cuda_stream_expert_cache &v = g_stream_expert_caches[c];
            if (!v.valid) continue;
            for (const auto &slot : v.slots) if (slot.valid)
                rows.push_back({slot.age, c, slot.layer, slot.expert, slot.gate_expert_bytes, slot.down_expert_bytes});
        }
    }
    std::stable_sort(rows.begin(), rows.end(), [](const ds4_combo_resident_entry &a,
                                                  const ds4_combo_resident_entry &b) {
        return a.age < b.age;
    });
    for (size_t i = 0; i < rows.size() && i < cap; i++) {
        if (layers) layers[i] = rows[i].layer;
        if (experts) experts[i] = rows[i].expert;
        if (gate_bytes) gate_bytes[i] = rows[i].gate;
        if (down_bytes) down_bytes[i] = rows[i].down;
    }
    return rows.size() > UINT32_MAX ? UINT32_MAX : (uint32_t)rows.size();
}

/* ---- DS4COMBO growable context: in-place VRAM expert tier resize ------------------------------- */

static void cuda_stream_expert_cache_vmm_settle(cuda_stream_expert_cache *c) {
    uint64_t cap = c->capacity;
    const uint64_t per[3] = {c->gate_expert_bytes, c->gate_expert_bytes, c->down_expert_bytes};
    for (int i = 0; i < 3; i++) {
        const uint64_t fit = c->vm[i].mapped / per[i];
        if (fit < cap) cap = fit;
    }
    c->capacity = (uint32_t)cap;
    c->gate_capacity = c->up_capacity = cap * c->gate_expert_bytes;
    c->down_capacity = cap * c->down_expert_bytes;
}

/* Grow a VMM-backed class to `cap` slots in place; new slots start empty.
 * Stops early when physical memory runs out. Returns the capacity held. */
static uint32_t cuda_stream_expert_cache_vmm_grow(cuda_stream_expert_cache *c, uint32_t cap) {
    if (!c->valid || !c->vmm || cap <= c->capacity) return c->capacity;
    const uint32_t old = c->capacity;
    const uint64_t per[3] = {c->gate_expert_bytes, c->gate_expert_bytes, c->down_expert_bytes};
    for (int i = 0; i < 3; i++) (void)cuda_vmm_resize(&c->vm[i], (uint64_t)cap * per[i], 0);
    (void)cudaGetLastError();
    c->capacity = cap;
    cuda_stream_expert_cache_vmm_settle(c);
    if (c->capacity < old) c->capacity = old;  /* never below what was already backed */
    try { c->slots.resize(c->capacity); } catch (...) { c->capacity = old; }
    c->rank_worst_valid = 0;
    return c->capacity;
}

/* Shrink a VMM-backed class to `cap` slots: the coldest residents beyond
 * `cap` are evicted (demoted to a free host-tier slot when one exists), the
 * survivors are packed into the low slots in their existing order, and the
 * freed tail is unmapped. */
static int cuda_stream_expert_cache_vmm_shrink(cuda_stream_expert_cache *c, uint32_t cap,
                                                uint32_t *evicted, uint32_t *demoted) {
    if (!c->valid || !c->vmm || cap >= c->capacity) return 1;
    const uint64_t gb = c->gate_expert_bytes, db = c->down_expert_bytes;
    std::vector<uint32_t> live;
    for (uint32_t i = 0; i < c->capacity; i++) if (c->slots[i].valid) live.push_back(i);
    if (live.size() > cap) {
        std::vector<uint32_t> order = live;
        std::stable_sort(order.begin(), order.end(), [c](uint32_t a, uint32_t b) {
            const auto &x = c->slots[a], &y = c->slots[b];
            return cuda_stream_cache_older_or_colder(x.layer, x.expert, x.age, y.layer, y.expert, y.age);
        });
        const size_t drop = live.size() - cap;
        cuda_stream_host_expert_cache *h =
            &g_stream_host_expert_caches[cuda_stream_host_expert_cache_class_index(gb, db)];
        const bool host_ok = h->valid && h->gate_expert_bytes == gb && h->down_expert_bytes == db;
        uint32_t next_free = 0;
        for (size_t k = 0; k < drop; k++) {
            cuda_stream_expert_cache_slot &v = c->slots[order[k]];
            if (host_ok && cuda_stream_host_expert_cache_find(h, v.model_map, v.model_size, v.layer,
                    v.n_total_expert, v.expert, v.gate_offset, v.up_offset, v.down_offset, gb, db) < 0) {
                while (next_free < h->capacity && h->slots[next_free].valid) next_free++;
                if (next_free < h->capacity) {
                    const uint32_t hs = next_free;
                    const uint64_t vs = order[k];
                    if (cudaMemcpy(h->gate_ptr + hs * gb, c->gate_ptr + vs * gb, (size_t)gb, cudaMemcpyDeviceToHost) == cudaSuccess &&
                        cudaMemcpy(h->up_ptr + hs * gb, c->up_ptr + vs * gb, (size_t)gb, cudaMemcpyDeviceToHost) == cudaSuccess &&
                        cudaMemcpy(h->down_ptr + hs * db, c->down_ptr + vs * db, (size_t)db, cudaMemcpyDeviceToHost) == cudaSuccess) {
                        cuda_stream_host_expert_cache_slot &e = h->slots[hs];
                        e.valid = 1; e.model_map = v.model_map; e.model_size = v.model_size;
                        e.layer = v.layer; e.n_total_expert = v.n_total_expert; e.expert = v.expert;
                        e.gate_offset = v.gate_offset; e.up_offset = v.up_offset; e.down_offset = v.down_offset;
                        e.gate_expert_bytes = gb; e.down_expert_bytes = db; e.age = ++h->tick;
                        if (h->count < h->capacity) h->count++;
                        if (demoted) (*demoted)++;
                    } else {
                        (void)cudaGetLastError();
                    }
                }
            }
            v.valid = 0;
            if (evicted) (*evicted)++;
        }
    }
    uint32_t dst = 0;
    for (uint32_t i = 0; i < c->capacity; i++) {
        if (!c->slots[i].valid) continue;
        if (i != dst) {
            if (cudaMemcpy(c->gate_ptr + (uint64_t)dst * gb, c->gate_ptr + (uint64_t)i * gb, (size_t)gb, cudaMemcpyDeviceToDevice) != cudaSuccess ||
                cudaMemcpy(c->up_ptr + (uint64_t)dst * gb, c->up_ptr + (uint64_t)i * gb, (size_t)gb, cudaMemcpyDeviceToDevice) != cudaSuccess ||
                cudaMemcpy(c->down_ptr + (uint64_t)dst * db, c->down_ptr + (uint64_t)i * db, (size_t)db, cudaMemcpyDeviceToDevice) != cudaSuccess) {
                (void)cudaGetLastError();
                return 0;
            }
            c->slots[dst] = c->slots[i];
            c->slots[i].valid = 0;
        }
        dst++;
    }
    c->count = dst;
    c->capacity = cap;
    c->slots.resize(cap);
    c->rank_worst_valid = 0;
    const uint64_t per[3] = {gb, gb, db};
    for (int i = 0; i < 3; i++)
        if (!cuda_vmm_resize(&c->vm[i], (uint64_t)cap * per[i], 0)) return 0;
    cuda_stream_expert_cache_vmm_settle(c);
    return 1;
}

extern "C" void ds4_gpu_stream_expert_cache_set_floor(uint64_t bytes) {
    g_stream_expert_ctx_floor_bytes = bytes;
}

/* Use VMM for the VRAM expert tier from its first allocation. */
extern "C" void ds4_gpu_stream_expert_cache_enable_ctx_resize(void) {
    g_stream_expert_ctx_vmm = 1;
}

/* Bytes the VRAM expert tier currently backs (all classes). */
extern "C" uint64_t ds4_gpu_stream_expert_cache_held_bytes(void) {
    uint64_t total = 0;
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        const cuda_stream_expert_cache &c = g_stream_expert_caches[i];
        if (c.valid) total += (uint64_t)c.capacity * (2u * c.gate_expert_bytes + c.down_expert_bytes);
    }
    return total;
}

/* VRAM expert tier size in experts: allocated slots, or the budget the
 * ceiling allows when nothing is allocated yet. */
extern "C" uint32_t ds4_gpu_stream_expert_cache_tier_count(void) {
    uint64_t n = 0;
    bool any = false;
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        if (g_stream_expert_caches[i].valid) { n += g_stream_expert_caches[i].capacity; any = true; }
    }
    if (!any) {
        const uint64_t primary = g_stream_expert_primary_bytes;
        n = cuda_stream_expert_cache_requested_budget();
        if (primary && g_stream_expert_ctx_ceiling_bytes != UINT64_MAX &&
            n > g_stream_expert_ctx_ceiling_bytes / primary)
            n = g_stream_expert_ctx_ceiling_bytes / primary;
    }
    return n > UINT32_MAX ? UINT32_MAX : (uint32_t)n;
}

/* Set the VRAM expert tier's byte ceiling and resize every allocated class
 * to its budget under it, in place. Returns 0 if a shrink could not free
 * the memory; the caller fails the request. */
extern "C" int ds4_gpu_stream_expert_cache_set_ceiling(uint64_t bytes, uint32_t *evicted,
                                                       uint32_t *demoted) {
    if (evicted) *evicted = 0;
    if (demoted) *demoted = 0;
    g_stream_expert_ctx_ceiling_bytes = bytes;
    if (cudaDeviceSynchronize() != cudaSuccess) return 0;
    int ok = 1;
    bool changed = false;
    for (uint32_t ci = 0; ci < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; ci++) {
        cuda_stream_expert_cache *c = &g_stream_expert_caches[ci];
        if (!c->valid) continue;
        const uint64_t eb = cuda_stream_expert_cache_expert_bytes(c->gate_expert_bytes, c->down_expert_bytes);
        uint32_t cap = cuda_stream_expert_cache_class_budget(ci, eb);
        if (c->runtime_cap != 0 && cap > c->runtime_cap) cap = c->runtime_cap;
        if (cap == c->capacity) continue;
        if (!c->vmm) {
            /* Allocated before resizing was enabled: only a full release can shrink it. */
            if (cap < c->capacity) {
                if (evicted) *evicted += c->count;
                cuda_stream_expert_cache_release(c);
                changed = true;
            }
            continue;
        }
        if (cap < c->capacity) {
            if (cap == 0) {
                if (evicted) *evicted += c->count;
                cuda_stream_expert_cache_release(c);
            } else if (!cuda_stream_expert_cache_vmm_shrink(c, cap, evicted, demoted)) {
                ok = 0;
            }
        } else {
            (void)cuda_stream_expert_cache_vmm_grow(c, cap);
        }
        changed = true;
    }
    if (changed) {
        cuda_stream_selected_cache_invalidate();
        ds4_gpu_decode_graphs_invalidate();
    }
    if (cudaDeviceSynchronize() != cudaSuccess) ok = 0;
    return ok;
}

/* DS4COMBO borrowed layer prefill. The selected-expert loader of a V4.1 layer
 * sweep takes the VRAM expert tier's memory instead of adding a second
 * arena to the plan. Returns the full layers (<= want_layers) the loader may
 * hold, or 0 when even one does not fit; nothing is released in that case.
 * The decode tier is released (its contents are this turn's prefill
 * admissions; the combo restore reseeds them) and comes back lazily at its
 * normal size, never below the fixed-plan floor, after
 * ds4_gpu_stream_prefill_borrow_end(). */
extern "C" uint32_t ds4_gpu_stream_prefill_borrow(uint32_t want_layers, uint32_t n_total_expert,
                                                  uint64_t gate_expert_bytes, uint64_t down_expert_bytes,
                                                  uint64_t *free_out, uint64_t *borrowed_out,
                                                  uint64_t *reserve_out) {
    if (free_out) *free_out = 0;
    if (borrowed_out) *borrowed_out = 0;
    if (reserve_out) *reserve_out = 0;
    const uint64_t eb = cuda_stream_expert_cache_expert_bytes(gate_expert_bytes, down_expert_bytes);
    if (!g_ssd_streaming_mode || g_n_gpus != 1 || !want_layers || !n_total_expert || !eb) return 0;
    ds4_gpu_stream_expert_cache_prefetch_finish(false);
    if (ds4_gpu_set_current_device(0) != 0 ||
        !cuda_ok(cudaDeviceSynchronize(), "prefill borrow synchronize")) return 0;
    size_t free_bytes = 0, total_bytes = 0;
    if (!cuda_ok(cudaMemGetInfo(&free_bytes, &total_bytes), "prefill borrow memory")) return 0;
    const uint64_t tier = ds4_gpu_stream_expert_cache_held_bytes();
    const auto &sc = g_stream_selected_cache;
    const uint64_t arena = sc.gate_capacity + sc.up_capacity + sc.down_capacity + sc.prefill_capacity;
    const uint64_t reserve = cuda_stream_expert_cache_reserve_bytes();
    const uint64_t pool = (uint64_t)free_bytes + tier + arena;
    const uint64_t avail = pool > reserve ? pool - reserve : 0;
    const uint64_t layer = (uint64_t)n_total_expert * eb;
    uint64_t layers = avail / layer;
    if (layers > want_layers) layers = want_layers;
    if (free_out) *free_out = (uint64_t)free_bytes;
    if (borrowed_out) *borrowed_out = tier + arena;
    if (reserve_out) *reserve_out = reserve;
    if (!layers) return 0;
    const uint32_t slots = (uint32_t)layers * n_total_expert;
    cuda_stream_expert_cache_release_all();
    if (g_stream_expert_slots.size() != slots || sc.gate_expert_bytes != gate_expert_bytes ||
        sc.down_expert_bytes != down_expert_bytes)
        cuda_stream_selected_cache_release();
    cuda_stream_selected_cache_invalidate();
    ds4_gpu_decode_graphs_invalidate();
    g_stream_prefill_borrow_slots = slots;
    g_stream_prefill_borrow_notice = 0;
    return (uint32_t)layers;
}

extern "C" void ds4_gpu_stream_prefill_borrow_end(void) {
    if (!g_stream_prefill_borrow_slots) return;
    /* A next-layer read may still target the loader being released. */
    cuda_stream_prefetch_drop_pending();
    ds4_gpu_stream_expert_cache_prefetch_finish(true);
    (void)cudaDeviceSynchronize();
    cuda_stream_selected_cache_release();
    g_stream_prefill_borrow_slots = 0;
    ds4_gpu_decode_graphs_invalidate();
}

/* Re-stamp LRU ages in the given oldest->newest order after a restore seed, so the
 * restored cache evicts in the same order the exported one would have.  Returns the
 * number of listed entries that are NOT resident (caller fails loudly on nonzero). */
/* DS4COMBO expert restore: allocate the class cache at its full configured budget (the hotlist
 * seed path sizes a missing cache to the seeded layer's count). Returns the capacity held. */
extern "C" uint32_t ds4_gpu_stream_expert_cache_prepare_full(uint64_t gate_expert_bytes,
                                                             uint64_t down_expert_bytes) {
    if (!g_ssd_streaming_mode) return 0;
    cuda_stream_expert_cache *cache = cuda_stream_expert_cache_prepare(
        gate_expert_bytes, down_expert_bytes, cuda_stream_expert_cache_configured_budget());
    return cache ? cache->capacity : 0;
}

/* DS4COMBO expert restore: empty the VRAM slots (allocation kept) so the restored list is not
 * blocked by the eviction-protected quarter holding this turn's prefill admissions
 * (measured 234/301 resident without this). Returns the slots cleared. */
extern "C" uint32_t ds4_gpu_stream_expert_cache_clear_slots(void) {
    uint32_t cleared = 0;
    for (uint32_t c = 0; c < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; c++) {
        cuda_stream_expert_cache &v = g_stream_expert_caches[c];
        if (!v.valid) continue;
        for (auto &slot : v.slots) if (slot.valid) { slot.valid = 0; cleared++; }
        v.count = 0;
        v.rank_worst_valid = 0;
    }
    return cleared;
}

extern "C" uint32_t ds4_gpu_stream_expert_cache_apply_order(
        int host, const uint32_t *layers, const uint32_t *experts,
        const uint64_t *gate_bytes, const uint64_t *down_bytes, uint32_t n) {
    uint32_t missing = 0;
    for (uint32_t i = 0; i < n; i++) {
        bool found = false;
        for (uint32_t c = 0; c < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES && !found; c++) {
            if (host) {
                cuda_stream_host_expert_cache &h = g_stream_host_expert_caches[c];
                if (!h.valid) continue;
                for (auto &slot : h.slots) if (slot.valid && slot.layer == layers[i] &&
                        slot.expert == experts[i] && slot.gate_expert_bytes == gate_bytes[i] &&
                        slot.down_expert_bytes == down_bytes[i]) { slot.age = ++h.tick; found = true; break; }
            } else {
                cuda_stream_expert_cache &v = g_stream_expert_caches[c];
                if (!v.valid) continue;
                for (auto &slot : v.slots) if (slot.valid && slot.layer == layers[i] &&
                        slot.expert == experts[i] && slot.gate_expert_bytes == gate_bytes[i] &&
                        slot.down_expert_bytes == down_bytes[i]) { slot.age = ++v.tick; found = true; break; }
            }
        }
        if (!found) missing++;
    }
    return missing;
}

/* [2026-08-18] THE VIRTUAL CACHE: a runtime record of which experts a workload ACTUALLY selects,
 * including the ones deliberately EXCLUDED from the cache.
 *
 * The two-bound tiers rank experts from `ds4_default_streaming_hotlist_flash`, a STATIC table baked
 * into the binary: the top K per layer are marked TIER_PREFETCH and kept OUT of the cache on purpose,
 * so they are always streamed, and the next M are TIER_CACHE. That design only pays off if the static
 * ranking matches the workload - and nothing measured whether it does.
 * `ds4_gpu_stream_expert_cache_reset_route_hotness()` was an EMPTY function and no counter existed.
 *
 * These counters are the missing half. Every selection is tallied per (layer, expert) alongside the
 * tier that expert was assigned, so a run can answer the question the design rests on: were the
 * excluded-K really the hottest, and how much of the actual selection mass did they carry?
 *
 * Cost is one increment per selected expert per layer - against a fetch measured in hundreds of
 * milliseconds - so it is always on. The dump is opt-in via DS4_CUDA_ROUTE_HOTNESS_DUMP, printed once
 * at reset (start of a prefill) and at process exit, because printing 43x256 counters per token would
 * itself be the bottleneck. */
#define DS4_ROUTE_HOTNESS_LAYERS 128
#define DS4_ROUTE_HOTNESS_EXPERTS 512

/* R9 previous-token predictor. DSV4-Flash has 43 routed layer visits and six
 * selections per token, so the entire predictor is exactly 43x6 int32s plus
 * one count byte per layer. The selection for token T is recorded only after
 * its router has run; token T+1 reads it from the existing pre-router promotion
 * hook. DS4_CUDA_RAM_PROMOTION_PREVIOUS_TOKEN defaults to 0 because the old
 * host-cache age ranking is the required control until the paired A/B passes. */
#define DS4_ROUTE_PREVIOUS_LAYERS 43u
#define DS4_ROUTE_PREVIOUS_SELECTED 6u
static int32_t g_route_previous[DS4_ROUTE_PREVIOUS_LAYERS][DS4_ROUTE_PREVIOUS_SELECTED];
static uint8_t g_route_previous_n[DS4_ROUTE_PREVIOUS_LAYERS];

static void cuda_route_previous_note(uint32_t layer, const int32_t *ids, uint32_t n) {
    if (layer >= DS4_ROUTE_PREVIOUS_LAYERS || !ids || n == 0) return;
    if (n > DS4_ROUTE_PREVIOUS_SELECTED) n = DS4_ROUTE_PREVIOUS_SELECTED;
    memcpy(g_route_previous[layer], ids, (size_t)n * sizeof(ids[0]));
    g_route_previous_n[layer] = (uint8_t)n;
}

static uint32_t cuda_route_previous_predict(uint32_t layer, int32_t *out, uint32_t want) {
    if (cuda_affinity_token_biased()) return 0;
    if (layer >= DS4_ROUTE_PREVIOUS_LAYERS || !out || want == 0) return 0;
    uint32_t n = g_route_previous_n[layer];
    if (n > want) n = want;
    memcpy(out, g_route_previous[layer], (size_t)n * sizeof(out[0]));
    return n;
}

static uint32_t g_route_hotness[DS4_ROUTE_HOTNESS_LAYERS][DS4_ROUTE_HOTNESS_EXPERTS];
/* Reuse the router's existing observations for both retention tiers. */
static uint32_t cuda_stream_cache_frequency(uint32_t layer, uint32_t expert) {
    if (layer >= DS4_ROUTE_HOTNESS_LAYERS || expert >= DS4_ROUTE_HOTNESS_EXPERTS) return 0;
    return g_route_hotness[layer][expert];
}
static uint64_t g_route_hotness_layer_total[DS4_ROUTE_HOTNESS_LAYERS];
static const uint8_t *g_route_hotness_tiers[DS4_ROUTE_HOTNESS_LAYERS];
static uint64_t g_route_hotness_total = 0;
static uint64_t g_route_hotness_model_identity = 0;
static uint64_t g_route_hotness_model_bytes = 0;
static uint32_t g_route_hotness_model_layers = 0;
static uint32_t g_route_hotness_model_experts = 0;
static int g_route_hotness_model_mixed = 0;
static uint64_t g_route_hotness_epoch = 0;
static uint64_t g_route_hotness_written_epoch = ~0ull;
static uint64_t g_route_live_last_refresh_total = 0;
static int g_route_live_refresh_forced = 0;
static int g_route_live_fallback_announced = 0;
static int g_route_hotness_since_reset = 0;
static int g_route_hotness_reset_seen = 0;
static uint32_t g_route_live_refresh_tokens = 16u;
static uint32_t g_route_live_min_layer_selections = 96u;

/* The tier table lives in ds4.c and is not callable from here, but every selected-load call already
 * carries the layer's tier vector on its table, so the pointer is captured as it goes past. */
extern "C" void ds4_gpu_stream_expert_cache_dump_route_hotness(const char *tag);

static void cuda_route_hotness_atexit(void) {
    ds4_gpu_stream_expert_cache_dump_route_hotness("exit");
}

static void cuda_route_hotness_note(uint32_t layer, const int32_t *ids, uint32_t n,
                                    const uint8_t *tiers, uint64_t model_identity,
                                    uint64_t model_bytes, uint32_t n_total_expert) {
    /* GATE THE COUNTING, not just the report.
     *
     * "One increment per selected expert against a fetch measured in hundreds of milliseconds" is true
     * per call, but the PREFILL entry passes a whole chunk at once: n_tokens * n_selected, which for a
     * 3643-token prompt is ~940k scattered writes into a 256 KB table across 43 layers. Always-on
     * counting also means its cost CANNOT BE A/B'd - and this session already had to chase a 40%
     * prefill drop with no way to switch the new code off. Default ON so the instrument is there when
     * wanted; DS4_CUDA_ROUTE_HOTNESS=0 turns the counting itself off in the same binary. */
    static int enabled = -1;
    if (enabled < 0) {
        const char *e = getenv("DS4_CUDA_ROUTE_HOTNESS");
        enabled = !(e && e[0] == '0');
    }
    if (!enabled) return;
    if (layer >= DS4_ROUTE_HOTNESS_LAYERS || !ids) return;
    /* Report at PROCESS EXIT, registered on first use.
     *
     * Hanging the dump off "end of generation" failed three times, each for a different reason: the
     * only caller ran at prefill START (before any selection existed), then the hook was on the decode
     * entry while the run's selections went through the prefill entry, and then the timing line turned
     * out to be printed by one of SIX sites sharing that format string. atexit sidesteps the question
     * entirely - whichever path ends the run, the process still exits. */
    static int registered = 0;
    if (!registered) { registered = 1; atexit(cuda_route_hotness_atexit); }
    if (g_route_hotness_model_identity == 0) {
        g_route_hotness_model_identity = model_identity;
        g_route_hotness_model_bytes = model_bytes;
        g_route_hotness_model_experts = n_total_expert;
    } else if (g_route_hotness_model_identity != model_identity ||
               g_route_hotness_model_bytes != model_bytes ||
               g_route_hotness_model_experts != n_total_expert) {
        g_route_hotness_model_mixed = 1;
    }
    if (layer + 1u > g_route_hotness_model_layers) {
        g_route_hotness_model_layers = layer + 1u;
    }
    if (tiers) g_route_hotness_tiers[layer] = tiers;
    uint64_t layer_added = 0;
    for (uint32_t i = 0; i < n; i++) {
        const int32_t e = ids[i];
        if (e < 0 || (uint32_t)e >= DS4_ROUTE_HOTNESS_EXPERTS) continue;
        g_route_hotness[layer][e]++;
        g_route_hotness_total++;
        layer_added++;
    }
    g_route_hotness_layer_total[layer] += layer_added;
    if (layer_added != 0) g_route_hotness_since_reset = 1;
}

struct cuda_route_hotlist_output_entry {
    uint32_t layer;
    uint32_t expert;
    uint32_t hits;
};

static int cuda_route_hotlist_output_cmp(const void *a, const void *b) {
    const cuda_route_hotlist_output_entry *ea =
        (const cuda_route_hotlist_output_entry *)a;
    const cuda_route_hotlist_output_entry *eb =
        (const cuda_route_hotlist_output_entry *)b;
    if (ea->hits != eb->hits) return ea->hits > eb->hits ? -1 : 1;
    if (ea->layer != eb->layer) return ea->layer < eb->layer ? -1 : 1;
    if (ea->expert != eb->expert) return ea->expert < eb->expert ? -1 : 1;
    return 0;
}

extern "C" int ds4_gpu_stream_expert_cache_refresh_live_route_ranks(
        uint32_t *ranks,
        uint32_t  rank_stride,
        uint32_t  current_layer,
        uint32_t  n_layers,
        uint32_t  n_experts,
        uint32_t  selections_per_token) {
    static int live_enabled = -1;
    if (live_enabled < 0) {
        live_enabled = cuda_env_flag_enabled(
            "DS4_CUDA_LIVE_ROUTE_HOTLIST", 0);
    }
    if (!live_enabled) return 0;
    static int config_initialized = 0;
    if (!config_initialized) {
        config_initialized = 1;
        g_route_live_refresh_tokens = cuda_parse_u32_env_clamped(
            "DS4_CUDA_LIVE_ROUTE_HOTLIST_REFRESH_TOKENS", 16u,
            1u, 65536u, NULL);
        g_route_live_min_layer_selections = cuda_parse_u32_env_clamped(
            "DS4_CUDA_LIVE_ROUTE_HOTLIST_MIN_SELECTIONS", 96u,
            1u, 1048576u, NULL);
        fprintf(stderr,
                "ds4: CUDA live route hotlist enabled [R9_LIVE_HOTLIST_V1]: "
                "reset=halve-counts minimum=%u selections/layer refresh=%u tokens "
                "(DS4_CUDA_LIVE_ROUTE_HOTLIST defaults to 0)\n",
                g_route_live_min_layer_selections,
                g_route_live_refresh_tokens);
    }
    if (!ranks || n_layers == 0 || n_layers > DS4_ROUTE_HOTNESS_LAYERS ||
        n_experts == 0 || n_experts > DS4_ROUTE_HOTNESS_EXPERTS ||
        rank_stride < n_experts || current_layer >= n_layers ||
        selections_per_token == 0) {
        g_route_live_ranks_ready = 0;
        return 0;
    }
    /* Layer zero is the token boundary on Flash. Checking the accumulated mass
     * only here prevents a layer-major prefill chunk from refreshing after a
     * partial set of layers and biasing the new ranks toward that prefix. */
    if (current_layer != 0) return g_route_live_ranks_ready;

    uint64_t minimum_observed = UINT64_MAX;
    const int model_ready =
        !g_route_hotness_model_mixed &&
        g_route_hotness_model_identity != 0 &&
        g_route_hotness_model_layers >= n_layers &&
        g_route_hotness_model_experts == n_experts;
    for (uint32_t layer = 0; layer < n_layers; layer++) {
        if (g_route_hotness_layer_total[layer] < minimum_observed) {
            minimum_observed = g_route_hotness_layer_total[layer];
        }
    }
    const int mass_ready =
        model_ready && minimum_observed >= g_route_live_min_layer_selections;
    if (!mass_ready) {
        g_route_live_ranks_ready = 0;
        if (!g_route_live_fallback_announced) {
            g_route_live_fallback_announced = 1;
            fprintf(stderr,
                    "ds4: CUDA live route hotlist has insufficient mass "
                    "(%llu observed minimum, need %u selections in every one of %u layers); "
                    "falling back to the existing static/LRU admission policy until ready\n",
                    (unsigned long long)minimum_observed,
                    g_route_live_min_layer_selections,
                    n_layers);
        }
        return 0;
    }

    const uint64_t refresh_mass =
        (uint64_t)g_route_live_refresh_tokens * n_layers * selections_per_token;
    const uint64_t mass_since_refresh =
        g_route_hotness_total >= g_route_live_last_refresh_total ?
            g_route_hotness_total - g_route_live_last_refresh_total :
            g_route_hotness_total;
    if (g_route_live_ranks_ready && !g_route_live_refresh_forced &&
        mass_since_refresh < refresh_mass) {
        return 1;
    }

    const uint64_t capacity64 = (uint64_t)n_layers * n_experts;
    if (capacity64 > SIZE_MAX / sizeof(cuda_route_hotlist_output_entry)) {
        return g_route_live_ranks_ready;
    }
    const double refresh_t0 = cuda_decode_profile_now_ms();
    cuda_route_hotlist_output_entry *entries =
        (cuda_route_hotlist_output_entry *)malloc(
            (size_t)capacity64 * sizeof(entries[0]));
    if (!entries) {
        fprintf(stderr,
                "ds4: CUDA live route hotlist refresh allocation failed; retaining prior ranks\n");
        return g_route_live_ranks_ready;
    }

    size_t count = 0;
    for (uint32_t layer = 0; layer < n_layers; layer++) {
        for (uint32_t expert = 0; expert < n_experts; expert++) {
            const uint32_t hits = g_route_hotness[layer][expert];
            if (hits == 0) continue;
            entries[count].layer = layer;
            entries[count].expert = expert;
            entries[count].hits = hits;
            count++;
        }
    }
    qsort(entries, count, sizeof(entries[0]), cuda_route_hotlist_output_cmp);

    uint64_t ranks_changed = 0;
    for (uint32_t layer = 0; layer < n_layers; layer++) {
        for (uint32_t expert = 0; expert < n_experts; expert++) {
            if (g_route_hotness[layer][expert] != 0) continue;
            uint32_t *rank = &ranks[(size_t)layer * rank_stride + expert];
            if (*rank != UINT32_MAX) ranks_changed++;
            *rank = UINT32_MAX;
        }
    }
    for (size_t i = 0; i < count; i++) {
        uint32_t *rank = &ranks[(size_t)entries[i].layer * rank_stride +
                                entries[i].expert];
        const uint32_t new_rank = (uint32_t)i;
        if (*rank != new_rank) ranks_changed++;
        *rank = new_rank;
    }
    /* Resident slots cached the ordinal that was current when they were
     * admitted. Refresh those ordinals with the map so incoming and incumbent
     * ranks always come from the same epoch. */
    for (uint32_t class_index = 0;
         class_index < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES;
         class_index++) {
        cuda_stream_expert_cache &cache =
            g_stream_expert_caches[class_index];
        cache.rank_worst_valid = 0;
        for (size_t slot_index = 0;
             slot_index < cache.slots.size();
             slot_index++) {
            cuda_stream_expert_cache_slot &slot = cache.slots[slot_index];
            if (!slot.valid || slot.model_size != g_route_hotness_model_bytes ||
                slot.layer >= n_layers || slot.expert >= n_experts) {
                continue;
            }
            slot.route_rank =
                ranks[(size_t)slot.layer * rank_stride + slot.expert];
        }
    }
    free(entries);

    const int first_refresh = !g_route_live_ranks_ready;
    g_route_live_ranks_ready = 1;
    g_route_live_refresh_forced = 0;
    g_route_live_last_refresh_total = g_route_hotness_total;
    g_decode_profile.live_hotlist_refreshes += 1;
    g_decode_profile.live_hotlist_refresh_ms +=
        cuda_decode_profile_now_ms() - refresh_t0;
    g_decode_profile.live_hotlist_ranks_changed += ranks_changed;
    if (first_refresh) {
        fprintf(stderr,
                "ds4: CUDA live route hotlist activated: ranked=%llu selections=%llu "
                "minimum-layer-mass=%llu\n",
                (unsigned long long)count,
                (unsigned long long)g_route_hotness_total,
                (unsigned long long)minimum_observed);
    }
    return 1;
}

/* The route dump doubles as the profile-pass writer. The learned-ranking flag
 * is intentionally not required here: profile with the static control, then
 * opt into loading the resulting model-bound file in a later A/B arm. */
static void cuda_route_hotlist_write(void) {
    const char *path = getenv("DS4_CUDA_ROUTE_HOTLIST_FILE");
    if (!path || !path[0] || g_route_hotness_total == 0 ||
        g_route_hotness_written_epoch == g_route_hotness_epoch) {
        return;
    }
    if (g_route_hotness_model_mixed || g_route_hotness_model_identity == 0 ||
        g_route_hotness_model_layers == 0 || g_route_hotness_model_experts == 0) {
        fprintf(stderr,
                "ds4: refusing to write learned route hotlist %s: "
                "profile model identity is missing or mixed\n",
                path);
        g_route_hotness_written_epoch = g_route_hotness_epoch;
        return;
    }

    const uint64_t capacity64 =
        (uint64_t)g_route_hotness_model_layers * g_route_hotness_model_experts;
    if (capacity64 == 0 || capacity64 > SIZE_MAX / sizeof(cuda_route_hotlist_output_entry)) {
        fprintf(stderr, "ds4: learned route hotlist entry capacity overflow\n");
        g_route_hotness_written_epoch = g_route_hotness_epoch;
        return;
    }
    cuda_route_hotlist_output_entry *entries =
        (cuda_route_hotlist_output_entry *)malloc(
            (size_t)capacity64 * sizeof(entries[0]));
    if (!entries) {
        fprintf(stderr, "ds4: failed to allocate learned route hotlist entries\n");
        g_route_hotness_written_epoch = g_route_hotness_epoch;
        return;
    }
    size_t count = 0;
    for (uint32_t layer = 0; layer < g_route_hotness_model_layers; layer++) {
        for (uint32_t expert = 0; expert < g_route_hotness_model_experts; expert++) {
            const uint32_t hits = g_route_hotness[layer][expert];
            if (hits == 0) continue;
            entries[count].layer = layer;
            entries[count].expert = expert;
            entries[count].hits = hits;
            count++;
        }
    }
    qsort(entries, count, sizeof(entries[0]), cuda_route_hotlist_output_cmp);

    FILE *fp = fopen(path, "wb");
    if (!fp) {
        fprintf(stderr,
                "ds4: failed to open learned route hotlist output %s: %s\n",
                path,
                strerror(errno));
        free(entries);
        g_route_hotness_written_epoch = g_route_hotness_epoch;
        return;
    }
    fprintf(fp,
            "DS4_ROUTE_HOTLIST 1\n"
            "model_id %016llx\n"
            "model_bytes %llu\n"
            "layers %u\n"
            "experts %u\n"
            "selections %llu\n"
            "entries layer expert hits\n",
            (unsigned long long)g_route_hotness_model_identity,
            (unsigned long long)g_route_hotness_model_bytes,
            g_route_hotness_model_layers,
            g_route_hotness_model_experts,
            (unsigned long long)g_route_hotness_total);
    for (size_t i = 0; i < count; i++) {
        fprintf(fp, "%u %u %u\n",
                entries[i].layer, entries[i].expert, entries[i].hits);
    }
    free(entries);

    if (fclose(fp) != 0) {
        fprintf(stderr,
                "ds4: failed to close learned route hotlist output %s: %s\n",
                path,
                strerror(errno));
    } else {
        fprintf(stderr,
                "ds4: wrote learned route hotlist %s id=%016llx entries=%llu selections=%llu\n",
                path,
                (unsigned long long)g_route_hotness_model_identity,
                (unsigned long long)count,
                (unsigned long long)g_route_hotness_total);
    }
    g_route_hotness_written_epoch = g_route_hotness_epoch;
}

/* Print, per layer, how much of the ACTUAL selection mass landed in each tier, and whether the
 * statically-chosen top-K were in fact the observed top-K. A design that excludes the hottest experts
 * on purpose is only correct to the extent those two agree. */
extern "C" void ds4_gpu_stream_expert_cache_dump_route_hotness(const char *tag) {
    if (!getenv("DS4_CUDA_ROUTE_HOTNESS_DUMP")) return;
    /* Report EVEN WITH ZERO SELECTIONS. The first two versions of this returned silently when the
     * counter was empty, and silence is indistinguishable from "the dump was never called" - which
     * cost two build-and-run cycles working out which of those was true. An instrument that says
     * "0 selections" is telling you something; one that prints nothing is not. */
    if (g_route_hotness_total == 0) {
        fprintf(stderr, "ds4: CUDA route hotness [%s] NO SELECTIONS RECORDED "
                        "(counters never incremented on this path)\n", tag ? tag : "");
        return;
    }
    uint64_t mass_prefetch = 0, mass_cache = 0, mass_other = 0;
    uint64_t topk_hit = 0, topk_total = 0;
    for (uint32_t l = 0; l < DS4_ROUTE_HOTNESS_LAYERS; l++) {
        const uint8_t *tiers = g_route_hotness_tiers[l];
        /* observed ranking for this layer */
        uint32_t best[8]; uint32_t bestv[8];
        for (uint32_t i = 0; i < 8; i++) { best[i] = 0; bestv[i] = 0; }
        for (uint32_t e = 0; e < DS4_ROUTE_HOTNESS_EXPERTS; e++) {
            const uint32_t v = g_route_hotness[l][e];
            if (v == 0) continue;
            const uint8_t t = tiers ? tiers[e] : 0;
            if (t == DS4_STREAM_EXPERT_TIER_PREFETCH) mass_prefetch += v;
            else if (t == DS4_STREAM_EXPERT_TIER_CACHE) mass_cache += v;
            else mass_other += v;
            for (uint32_t i = 0; i < 8; i++) {
                if (v > bestv[i]) {
                    for (uint32_t j = 7; j > i; j--) { bestv[j] = bestv[j-1]; best[j] = best[j-1]; }
                    bestv[i] = v; best[i] = e; break;
                }
            }
        }
        if (!tiers) continue;
        for (uint32_t i = 0; i < 8; i++) {
            if (bestv[i] == 0) continue;
            topk_total++;
            if (tiers[best[i]] == DS4_STREAM_EXPERT_TIER_PREFETCH) topk_hit++;
        }
    }
    const double tot = (double)g_route_hotness_total;
    fprintf(stderr,
            "ds4: CUDA route hotness [%s] selections=%llu  mass: prefetch-tier %.1f%% "
            "cache-tier %.1f%% untiered %.1f%%  observed-top8 in prefetch tier: %llu/%llu\n",
            tag ? tag : "",
            (unsigned long long)g_route_hotness_total,
            100.0 * (double)mass_prefetch / tot,
            100.0 * (double)mass_cache / tot,
            100.0 * (double)mass_other / tot,
            (unsigned long long)topk_hit,
            (unsigned long long)topk_total);
    cuda_route_hotlist_write();
}

extern "C" void ds4_gpu_stream_expert_cache_reset_route_hotness(void) {
    const int live_enabled =
        cuda_env_flag_enabled("DS4_CUDA_LIVE_ROUTE_HOTLIST", 0) ||
        cuda_stream_cache_lfu_enabled();
    /* The short-prefill wrapper and its decode-style callee both issue this
     * hook at position zero. Do not decay twice when no selection occurred
     * between those calls. */
    if (live_enabled && g_route_hotness_reset_seen &&
        !g_route_hotness_since_reset && !g_route_hotness_model_mixed) {
        memset(g_route_previous_n, 0, sizeof(g_route_previous_n));
        return;
    }
    g_route_hotness_reset_seen = 1;
    ds4_gpu_stream_expert_cache_dump_route_hotness("reset");
    if (live_enabled && !g_route_hotness_model_mixed) {
        /* Session-cumulative with deterministic half-life: retain cross-request
         * evidence, but give a new request equal weight after one reset. The
         * exact post-decay total is recomputed because integer floors make
         * `old_total / 2` inaccurate for odd cells. */
        uint64_t decayed_total = 0;
        memset(g_route_hotness_layer_total, 0,
               sizeof(g_route_hotness_layer_total));
        for (uint32_t layer = 0; layer < DS4_ROUTE_HOTNESS_LAYERS; layer++) {
            for (uint32_t expert = 0; expert < DS4_ROUTE_HOTNESS_EXPERTS; expert++) {
                g_route_hotness[layer][expert] >>= 1;
                g_route_hotness_layer_total[layer] +=
                    g_route_hotness[layer][expert];
                decayed_total += g_route_hotness[layer][expert];
            }
        }
        g_route_hotness_total = decayed_total;
        g_route_live_last_refresh_total = decayed_total;
        g_decode_profile.live_hotlist_decay_passes += 1;
        g_route_live_ranks_ready = g_route_hotness_model_layers != 0;
        for (uint32_t layer = 0;
             g_route_live_ranks_ready &&
                 layer < g_route_hotness_model_layers;
             layer++) {
            if (g_route_hotness_layer_total[layer] <
                g_route_live_min_layer_selections) {
                g_route_live_ranks_ready = 0;
            }
        }
        g_route_live_refresh_forced = g_route_live_ranks_ready;
    } else {
        memset(g_route_hotness, 0, sizeof(g_route_hotness));
        memset(g_route_hotness_layer_total, 0,
               sizeof(g_route_hotness_layer_total));
        g_route_hotness_total = 0;
        g_route_hotness_model_layers = 0;
        g_route_live_last_refresh_total = 0;
        g_route_live_ranks_ready = 0;
        g_route_live_refresh_forced = 0;
    }
    memset(g_route_previous_n, 0, sizeof(g_route_previous_n));
    g_route_hotness_since_reset = 0;
    g_route_hotness_model_mixed = 0;
    g_route_hotness_epoch++;
}

extern "C" void ds4_gpu_stream_expert_cache_release_resident(void) {
    cuda_stream_expert_cache_release_all();
}

#if defined(_WIN32)
static void cuda_ram_hot_prefetch_stats_dump_at(const char *tag);
static void cuda_ram_hot_prefetch_stats_atexit(void);
#endif

/* Always-on, no flag: an A/B without a mechanism counter cannot distinguish "the lever did nothing"
 * from "the lever never fired". Printed at the prefill->decode transition, which is the only moment the
 * prefill total is final and the decode total is still zero. */
extern "C" void ds4_gpu_stream_expert_cache_report_admits(void) {
    fprintf(stderr,
            "ds4: CUDA expert cache admissions: prefill %llu, decode %llu\n",
            g_expert_cache_admits_prefill,
            g_expert_cache_admits_decode);
    /* [2026-08-23] The VRAM/host hit rates used to be reachable ONLY through
     * atexit(cuda_expert_cache_stats_dump). Every campaign here ends an arm with `kill` from MSYS
     * bash, which cannot deliver a POSIX signal to a native Windows process - it hard-terminates it,
     * so atexit never runs and the line never appears. Measured: zero "expert cache hit rate" lines
     * across every server log in this campaign, while the CLI control emits it fine.
     *
     * That left the host expert cache completely unmeasured. Its size was raised 2.00 -> 10.02 GiB
     * with no way to tell whether the extra capacity was ever filled or hit - exactly the
     * "did the lever do nothing, or never fire?" gap this function's own comment above exists to
     * close. So emit it here too, on the same always-on branch. atexit keeps its registration for
     * the CLI, where it does run; a duplicate line there is far cheaper than a silent server.
     */
    cuda_expert_cache_stats_dump();
#if defined(_WIN32)
    /* Paired R9 mechanism metric. Keep this beside admissions so both the
     * predictor-off control and treatment report from the same branch. */
    cuda_ram_hot_prefetch_stats_dump_at("prefill->decode");
#endif
}

extern "C" void ds4_gpu_stream_expert_cache_set_phase_decode(
        int decode,
        int edge_vram_enabled) {
#if defined(_WIN32)
    const int entering_decode = decode && !g_stream_expert_cache_phase_decode;
#endif
    /* Leaving decode: the async expert restore completes before the next prefill
     * (and before any borrow); a failure is reported by the next eval. */
    if (!decode && g_stream_expert_cache_phase_decode)
        (void)ds4_gpu_expert_restore_async_drain("decode-exit");
    if (!decode && (g_affinity_anchor>0.0f || g_affinity_cap)) {
        cuda_affinity_background_finish();g_affinity_decoded=0;g_affinity_current_biased=false;
    }
    g_stream_expert_cache_edge_vram_enabled = edge_vram_enabled != 0;
    g_stream_expert_cache_phase_decode = decode != 0;

#if defined(_WIN32)
    /* Phase bandwidth is cheap transport accounting and remains visible even
     * when the synchronization-heavy decode profiler is disabled. */
    ds4_ds_stats_set_phase(decode);

    /* Register before every treatment-dependent early return. A zero-launch
     * control is evidence and must still produce the final paired metric. */
    static int promotion_stats_registered = 0;
    if (!promotion_stats_registered) {
        promotion_stats_registered = 1;
        atexit(cuda_ram_hot_prefetch_stats_atexit);
    }
#endif

    /* [2026-08-18] Report the admission counts at the FIRST prefill->decode transition, and do it HERE,
     * ABOVE the early return below. That return fires whenever the edge-vram gate is off - which is
     * exactly the control arm the counter exists to measure. A report placed after it would print only
     * in the treatment arm and silently vanish from every baseline, making the A/B look self-confirming.
     * Same failure shape as the gate that passed build, marker and stderr checks while doing nothing. */
    if (g_stream_expert_cache_phase_decode) {
        static int reported = 0;
        if (!reported) {
            reported = 1;
            ds4_gpu_stream_expert_cache_report_admits();
        }
#if defined(_WIN32)
        if (entering_decode) {
            if (g_prefill_pipeline.active) cuda_prefill_pipeline_release();
            /* Normal R4 completion has already released its worker and arena
             * by this point. Refill host residency here anyway: unlike the
             * old active-only call, this is the real edge after the graph
             * prefill workspace was released by the caller. */
            cuda_stream_host_expert_cache_decode_edge_refill();
        }
#endif
    }

    if (!g_stream_expert_cache_edge_vram_enabled) {
        g_stream_expert_cache_physical_budget_bytes = 0;
        g_stream_expert_cache_physical_clamp_notice = 0;
        return;
    }

    size_t free_before = 0, total_before = 0;
    (void)cudaMemGetInfo(&free_before, &total_before);
    (void)cudaGetLastError();
    if (!g_stream_expert_cache_phase_decode) {
        uint64_t resident_bytes = 0;
        for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
            const cuda_stream_expert_cache *cache = &g_stream_expert_caches[i];
            resident_bytes += cache->gate_capacity + cache->up_capacity +
                              cache->down_capacity;
        }
        cuda_stream_expert_cache_release_all();
        size_t free_after = 0, total_after = 0;
        (void)cudaMemGetInfo(&free_after, &total_after);
        (void)cudaGetLastError();
        fprintf(stderr,
                "ds4: CUDA prefill edge evicted expert cache %.2f GiB; "
                "free VRAM %.2f -> %.2f GiB\n",
                (double)resident_bytes / 1073741824.0,
                (double)free_before / 1073741824.0,
                (double)free_after / 1073741824.0);

        /* The decode model-weight arena used to survive until
         * ds4_gpu_prefill_pipeline_begin(), but the caller allocates the
         * request's prefill workspace before the pipeline begins.  Reclaim it
         * at the same default-on phase edge as the expert slabs so request N+1
         * can allocate scratch.  The pipeline-begin release remains as an
         * idempotent safety net for callers that do not use this phase unit. */
        const cuda_model_range_release_stats model_released =
            cuda_model_range_release_all();
        size_t free_after_model = 0, total_after_model = 0;
        (void)cudaMemGetInfo(&free_after_model, &total_after_model);
        (void)cudaGetLastError();
        fprintf(stderr,
                "ds4: DS4_PREFILL_EDGE_EVICT_V1 path=phase-transition "
                "expert_bytes=%llu model_arena_bytes=%llu model_standalone_bytes=%llu "
                "model_total_bytes=%llu cache_full=%d->%d free_vram_bytes=%llu->%llu\n",
                (unsigned long long)resident_bytes,
                (unsigned long long)model_released.arena_bytes,
                (unsigned long long)model_released.standalone_bytes,
                (unsigned long long)(model_released.arena_bytes +
                                     model_released.standalone_bytes),
                model_released.cache_full_before,
                g_model_cache_full,
                (unsigned long long)free_after,
                (unsigned long long)free_after_model);
        g_stream_expert_cache_physical_budget_bytes = 0;
        g_stream_expert_cache_physical_clamp_notice = 0;
        return;
    }

    /* R10: snapshot physical availability only after the caller has released
     * the oversized prefill workspace.  Every class derives its request from
     * this one edge snapshot, so an inflated configured request cannot make a
     * later class spend VRAM that did not physically exist at the boundary. */
    g_stream_expert_cache_physical_budget_bytes = (uint64_t)free_before;
    g_stream_expert_cache_physical_clamp_notice = 0;
    fprintf(stderr,
            "ds4: CUDA decode edge cache refill enabled after prefill scratch release; "
            "physical free VRAM %.2f / %.2f GiB\n",
            (double)free_before / 1073741824.0,
            (double)total_before / 1073741824.0);
}

extern "C" uint32_t ds4_gpu_stream_expert_cache_budget_for_expert_size(
        uint64_t gate_expert_bytes,
        uint64_t down_expert_bytes) {
    if (!cuda_stream_expert_cache_budget_visible_to_shared() ||
        cuda_stream_expert_cache_expert_bytes(gate_expert_bytes,
                                              down_expert_bytes) == 0) {
        return 0;
    }
    const uint64_t expert_bytes =
        cuda_stream_expert_cache_expert_bytes(gate_expert_bytes,
                                              down_expert_bytes);
    return cuda_stream_expert_cache_class_budget(
            cuda_stream_expert_cache_class_index(gate_expert_bytes,
                                                 down_expert_bytes),
            expert_bytes);
}

extern "C" int ds4_gpu_stream_expert_cache_seed_selected(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *selected_ids,
        uint32_t                           n_selected) {
    if (!g_ssd_streaming_mode) return 1;
    if (!table) return 0;
    const void *model_map = table->model_map;
    const uint64_t model_size = table->model_size;
    const uint32_t layer = table->layer;
    const uint32_t n_total_expert = table->n_total_expert;
    const uint64_t gate_offset = table->gate_offset;
    const uint64_t up_offset = table->up_offset;
    const uint64_t down_offset = table->down_offset;
    const uint64_t gate_expert_bytes = table->gate_expert_bytes;
    const uint64_t down_expert_bytes = table->down_expert_bytes;
    if (!model_map || !selected_ids || n_selected == 0 ||
        n_selected > n_total_expert ||
        !cuda_stream_layer_expert_ranges_valid(model_size,
                                               n_total_expert,
                                               gate_offset,
                                               up_offset,
                                               down_offset,
                                               gate_expert_bytes,
                                               down_expert_bytes,
                                               "seed selected")) {
        return 0;
    }

    cuda_stream_expert_cache *cache =
        cuda_stream_expert_cache_prepare(gate_expert_bytes,
                                         down_expert_bytes,
                                         n_selected);
    if (!cache) return 1;
    for (uint32_t i = 0; i < n_selected; i++) {
        if (selected_ids[i] < 0 || (uint32_t)selected_ids[i] >= n_total_expert) {
            fprintf(stderr,
                    "ds4: CUDA streaming seed selected expert id %d is outside 0..%u at layer %u\n",
                    selected_ids[i],
                    n_total_expert,
                    layer);
            return 0;
        }
        if (table->expert_tiers &&
            table->expert_tiers[(uint32_t)selected_ids[i]] !=
                DS4_STREAM_EXPERT_TIER_CACHE) {
            continue;
        }
        if (!cuda_stream_expert_cache_seed_one(cache,
                                               model_map,
                                               model_size,
                                               layer,
                                               n_total_expert,
                                               (uint32_t)selected_ids[i],
                                               table->expert_ranks,
                                               gate_offset,
                                               up_offset,
                                               down_offset,
                                               gate_expert_bytes,
                                               down_expert_bytes)) {
            cuda_stream_expert_cache_invalidate(cache);
            return 1;
        }
    }
    return 1;
}

#if defined(_WIN32)
static void cuda_ram_hot_prefetch_stats_dump_at(const char *tag) {
    const double accuracy = g_ram_hot_prefetch_launched != 0 ?
        100.0 * (double)g_ram_hot_prefetch_hits /
            (double)g_ram_hot_prefetch_launched : 0.0;
    fprintf(stderr,
            "ds4: CUDA RAM promotion accuracy [%s]: launched=%llu selected_hits=%llu (%.1f%%)\n",
            tag ? tag : "",
            (unsigned long long)g_ram_hot_prefetch_launched,
            (unsigned long long)g_ram_hot_prefetch_hits,
            accuracy);
}

static void cuda_ram_hot_prefetch_stats_atexit(void) {
    cuda_ram_hot_prefetch_stats_dump_at("exit");
}

extern "C" int ds4_gpu_stream_host_expert_prefetch_layer(
        const ds4_gpu_stream_expert_table *table) {
    if (cuda_affinity_token_biased()) return 1;
    const uint32_t k = cuda_ram_hot_prefetch_k();
    if (k == 0 || !g_ssd_streaming_mode || !table) return 1;
    if (!cuda_ds_gpu_destination_enabled() ||
        !cuda_ds_gpu_prefetch_arena_ensure()) {
        return 1;
    }
    if (!cuda_stream_layer_expert_ranges_valid(
            table->model_size, table->n_total_expert,
            table->gate_offset, table->up_offset, table->down_offset,
            table->gate_expert_bytes, table->down_expert_bytes,
            "next-layer RAM hot prefetch")) {
        return 0;
    }

    cuda_ram_hot_prefetch_state &s = g_ram_hot_prefetch;
    if (s.active && s.ready &&
        !cuda_ok(cudaEventSynchronize(s.ready),
                 "retire prior next-layer RAM hot prefetch")) {
        s.active = 0;
        return 1;
    }
    s.active = 0;
    s.count = 0;
    s.ready_waited = 0;

    const uint64_t required =
        (uint64_t)k * (table->gate_expert_bytes * 2ull +
                       table->down_expert_bytes);
    if (required > cuda_ram_hot_prefetch_reserve_bytes()) {
        static int warned_capacity = 0;
        if (!warned_capacity) {
            warned_capacity = 1;
            fprintf(stderr,
                    "ds4: CUDA next-layer RAM hot prefetch needs %.1f MiB for K=%u; "
                    "reserved %.1f MiB (raise DS4_CUDA_RAM_PREFETCH_MB)\n",
                    (double)required / 1048576.0,
                    k,
                    (double)cuda_ram_hot_prefetch_reserve_bytes() / 1048576.0);
        }
        return 1;
    }

    const uint32_t hclass = cuda_stream_host_expert_cache_class_index(
        table->gate_expert_bytes, table->down_expert_bytes);
    cuda_stream_host_expert_cache *hcache =
        &g_stream_host_expert_caches[hclass];
    if (!hcache->valid ||
        hcache->gate_expert_bytes != table->gate_expert_bytes ||
        hcache->down_expert_bytes != table->down_expert_bytes) {
        return 1;
    }
    const uint32_t configured_cache_budget =
        cuda_stream_expert_cache_configured_budget();
    cuda_stream_expert_cache *vcache = configured_cache_budget != 0 ?
        cuda_stream_expert_cache_prepare(table->gate_expert_bytes,
                                         table->down_expert_bytes,
                                         configured_cache_budget) : NULL;

    uint32_t chosen[DS4_CUDA_RAM_HOT_PREFETCH_MAX];
    uint64_t chosen_age[DS4_CUDA_RAM_HOT_PREFETCH_MAX];
    uint32_t chosen_count = 0;

    /* R9 treatment: previous-token candidates first, then the unchanged host
     * age ordering. The flag is explicit opt-in so this binary's default arm
     * remains the measured 1.5%-accurate ranking. */
    static int predict_enabled = -1;
    if (predict_enabled < 0) {
        const char *pe = getenv("DS4_CUDA_RAM_PROMOTION_PREVIOUS_TOKEN");
        predict_enabled = pe && pe[0] && strcmp(pe, "0") != 0;
        fprintf(stderr,
                "ds4: CUDA RAM promotion previous-token predictor %s "
                "(DS4_CUDA_RAM_PROMOTION_PREVIOUS_TOKEN default=0)\n",
                predict_enabled ? "ENABLED" : "disabled");
    }
    if (predict_enabled && k != 0) {
        int32_t want[DS4_CUDA_RAM_HOT_PREFETCH_MAX];
        const uint32_t got = cuda_route_previous_predict(
            table->layer, want,
            k < DS4_CUDA_RAM_HOT_PREFETCH_MAX ?
                k : DS4_CUDA_RAM_HOT_PREFETCH_MAX);
        for (uint32_t w = 0; w < got && chosen_count < k; w++) {
            for (uint32_t hi = 0; hi < hcache->capacity; hi++) {
                const cuda_stream_host_expert_cache_slot &slot = hcache->slots[hi];
                if (!slot.valid || slot.layer != table->layer ||
                    slot.model_map != table->model_map ||
                    slot.model_size != table->model_size ||
                    slot.n_total_expert != table->n_total_expert ||
                    slot.gate_offset != table->gate_offset ||
                    slot.up_offset != table->up_offset ||
                    slot.down_offset != table->down_offset ||
                    slot.gate_expert_bytes != table->gate_expert_bytes ||
                    slot.down_expert_bytes != table->down_expert_bytes ||
                    (table->expert_tiers &&
                     table->expert_tiers[slot.expert] !=
                        DS4_STREAM_EXPERT_TIER_CACHE) ||
                    slot.expert != (uint32_t)want[w]) {
                    continue;
                }
                /* Already resident in VRAM: warming it would be a wasted transfer. */
                if (vcache && cuda_stream_expert_cache_find(
                        vcache, table->model_map, table->model_size, table->layer,
                        table->n_total_expert, slot.expert,
                        table->gate_offset, table->up_offset, table->down_offset,
                        table->gate_expert_bytes, table->down_expert_bytes) >= 0) {
                    break;
                }
                chosen[chosen_count] = hi;
                chosen_age[chosen_count] = slot.age;
                chosen_count++;
                break;
            }
        }
    }
    const uint32_t predicted_count = chosen_count;

    for (uint32_t hi = 0; chosen_count < k && hi < hcache->capacity; hi++) {
        const cuda_stream_host_expert_cache_slot &slot = hcache->slots[hi];
        if (!slot.valid || slot.model_map != table->model_map ||
            slot.model_size != table->model_size || slot.layer != table->layer ||
            slot.n_total_expert != table->n_total_expert ||
            slot.gate_offset != table->gate_offset ||
            slot.up_offset != table->up_offset ||
            slot.down_offset != table->down_offset ||
            slot.gate_expert_bytes != table->gate_expert_bytes ||
            slot.down_expert_bytes != table->down_expert_bytes ||
            (table->expert_tiers &&
             table->expert_tiers[slot.expert] != DS4_STREAM_EXPERT_TIER_CACHE) ||
            cuda_stream_expert_cache_probe(
                vcache, table->model_map, table->model_size, table->layer,
                table->n_total_expert, slot.expert,
                table->gate_offset, table->up_offset, table->down_offset,
                table->gate_expert_bytes, table->down_expert_bytes) >= 0) {
            continue;
        }
        bool already_chosen = false;
        for (uint32_t i = 0; i < chosen_count; i++) {
            if (chosen[i] == hi) { already_chosen = true; break; }
        }
        if (already_chosen) continue;
        uint32_t pos = predicted_count;
        while (pos < chosen_count && chosen_age[pos] >= slot.age) pos++;
        if (chosen_count < k) {
            for (uint32_t move = chosen_count; move > pos; move--) {
                chosen[move] = chosen[move - 1u];
                chosen_age[move] = chosen_age[move - 1u];
            }
            chosen_count++;
        } else if (pos < k) {
            for (uint32_t move = k - 1u; move > pos; move--) {
                chosen[move] = chosen[move - 1u];
                chosen_age[move] = chosen_age[move - 1u];
            }
        } else {
            continue;
        }
        chosen[pos] = hi;
        chosen_age[pos] = slot.age;
    }
    if (chosen_count == 0) return 1;

    if (!s.stream && !cuda_ok(cudaStreamCreateWithFlags(
                                  &s.stream, cudaStreamNonBlocking),
                              "create next-layer RAM hot prefetch stream")) {
        return 1;
    }
    if (!s.ready && !cuda_ok(cudaEventCreateWithFlags(
                                 &s.ready, cudaEventDisableTiming),
                             "create next-layer RAM hot prefetch event")) {
        return 1;
    }

    const uint64_t base = cuda_ds_gpu_ssd_capacity();
    for (uint32_t i = 0; i < chosen_count; i++) {
        cuda_stream_host_expert_cache_slot &slot = hcache->slots[chosen[i]];
        const uint64_t host_gate = (uint64_t)chosen[i] * table->gate_expert_bytes;
        const uint64_t host_down = (uint64_t)chosen[i] * table->down_expert_bytes;
        const uint64_t gpu_gate = base + (uint64_t)i * table->gate_expert_bytes;
        const uint64_t gpu_up = base + (uint64_t)k * table->gate_expert_bytes +
                                (uint64_t)i * table->gate_expert_bytes;
        const uint64_t gpu_down = base + 2ull * (uint64_t)k * table->gate_expert_bytes +
                                  (uint64_t)i * table->down_expert_bytes;
        if (!cuda_ok(cudaMemcpyAsync(g_ds_gpu_prefetch_arena + gpu_gate,
                                     hcache->gate_ptr + host_gate,
                                     (size_t)table->gate_expert_bytes,
                                     cudaMemcpyHostToDevice, s.stream),
                     "next-layer RAM hot gate upload") ||
            !cuda_ok(cudaMemcpyAsync(g_ds_gpu_prefetch_arena + gpu_up,
                                     hcache->up_ptr + host_gate,
                                     (size_t)table->gate_expert_bytes,
                                     cudaMemcpyHostToDevice, s.stream),
                     "next-layer RAM hot up upload") ||
            !cuda_ok(cudaMemcpyAsync(g_ds_gpu_prefetch_arena + gpu_down,
                                     hcache->down_ptr + host_down,
                                     (size_t)table->down_expert_bytes,
                                     cudaMemcpyHostToDevice, s.stream),
                     "next-layer RAM hot down upload")) {
            s.active = 0;
            return 1;
        }
        s.experts[i] = (int32_t)slot.expert;
        /* Protect the source until the async copy has consumed it. */
        slot.age = ++hcache->tick;
    }
    if (!cuda_ok(cudaEventRecord(s.ready, s.stream),
                 "record next-layer RAM hot prefetch event")) {
        return 1;
    }
    s.model_map = table->model_map;
    s.model_size = table->model_size;
    s.layer = table->layer;
    s.n_total_expert = table->n_total_expert;
    s.gate_offset = table->gate_offset;
    s.up_offset = table->up_offset;
    s.down_offset = table->down_offset;
    s.gate_expert_bytes = table->gate_expert_bytes;
    s.down_expert_bytes = table->down_expert_bytes;
    s.count = chosen_count;
    s.active = 1;
    g_ram_hot_prefetch_launched += chosen_count;
    return 1;
}
#endif

/* ── DIRECTSTORAGE / COMPUTE OVERLAP ────────────────────────────────────────────────────────────────
 *
 * Gate for the deferred-wait path. Read once into a static: a getenv in a per-expert path cost ~35% of
 * decode in this program once, and this is called per layer per token.
 *
 * Default OFF for exactly one build, purely so the change can be A/B'd inside a single session against the
 * recorded baseline (median 6.80 t/s). Per the standing rule that fixes ship default-ON with documented
 * defaults rather than as hidden env config, this flips to default-ON and the flag is DELETED once the
 * regression axes and the multi-turn coherence check both pass. */
/* Runtime DirectStorage pipeline depth (ds4_dstorage.cpp). Every measured DS rate equals
 * batch_size/batch_latency, i.e. one batch at a time, and batch SIZE has saturated (a 1.4 GiB
 * batch still gives 14.7 GiB/s). More batches IN FLIGHT is the only route to the array peak. */
extern "C" uint32_t ds4_ds_pipeline_depth(void);
extern "C" uint32_t ds4_ds_pipeline_capacity(void);
extern "C" int ds4_ds_batch_oldest_ready(void);

/* Default-ON decode lookahead. The value is the maximum number of multi-layer
 * waves kept in flight (current included); 0 restores the legacy token-wide
 * frequency-tier batch for A/B measurement. */
static uint32_t cuda_ds_decode_pipeline_requested_depth(void) {
    static int initialized = 0;
    static uint32_t depth = 4;
    if (!initialized) {
        const char *env = getenv("DS4_CUDA_DECODE_PIPELINE_DEPTH");
        if (env && env[0]) {
            char *end = NULL;
            const unsigned long value = strtoul(env, &end, 10);
            if (end != env && end && *end == '\0' && value <= UINT32_MAX) {
                depth = (uint32_t)value;
            } else {
                fprintf(stderr,
                        "ds4: invalid DS4_CUDA_DECODE_PIPELINE_DEPTH=%s; using default depth 4\n",
                        env);
            }
        }
        initialized = 1;
    }
    return depth;
}

static int cuda_ds_expert_overlap_enabled(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_DS_OVERLAP");
        cached = (env && env[0] && env[0] != '0') ? 1 : 0;
    }
    return cached;
}

/* Diagnostic-only gate, cached for the same reason as the overlap gate above: this is queried once per
 * DirectStorage batch and must never add a getenv call to the per-layer/per-token path. */
static int cuda_ds_batch_trace_enabled(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_DS_BATCH_TRACE");
        cached = (env && env[0] && env[0] != '0') ? 1 : 0;
    }
    return cached;
}

/* Drain any outstanding DirectStorage batch. Idempotent, so it is safe to call at every point that might
 * be the first to touch fetched data. Accumulates the stats the blocking path used to record inline. */
static void cuda_ds_expert_fetch_drain(void) {
    while (ds4_ds_batch_inflight() != 0) {
#if defined(_WIN32)
        const int decode_pipeline_wait =
            g_ds_decode_pipeline.active &&
            g_ds_decode_pipeline.current < g_ds_decode_pipeline.count;
        const int hash_pipeline_wait =
            g_ds_hash_pipeline.active &&
            g_ds_hash_pipeline.current < g_ds_hash_pipeline.count;
        int decode_ready_before_wait = -1;
        if (decode_pipeline_wait) {
            cuda_ds_decode_pipeline_layer &current =
                g_ds_decode_pipeline.layers[g_ds_decode_pipeline.current];
            cuda_ds_decode_pipeline_wave &wave =
                g_ds_decode_pipeline.waves[current.wave];
            if (wave.drained || !wave.submitted) {
                wave.drained = 1;
                break;
            }
            decode_ready_before_wait = ds4_ds_batch_oldest_ready();
        }
        if (hash_pipeline_wait) {
            const uint32_t current = g_ds_hash_pipeline.current;
            if (g_ds_hash_pipeline.current_drained ||
                !g_ds_hash_pipeline.submitted[current]) {
                g_ds_hash_pipeline.current_drained = 1;
                break;
            }
        }
#endif
        uint64_t got_bytes = 0;
        double   got_ms    = 0.0;
        double   wait_ms   = 0.0;
        if (g_ds_decode_bandwidth.batch_wait(
                &got_bytes, &got_ms, &wait_ms)) {
            g_ds_prefetch_bytes += got_bytes;
            g_ds_prefetch_ms    += got_ms;
#if defined(_WIN32)
            if (decode_pipeline_wait && g_ds_decode_pipeline.active &&
                g_ds_decode_pipeline.current < g_ds_decode_pipeline.count) {
                cuda_ds_decode_pipeline_layer &current =
                    g_ds_decode_pipeline.layers[g_ds_decode_pipeline.current];
                cuda_ds_decode_pipeline_wave &wave =
                    g_ds_decode_pipeline.waves[current.wave];
                wave.drained = 1;
                g_decode_profile.decode_pipeline_ds_wait_ms += wait_ms;
                if (decode_ready_before_wait == 0) {
                    g_decode_profile.decode_pipeline_blocked++;
                }
            } else if (g_ds_hash_pipeline.active &&
                g_ds_hash_pipeline.current < g_ds_hash_pipeline.count) {
                const uint32_t current = g_ds_hash_pipeline.current;
                g_ds_hash_pipeline_stats.waits[current]++;
                g_ds_hash_pipeline_stats.batch_ms[current] += got_ms;
                g_ds_hash_pipeline_stats.wait_ms[current] += wait_ms;
                g_ds_hash_pipeline_stats.layer[current] =
                    g_ds_hash_pipeline.tables[current].layer;
                g_ds_hash_pipeline.current_drained = 1;
            }
#endif
            if (cuda_decode_profile_enabled()) {
                g_decode_profile.ds_batches++;
                g_decode_profile.ds_batch_ms += got_ms;
                g_decode_profile.ds_wait_calls++;
                g_decode_profile.ds_wait_ms += wait_ms;
            }
            if (cuda_ds_batch_trace_enabled()) {
                fprintf(stderr, "ds4: DSBATCH bytes=%llu ms=%.3f\n",
                        (unsigned long long)got_bytes, got_ms);
            }
        } else {
            /* A failed batch must never be mistaken for fetched data - same rule as the blocking path. */
            cuda_ds_prefetch_reset();
            fprintf(stderr, "ds4: CUDA batched prefetch wait failed; disabling it for this run\n");
            g_ds_prefetch_disabled = 1;
#if defined(_WIN32)
            g_ds_decode_pipeline.active = 0;
            g_ds_decode_pipeline.staging_slot = -1;
            g_ds_hash_pipeline.active = 0;
#endif
            break;
        }
#if defined(_WIN32)
        if (decode_pipeline_wait || hash_pipeline_wait) break;
#endif
    }
}

#if defined(_WIN32)
static int cuda_ds_hot_prefetch_matches(
        const void *model_map,
        uint32_t layer) {
    if (g_ds_decode_pipeline.active &&
        g_ds_decode_pipeline.current < g_ds_decode_pipeline.count) {
        const ds4_gpu_stream_expert_table &table =
            g_ds_decode_pipeline.layers[g_ds_decode_pipeline.current].table;
        return model_map == table.model_map && layer == table.layer;
    }
    if (!g_ds_hot_prefetch_active || g_ds_hot_prefetch_map != model_map) return 0;
    if (g_ds_hash_pipeline.active &&
        g_ds_hash_pipeline.current < g_ds_hash_pipeline.count) {
        return layer ==
            g_ds_hash_pipeline.tables[g_ds_hash_pipeline.current].layer;
    }
    return layer <= g_ds_hot_prefetch_last_layer;
}

static void cuda_ds_hot_prefetch_retire(void) {
    cuda_ds_phase_scope retire_scope(&g_ds_decode_bandwidth.phase_retire_ms);
    if (g_ds_decode_pipeline.active) {
        for (uint32_t i = g_ds_decode_pipeline.current;
             i < g_ds_decode_pipeline.count; i++) {
            const cuda_ds_decode_pipeline_layer &layer =
                g_ds_decode_pipeline.layers[i];
            if (layer.wave >= g_ds_decode_pipeline.next_submit) break;
            if (layer.predicted_experts > layer.used_predicted_experts) {
                g_decode_profile.decode_pipeline_mispredicted_experts +=
                    layer.predicted_experts - layer.used_predicted_experts;
            }
        }
        g_ds_decode_pipeline.active = 0;
        g_ds_decode_pipeline.staging_slot = -1;
    }
    cuda_ds_expert_fetch_drain();
    g_ds_hot_prefetch_active = 0;
    g_ds_hot_prefetch_map = NULL;
    cuda_ds_prefetch_reset();
    ds4_ds_batch_reset();
}

static int cuda_ds_hash_layer_pipeline_enabled(void) {
    static int cached = -1;
    if (cached < 0) {
        const char *env = getenv("DS4_CUDA_HASH_LAYER_PIPELINE");
        cached = (env && env[0] && env[0] != '0') ? 1 : 0;
    }
    return cached;
}

static void cuda_ds_hot_prefetch_rollback(
        int append,
        int decode_pipeline_slot,
        uint64_t used_before,
        size_t spans_before) {
    if (decode_pipeline_slot >= 0) {
        g_ds_decode_pipeline.slots[(uint32_t)decode_pipeline_slot].used = used_before;
        g_ds_prefetch_spans.resize(spans_before);
    } else if (append) {
        g_ds_prefetch_used = used_before;
        g_ds_prefetch_spans.resize(spans_before);
    } else {
        cuda_ds_prefetch_reset();
    }
}

/* Stage and submit one immutable hot-prefetch group.  The caller owns batch
 * retirement and, for the pipeline, the lifetime of tables/exact_selected. */
static int cuda_ds_hot_prefetch_submit(
        const ds4_gpu_stream_expert_table *tables,
        uint32_t n_tables,
        const int32_t *exact_selected,
        uint32_t exact_stride,
        int append) {
    cuda_ds_phase_scope plan_scope(&g_ds_decode_bandwidth.phase_plan_ms);
    if (!g_ssd_streaming_mode || !tables || n_tables == 0) return 1;
    if (!cuda_ds_prefetch_enabled() || g_model_fd < 0) {
        return 1;
    }
    if (!ds4_ds_init_from_fd(g_model_fd)) return 1;
    const int use_gpu_destination =
        cuda_ds_gpu_destination_enabled() && cuda_ds_gpu_prefetch_arena_ensure();
    if (!use_gpu_destination && g_ds_prefetch_arena == NULL) {
        g_ds_prefetch_capacity = cuda_ds_prefetch_capacity_bytes();
        g_ds_prefetch_arena = (char *)malloc((size_t)g_ds_prefetch_capacity);
        if (g_ds_prefetch_arena == NULL) {
            fprintf(stderr,
                    "ds4: CUDA hot prefetch disabled: cannot allocate a %.0f MiB arena\n",
                    (double)g_ds_prefetch_capacity / 1048576.0);
            g_ds_prefetch_disabled = 1;
            return 1;
        }
    }

    if (g_ds_decode_pipeline.active &&
        g_ds_decode_pipeline.staging_slot >= 0 &&
        use_gpu_destination != g_ds_decode_pipeline.use_gpu_destination) {
        fprintf(stderr,
                "ds4: CUDA decode pipeline staging destination changed while the "
                "token was active; abandoning lookahead\n");
        return 1;
    }

    const int decode_pipeline_slot =
        g_ds_decode_pipeline.active ? g_ds_decode_pipeline.staging_slot : -1;
    const uint64_t used_before = decode_pipeline_slot >= 0 ?
        g_ds_decode_pipeline.slots[(uint32_t)decode_pipeline_slot].used :
        (append ? g_ds_prefetch_used : 0);
    const size_t spans_before = g_ds_prefetch_spans.size();
    if (!append && decode_pipeline_slot < 0) cuda_ds_prefetch_reset();
    ds4_ds_batch_reset();
    uint32_t n_prefetch = 0;
    uint32_t last_prefetch_layer = 0;
    const void *model_map = NULL;
    for (uint32_t ti = 0; ti < n_tables; ti++) {
        const ds4_gpu_stream_expert_table *table = &tables[ti];
        if ((g_model_fd_host_base != NULL && table->model_map != g_model_fd_host_base) ||
            (model_map != NULL && table->model_map != model_map) ||
            !cuda_stream_layer_expert_ranges_valid(table->model_size,
                                                   table->n_total_expert,
                                                   table->gate_offset,
                                                   table->up_offset,
                                                   table->down_offset,
                                                   table->gate_expert_bytes,
                                                   table->down_expert_bytes,
                                                   "token hot prefetch")) {
            ds4_ds_batch_reset();
            cuda_ds_hot_prefetch_rollback(
                append, decode_pipeline_slot, used_before, spans_before);
            return 1;
        }
        model_map = table->model_map;
        for (uint32_t expert = 0; table->expert_tiers &&
                                  expert < table->n_total_expert; expert++) {
            if (table->expert_tiers[expert] != DS4_STREAM_EXPERT_TIER_PREFETCH) continue;
            const uint64_t gate_src = table->gate_offset +
                (uint64_t)expert * table->gate_expert_bytes;
            const uint64_t up_src = table->up_offset +
                (uint64_t)expert * table->gate_expert_bytes;
            const uint64_t down_src = table->down_offset +
                (uint64_t)expert * table->down_expert_bytes;
            if (!cuda_ds_prefetch_stage(table->model_map, gate_src,
                                        table->gate_expert_bytes, use_gpu_destination) ||
                !cuda_ds_prefetch_stage(table->model_map, up_src,
                                        table->gate_expert_bytes, use_gpu_destination) ||
                !cuda_ds_prefetch_stage(table->model_map, down_src,
                                        table->down_expert_bytes, use_gpu_destination)) {
                fprintf(stderr,
                        "ds4: CUDA token hot prefetch K exceeds the %.0f MiB arena; "
                        "falling back to on-demand tier-1 loads\n",
                        (double)(use_gpu_destination ? cuda_ds_gpu_ssd_capacity() :
                                                       g_ds_prefetch_capacity) / 1048576.0);
                ds4_ds_batch_reset();
                cuda_ds_hot_prefetch_rollback(
                    append, decode_pipeline_slot, used_before, spans_before);
                return 1;
            }
            n_prefetch++;
            if (table->layer > last_prefetch_layer) last_prefetch_layer = table->layer;
        }

        /* Hash-routed layers expose their six exact expert ids from tid2eid as
         * soon as the token id is known. Do not turn cache hits into redundant
         * reads: stage only selections absent from both VRAM and host caches. */
        if (exact_selected && exact_stride != 0) {
            const uint32_t configured_cache_budget =
                cuda_stream_expert_cache_configured_budget();
            cuda_stream_expert_cache *expert_cache =
                configured_cache_budget != 0 ?
                    cuda_stream_expert_cache_prepare(table->gate_expert_bytes,
                                                     table->down_expert_bytes,
                                                     configured_cache_budget) : NULL;
            for (uint32_t si = 0; si < exact_stride; si++) {
                const int32_t selected = exact_selected[(size_t)ti * exact_stride + si];
                if (selected < 0 || (uint32_t)selected >= table->n_total_expert) continue;
                const uint32_t expert = (uint32_t)selected;
                const int cache_eligible =
                    table->expert_tiers == NULL ||
                    table->expert_tiers[expert] == DS4_STREAM_EXPERT_TIER_CACHE;
                if (cache_eligible && expert_cache) {
                    const int cache_slot = cuda_stream_expert_cache_find(
                        expert_cache,
                        table->model_map,
                        table->model_size,
                        table->layer,
                        table->n_total_expert,
                        expert,
                        table->gate_offset,
                        table->up_offset,
                        table->down_offset,
                        table->gate_expert_bytes,
                        table->down_expert_bytes);
                    if (cache_slot >= 0) {
                        if (g_ds_hash_pipeline.active || g_ds_decode_pipeline.active) {
                            const uint64_t gate_src = table->gate_offset +
                                (uint64_t)expert * table->gate_expert_bytes;
                            const uint64_t up_src = table->up_offset +
                                (uint64_t)expert * table->gate_expert_bytes;
                            const uint64_t down_src = table->down_offset +
                                (uint64_t)expert * table->down_expert_bytes;
                            const uint64_t cache_gate =
                                (uint64_t)(uint32_t)cache_slot * table->gate_expert_bytes;
                            const uint64_t cache_down =
                                (uint64_t)(uint32_t)cache_slot * table->down_expert_bytes;
                            if (!cuda_ds_prefetch_snapshot_span(
                                    table->model_map, gate_src,
                                    table->gate_expert_bytes,
                                    expert_cache->gate_ptr + cache_gate,
                                    cudaMemcpyDeviceToDevice,
                                    "hash pipeline VRAM gate snapshot") ||
                                !cuda_ds_prefetch_snapshot_span(
                                    table->model_map, up_src,
                                    table->gate_expert_bytes,
                                    expert_cache->up_ptr + cache_gate,
                                    cudaMemcpyDeviceToDevice,
                                    "hash pipeline VRAM up snapshot") ||
                                !cuda_ds_prefetch_snapshot_span(
                                    table->model_map, down_src,
                                    table->down_expert_bytes,
                                    expert_cache->down_ptr + cache_down,
                                    cudaMemcpyDeviceToDevice,
                                    "hash pipeline VRAM down snapshot")) {
                                ds4_ds_batch_reset();
                                cuda_ds_hot_prefetch_rollback(
                                    append, decode_pipeline_slot,
                                    used_before, spans_before);
                                return 1;
                            }
                            expert_cache->slots[(uint32_t)cache_slot].age =
                                ++expert_cache->tick;
                            n_prefetch++;
                        }
                        continue;
                    }
                }
                if (cache_eligible) {
                    const uint32_t hclass =
                        cuda_stream_host_expert_cache_class_index(
                            table->gate_expert_bytes, table->down_expert_bytes);
                    cuda_stream_host_expert_cache *hcache =
                        &g_stream_host_expert_caches[hclass];
                    if (hcache->valid &&
                        hcache->gate_expert_bytes == table->gate_expert_bytes &&
                        hcache->down_expert_bytes == table->down_expert_bytes) {
                        const int host_slot = cuda_stream_host_expert_cache_find(
                                hcache,
                                table->model_map,
                                table->model_size,
                                table->layer,
                                table->n_total_expert,
                                expert,
                                table->gate_offset,
                                table->up_offset,
                                table->down_offset,
                                table->gate_expert_bytes,
                                table->down_expert_bytes);
                        if (host_slot >= 0) {
                            if (g_ds_hash_pipeline.active || g_ds_decode_pipeline.active) {
                                const uint64_t gate_src = table->gate_offset +
                                    (uint64_t)expert * table->gate_expert_bytes;
                                const uint64_t up_src = table->up_offset +
                                    (uint64_t)expert * table->gate_expert_bytes;
                                const uint64_t down_src = table->down_offset +
                                    (uint64_t)expert * table->down_expert_bytes;
                                const uint64_t host_gate =
                                    (uint64_t)(uint32_t)host_slot * table->gate_expert_bytes;
                                const uint64_t host_down =
                                    (uint64_t)(uint32_t)host_slot * table->down_expert_bytes;
                                if (!cuda_ds_prefetch_snapshot_span(
                                        table->model_map, gate_src,
                                        table->gate_expert_bytes,
                                        hcache->gate_ptr + host_gate,
                                        cudaMemcpyHostToDevice,
                                        "hash pipeline RAM gate snapshot") ||
                                    !cuda_ds_prefetch_snapshot_span(
                                        table->model_map, up_src,
                                        table->gate_expert_bytes,
                                        hcache->up_ptr + host_gate,
                                        cudaMemcpyHostToDevice,
                                        "hash pipeline RAM up snapshot") ||
                                    !cuda_ds_prefetch_snapshot_span(
                                        table->model_map, down_src,
                                        table->down_expert_bytes,
                                        hcache->down_ptr + host_down,
                                        cudaMemcpyHostToDevice,
                                        "hash pipeline RAM down snapshot")) {
                                    ds4_ds_batch_reset();
                                    cuda_ds_hot_prefetch_rollback(
                                        append, decode_pipeline_slot,
                                        used_before, spans_before);
                                    return 1;
                                }
                                hcache->slots[(uint32_t)host_slot].age = ++hcache->tick;
                                n_prefetch++;
                            }
                            continue;
                        }
                    }
                }
                const uint64_t gate_src = table->gate_offset +
                    (uint64_t)expert * table->gate_expert_bytes;
                const uint64_t up_src = table->up_offset +
                    (uint64_t)expert * table->gate_expert_bytes;
                const uint64_t down_src = table->down_offset +
                    (uint64_t)expert * table->down_expert_bytes;
                if (!cuda_ds_prefetch_stage(table->model_map, gate_src,
                                            table->gate_expert_bytes, use_gpu_destination) ||
                    !cuda_ds_prefetch_stage(table->model_map, up_src,
                                            table->gate_expert_bytes, use_gpu_destination) ||
                    !cuda_ds_prefetch_stage(table->model_map, down_src,
                                            table->down_expert_bytes, use_gpu_destination)) {
                    ds4_ds_batch_reset();
                    cuda_ds_hot_prefetch_rollback(
                        append, decode_pipeline_slot, used_before, spans_before);
                    return 1;
                }
                n_prefetch++;
                if (table->layer > last_prefetch_layer) last_prefetch_layer = table->layer;
            }
        }
    }
    if (n_prefetch == 0) {
        ds4_ds_batch_reset();
        cuda_ds_hot_prefetch_rollback(
            append, decode_pipeline_slot, used_before, spans_before);
        return 1;
    }
    const int has_requests = ds4_ds_batch_count() != 0;
    if (has_requests) {
        ds4_ds_stats_set_batch_layer(tables[0].layer,
                                     last_prefetch_layer);
    }
    if (has_requests && !g_ds_decode_bandwidth.batch_submit()) {
        ds4_ds_batch_reset();
        cuda_ds_hot_prefetch_rollback(
            append, decode_pipeline_slot, used_before, spans_before);
        return 1;
    }

    if (has_requests) g_ds_prefetch_batches++;
    g_ds_hot_prefetch_active = 1;
    g_ds_hot_prefetch_map = model_map;
    if (!append || last_prefetch_layer > g_ds_hot_prefetch_last_layer) {
        g_ds_hot_prefetch_last_layer = last_prefetch_layer;
    }
    if (decode_pipeline_slot < 0) {
        g_ds_hot_prefetch_used = g_ds_prefetch_used;
        g_ds_hot_prefetch_spans = g_ds_prefetch_spans.size();
    }
    return 1;
}

static int cuda_ds_decode_pipeline_layer_owns_expert(
        const cuda_ds_decode_pipeline_layer *layer,
        uint32_t expert) {
    if (!layer || expert >= layer->table.n_total_expert) return 0;
    const ds4_gpu_stream_expert_table &table = layer->table;
    const uint64_t gate_src = table.gate_offset +
        (uint64_t)expert * table.gate_expert_bytes;
    const uint64_t up_src = table.up_offset +
        (uint64_t)expert * table.gate_expert_bytes;
    const uint64_t down_src = table.down_offset +
        (uint64_t)expert * table.down_expert_bytes;
    const cuda_ds_prefetch_span *gate =
        cuda_ds_prefetch_find_span(table.model_map, gate_src,
                                   table.gate_expert_bytes);
    const cuda_ds_prefetch_span *up =
        cuda_ds_prefetch_find_span(table.model_map, up_src,
                                   table.gate_expert_bytes);
    const cuda_ds_prefetch_span *down =
        cuda_ds_prefetch_find_span(table.model_map, down_src,
                                   table.down_expert_bytes);
    return gate && up && down &&
           gate->decode_pipeline_slot == (int)layer->slot &&
           up->decode_pipeline_slot == (int)layer->slot &&
           down->decode_pipeline_slot == (int)layer->slot;
}

static int cuda_ds_decode_pipeline_layer_fully_staged(
        const cuda_ds_decode_pipeline_layer *layer) {
    if (!layer) return 0;
    for (uint32_t expert = 0; layer->table.expert_tiers &&
                              expert < layer->table.n_total_expert; expert++) {
        if (layer->table.expert_tiers[expert] ==
                DS4_STREAM_EXPERT_TIER_PREFETCH &&
            !cuda_ds_decode_pipeline_layer_owns_expert(layer, expert)) {
            return 0;
        }
    }
    for (uint32_t si = 0; si < DS4_CUDA_HASH_PIPELINE_MAX_SELECTED; si++) {
        const int32_t selected = layer->selected[si];
        if (selected >= 0 &&
            (uint32_t)selected < layer->table.n_total_expert &&
            !cuda_ds_decode_pipeline_layer_owns_expert(
                layer, (uint32_t)selected)) {
            return 0;
        }
    }
    return 1;
}

static int cuda_ds_decode_pipeline_submit_ahead(void) {
    while (g_ds_decode_pipeline.active &&
           g_ds_decode_pipeline.next_submit < g_ds_decode_pipeline.wave_count &&
           g_ds_decode_pipeline.next_submit - g_ds_decode_pipeline.current_wave <
               g_ds_decode_pipeline.depth &&
           ds4_ds_batch_inflight() < g_ds_decode_pipeline.depth) {
        const uint32_t submit = g_ds_decode_pipeline.next_submit;
        cuda_ds_decode_pipeline_wave &wave =
            g_ds_decode_pipeline.waves[submit];
        const uint32_t slot = submit % g_ds_decode_pipeline.depth;
        cuda_ds_decode_pipeline_slot_reset(slot);
        wave.slot = slot;
        wave.staged = 0;
        wave.submitted = 0;
        wave.drained = 0;

        ds4_gpu_stream_expert_table
            tables[DS4_CUDA_HASH_PIPELINE_MAX_LAYERS];
        int32_t selected[DS4_CUDA_HASH_PIPELINE_MAX_LAYERS]
                        [DS4_CUDA_HASH_PIPELINE_MAX_SELECTED];
        for (uint32_t wi = 0; wi < wave.count; wi++) {
            cuda_ds_decode_pipeline_layer &layer =
                g_ds_decode_pipeline.layers[wave.first + wi];
            layer.slot = slot;
            layer.arrived = 0;
            layer.arrival_resident = 0;
            tables[wi] = layer.table;
            memcpy(selected[wi], layer.selected, sizeof(selected[wi]));
        }

        g_ds_decode_pipeline.staging_slot = (int)slot;
        const uint32_t inflight_before = ds4_ds_batch_inflight();
        (void)cuda_ds_hot_prefetch_submit(
            tables,
            wave.count,
            &selected[0][0],
            DS4_CUDA_HASH_PIPELINE_MAX_SELECTED,
            1);
        g_ds_decode_pipeline.staging_slot = -1;
        wave.submitted = ds4_ds_batch_inflight() > inflight_before;
        for (uint32_t wi = 0; wi < wave.count; wi++) {
            cuda_ds_decode_pipeline_layer &layer =
                g_ds_decode_pipeline.layers[wave.first + wi];
            if (!cuda_ds_decode_pipeline_layer_fully_staged(&layer)) {
                fprintf(stderr,
                        "ds4: CUDA decode wide wave %u could not stage layer %u: "
                        "wave_reserved=%.1f MiB slot=%.1f MiB requests=%u/%u; "
                        "abandoning lookahead for this token\n",
                        submit,
                        layer.table.layer,
                        (double)wave.reserved_bytes / 1048576.0,
                        (double)g_ds_decode_pipeline.slot_bytes / 1048576.0,
                        wave.reserved_requests,
                        ds4_ds_batch_capacity());
                return 0;
            }
            g_decode_profile.decode_pipeline_prefetched_experts +=
                layer.predicted_experts;
        }
        wave.staged = 1;
        g_ds_decode_pipeline.next_submit++;
        if (wave.submitted) {
            g_decode_profile.decode_pipeline_batches_ahead++;
        }
    }
    return 1;
}

static int cuda_ds_decode_pipeline_capture(
        const ds4_gpu_stream_expert_table *tables,
        uint32_t n_tables,
        const int32_t *exact_selected,
        uint32_t exact_stride) {
    const uint32_t requested = cuda_ds_decode_pipeline_requested_depth();
    int has_frequency_tier = 0;
    for (uint32_t ti = 0; ti < n_tables && !has_frequency_tier; ti++) {
        for (uint32_t expert = 0; tables[ti].expert_tiers &&
                                  expert < tables[ti].n_total_expert; expert++) {
            if (tables[ti].expert_tiers[expert] ==
                    DS4_STREAM_EXPERT_TIER_PREFETCH) {
                has_frequency_tier = 1;
                break;
            }
        }
    }
    if (!has_frequency_tier) {
        /* [2026-08-20] This used to return silently, and that cost a campaign. The decode
         * pipeline predicts tier-1 experts, so with DS4_CUDA_STREAMING_PREFETCH_K=0 and
         * DS4_CUDA_STREAMING_CACHE_M=0 nothing is ever marked TIER_PREFETCH and there is
         * nothing to look ahead at. The run then behaves exactly like the legacy path while
         * DS4_CUDA_DECODE_PIPELINE_DEPTH reads 4, so an A/B against it silently compares
         * baseline with baseline. "Disabled by depth=0" and "no prediction to work with" are
         * different states and both must be visible. */
        static int announced_no_tier = 0;
        if (!announced_no_tier) {
            announced_no_tier = 1;
            fprintf(stderr,
                    "ds4: CUDA decode pipeline INACTIVE: no expert is in the frequency "
                    "prefetch tier, so there is nothing to look ahead at. Set "
                    "DS4_CUDA_STREAMING_PREFETCH_K (and DS4_CUDA_STREAMING_CACHE_M) non-zero "
                    "to give it a prediction; depth=%u is otherwise inert.\n",
                    requested);
        }
        return 0;
    }
    if (requested == 0) {
        static int announced_disabled = 0;
        if (!announced_disabled) {
            announced_disabled = 1;
            fprintf(stderr,
                    "ds4: CUDA decode frequency-tier pipeline disabled by "
                    "DS4_CUDA_DECODE_PIPELINE_DEPTH=0\n");
        }
        return 0;
    }
    if (!g_ssd_streaming_mode || !tables || n_tables == 0 ||
        n_tables > DS4_CUDA_HASH_PIPELINE_MAX_LAYERS ||
        !cuda_ds_prefetch_enabled() || g_model_fd < 0 ||
        !ds4_ds_init_from_fd(g_model_fd)) {
        return 0;
    }

    const int use_gpu_destination =
        cuda_ds_gpu_destination_enabled() && cuda_ds_gpu_prefetch_arena_ensure();
    if (!use_gpu_destination && g_ds_prefetch_arena == NULL) {
        g_ds_prefetch_capacity = cuda_ds_prefetch_capacity_bytes();
        g_ds_prefetch_arena = (char *)malloc((size_t)g_ds_prefetch_capacity);
        if (!g_ds_prefetch_arena) {
            fprintf(stderr,
                    "ds4: CUDA decode pipeline cannot allocate its %.0f MiB host arena\n",
                    (double)g_ds_prefetch_capacity / 1048576.0);
            return 0;
        }
    }
    const uint64_t arena_capacity = use_gpu_destination ?
        cuda_ds_gpu_ssd_capacity() : g_ds_prefetch_capacity;
    if (arena_capacity == 0) {
        fprintf(stderr,
                "ds4: CUDA decode pipeline has zero usable staging capacity; "
                "check DS4_CUDA_DS_PREFETCH_MB and the GPU-destination reserve\n");
        return 0;
    }

    g_ds_decode_pipeline = {};
    g_ds_decode_pipeline.staging_slot = -1;
    g_ds_decode_pipeline.requested_depth = requested;
    g_ds_decode_pipeline.use_gpu_destination = use_gpu_destination;
    g_ds_decode_pipeline.count = n_tables;
    uint64_t max_slot_bytes = 0;
    for (uint32_t ti = 0; ti < n_tables; ti++) {
        cuda_ds_decode_pipeline_layer &dst =
            g_ds_decode_pipeline.layers[ti];
        dst.table = tables[ti];
        memset(dst.selected, 0xff, sizeof(dst.selected));
        if (exact_selected && exact_stride != 0) {
            const uint32_t copy =
                exact_stride < DS4_CUDA_HASH_PIPELINE_MAX_SELECTED ?
                    exact_stride : DS4_CUDA_HASH_PIPELINE_MAX_SELECTED;
            memcpy(dst.selected,
                   exact_selected + (size_t)ti * exact_stride,
                   (size_t)copy * sizeof(dst.selected[0]));
        }

        uint32_t predicted = 0;
        for (uint32_t expert = 0; dst.table.expert_tiers &&
                                  expert < dst.table.n_total_expert; expert++) {
            if (dst.table.expert_tiers[expert] ==
                    DS4_STREAM_EXPERT_TIER_PREFETCH) {
                predicted++;
            }
        }
        dst.predicted_experts = predicted;

        uint32_t exact_additions = 0;
        uint32_t exact_valid = 0;
        for (uint32_t si = 0; si < DS4_CUDA_HASH_PIPELINE_MAX_SELECTED; si++) {
            const int32_t selected = dst.selected[si];
            if (selected < 0 ||
                (uint32_t)selected >= dst.table.n_total_expert) continue;
            int duplicate = 0;
            for (uint32_t prior = 0; prior < si; prior++) {
                if (dst.selected[prior] == selected) {
                    duplicate = 1;
                    break;
                }
            }
            if (duplicate) continue;
            exact_valid++;
            if (!dst.table.expert_tiers ||
                dst.table.expert_tiers[(uint32_t)selected] !=
                    DS4_STREAM_EXPERT_TIER_PREFETCH) {
                exact_additions++;
            }
        }
        const uint32_t reserve_experts = predicted +
            (exact_valid != 0 ? exact_additions :
             DS4_CUDA_HASH_PIPELINE_MAX_SELECTED);
        if (dst.table.gate_expert_bytes >
                (UINT64_MAX - dst.table.down_expert_bytes) / 2ull) {
            fprintf(stderr,
                    "ds4: CUDA decode pipeline expert size overflow at layer %u\n",
                    dst.table.layer);
            return 0;
        }
        const uint64_t expert_bytes =
            dst.table.gate_expert_bytes * 2ull +
            dst.table.down_expert_bytes;
        if (reserve_experts != 0 &&
            expert_bytes > UINT64_MAX / reserve_experts) {
            fprintf(stderr,
                    "ds4: CUDA decode pipeline slot size overflow at layer %u\n",
                    dst.table.layer);
            return 0;
        }
        const uint64_t layer_bytes = expert_bytes * reserve_experts;
        if (reserve_experts > UINT32_MAX / 3u) {
            fprintf(stderr,
                    "ds4: CUDA decode pipeline request-count overflow at layer %u\n",
                    dst.table.layer);
            return 0;
        }
        dst.reserved_bytes = layer_bytes;
        dst.reserved_requests = reserve_experts * 3u;
        if (g_ds_decode_pipeline.token_reserved_bytes >
                UINT64_MAX - layer_bytes ||
            g_ds_decode_pipeline.token_reserved_requests >
                UINT32_MAX - dst.reserved_requests) {
            fprintf(stderr,
                    "ds4: CUDA decode token-wide plan overflow at layer %u\n",
                    dst.table.layer);
            return 0;
        }
        g_ds_decode_pipeline.token_reserved_bytes += layer_bytes;
        g_ds_decode_pipeline.token_reserved_requests +=
            dst.reserved_requests;
        if (layer_bytes > max_slot_bytes) max_slot_bytes = layer_bytes;
    }
    if (max_slot_bytes == 0) return 0;

    uint32_t depth = requested;
    const uint32_t reported_transport_capacity = ds4_ds_pipeline_capacity();
    const uint32_t transport_capacity =
        reported_transport_capacity < DS4_CUDA_DECODE_PIPELINE_MAX_DEPTH ?
            reported_transport_capacity : DS4_CUDA_DECODE_PIPELINE_MAX_DEPTH;
    if (depth > transport_capacity) {
        fprintf(stderr,
                "ds4: CUDA decode pipeline depth %u exceeds the DirectStorage "
                "slot limit %u; reducing depth to %u\n",
                requested, transport_capacity, transport_capacity);
        depth = transport_capacity;
    }
    if (depth > n_tables) depth = n_tables;
    const uint64_t arena_depth64 = arena_capacity / max_slot_bytes;
    const uint32_t arena_depth = arena_depth64 > UINT32_MAX ?
        UINT32_MAX : (uint32_t)arena_depth64;
    if (depth > arena_depth) {
        fprintf(stderr,
                "ds4: CUDA decode pipeline depth %u needs %.1f MiB of the %.1f MiB "
                "staging arena; reducing depth to %u\n",
                depth,
                (double)depth * (double)max_slot_bytes / 1048576.0,
                (double)arena_capacity / 1048576.0,
                arena_depth);
        depth = arena_depth;
    }
    if (depth == 0) {
        fprintf(stderr,
                "ds4: CUDA decode pipeline cannot fit one %.1f MiB layer slot in "
                "the %.1f MiB staging arena; using on-demand loads\n",
                (double)max_slot_bytes / 1048576.0,
                (double)arena_capacity / 1048576.0);
        return 0;
    }

    g_ds_decode_pipeline.depth = depth;
    /* Give every live transport slot its equal share of the entire arena.
     * The previous ring fixed capacity to one maximum layer and left the
     * remainder unusable. A slot now owns a multi-layer wave. */
    g_ds_decode_pipeline.slot_bytes = arena_capacity / depth;
    for (uint32_t slot = 0; slot < depth; slot++) {
        g_ds_decode_pipeline.slots[slot].arena_offset =
            (uint64_t)slot * g_ds_decode_pipeline.slot_bytes;
        g_ds_decode_pipeline.slots[slot].capacity =
            g_ds_decode_pipeline.slot_bytes;
    }

    /* Capture every layer once, at token start, into consecutive wide waves.
     * Bytes and request count are both hard bounds. A wave's arena region is
     * immutable until all of its layers have copied their selected weights. */
    const uint32_t request_capacity = ds4_ds_batch_capacity();
    uint32_t first = 0;
    while (first < n_tables) {
        if (g_ds_decode_pipeline.wave_count >=
                DS4_CUDA_HASH_PIPELINE_MAX_LAYERS) {
            fprintf(stderr,
                    "ds4: CUDA decode token-wide plan exceeds the %u-wave metadata limit\n",
                    DS4_CUDA_HASH_PIPELINE_MAX_LAYERS);
            return 0;
        }
        cuda_ds_decode_pipeline_wave &wave =
            g_ds_decode_pipeline.waves[g_ds_decode_pipeline.wave_count];
        wave.first = first;
        while (first + wave.count < n_tables) {
            cuda_ds_decode_pipeline_layer &layer =
                g_ds_decode_pipeline.layers[first + wave.count];
            if (layer.reserved_bytes > g_ds_decode_pipeline.slot_bytes ||
                layer.reserved_requests > request_capacity) {
                fprintf(stderr,
                        "ds4: CUDA decode wide issue cannot fit layer %u: "
                        "needs %.1f MiB/%u requests, wave slot has %.1f MiB/%u "
                        "requests (arena %.1f MiB, transport slots %u); using "
                        "on-demand loads\n",
                        layer.table.layer,
                        (double)layer.reserved_bytes / 1048576.0,
                        layer.reserved_requests,
                        (double)g_ds_decode_pipeline.slot_bytes / 1048576.0,
                        request_capacity,
                        (double)arena_capacity / 1048576.0,
                        transport_capacity);
                return 0;
            }
            if (wave.count != 0 &&
                (layer.reserved_bytes >
                    g_ds_decode_pipeline.slot_bytes - wave.reserved_bytes ||
                 layer.reserved_requests >
                    request_capacity - wave.reserved_requests)) {
                break;
            }
            layer.wave = g_ds_decode_pipeline.wave_count;
            wave.reserved_bytes += layer.reserved_bytes;
            wave.reserved_requests += layer.reserved_requests;
            wave.count++;
        }
        if (wave.count == 0) return 0;
        first += wave.count;
        g_ds_decode_pipeline.wave_count++;
    }
    cuda_ds_prefetch_reset();
    g_ds_decode_pipeline.active = 1;
    g_decode_profile.decode_pipeline_depth = depth;

    static uint32_t announced_requested = UINT32_MAX;
    static uint32_t announced_effective = UINT32_MAX;
    static uint64_t announced_slot_bytes = UINT64_MAX;
    static uint32_t announced_waves = UINT32_MAX;
    if (announced_requested != requested ||
        announced_effective != depth ||
        announced_slot_bytes != g_ds_decode_pipeline.slot_bytes ||
        announced_waves != g_ds_decode_pipeline.wave_count) {
        announced_requested = requested;
        announced_effective = depth;
        announced_slot_bytes = g_ds_decode_pipeline.slot_bytes;
        announced_waves = g_ds_decode_pipeline.wave_count;
        fprintf(stderr,
                "ds4: CUDA decode token-wide DirectStorage stream enabled: "
                "layers=%u waves=%u concurrent_waves=%u requested_depth=%u "
                "wave_slot=%.1f MiB arena=%.1f MiB transport_slots=%u "
                "request_cap=%u token_reserved=%.1f MiB/%u requests destination=%s "
                "(DS4_CUDA_DECODE_PIPELINE_DEPTH=0 disables)\n",
                n_tables,
                g_ds_decode_pipeline.wave_count,
                depth,
                requested,
                (double)g_ds_decode_pipeline.slot_bytes / 1048576.0,
                (double)arena_capacity / 1048576.0,
                transport_capacity,
                request_capacity,
                (double)g_ds_decode_pipeline.token_reserved_bytes / 1048576.0,
                g_ds_decode_pipeline.token_reserved_requests,
                use_gpu_destination ? "GPU" : "host");
        if (g_ds_decode_pipeline.wave_count > depth) {
            fprintf(stderr,
                    "ds4: CUDA decode token-wide issue is capacity-windowed: "
                    "%u waves cannot coexist in %u transport slots / %.1f MiB; "
                    "issuing %u wide waves now and refilling only retired arena "
                    "regions (no silent overwrite)\n",
                    g_ds_decode_pipeline.wave_count,
                    transport_capacity,
                    (double)arena_capacity / 1048576.0,
                    depth);
        }
    }
    return 1;
}

static void cuda_ds_decode_pipeline_note_arrival(
        const void *model_map,
        uint32_t layer,
        const int32_t *selected,
        uint32_t selected_count) {
    if (!g_ds_decode_pipeline.active ||
        g_ds_decode_pipeline.current >= g_ds_decode_pipeline.count) return;
    cuda_ds_decode_pipeline_layer &current =
        g_ds_decode_pipeline.layers[g_ds_decode_pipeline.current];
    if (current.table.model_map != model_map || current.table.layer != layer ||
        current.arrived) return;
    current.arrived = 1;
    cuda_ds_decode_pipeline_wave &wave =
        g_ds_decode_pipeline.waves[current.wave];
    if (wave.drained ||
        (wave.submitted && ds4_ds_batch_oldest_ready() == 1)) {
        current.arrival_resident = 1;
        g_decode_profile.decode_pipeline_arrival_resident++;
    }
    for (uint32_t i = 0; selected && i < selected_count; i++) {
        if (selected[i] < 0 ||
            (uint32_t)selected[i] >= current.table.n_total_expert) continue;
        int duplicate = 0;
        for (uint32_t prior = 0; prior < i; prior++) {
            if (selected[prior] == selected[i]) {
                duplicate = 1;
                break;
            }
        }
        const uint32_t expert = (uint32_t)selected[i];
        if (!duplicate && current.table.expert_tiers &&
            current.table.expert_tiers[expert] ==
                DS4_STREAM_EXPERT_TIER_PREFETCH &&
            cuda_ds_decode_pipeline_layer_owns_expert(&current, expert)) {
            current.used_predicted_experts++;
        }
    }
}

static void cuda_ds_decode_pipeline_advance(uint32_t completed_layer) {
    if (!g_ds_decode_pipeline.active ||
        g_ds_decode_pipeline.current >= g_ds_decode_pipeline.count) return;
    cuda_ds_phase_scope retire_scope(&g_ds_decode_bandwidth.phase_retire_ms);
    cuda_ds_decode_pipeline_layer &completed =
        g_ds_decode_pipeline.layers[g_ds_decode_pipeline.current];
    if (completed.table.layer != completed_layer) return;
    if (completed.predicted_experts > completed.used_predicted_experts) {
        g_decode_profile.decode_pipeline_mispredicted_experts +=
            completed.predicted_experts - completed.used_predicted_experts;
    }
    const uint32_t completed_wave = completed.wave;
    g_ds_decode_pipeline.current++;
    if (g_ds_decode_pipeline.current >= g_ds_decode_pipeline.count) {
        g_ds_decode_pipeline.active = 0;
        g_ds_decode_pipeline.staging_slot = -1;
        cuda_ds_hot_prefetch_retire();
        return;
    }
    const cuda_ds_decode_pipeline_wave &wave =
        g_ds_decode_pipeline.waves[completed_wave];
    if (g_ds_decode_pipeline.current < wave.first + wave.count) {
        return;
    }
    /* Every selected tensor in this wave is now in its compact compute
     * buffer. Only here may its arena region be overwritten by a later wave. */
    cuda_ds_decode_pipeline_slot_reset(wave.slot);
    g_ds_decode_pipeline.current_wave = completed_wave + 1u;
    if (!cuda_ds_decode_pipeline_submit_ahead()) {
        cuda_ds_hot_prefetch_retire();
    }
}

static int cuda_ds_hash_pipeline_capture(
        const ds4_gpu_stream_expert_table *tables,
        uint32_t n_tables,
        const int32_t *exact_selected,
        uint32_t exact_stride) {
    memset(&g_ds_hash_pipeline, 0, sizeof(g_ds_hash_pipeline));
    if (!cuda_ds_hash_layer_pipeline_enabled() ||
        !cuda_ds_gpu_destination_enabled() ||
        !tables || n_tables == 0 || !exact_selected || exact_stride == 0) {
        return 0;
    }

    /* Keep the experiment isolated to exact hash routes.  A configured
     * frequency-tier prefetch has different lifetime semantics, so retain the
     * legacy token-wide batch when it is present. */
    for (uint32_t ti = 0; ti < n_tables; ti++) {
        const ds4_gpu_stream_expert_table *table = &tables[ti];
        for (uint32_t expert = 0; table->expert_tiers &&
                                  expert < table->n_total_expert; expert++) {
            if (table->expert_tiers[expert] == DS4_STREAM_EXPERT_TIER_PREFETCH) {
                static int warned_tiers = 0;
                if (!warned_tiers) {
                    warned_tiers = 1;
                    fprintf(stderr,
                            "ds4: CUDA hash-layer pipeline retained legacy batching because "
                            "frequency-tier prefetch is configured\n");
                }
                return 0;
            }
        }
    }

    for (uint32_t ti = 0; ti < n_tables; ti++) {
        const int32_t *row = exact_selected + (size_t)ti * exact_stride;
        uint32_t valid = 0;
        for (uint32_t si = 0; si < exact_stride; si++) {
            if (row[si] >= 0 && (uint32_t)row[si] < tables[ti].n_total_expert) valid++;
        }
        if (valid == 0) continue;
        if (g_ds_hash_pipeline.count >= DS4_CUDA_HASH_PIPELINE_MAX_LAYERS) return 0;
        const uint32_t dst = g_ds_hash_pipeline.count++;
        g_ds_hash_pipeline.tables[dst] = tables[ti];
        memset(g_ds_hash_pipeline.selected[dst], 0xff,
               sizeof(g_ds_hash_pipeline.selected[dst]));
        const uint32_t copy = exact_stride < DS4_CUDA_HASH_PIPELINE_MAX_SELECTED ?
            exact_stride : DS4_CUDA_HASH_PIPELINE_MAX_SELECTED;
        memcpy(g_ds_hash_pipeline.selected[dst], row,
               (size_t)copy * sizeof(row[0]));
    }
    if (g_ds_hash_pipeline.count == 0) return 0;
    g_ds_hash_pipeline.active = 1;
    static int announced = 0;
    if (!announced) {
        announced = 1;
        atexit(cuda_ds_hash_pipeline_stats_dump);
        fprintf(stderr,
                "ds4: CUDA exact hash-layer DirectStorage pipeline enabled (%u layers)\n",
                g_ds_hash_pipeline.count);
    }
    g_ds_hash_pipeline_stats.tokens++;
    return 1;
}

static void cuda_ds_hash_pipeline_submit_ahead(void) {
    while (g_ds_hash_pipeline.active &&
           g_ds_hash_pipeline.next_submit < g_ds_hash_pipeline.count &&
           ds4_ds_batch_inflight() < ds4_ds_pipeline_depth()) {
        const uint32_t submit = g_ds_hash_pipeline.next_submit++;
        const uint32_t before = ds4_ds_batch_inflight();
        (void)cuda_ds_hot_prefetch_submit(
            &g_ds_hash_pipeline.tables[submit],
            1,
            g_ds_hash_pipeline.selected[submit],
            DS4_CUDA_HASH_PIPELINE_MAX_SELECTED,
            g_ds_hot_prefetch_active ? 1 : 0);
        g_ds_hash_pipeline.submitted[submit] =
            ds4_ds_batch_inflight() > before ? 1u : 0u;
    }
}

static void cuda_ds_hash_pipeline_advance(uint32_t completed_layer) {
    if (!g_ds_hash_pipeline.active ||
        g_ds_hash_pipeline.current >= g_ds_hash_pipeline.count ||
        g_ds_hash_pipeline.tables[g_ds_hash_pipeline.current].layer != completed_layer) {
        return;
    }

    /* Only the oldest FIFO slot was drained. L+1 remains live in the other
     * slot while this layer's compact buffers become compute inputs. Refill
     * the freed slot with L+2 before the caller enqueues this layer's routed
     * and shared expert kernels. The immutable arena holds all three exact
     * layers (the legacy aggregate batch already proved that capacity). */
    g_ds_hash_pipeline.current++;
    g_ds_hash_pipeline.current_drained = 0;
    if (g_ds_hash_pipeline.current >= g_ds_hash_pipeline.count) {
        g_ds_hash_pipeline.active = 0;
        cuda_ds_hot_prefetch_retire();
        return;
    }
    cuda_ds_hash_pipeline_submit_ahead();
}

extern "C" int ds4_gpu_stream_expert_prefetch_token_begin(
        const ds4_gpu_stream_expert_table *tables,
        uint32_t n_tables,
        const int32_t *exact_selected,
        uint32_t exact_stride,
        uint64_t token_index) {
    if (cuda_affinity_token_biased()) {
        g_decode_profile.decode_pipeline_depth=0;
        g_ds_decode_bandwidth.begin(token_index);
        return 1;
    }
    if (!g_ssd_streaming_mode || !tables || n_tables == 0) return 1;
    g_decode_profile.decode_pipeline_depth = 0;
    if (g_ds_hot_prefetch_active || ds4_ds_batch_inflight() != 0 ||
        g_ds_decode_pipeline.active) {
        /* Defensive cleanup after an aborted token: disable the current-wave
         * drain guard so retirement waits every outstanding FIFO slot. */
        g_ds_decode_pipeline.active = 0;
        g_ds_decode_pipeline.staging_slot = -1;
        g_ds_hash_pipeline.active = 0;
        cuda_ds_hot_prefetch_retire();
    }
    g_ds_decode_bandwidth.begin(token_index);
    {
        cuda_ds_phase_scope setup_scope(
            &g_ds_decode_bandwidth.phase_setup_ms);
        if (cuda_ds_decode_pipeline_capture(tables, n_tables,
                                            exact_selected, exact_stride)) {
            if (cuda_ds_decode_pipeline_submit_ahead()) return 1;
            cuda_ds_hot_prefetch_retire();
        }
        if (cuda_ds_hash_pipeline_capture(tables, n_tables,
                                          exact_selected, exact_stride)) {
            cuda_ds_hash_pipeline_submit_ahead();
            return 1;
        }
        return cuda_ds_hot_prefetch_submit(tables, n_tables,
                                           exact_selected, exact_stride, 0);
    }
}

extern "C" void ds4_gpu_stream_expert_prefetch_token_end(void) {
    {
        cuda_ds_phase_scope teardown_scope(
            &g_ds_decode_bandwidth.phase_teardown_ms);
        if (g_ds_decode_pipeline.active) {
            cuda_ds_hot_prefetch_retire();
        }
        g_ds_hash_pipeline.active = 0;
        if (g_ds_hot_prefetch_active || ds4_ds_batch_inflight() != 0 ||
            g_ds_decode_pipeline.active) {
            cuda_ds_hot_prefetch_retire();
        }
    }
    g_ds_decode_bandwidth.end();
}
#endif

#if defined(_WIN32)
static uint64_t cuda_prefill_pipeline_align(uint64_t value) {
    return (value + 255ull) & ~255ull;
}

struct cuda_prefill_pipeline_excluded_range {
    uint64_t begin;
    uint64_t end;
};

static int cuda_prefill_pipeline_append_span(
        cuda_prefill_pipeline_layer *layer,
        uint64_t file_offset,
        uint64_t bytes,
        uint64_t *packed) {
    if (!layer || !packed || bytes == 0 || bytes > UINT32_MAX ||
        *packed > UINT64_MAX - cuda_prefill_pipeline_align(bytes)) {
        return 0;
    }
    layer->model_spans.push_back({
        file_offset, (uint32_t)bytes, 0, *packed
    });
    const uint64_t request_cap = 64ull * 1024ull * 1024ull;
    for (uint64_t done = 0; done < bytes; done += request_cap) {
        const uint64_t chunk =
            bytes - done < request_cap ? bytes - done : request_cap;
        layer->spans.push_back({
            file_offset + done, (uint32_t)chunk, 0, *packed + done
        });
    }
    *packed += cuda_prefill_pipeline_align(bytes);
    return 1;
}

/* Build the layer wave while retaining only experts [0,resident_experts) in
 * the slot. Non-expert tensors remain fully resident. The full-count case
 * takes the same spans and packing as the original R4 path. */
static int cuda_prefill_pipeline_build_layer_spans(
        const ds4_gpu_prefill_layer_plan &plan,
        uint32_t resident_experts,
        cuda_prefill_pipeline_layer *layer) {
    if (!layer || resident_experts > plan.table.n_total_expert) return 0;
    layer->spans.clear();
    layer->model_spans.clear();

    const uint64_t gate_full =
        (uint64_t)plan.table.n_total_expert * plan.table.gate_expert_bytes;
    const uint64_t down_full =
        (uint64_t)plan.table.n_total_expert * plan.table.down_expert_bytes;
    if (plan.table.gate_offset > plan.table.model_size ||
        plan.table.up_offset > plan.table.model_size ||
        plan.table.down_offset > plan.table.model_size ||
        gate_full > plan.table.model_size - plan.table.gate_offset ||
        gate_full > plan.table.model_size - plan.table.up_offset ||
        down_full > plan.table.model_size - plan.table.down_offset) {
        return 0;
    }

    cuda_prefill_pipeline_excluded_range excluded[3];
    uint32_t excluded_count = 0;
    if (resident_experts < plan.table.n_total_expert) {
        const uint64_t gate_keep =
            (uint64_t)resident_experts * plan.table.gate_expert_bytes;
        const uint64_t down_keep =
            (uint64_t)resident_experts * plan.table.down_expert_bytes;
        excluded[excluded_count++] = {
            plan.table.gate_offset + gate_keep,
            plan.table.gate_offset + gate_full
        };
        excluded[excluded_count++] = {
            plan.table.up_offset + gate_keep,
            plan.table.up_offset + gate_full
        };
        excluded[excluded_count++] = {
            plan.table.down_offset + down_keep,
            plan.table.down_offset + down_full
        };
        for (uint32_t i = 1; i < excluded_count; i++) {
            const cuda_prefill_pipeline_excluded_range value = excluded[i];
            uint32_t j = i;
            while (j != 0 && excluded[j - 1u].begin > value.begin) {
                excluded[j] = excluded[j - 1u];
                j--;
            }
            excluded[j] = value;
        }
    }

    uint64_t packed = 0;
    for (uint32_t s = 0; s < plan.span_count; s++) {
        const uint64_t begin = plan.span_offsets[s];
        const uint64_t bytes = plan.span_sizes[s];
        if (bytes == 0 || bytes > UINT32_MAX || begin > plan.table.model_size ||
            bytes > plan.table.model_size - begin) {
            return 0;
        }
        const uint64_t end = begin + bytes;
        uint64_t cursor = begin;
        for (uint32_t r = 0; r < excluded_count && cursor < end; r++) {
            if (excluded[r].end <= cursor || excluded[r].begin >= end) continue;
            const uint64_t keep_end =
                excluded[r].begin < end ? excluded[r].begin : end;
            if (keep_end > cursor &&
                !cuda_prefill_pipeline_append_span(
                    layer, cursor, keep_end - cursor, &packed)) {
                return 0;
            }
            if (excluded[r].end > cursor) cursor = excluded[r].end;
            if (cursor > end) cursor = end;
        }
        if (cursor < end &&
            !cuda_prefill_pipeline_append_span(
                layer, cursor, end - cursor, &packed)) {
            return 0;
        }
    }
    layer->packed_bytes = packed;
    layer->resident_expert_count = resident_experts;
    return packed != 0;
}

enum {
    CUDA_PREFILL_TRACE_WAIT_SATISFIED = 1u,
    CUDA_PREFILL_TRACE_COMPUTE_START = 2u,
    CUDA_PREFILL_TRACE_COMPUTE_DONE = 3u,
};

static uint64_t cuda_prefill_pipeline_trace_now_us(void) {
    using namespace std::chrono;
    return (uint64_t)duration_cast<microseconds>(
        steady_clock::now().time_since_epoch()).count();
}

static void cuda_prefill_pipeline_trace_emit(
        const char *phase,
        uint32_t layer,
        uint32_t slot,
        uint64_t fence_waited,
        uint64_t fence_signalled,
        uint32_t previous_layer,
        uint64_t spin_count,
        uint64_t spin_us) {
    if (!g_prefill_pipeline.trace_enabled) return;
    std::lock_guard<std::mutex> lock(g_prefill_pipeline_trace_mutex);
    const uint64_t seq = g_prefill_pipeline_trace_seq.fetch_add(1) + 1;
    const uint64_t now_us = cuda_prefill_pipeline_trace_now_us();
    const uint64_t elapsed_us = now_us >= g_prefill_pipeline.trace_epoch_us ?
        now_us - g_prefill_pipeline.trace_epoch_us : 0;
    fprintf(stderr,
            "ds4: R4 runtime seq=%llu us=%llu phase=%s layer=%u slot=%u "
            "fence_waited=%llu fence_signalled=%llu previous=%u "
            "spun=%u spin_count=%llu spin_us=%llu\n",
            (unsigned long long)seq,
            (unsigned long long)elapsed_us,
            phase, layer, slot,
            (unsigned long long)fence_waited,
            (unsigned long long)fence_signalled,
            previous_layer,
            spin_count != 0 ? 1u : 0u,
            (unsigned long long)spin_count,
            (unsigned long long)spin_us);
}

static void CUDART_CB cuda_prefill_pipeline_trace_callback(void *user_data) {
    const cuda_prefill_pipeline_trace_point *point =
        (const cuda_prefill_pipeline_trace_point *)user_data;
    const char *phase = point->phase == CUDA_PREFILL_TRACE_WAIT_SATISFIED ?
        "wait_satisfied" :
        point->phase == CUDA_PREFILL_TRACE_COMPUTE_START ?
            "compute_start" : "compute_done";
    cuda_prefill_pipeline_trace_emit(
        phase, point->layer, point->slot,
        point->phase == CUDA_PREFILL_TRACE_COMPUTE_DONE ? 0 : point->fence_value,
        point->phase == CUDA_PREFILL_TRACE_COMPUTE_DONE ? point->fence_value : 0,
        g_prefill_pipeline.layers[point->layer].previous_layer,
        0, 0);
}

static void cuda_prefill_pipeline_worker(void) {
    (void)cudaSetDevice(g_prefill_pipeline.device);
    for (;;) {
        uint32_t layer = UINT32_MAX;
        {
            std::unique_lock<std::mutex> lock(g_prefill_pipeline.mutex);
            g_prefill_pipeline.cv.wait(lock, [] {
                if (g_prefill_pipeline.stop) return true;
                for (uint32_t i = 0; i < g_prefill_pipeline.n_layers; i++) {
                    if (g_prefill_pipeline.requested[i] &&
                        !g_prefill_pipeline.submitted[i]) return true;
                }
                return false;
            });
            if (g_prefill_pipeline.stop) break;
            for (uint32_t i = 0; i < g_prefill_pipeline.n_layers; i++) {
                if (g_prefill_pipeline.requested[i] &&
                    !g_prefill_pipeline.submitted[i]) {
                    layer = i;
                    break;
                }
            }
        }
        if (layer == UINT32_MAX) continue;
        cuda_prefill_pipeline_layer &plan =
            g_prefill_pipeline.layers[layer];
        const uint32_t slot_index = plan.slot;
        uint64_t spin_count = 0;
        const uint64_t spin_t0 = cuda_prefill_pipeline_trace_now_us();
        if (plan.previous_layer != UINT32_MAX) {
            const cuda_prefill_pipeline_layer &previous =
                g_prefill_pipeline.layers[plan.previous_layer];
            cudaError_t query;
            do {
                query = cudaEventQuery(previous.compute_done);
                if (query == cudaErrorNotReady) {
                    spin_count++;
                    std::this_thread::sleep_for(std::chrono::microseconds(100));
                }
            } while (query == cudaErrorNotReady && !g_prefill_pipeline.stop);
            if (query != cudaSuccess) {
                fprintf(stderr,
                        "ds4: CUDA R4 slot %u compute_done query failed: %s\n",
                        slot_index, cudaGetErrorString(query));
                std::lock_guard<std::mutex> lock(g_prefill_pipeline.mutex);
                g_prefill_pipeline.failed = 1;
                g_prefill_pipeline.cv.notify_all();
                break;
            }
        }
        const uint64_t spin_t1 = cuda_prefill_pipeline_trace_now_us();
        cuda_prefill_pipeline_trace_emit(
            "slot_ready", layer, slot_index, 0, 0, plan.previous_layer,
            spin_count, spin_count != 0 ? spin_t1 - spin_t0 : 0);
        uint64_t fence_value = 0;
        const int ok = ds4_ds_prefill_wave_submit(layer, &fence_value);
        if (ok) {
            cuda_prefill_pipeline_trace_emit(
                "wave_submit", layer, slot_index, 0, fence_value,
                plan.previous_layer, spin_count,
                spin_count != 0 ? spin_t1 - spin_t0 : 0);
        }
        {
            std::lock_guard<std::mutex> lock(g_prefill_pipeline.mutex);
            if (!ok) g_prefill_pipeline.failed = 1;
            plan.fence_value = fence_value;
            g_prefill_pipeline.submitted[layer] = 1;
            g_prefill_pipeline.cv.notify_all();
        }
        if (!ok) break;
    }
}

/* R4 teardown and the host-cache refill share the same release ordering, but
 * they are different lifecycle events. Ordinary pipeline teardown passes 0;
 * only the real prefill-to-decode phase edge passes 1, after the caller has
 * released graph prefill scratch. The cleanup below is intentionally
 * idempotent for the exceptional case where a pipeline is still active. */
static void cuda_prefill_pipeline_release_internal(int refill_host_decode_edge) {
    g_prefill_pipeline_resident_spans = 0;
    g_prefill_pipeline_partial_resident_spans = 0;
    g_prefill_pipeline_host_cache_charge_bytes = 0;
    const int latch_release_enabled =
        cuda_stream_host_expert_cache_latch_release_enabled();
    /* Value-based A/B switch (an explicit zero disables), unlike the
     * presence-based prefill-pipeline flag.
     *
     * Free-first growth is default-on. Each undersized class is released, then
     * GlobalMemoryStatusEx is sampled and the replacement target is physically
     * clamped. The check is repeated after each refill so a later class sees
     * physical memory consumed by an earlier one. If measurement or allocation
     * fails, the old capacity is rebuilt empty and the failure is reported.
     *
     * The earlier pipeline-teardown placement measured a throughput null on
     * the 2026-08-20 90 GB configuration and mechanically grew class 0, but it
     * did not run at the shipped graph-workspace release edge. That evidence
     * does not measure this corrected placement or the active-class budget
     * redistribution. This work-order path remains default-on and requires the
     * deferred fp165g build/acceptance pass. */
    const int decode_refill_enabled =
        cuda_env_flag_enabled("DS4_CUDA_HOST_CACHE_DECODE_REFILL", 1);
    int refill_pending[DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES] = {};
    uint32_t refill_old_cap[DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES] = {};
    uint32_t refill_target_cap[DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES] = {};
    uint32_t active_classes = 0;
    if (refill_host_decode_edge) {
        for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
            if (g_stream_host_expert_runtime_cap[i] != 0 &&
                g_stream_host_expert_class_bytes[i] != 0) {
                active_classes++;
            }
        }
    }
    if (active_classes == 0) {
        active_classes = DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES;
    }
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        if (!refill_host_decode_edge) continue;
        const uint32_t old_cap = g_stream_host_expert_runtime_cap[i];
        if (old_cap == 0) continue;
        cuda_stream_host_expert_cache *cache =
            &g_stream_host_expert_caches[i];
        const uint64_t allocated_before =
            cuda_stream_host_expert_cache_allocated_bytes(cache);
        const uint64_t expert_bytes = cache->valid ?
            cuda_stream_expert_cache_expert_bytes(
                cache->gate_expert_bytes, cache->down_expert_bytes) :
            (g_stream_host_expert_class_bytes[i] / old_cap);
        if (!latch_release_enabled) {
            fprintf(stderr,
                    "ds4: CUDA RAM host cache budget latch release disabled "
                    "class=%u; retained %u experts / %.2f GiB preserved=%u "
                    "[DS4_HOST_CACHE_BUDGET_LATCH_V1]\n",
                    i,
                    old_cap,
                    (double)((uint64_t)old_cap * expert_bytes) / 1073741824.0,
                    cache->valid ? cache->count : 0);
            const uint32_t target_cap =
                g_stream_host_expert_cap_was_budget_derived[i] ?
                    cuda_stream_host_expert_cache_budget_cap_for_classes(
                        expert_bytes, 0, active_classes) :
                    old_cap;
            cuda_stream_host_expert_cache_report_decode_refill(
                i,
                active_classes,
                g_stream_host_expert_cap_was_budget_derived[i],
                decode_refill_enabled,
                0,
                old_cap,
                old_cap,
                target_cap,
                target_cap,
                0,
                0,
                0,
                0,
                allocated_before,
                allocated_before,
                cuda_stream_host_expert_cache_total_allocated_bytes(),
                0,
                0,
                0,
                "latch-release-disabled");
            continue;
        }
        if (g_stream_host_expert_cap_was_budget_derived[i]) {
            /* Prefill has now observed every model shape. Redistribute the
             * aggregate NGB request over the classes that actually exist,
             * rather than permanently reserving half for an absent class. */
            const uint32_t decode_cap =
                cuda_stream_host_expert_cache_budget_cap_for_classes(
                    expert_bytes, 0, active_classes);
            const uint32_t cached_before = cache->valid ? cache->count : 0;
            g_stream_host_expert_runtime_cap[i] = 0;
            g_stream_host_expert_cap_was_budget_derived[i] = 0;
            fprintf(stderr,
                    "ds4: CUDA RAM host cache budget latch released class=%u "
                    "%u -> %u experts (%.2f -> %.2f GiB) preserved=%u "
                    "[DS4_HOST_CACHE_BUDGET_LATCH_V1]\n",
                    i,
                    old_cap,
                    decode_cap,
                    (double)((uint64_t)old_cap * expert_bytes) / 1073741824.0,
                    (double)((uint64_t)decode_cap * expert_bytes) / 1073741824.0,
                    cached_before);
            /* Queue the free-first replacement after the idempotent R4 cleanup
             * below. On the normal path that cleanup already ran at prefill
             * finish and the outer graph scratch was released before this
             * decode-edge entry. */
            refill_pending[i] = 1;
            refill_old_cap[i] = old_cap;
            refill_target_cap[i] = decode_cap;
        } else {
            fprintf(stderr,
                    "ds4: CUDA RAM host cache budget class=%u latch retained "
                    "(physically bounded) %u experts / %.2f GiB preserved=%u "
                    "[DS4_HOST_CACHE_BUDGET_LATCH_V1]\n",
                    i,
                    old_cap,
                    (double)((uint64_t)old_cap * expert_bytes) / 1073741824.0,
                    cache->valid ? cache->count : 0);
            cuda_stream_host_expert_cache_report_decode_refill(
                i,
                active_classes,
                0,
                decode_refill_enabled,
                0,
                old_cap,
                old_cap,
                old_cap,
                old_cap,
                0,
                0,
                0,
                0,
                allocated_before,
                allocated_before,
                cuda_stream_host_expert_cache_total_allocated_bytes(),
                0,
                0,
                0,
                "physically-bounded");
        }
    }
    if (g_prefill_pipeline.worker.joinable()) {
        {
            std::lock_guard<std::mutex> lock(g_prefill_pipeline.mutex);
            g_prefill_pipeline.stop = 1;
            g_prefill_pipeline.cv.notify_all();
        }
        g_prefill_pipeline.worker.join();
    }
    for (cuda_prefill_pipeline_layer &layer : g_prefill_pipeline.layers) {
        if (layer.compute_done) (void)cudaEventDestroy(layer.compute_done);
        layer.compute_done = NULL;
    }
    for (uint32_t i = 0; i < DS4_CUDA_PREFILL_PIPELINE_SLOTS; i++) {
        g_prefill_pipeline.slots[i] = {};
    }
    ds4_ds_prefill_waves_release();
    if (g_prefill_pipeline.arena) {
        cuda_model_range_release_all();
        ds4_ds_prefill_arenas_release();
    }
    for (uint32_t i = 0; i < DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES; i++) {
        if (!refill_pending[i]) continue;
        cuda_stream_host_expert_cache *cache =
            &g_stream_host_expert_caches[i];
        const uint32_t old_cap = refill_old_cap[i];
        const uint32_t decode_cap = refill_target_cap[i];
        const uint32_t cached_before = cache->valid ? cache->count : 0;
        const uint64_t allocated_before =
            cuda_stream_host_expert_cache_allocated_bytes(cache);
        int attempted = 0;
        int realloc_succeeded = 0;
        int fallback_taken = 0;
        uint32_t cap_after = cache->valid ? cache->capacity : 0;
        uint32_t selected_cap = decode_cap;
        uint32_t experts_discarded = 0;
        uint64_t transient_peak_bytes =
            cuda_stream_host_expert_cache_total_allocated_bytes();
        cuda_stream_host_expert_cache_decode_feasibility feasibility = {};
        const char *status = "disabled";
        if (decode_refill_enabled &&
            cache->valid &&
            cache->capacity >= decode_cap) {
            status = "already-sized";
        } else if (decode_refill_enabled) {
            attempted = 1;
            const char *failure_reason = NULL;
            const cuda_stream_host_expert_cache_decode_refill_result result =
                cuda_stream_host_expert_cache_decode_refill(
                    i, decode_cap, &feasibility, &selected_cap,
                    &failure_reason, &transient_peak_bytes);
            if (result == DS4_HOST_CACHE_DECODE_REFILL_SUCCEEDED) {
                    cap_after = cache->capacity;
                    g_stream_host_expert_runtime_cap[i] = cap_after;
                    g_stream_host_expert_cap_was_budget_derived[i] = 0;
                    realloc_succeeded = 1;
                    experts_discarded = cached_before;
                    status = "refilled";
                    fprintf(stderr,
                            "ds4: CUDA decode edge RAM expert cache class %u "
                            "re-allocated %u -> %u experts / %.2f -> %.2f GiB "
                            "after discarding %u cached experts "
                            "[DS4_HOST_CACHE_DECODE_REFILL_V1]\n",
                            i,
                            old_cap,
                            cap_after,
                            (double)allocated_before / 1073741824.0,
                            (double)cuda_stream_host_expert_cache_allocated_bytes(cache) /
                                1073741824.0,
                            experts_discarded);
                } else if (result ==
                           DS4_HOST_CACHE_DECODE_REFILL_REBUILT_OLD_CAP) {
                    cap_after = cache->capacity;
                    experts_discarded = cached_before;
                    fallback_taken = 1;
                    status = "fallback-rebuilt-empty";
                    fprintf(stderr,
                            "ds4: CUDA RAM host cache decode refill failed "
                            "class=%u selected=%u requested=%u experts; "
                            "rebuilt empty at old capacity %u experts / %llu "
                            "allocated bytes after discarding %u cached "
                            "experts (%s) [DS4_HOST_CACHE_DECODE_REFILL_V1]\n",
                            i,
                            selected_cap,
                            decode_cap,
                            cap_after,
                            (unsigned long long)
                                cuda_stream_host_expert_cache_allocated_bytes(cache),
                            cached_before,
                            failure_reason ? failure_reason : "unknown failure");
                } else if (result ==
                           DS4_HOST_CACHE_DECODE_REFILL_EMERGENCY_INVALID) {
                    cap_after = 0;
                    experts_discarded = cached_before;
                    fallback_taken = 1;
                    status = "emergency-invalid";
                    fprintf(stderr,
                            "ds4: EMERGENCY: CUDA RAM host cache decode refill "
                            "class=%u could allocate neither selected=%u "
                            "(requested=%u) nor old=%u experts; class is "
                            "INVALID with zero allocated bytes after "
                            "discarding %u cached experts (%s) "
                            "[DS4_HOST_CACHE_DECODE_REFILL_V1]\n",
                            i,
                            selected_cap,
                            decode_cap,
                            old_cap,
                            cached_before,
                            failure_reason ? failure_reason : "unknown failure");
                } else {
                    cap_after =
                        cache->valid && cache->capacity != 0 ?
                            cache->capacity : old_cap;
                    g_stream_host_expert_runtime_cap[i] = cap_after;
                    status = "fallback-retained";
                    fprintf(stderr,
                            "ds4: CUDA RAM host cache decode refill failed "
                            "class=%u selected=%u requested=%u experts; "
                            "retained existing %u-expert cache / %llu "
                            "allocated bytes with %u cached experts (%s) "
                            "[DS4_HOST_CACHE_DECODE_REFILL_V1]\n",
                            i,
                            selected_cap,
                            decode_cap,
                            cap_after,
                            (unsigned long long)allocated_before,
                            cached_before,
                            failure_reason ? failure_reason : "unknown failure");
            }
        }
        cuda_stream_host_expert_cache_report_decode_refill(
            i,
            active_classes,
            1,
            decode_refill_enabled,
            attempted,
            old_cap,
            cap_after,
            decode_cap,
            selected_cap,
            feasibility.measured,
            feasibility.available_bytes,
            feasibility.reserve_bytes,
            feasibility.other_class_bytes,
            allocated_before,
            cuda_stream_host_expert_cache_allocated_bytes(cache),
            transient_peak_bytes,
            experts_discarded,
            realloc_succeeded,
            fallback_taken,
            status);
    }
    g_prefill_pipeline.layers.clear();
    g_prefill_pipeline.requested.clear();
    g_prefill_pipeline.submitted.clear();
    g_prefill_pipeline.active = 0;
    g_prefill_pipeline.failed = 0;
    g_prefill_pipeline.stop = 0;
    g_prefill_pipeline.n_layers = 0;
    g_prefill_pipeline.arena = NULL;
    g_prefill_pipeline.arena_bytes = 0;
    g_prefill_pipeline.trace_enabled = 0;
    g_prefill_pipeline.trace_epoch_us = 0;
    g_q8_cache_suppressed = g_prefill_pipeline.saved_q8_cache_suppressed;
    g_prefill_pipeline.saved_q8_cache_suppressed = 0;
}

static void cuda_prefill_pipeline_release(void) {
    cuda_prefill_pipeline_release_internal(0);
}

static void cuda_stream_host_expert_cache_decode_edge_refill(void) {
    cuda_prefill_pipeline_release_internal(1);
}

extern "C" int ds4_gpu_prefill_pipeline_begin(
        const ds4_gpu_prefill_layer_plan *plans,
        uint32_t                          n_layers,
        uint64_t                          configured_kv_bytes) {
    if (!g_ssd_streaming_mode || !plans ||
        n_layers < DS4_CUDA_PREFILL_PIPELINE_SLOTS ||
        getenv("DS4_CUDA_DS_GPU_DEST") == NULL ||
        getenv("DS4_CUDA_DISABLE_PREFILL_PIPELINE") != NULL) return 0;
    if (g_prefill_pipeline.active) cuda_prefill_pipeline_release();
    if (!ds4_ds_available() &&
        (g_model_fd < 0 || !ds4_ds_init_from_fd(g_model_fd))) return 0;

    cuda_stream_selected_cache_release();
    cuda_model_range_release_all();
    cuda_q8_f16_cache_release_all();
    for (const cuda_q8_f32_range &r : g_q8_f32_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f32_ranges.clear();
    g_q8_f32_by_offset.clear();
    g_q8_f32_bytes = 0;
    g_prefill_pipeline.saved_q8_cache_suppressed = g_q8_cache_suppressed;
    g_q8_cache_suppressed = 1;
    g_prefill_pipeline.layers.resize(n_layers);
    g_prefill_pipeline.requested.assign(n_layers, 0);
    g_prefill_pipeline.submitted.assign(n_layers, 0);
    g_prefill_pipeline.n_layers = n_layers;
    uint64_t slot_capacity[DS4_CUDA_PREFILL_PIPELINE_SLOTS] = {};
    uint32_t min_total_experts = UINT32_MAX;
    for (uint32_t i = 0; i < n_layers; i++) {
        const ds4_gpu_prefill_layer_plan &plan = plans[i];
        const ds4_gpu_stream_expert_table &table = plan.table;
        if (!table.model_map || table.n_total_expert == 0 ||
            table.gate_expert_bytes == 0 || table.down_expert_bytes == 0 ||
            !plan.span_offsets || !plan.span_sizes || plan.span_count == 0 ||
            (uint64_t)table.n_total_expert > UINT64_MAX / table.gate_expert_bytes ||
            (uint64_t)table.n_total_expert > UINT64_MAX / table.down_expert_bytes) {
            cuda_prefill_pipeline_release();
            return 0;
        }
        if (table.n_total_expert < min_total_experts) {
            min_total_experts = table.n_total_expert;
        }
        cuda_prefill_pipeline_layer &dst = g_prefill_pipeline.layers[i];
        dst.table = table;
        dst.fence_value = 0;
        dst.compute_done = NULL;
        dst.previous_layer = UINT32_MAX;
        dst.next_layer = UINT32_MAX;
        if (!cuda_prefill_pipeline_build_layer_spans(
                plan, table.n_total_expert, &dst)) {
            cuda_prefill_pipeline_release();
            return 0;
        }
    }
    uint32_t previous_by_slot[DS4_CUDA_PREFILL_PIPELINE_SLOTS];
    uint32_t first_by_slot[DS4_CUDA_PREFILL_PIPELINE_SLOTS];
    for (uint32_t slot = 0; slot < DS4_CUDA_PREFILL_PIPELINE_SLOTS; slot++) {
        previous_by_slot[slot] = UINT32_MAX;
        first_by_slot[slot] = UINT32_MAX;
    }
    /* Loading layer N+1 while layer N computes requires distinct backing
     * resources. Keep consecutive layers on different slots even when their
     * expert geometries match; each slot grows to its largest assigned layer. */
    for (uint32_t i = 0; i < n_layers; i++) {
        cuda_prefill_pipeline_layer &layer = g_prefill_pipeline.layers[i];
        const uint32_t slot = i % DS4_CUDA_PREFILL_PIPELINE_SLOTS;
        assert(i == 0 ||
               slot != g_prefill_pipeline.layers[i - 1u].slot);
        layer.slot = slot;
        if (first_by_slot[slot] == UINT32_MAX) first_by_slot[slot] = i;
        if (previous_by_slot[slot] != UINT32_MAX) {
            layer.previous_layer = previous_by_slot[slot];
            g_prefill_pipeline.layers[previous_by_slot[slot]].next_layer = i;
        }
        previous_by_slot[slot] = i;
        for (ds4_ds_wave_span &span : layer.model_spans) {
            span.arena_slot = slot;
        }
        for (ds4_ds_wave_span &span : layer.spans) {
            span.arena_slot = slot;
        }
        if (layer.packed_bytes > slot_capacity[slot]) {
            slot_capacity[slot] = layer.packed_bytes;
        }
    }
    for (uint32_t slot = 0; slot < DS4_CUDA_PREFILL_PIPELINE_SLOTS; slot++) {
        if (slot_capacity[slot] == 0 || first_by_slot[slot] == UINT32_MAX) {
            cuda_prefill_pipeline_release();
            return 0;
        }
    }
    auto rebuild_resident_prefix = [&](uint32_t resident_experts,
                                       uint64_t *capacities) -> int {
        memset(capacities, 0,
               sizeof(uint64_t) * DS4_CUDA_PREFILL_PIPELINE_SLOTS);
        for (uint32_t i = 0; i < n_layers; i++) {
            cuda_prefill_pipeline_layer &layer = g_prefill_pipeline.layers[i];
            const uint32_t keep = resident_experts < layer.table.n_total_expert ?
                resident_experts : layer.table.n_total_expert;
            if (!cuda_prefill_pipeline_build_layer_spans(
                    plans[i], keep, &layer)) {
                return 0;
            }
            for (ds4_ds_wave_span &span : layer.model_spans) {
                span.arena_slot = layer.slot;
            }
            for (ds4_ds_wave_span &span : layer.spans) {
                span.arena_slot = layer.slot;
            }
            if (layer.packed_bytes > capacities[layer.slot]) {
                capacities[layer.slot] = layer.packed_bytes;
            }
        }
        return 1;
    };
    auto sum_slot_capacities = [](const uint64_t *capacities,
                                  uint64_t *total) -> int {
        uint64_t sum = 0;
        for (uint32_t slot = 0; slot < DS4_CUDA_PREFILL_PIPELINE_SLOTS; slot++) {
            if (sum > UINT64_MAX - capacities[slot]) return 0;
            sum += capacities[slot];
        }
        *total = sum;
        return 1;
    };
    uint64_t full_arena_bytes = 0;
    if (!sum_slot_capacities(slot_capacity, &full_arena_bytes)) {
        cuda_prefill_pipeline_release();
        return 0;
    }
    if (g_stream_host_expert_budget_bytes_override != 0 &&
        configured_kv_bytes <=
            g_stream_host_expert_budget_bytes_override &&
        DS4_CUDA_PREFILL_MIN_HOST_CACHE_BYTES <=
            g_stream_host_expert_budget_bytes_override - configured_kv_bytes) {
        const uint64_t max_arena_bytes =
            g_stream_host_expert_budget_bytes_override - configured_kv_bytes -
            DS4_CUDA_PREFILL_MIN_HOST_CACHE_BYTES;
        if (full_arena_bytes > max_arena_bytes && min_total_experts > 1u) {
            uint32_t low = 1u;
            uint32_t high = min_total_experts - 1u;
            uint32_t best = 0;
            while (low <= high) {
                const uint32_t mid = low + (high - low) / 2u;
                uint64_t trial_capacity[DS4_CUDA_PREFILL_PIPELINE_SLOTS] = {};
                uint64_t trial_bytes = 0;
                if (!rebuild_resident_prefix(mid, trial_capacity) ||
                    !sum_slot_capacities(trial_capacity, &trial_bytes)) {
                    cuda_prefill_pipeline_release();
                    return 0;
                }
                if (trial_bytes <= max_arena_bytes) {
                    best = mid;
                    low = mid + 1u;
                } else {
                    high = mid - 1u;
                }
            }
            if (best != 0) {
                if (!rebuild_resident_prefix(best, slot_capacity)) {
                    cuda_prefill_pipeline_release();
                    return 0;
                }
                g_prefill_pipeline_partial_resident_spans = 1;
                fprintf(stderr,
                        "ds4: R4 adaptive expert residency: %u/%u experts per "
                        "large-class layer resident; selected tail uses "
                        "synchronous fallback [DS4_R4_ADAPTIVE_EXPERT_RESIDENCY]\n",
                        best, min_total_experts);
            } else if (!rebuild_resident_prefix(
                           min_total_experts, slot_capacity)) {
                cuda_prefill_pipeline_release();
                return 0;
            }
        }
    }
    uint64_t arena_bytes = 0;
    for (uint32_t i = 0; i < DS4_CUDA_PREFILL_PIPELINE_SLOTS; i++) {
        g_prefill_pipeline.slots[i].arena_offset = arena_bytes;
        g_prefill_pipeline.slots[i].capacity = slot_capacity[i];
        if (arena_bytes > UINT64_MAX - slot_capacity[i]) {
            cuda_prefill_pipeline_release();
            return 0;
        }
        arena_bytes += slot_capacity[i];
    }
    uint64_t host_cache_charge = arena_bytes;
    if (configured_kv_bytes > UINT64_MAX - host_cache_charge) {
        cuda_prefill_pipeline_release();
        return 0;
    }
    host_cache_charge += configured_kv_bytes;
    if (g_stream_host_expert_budget_bytes_override != 0) {
        /* Preserve the workable aggregate cache floor after the arena and
         * full-context KV charge, otherwise retain the host cache budget and
         * fall back before allocating or activating any pipeline resources. */
        const uint64_t remaining_cache_bytes =
            g_stream_host_expert_budget_bytes_override > host_cache_charge ?
                g_stream_host_expert_budget_bytes_override - host_cache_charge : 0;
        if (remaining_cache_bytes <
                DS4_CUDA_PREFILL_MIN_HOST_CACHE_BYTES) {
            fprintf(stderr,
                    "ds4: R4 PREFILL PIPELINE DISABLED: joint arena/cache "
                    "budget leaves %.2f GiB host expert cache (request %.2f "
                    "GiB - arena %.2f GiB - configured KV %.2f GiB), below "
                    "the %.2f GiB safety floor (%.2f GiB/class); falling back "
                    "to serial prefill\n",
                    (double)remaining_cache_bytes / 1073741824.0,
                    (double)g_stream_host_expert_budget_bytes_override /
                        1073741824.0,
                    (double)arena_bytes / 1073741824.0,
                    (double)configured_kv_bytes / 1073741824.0,
                    (double)DS4_CUDA_PREFILL_MIN_HOST_CACHE_BYTES /
                        1073741824.0,
                    (double)(DS4_CUDA_PREFILL_MIN_HOST_CACHE_BYTES /
                             DS4_CUDA_STREAM_EXPERT_CACHE_CLASSES) /
                        1073741824.0);
            cuda_prefill_pipeline_release();
            return 0;
        }
        g_prefill_pipeline_host_cache_charge_bytes = host_cache_charge;
        fprintf(stderr,
                "ds4: R4 joint arena/cache budget: host request %.2f GiB - "
                "arena %.2f GiB - configured KV %.2f GiB = %.2f GiB cache\n",
                (double)g_stream_host_expert_budget_bytes_override / 1073741824.0,
                (double)arena_bytes / 1073741824.0,
                (double)configured_kv_bytes / 1073741824.0,
                (double)(g_stream_host_expert_budget_bytes_override -
                         host_cache_charge) / 1073741824.0);
    }
    void *arena_ptrs[DS4_CUDA_PREFILL_PIPELINE_SLOTS] = {};
    if (!ds4_ds_prefill_arenas_create(
            slot_capacity, DS4_CUDA_PREFILL_PIPELINE_SLOTS, arena_ptrs) ||
        !ds4_ds_prefill_waves_create(n_layers)) {
        cuda_prefill_pipeline_release();
        return 0;
    }
    g_prefill_pipeline.arena = (char *)arena_ptrs[0];
    g_prefill_pipeline.arena_bytes = arena_bytes;
    for (uint32_t slot = 0; slot < DS4_CUDA_PREFILL_PIPELINE_SLOTS; slot++) {
        g_prefill_pipeline.slots[slot].ptr = (char *)arena_ptrs[slot];
    }
    for (uint32_t i = 0; i < n_layers; i++) {
        cuda_prefill_pipeline_layer &layer = g_prefill_pipeline.layers[i];
        const uint32_t slot = layer.slot;
        char *slot_ptr = g_prefill_pipeline.slots[slot].ptr;
        for (size_t s = 0; s < layer.model_spans.size(); s++) {
            g_model_ranges.push_back({
                layer.table.model_map,
                layer.model_spans[s].file_offset,
                layer.model_spans[s].bytes,
                slot_ptr + layer.model_spans[s].arena_offset,
                NULL, NULL, 0, 0, 1, 0, 1
            });
            g_model_range_by_offset[layer.model_spans[s].file_offset] =
                g_model_ranges.size() - 1u;
            g_model_range_bytes += layer.model_spans[s].bytes;
        }
        const uint64_t resident_gate_bytes =
            (uint64_t)layer.resident_expert_count *
            layer.table.gate_expert_bytes;
        const uint64_t resident_down_bytes =
            (uint64_t)layer.resident_expert_count *
            layer.table.down_expert_bytes;
        const char *gate_ptr = cuda_model_range_ptr(
            layer.table.model_map, layer.table.gate_offset,
            resident_gate_bytes, "R4 gate table");
        const char *up_ptr = cuda_model_range_ptr(
            layer.table.model_map, layer.table.up_offset,
            resident_gate_bytes, "R4 up table");
        const char *down_ptr = cuda_model_range_ptr(
            layer.table.model_map, layer.table.down_offset,
            resident_down_bytes, "R4 down table");
        if (!gate_ptr || !up_ptr || !down_ptr) {
            cuda_prefill_pipeline_release();
            return 0;
        }
        layer.gate_arena_offset = (uint64_t)(gate_ptr - slot_ptr);
        layer.up_arena_offset = (uint64_t)(up_ptr - slot_ptr);
        layer.down_arena_offset = (uint64_t)(down_ptr - slot_ptr);
        if (!ds4_ds_prefill_wave_build(
                i, layer.spans.data(), (uint32_t)layer.spans.size())) {
            cuda_prefill_pipeline_release();
            return 0;
        }
    }
    for (uint32_t i = 0; i < n_layers; i++) {
        if (!cuda_ok(cudaEventCreateWithFlags(
                         &g_prefill_pipeline.layers[i].compute_done,
                         cudaEventDisableTiming), "R4 layer compute_done create")) {
            cuda_prefill_pipeline_release();
            return 0;
        }
    }
    (void)cudaGetDevice(&g_prefill_pipeline.device);
    g_prefill_pipeline.active = 1;
    g_prefill_pipeline_resident_spans = 1;
    g_prefill_pipeline.failed = 0;
    g_prefill_pipeline.stop = 0;
    g_prefill_pipeline.trace_enabled =
        getenv("DS4_CUDA_PREFILL_PIPELINE_TRACE") != NULL;
    g_prefill_pipeline.trace_epoch_us = cuda_prefill_pipeline_trace_now_us();
    g_prefill_pipeline_trace_seq.store(0);
    for (uint32_t i = 0; i < n_layers; i++) {
        cuda_prefill_pipeline_layer &layer = g_prefill_pipeline.layers[i];
        layer.trace_wait_satisfied = {
            i, layer.slot, CUDA_PREFILL_TRACE_WAIT_SATISFIED, 0
        };
        layer.trace_compute_start = {
            i, layer.slot, CUDA_PREFILL_TRACE_COMPUTE_START, 0
        };
        layer.trace_compute_done = {
            i, layer.slot, CUDA_PREFILL_TRACE_COMPUTE_DONE, 0
        };
    }
    for (uint32_t slot = 0; slot < DS4_CUDA_PREFILL_PIPELINE_SLOTS; slot++) {
        if (first_by_slot[slot] != UINT32_MAX) {
            g_prefill_pipeline.requested[first_by_slot[slot]] = 1;
        }
    }
    g_prefill_pipeline.worker = std::thread(cuda_prefill_pipeline_worker);
    g_prefill_pipeline.cv.notify_all();
    fprintf(stderr,
            "ds4: R4 direct layer-fence alternating prefill arena: "
            "2 slots, %.2f GiB, "
            "slot capacities %.2f/%.2f GiB, %u prebuilt waves\n",
            (double)arena_bytes / 1073741824.0,
            (double)slot_capacity[0] / 1073741824.0,
            (double)slot_capacity[1] / 1073741824.0,
            n_layers);
    return 1;
}

extern "C" int ds4_gpu_prefill_pipeline_active(void) {
    return g_prefill_pipeline.active;
}

extern "C" int ds4_gpu_prefill_pipeline_wait_layer(uint32_t layer) {
    if (!g_prefill_pipeline.active || layer >= g_prefill_pipeline.n_layers) return 0;
    {
        std::unique_lock<std::mutex> lock(g_prefill_pipeline.mutex);
        g_prefill_pipeline.cv.wait(lock, [layer] {
            return g_prefill_pipeline.failed ||
                   g_prefill_pipeline.submitted[layer] != 0;
        });
        if (g_prefill_pipeline.failed) return 0;
    }
    cuda_prefill_pipeline_layer &plan =
        g_prefill_pipeline.layers[layer];
    const uint32_t slot = plan.slot;
    const uint64_t wait_fence_value = plan.fence_value;
    if (!ds4_ds_prefill_wave_cuda_wait(wait_fence_value,
                                       (void *)(cudaStream_t)0)) {
        return 0;
    }
    if (g_prefill_pipeline.trace_enabled) {
        plan.trace_wait_satisfied.fence_value = wait_fence_value;
        plan.trace_compute_start.fence_value = wait_fence_value;
        if (!cuda_ok(cudaLaunchHostFunc(
                         (cudaStream_t)0,
                         cuda_prefill_pipeline_trace_callback,
                         &plan.trace_wait_satisfied),
                     "R4 trace wait_satisfied callback") ||
            !cuda_ok(cudaLaunchHostFunc(
                         (cudaStream_t)0,
                         cuda_prefill_pipeline_trace_callback,
                         &plan.trace_compute_start),
                     "R4 trace compute_start callback")) {
            return 0;
        }
    }
    if (getenv("DS4_CUDA_PREFILL_PIPELINE_VERIFY_BYTES") != NULL) {
        if (!cuda_ok(cudaStreamSynchronize((cudaStream_t)0),
                     "R4 diagnostic layer fence wait")) return 0;
        unsigned char gpu_sample[4096];
        for (size_t i = 0; i < plan.model_spans.size(); i++) {
            const ds4_ds_wave_span &span = plan.model_spans[i];
            const uint64_t sample = span.bytes < sizeof(gpu_sample) ?
                span.bytes : sizeof(gpu_sample);
            const uint64_t positions[2] = {0, span.bytes - sample};
            for (uint32_t p = 0; p < 2; p++) {
                if (!cuda_ok(cudaMemcpy(
                                 gpu_sample,
                                 g_prefill_pipeline.slots[slot].ptr +
                                     span.arena_offset + positions[p],
                                 (size_t)sample, cudaMemcpyDeviceToHost),
                             "R4 diagnostic sample read")) return 0;
                const unsigned char *host =
                    (const unsigned char *)plan.table.model_map +
                    span.file_offset + positions[p];
                if (memcmp(gpu_sample, host, (size_t)sample) != 0) {
                    fprintf(stderr,
                            "ds4: R4 BYTE MISMATCH layer=%u span=%u edge=%u "
                            "file=%llu arena=%llu bytes=%llu\n",
                            layer, (unsigned)i, p,
                            (unsigned long long)(span.file_offset + positions[p]),
                            (unsigned long long)(span.arena_offset + positions[p]),
                            (unsigned long long)sample);
                    return 0;
                }
            }
        }
    }
    return 1;
}

extern "C" int ds4_gpu_prefill_pipeline_layer_done(uint32_t layer) {
    if (!g_prefill_pipeline.active || layer >= g_prefill_pipeline.n_layers) return 0;
    cuda_prefill_pipeline_layer &plan =
        g_prefill_pipeline.layers[layer];
    if (g_prefill_pipeline.trace_enabled) {
        plan.trace_compute_done.fence_value = plan.fence_value;
        if (!cuda_ok(cudaLaunchHostFunc(
                         (cudaStream_t)0,
                         cuda_prefill_pipeline_trace_callback,
                         &plan.trace_compute_done),
                     "R4 trace compute_done callback")) return 0;
    }
    if (!cuda_ok(cudaEventRecord(plan.compute_done, (cudaStream_t)0),
                 "R4 compute_done record")) return 0;
    const uint32_t future = plan.next_layer;
    if (future != UINT32_MAX) {
        std::lock_guard<std::mutex> lock(g_prefill_pipeline.mutex);
        g_prefill_pipeline.requested[future] = 1;
        g_prefill_pipeline.cv.notify_all();
    }
    return 1;
}

extern "C" int ds4_gpu_prefill_pipeline_finish(void) {
    if (!g_prefill_pipeline.active) return 1;
    if (g_prefill_pipeline.worker.joinable()) {
        {
            std::unique_lock<std::mutex> lock(g_prefill_pipeline.mutex);
            g_prefill_pipeline.cv.wait(lock, [] {
                if (g_prefill_pipeline.failed) return true;
                for (uint32_t i = 0; i < g_prefill_pipeline.n_layers; i++) {
                    if (!g_prefill_pipeline.submitted[i]) return false;
                }
                return true;
            });
            g_prefill_pipeline.stop = 1;
            g_prefill_pipeline.cv.notify_all();
        }
        g_prefill_pipeline.worker.join();
    }
    if (g_prefill_pipeline.failed) return 0;
    if (cuda_decode_profile_enabled()) g_decode_profile.commits++;
    if (!cuda_decode_profile_synchronize("R4 prefill pipeline finish")) return 0;
    return ds4_ds_prefill_waves_check_errors();
}

extern "C" void ds4_gpu_prefill_pipeline_release(void) {
    cuda_prefill_pipeline_release();
}
#endif

static int cuda_stream_selected_cache_begin_compact_load(
        const void    *model_map,
        uint64_t       model_size,
        uint32_t       layer,
        const int32_t *compact_ids,
        const int32_t *slot_ids,
        uint32_t       n_total_expert,
        uint32_t       compact_count,
        uint32_t       slot_count,
        uint64_t       gate_offset,
        uint64_t       up_offset,
        uint64_t       down_offset,
        uint64_t       gate_expert_bytes,
        uint64_t       down_expert_bytes,
        int            strict_failure,
        int            allow_global_cache,
        const uint8_t  *expert_tiers,
        const uint32_t *expert_ranks) {
    /* Register before every treatment-dependent early return so both the
     * policy-off control and policy-on treatment emit the same mechanism line. */
    cuda_expert_cache_stats_register();
    const int decode_profile = cuda_decode_profile_enabled();
    const double decode_profile_t0 =
        decode_profile ? cuda_decode_profile_now_ms() : 0.0;
#if defined(_WIN32)
    int hot_prefetch_match = cuda_ds_hot_prefetch_matches(model_map, layer);
    if ((g_ds_hot_prefetch_active || g_ds_decode_pipeline.active) &&
        !hot_prefetch_match) {
        g_ds_hash_pipeline.active = 0;
        cuda_ds_hot_prefetch_retire();
    }
#define DS4_SELECTED_RETURN(value) do {                                              \
        if (hot_prefetch_match) {                                                     \
            g_ds_hash_pipeline.active = 0;                                           \
            cuda_ds_hot_prefetch_retire();                                           \
        }                                                                             \
        return (value);                                                              \
    } while (0)
#else
    const int hot_prefetch_match = 0;
#define DS4_SELECTED_RETURN(value) return (value)
#endif
    cuda_stream_selected_cache_invalidate();
    cuda_model_load_progress_finish();

    if (!g_ssd_streaming_mode) DS4_SELECTED_RETURN(1);
    if (!model_map || !compact_ids || !slot_ids ||
        n_total_expert == 0 ||
        compact_count == 0 || compact_count > n_total_expert ||
        slot_count == 0 ||
        gate_expert_bytes == 0 || down_expert_bytes == 0) {
        DS4_SELECTED_RETURN(0);
    }
    if ((uint64_t)n_total_expert > UINT64_MAX / gate_expert_bytes ||
        (uint64_t)n_total_expert > UINT64_MAX / down_expert_bytes ||
        (uint64_t)compact_count > UINT64_MAX / gate_expert_bytes ||
        (uint64_t)compact_count > UINT64_MAX / down_expert_bytes) {
        fprintf(stderr, "ds4: CUDA streaming selected expert size overflow\n");
        DS4_SELECTED_RETURN(0);
    }
#if defined(_WIN32)
    if (hot_prefetch_match) {
        cuda_ds_decode_pipeline_note_arrival(
            model_map, layer, compact_ids, compact_count);
    }
#endif

    const uint64_t full_gate_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t full_down_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    const uint64_t compact_gate_bytes = (uint64_t)compact_count * gate_expert_bytes;
    const uint64_t compact_down_bytes = (uint64_t)compact_count * down_expert_bytes;
    if (gate_offset > model_size || up_offset > model_size || down_offset > model_size ||
        full_gate_bytes > model_size - gate_offset ||
        full_gate_bytes > model_size - up_offset ||
        full_down_bytes > model_size - down_offset) {
        fprintf(stderr, "ds4: CUDA streaming selected expert range outside model map\n");
        DS4_SELECTED_RETURN(0);
    }

    if (!allow_global_cache) {
        cuda_stream_expert_cache_release_all();
    }

    if (!cuda_stream_selected_ensure_bytes(&g_stream_selected_cache.gate_ptr,
                                           &g_stream_selected_cache.gate_capacity,
                                           compact_gate_bytes,
                                           "selected gate experts") ||
        !cuda_stream_selected_ensure_bytes(&g_stream_selected_cache.up_ptr,
                                           &g_stream_selected_cache.up_capacity,
                                           compact_gate_bytes,
                                           "selected up experts") ||
        !cuda_stream_selected_ensure_bytes(&g_stream_selected_cache.down_ptr,
                                           &g_stream_selected_cache.down_capacity,
                                           compact_down_bytes,
                                           "selected down experts") ||
        !cuda_stream_selected_ensure_i32(&g_stream_selected_cache.slot_selected_ptr,
                                         &g_stream_selected_cache.slot_selected_capacity,
                                         slot_count,
                                         "selected expert slots")) {
        DS4_SELECTED_RETURN(strict_failure ? 0 : 1);
    }

    const uint32_t configured_cache_budget =
        cuda_stream_expert_cache_configured_budget();
    const int use_global_cache =
        allow_global_cache &&
        configured_cache_budget != 0;
    cuda_stream_expert_cache *expert_cache = use_global_cache ?
        cuda_stream_expert_cache_prepare(gate_expert_bytes,
                                         down_expert_bytes,
                                         configured_cache_budget) :
        NULL;
    int expert_cache_disabled = expert_cache == NULL;
    const uint32_t cache_count_before =
        expert_cache && expert_cache->valid ? expert_cache->count : 0;
    uint32_t cache_hits = 0;
    uint32_t cache_misses = 0;
    uint32_t host_cache_hits = 0;
    uint32_t host_cache_misses = 0;
    const uint64_t host_hits_before = g_expert_host_hits;
    const uint64_t host_misses_before = g_expert_host_misses;
    uint32_t direct_loads = 0;

#if defined(_WIN32)
    {
    cuda_ds_phase_scope plan_scope(&g_ds_decode_bandwidth.phase_plan_ms);
    /* ---- Pre-pass: fetch this layer's misses as ONE DirectStorage batch ----
     *
     * Read-only with respect to both caches: it only calls the `find` helpers, never reserves a slot
     * and never touches an LRU age, so the serial loop below behaves exactly as it did before -- it
     * simply finds its bytes already in the arena. That is what keeps this free of the same-victim
     * and batch-hit-eviction hazards a planner restructure would carry. */
    if ((!g_prefill_pipeline_resident_spans ||
         cuda_r4_selective_prepass_enabled()) &&
        cuda_ds_prefetch_enabled() && g_model_fd >= 0 &&
        (g_model_fd_host_base == NULL || model_map == g_model_fd_host_base)) {
        const int ds_ready = ds4_ds_init_from_fd(g_model_fd);
        int use_gpu_destination = 0;
        if (ds_ready && hot_prefetch_match && !g_ds_prefetch_spans.empty()) {
            use_gpu_destination = g_ds_prefetch_spans[0].gpu_destination;
        } else if (ds_ready && compact_count <= 6u &&
                   cuda_ds_gpu_destination_enabled()) {
            use_gpu_destination = cuda_ds_gpu_prefetch_arena_ensure();
        }
        if (!use_gpu_destination && g_ds_prefetch_arena == NULL) {
            g_ds_prefetch_capacity = cuda_ds_prefetch_capacity_bytes();
            g_ds_prefetch_arena = (char *)malloc((size_t)g_ds_prefetch_capacity);
            if (g_ds_prefetch_arena == NULL) {
                fprintf(stderr,
                        "ds4: CUDA batched prefetch disabled: cannot allocate a %.0f MiB arena\n",
                        (double)g_ds_prefetch_capacity / 1048576.0);
                g_ds_prefetch_disabled = 1;
            }
        }
        if (ds_ready && (use_gpu_destination || g_ds_prefetch_arena != NULL)) {
            if (hot_prefetch_match) cuda_ds_prefetch_reset_transient();
            else cuda_ds_prefetch_reset();
            ds4_ds_batch_reset();
            uint32_t staged = 0, skipped = 0;
            /* [2026-08-20] DS4_PREPASS_STAGE_PROFILE_V1. The selective-prepass fix was INERT:
             * ds_batches stayed an exact 0.000 on requests 2+ while pread stayed at ~203 calls.
             * The gate now passes, so the loop is entered - which means stage() is refusing. Its
             * refusal is silent (`skipped++; break`) and abandons the whole layer on the FIRST
             * failure. Record which arena was chosen and the capacity actually in force, because
             * cuda_ds_gpu_ssd_capacity() returns 0 whenever the RAM-hot reserve >= capacity. */
            if (cuda_decode_profile_enabled()) {
                g_decode_profile.prepass_calls++;
                if (use_gpu_destination) g_decode_profile.prepass_gpudest++;
                g_decode_profile.prepass_cap_mib =
                    (double)(use_gpu_destination ? cuda_ds_gpu_ssd_capacity()
                                                 : g_ds_prefetch_capacity) / 1048576.0;
            }
            for (uint32_t i = 0; i < compact_count; i++) {
                if (compact_ids[i] < 0 || (uint32_t)compact_ids[i] >= n_total_expert) continue;
                const uint64_t expert = (uint64_t)(uint32_t)compact_ids[i];
                const int cache_eligible =
                    expert_tiers == NULL ||
                    expert_tiers[(uint32_t)expert] == DS4_STREAM_EXPERT_TIER_CACHE;
                const uint64_t gate_src = gate_offset + expert * gate_expert_bytes;
                const uint64_t up_src   = up_offset   + expert * gate_expert_bytes;
                const uint64_t down_src = down_offset + expert * down_expert_bytes;

                /* R4 covers only a prefix of large expert classes. Suppress staging only when
                 * every tensor for this expert resolves inside those resident spans; a tail
                 * expert remains a true miss and must use the normal batched DS path. This is
                 * a lookup only: no cache prepare, slot reservation, or LRU-age mutation. */
                if (g_prefill_pipeline_resident_spans &&
                    cuda_model_resident_range_ptr(model_map, gate_src,
                                                  gate_expert_bytes) &&
                    cuda_model_resident_range_ptr(model_map, up_src,
                                                  gate_expert_bytes) &&
                    cuda_model_resident_range_ptr(model_map, down_src,
                                                  down_expert_bytes)) {
                    continue;
                }

                /* The dedicated arena tail already holds this candidate from
                 * pinned RAM.  Keep the SSD batch disjoint so the two links do
                 * useful work instead of racing to fetch the same expert. */
                if (cuda_ram_hot_prefetch_find(
                        model_map, model_size, layer, n_total_expert,
                        (uint32_t)expert,
                        gate_offset, up_offset, down_offset,
                        gate_expert_bytes, down_expert_bytes) >= 0) {
                    continue;
                }

                /* Skip anything already resident: only true misses are worth a disk request.
                 * BOTH tiers must be consulted. Checking only the VRAM cache made the pre-pass
                 * re-read every host-RAM hit from disk, which added enormous pointless traffic and
                 * pushed a 65 s run past 120 s -- a straight regression. The host lookup is
                 * read-only: it resolves the class by shape and inspects it, never calling
                 * prepare(), so it cannot allocate, reallocate or disturb any LRU age. */
                if (cache_eligible && expert_cache &&
                    cuda_stream_expert_cache_find(expert_cache, model_map,
                        model_size, layer, n_total_expert, (uint32_t)expert, gate_offset,
                        up_offset, down_offset, gate_expert_bytes, down_expert_bytes) >= 0) {
                    continue;
                }
                if (cache_eligible) {
                    const uint32_t hclass =
                        cuda_stream_host_expert_cache_class_index(gate_expert_bytes,
                                                                  down_expert_bytes);
                    cuda_stream_host_expert_cache *hcache =
                        &g_stream_host_expert_caches[hclass];
                    if (hcache->valid &&
                        hcache->gate_expert_bytes == gate_expert_bytes &&
                        hcache->down_expert_bytes == down_expert_bytes &&
                        cuda_stream_host_expert_cache_find(hcache, model_map, model_size, layer,
                            n_total_expert, (uint32_t)expert, gate_offset, up_offset, down_offset,
                            gate_expert_bytes, down_expert_bytes) >= 0) {
                        continue;
                    }
                }
                /* A decode lookahead miss cannot be appended behind future
                 * waves: waiting for that later FIFO entry would drain the
                 * stream and recreate the serial critical path. Leave it to
                 * the existing synchronous selected-copy fallback, which can
                 * run while later waves remain in flight. Predicted spans stay
                 * immutable and are the only bytes consumed from this wave. */
                if (g_ds_decode_pipeline.active && hot_prefetch_match) {
                    const cuda_ds_decode_pipeline_layer &current =
                        g_ds_decode_pipeline.layers[g_ds_decode_pipeline.current];
                    if (!cuda_ds_decode_pipeline_layer_owns_expert(
                            &current, (uint32_t)expert)) {
                        continue;
                    }
                }
                if (!cuda_ds_prefetch_stage(model_map, gate_src, gate_expert_bytes,
                                            use_gpu_destination) ||
                    !cuda_ds_prefetch_stage(model_map, up_src, gate_expert_bytes,
                                            use_gpu_destination) ||
                    !cuda_ds_prefetch_stage(model_map, down_src, down_expert_bytes,
                                            use_gpu_destination)) {
                    skipped++;      /* arena full -- the rest simply take the old serial path */
                    if (cuda_decode_profile_enabled()) {
                        g_decode_profile.prepass_skipped++;
                        /* WHICH of the seven refusal branches fired. Without this the layer is
                         * abandoned silently and every expert drops to a 3 GB/s serial pread. */
                        g_decode_profile.prepass_fail_reason =
                            (double)ds4_ds_gpu_add_fail_reason();
                    }
                    break;
                }
                staged++;
                if (cuda_decode_profile_enabled()) g_decode_profile.prepass_staged++;
            }
            if (ds4_ds_batch_count() > 0) {
                if (decode_profile || ds4_ds_layer_trace_enabled())
                    ds4_ds_stats_set_batch_layer(layer, layer);
                uint64_t got_bytes = 0;
                double   got_ms    = 0.0;
                double   wait_ms   = 0.0;
                /* OVERLAP: submit without waiting, so the ~71% of this layer's experts that HIT the VRAM
                 * cache can be copied while the ~29% cold-tail misses are still in flight.
                 *
                 * MEASURED justification (2026-08-17, DS4_CUDA_DS_BATCH_TRACE over 7,645 batches):
                 * batch cost is 0.407 ms fixed + bytes/15.12 GiB/s (r^2=0.955), and the engine issues
                 * 29.9 batches per decoded token totalling 57.3 ms - 41% of a 138 ms token - all of it
                 * spent BLOCKED. Hiding it behind the hit-copies predicts 7.24 -> ~12 t/s.
                 *
                 * The wait is deferred to cuda_ds_expert_fetch_drain() below, which is called (a) before
                 * the first read of fetched data in the copy loop, (b) before the single early return in
                 * that loop, and (c) before cuda_ds_prefetch_reset() retires the staging arena. No new
                 * state is needed: ds4_ds_batch_inflight() already reports whether a slot is outstanding.
                 *
                 * ⚠️ A missed drain desynchronises the FIFO ring for every later layer, so all three call
                 * sites are load-bearing. */
                if (hot_prefetch_match || cuda_ds_expert_overlap_enabled()) {
                    if (g_ds_decode_bandwidth.batch_submit()) {
                        g_ds_prefetch_batches++;      /* bytes/ms are accumulated at drain time */
                    } else {
                        if (hot_prefetch_match) {
                            g_ds_hash_pipeline.active = 0;
                            cuda_ds_hot_prefetch_retire();
                            hot_prefetch_match = 0;
                        } else {
                            cuda_ds_prefetch_reset();
                        }
                        fprintf(stderr, "ds4: CUDA batched prefetch submit failed; disabling it for this run\n");
                        g_ds_prefetch_disabled = 1;
                    }
                } else if (g_ds_decode_bandwidth.batch_submit_wait(
                               &got_bytes, &got_ms, &wait_ms)) {
                    g_ds_prefetch_batches++;
                    g_ds_prefetch_bytes += got_bytes;
                    g_ds_prefetch_ms    += got_ms;
                    if (decode_profile) {
                        g_decode_profile.ds_batches++;
                        g_decode_profile.ds_batch_ms += got_ms;
                        g_decode_profile.ds_wait_calls++;
                        g_decode_profile.ds_wait_ms += wait_ms;
                    }
                    /* [DIAG 2026-08-16] THE decisive measurement for the prefill endgame: is a
                     * batch's cost fixed (submit->wait round trip) or proportional to its payload?
                     * Aggregate evidence already says fixed - a VRAM sweep moved the hit rate
                     * 43.6%->55.3% (17% fewer misses, so ~17% fewer bytes) and prefill throughput
                     * did not move at all (187-189 t/s). This prints the per-batch pair so ms can
                     * be plotted against bytes directly. Flat => split each layer's fetch in two
                     * and pipeline via the two-slot ring; rising => transfer-bound and the latency
                     * theory dies. */
                    if (cuda_ds_batch_trace_enabled()) {
                        fprintf(stderr, "ds4: DSBATCH bytes=%llu ms=%.3f\n",
                                (unsigned long long)got_bytes, got_ms);
                    }
                } else {
                    /* A failed batch must never be mistaken for fetched data. */
                    cuda_ds_prefetch_reset();
                    fprintf(stderr, "ds4: CUDA batched prefetch failed; disabling it for this run\n");
                    g_ds_prefetch_disabled = 1;
                }
            }
            if (skipped != 0 && g_ds_prefetch_batches <= 1) {
                fprintf(stderr,
                        "ds4: CUDA batched prefetch arena (%.0f MiB) held %u experts of this layer; "
                        "the remainder use serial reads. Raise DS4_CUDA_DS_PREFETCH_MB to cover more.\n",
                        (double)(use_gpu_destination ? cuda_ds_gpu_ssd_capacity() :
                                                       g_ds_prefetch_capacity) / 1048576.0,
                        staged);
            }
        }
    }
    }
#endif

    {
#if defined(_WIN32)
    cuda_ds_phase_scope copy_scope(&g_ds_decode_bandwidth.phase_copy_ms);
#endif
    /* [2026-08-16] Merged-run H2D state. The per-expert path issued THREE SYNCHRONOUS cudaMemcpy
     * calls per expert - 72,000 blocking transfers on a 16K prefill, measured at 10.87 GiB/s against
     * 25-50 GB/s of pinned-H2D link speed. Consecutive copies were measured 99.4% contiguous on BOTH
     * ends (host slot and compact slot) with runs averaging 156, so accumulating a run and flushing
     * it once collapses ~24,000 copies to ~154.
     *
     * Deferring is safe on the loop's early-out paths because each calls
     * cuda_stream_selected_cache_invalidate() before returning - a pending run is discarded along
     * with the cache it would have filled. It is NOT safe past cuda_ds_prefetch_reset(), which
     * retires the staging arena, so the flush below happens before it. */
    cuda_stream_host_expert_cache *run_cache = NULL;
    uint32_t run_first_host = 0, run_len = 0;
    uint64_t run_first_gate_dst = 0, run_first_down_dst = 0;
#define DS4_FLUSH_HOST_RUN()                                                              \
    (run_len == 0 ? 1 :                                                                   \
     (cuda_stream_host_expert_cache_copy_run_to_device(                                    \
          run_cache, run_first_host, run_len,                                              \
          g_stream_selected_cache.gate_ptr + run_first_gate_dst,                           \
          g_stream_selected_cache.up_ptr   + run_first_gate_dst,                           \
          g_stream_selected_cache.down_ptr + run_first_down_dst) ? (run_len = 0, 1) : 0))

    /* Two passes when overlap is enabled (hits, then drain, then misses); one pass otherwise, in which case
     * `pass` is fixed at 1 so the filter above is skipped entirely and the original single-pass behaviour is
     * preserved byte-for-byte. */
    const int ds_overlap_two_pass =
        hot_prefetch_match || cuda_ds_expert_overlap_enabled();
    const int pass_lo = ds_overlap_two_pass ? 0 : 1;
    for (int pass = pass_lo; pass <= 1; pass++) {
    if (ds_overlap_two_pass && pass == 1) {
        /* Everything resident has now been copied. Whatever the fetch bought is needed from here on. */
        cuda_ds_expert_fetch_drain();
    }
    for (uint32_t i = 0; i < compact_count; i++) {
        if (compact_ids[i] < 0 || (uint32_t)compact_ids[i] >= n_total_expert) {
            fprintf(stderr,
                    "ds4: CUDA streaming selected expert id %d is outside 0..%u at layer %u\n",
                    compact_ids[i],
                    n_total_expert,
                    layer);
            /* (b) the one early return inside the copy loop. Leaving a batch outstanding here would
             * desynchronise the FIFO ring for every subsequent layer, turning a clean error into
             * corrupted data later. */
            DS4_SELECTED_RETURN(0);
        }

        const uint64_t expert = (uint64_t)(uint32_t)compact_ids[i];
        const uint64_t gate_dst = (uint64_t)i * gate_expert_bytes;
        const uint64_t down_dst = (uint64_t)i * down_expert_bytes;
        const int cache_eligible =
            expert_tiers == NULL ||
            expert_tiers[(uint32_t)expert] == DS4_STREAM_EXPERT_TIER_CACHE;
        int copied_from_global_cache = 0;

        /* TWO-PASS FILTER, when overlap is on.
         *
         * pass 0 handles ONLY experts already resident in VRAM - they need no fetched data, so their copies
         * run while the DirectStorage batch is still in flight. pass 1 drains, then handles the misses.
         *
         * WHY THIS AND NOT THE SIMPLER LAZY WAIT: draining at the first touch of fetched data only overlaps
         * the hits that happen to precede the FIRST miss - E[2.13] of 4.26 hits at a 71% hit rate, each a
         * fraction of a millisecond against a 1.895 ms batch. Measured: that version gave 6.43/6.30 t/s
         * against a 6.80 baseline, i.e. nothing. Ordering all hits first is what makes the window big
         * enough to matter.
         *
         * SAFETY: the destination is computed from `i` (gate_dst = i * gate_expert_bytes), NOT from the
         * iteration order, so visiting indices in a permuted order preserves the slot mapping exactly. The
         * index-to-destination arithmetic is what must not change, and it does not.
         * The probe deliberately does NOT touch the hit/miss counters - the real find() below still does,
         * exactly once per expert, so the instrumentation stays honest. */
        if (ds_overlap_two_pass) {
            const int resident = cache_eligible &&
                cuda_stream_expert_cache_probe(expert_cache, model_map, model_size, layer,
                                               n_total_expert, (uint32_t)expert,
                                               gate_offset, up_offset, down_offset,
                                               gate_expert_bytes, down_expert_bytes) >= 0;
            if ((pass == 0) != (resident != 0)) continue;
        }

        /* LFU can select any host slot, including the source of a deferred
         * merged run. Consume that run before either tier can admit a miss.
         * LRU keeps its existing merged-copy behavior. */
        if (cuda_stream_cache_lfu_enabled() && !DS4_FLUSH_HOST_RUN()) {
            cuda_stream_selected_cache_invalidate();
            DS4_SELECTED_RETURN(strict_failure ? 0 : 1);
        }

        if (!cache_eligible) cache_misses++;
        if (cache_eligible && !expert_cache_disabled) {
            int cache_slot =
                cuda_stream_expert_cache_find(expert_cache,
                                              model_map,
                                              model_size,
                                              layer,
                                              n_total_expert,
                                              (uint32_t)expert,
                                              gate_offset,
                                              up_offset,
                                              down_offset,
                                              gate_expert_bytes,
                                              down_expert_bytes);
            if (cache_slot >= 0) {
                cache_hits++;
                expert_cache->slots[(uint32_t)cache_slot].age =
                    ++expert_cache->tick;
            } else {
                cache_misses++;
                const uint32_t route_rank = expert_ranks ?
                    expert_ranks[(uint32_t)expert] : UINT32_MAX;
                const uint32_t load_slot =
                    cuda_stream_expert_cache_admission_slot(
                        expert_cache, route_rank, expert_ranks != NULL, layer, (uint32_t)expert);
                if (load_slot != UINT32_MAX) {
                    const int append = !expert_cache->slots[load_slot].valid;
                    /* (a) FIRST TOUCH of fetched data on this layer - the deferred wait lands here, after the
                     * VRAM-cache hits above have already been processed. That gap is the overlap. */
                    cuda_ds_expert_fetch_drain();
                    if (cuda_stream_expert_cache_load_slot(expert_cache,
                                                           model_map,
                                                           model_size,
                                                           load_slot,
                                                           layer,
                                                           n_total_expert,
                                                           (uint32_t)expert,
                                                           route_rank,
                                                           gate_offset,
                                                           up_offset,
                                                           down_offset,
                                                           gate_expert_bytes,
                                                           down_expert_bytes)) {
                        if (append && expert_cache->count < expert_cache->capacity) {
                            expert_cache->count++;
                        }
                        cache_slot = (int)load_slot;
                    } else {
                        cuda_stream_expert_cache_invalidate(expert_cache);
                        expert_cache_disabled = 1;
                        cache_slot = -1;
                    }
                }
            }

            if (cache_slot >= 0) {
                copied_from_global_cache =
                    cuda_stream_expert_cache_copy_to_compact(
                            expert_cache,
                            (uint32_t)cache_slot,
                            i,
                            g_stream_selected_cache.gate_ptr,
                            g_stream_selected_cache.up_ptr,
                            g_stream_selected_cache.down_ptr);
                if (!copied_from_global_cache) {
                    cuda_stream_expert_cache_invalidate(expert_cache);
                    expert_cache_disabled = 1;
                }
            }
        }

        if (!copied_from_global_cache) {
            const uint64_t gate_src = gate_offset + expert * gate_expert_bytes;
            const uint64_t up_src = up_offset + expert * gate_expert_bytes;
            const uint64_t down_src = down_offset + expert * down_expert_bytes;
            int copied_from_host_cache = 0;
#if defined(_WIN32)
            copied_from_host_cache =
                cuda_ram_hot_prefetch_copy_expert_to_device(
                    g_stream_selected_cache.gate_ptr + gate_dst,
                    g_stream_selected_cache.up_ptr + gate_dst,
                    g_stream_selected_cache.down_ptr + down_dst,
                    model_map, model_size, layer, n_total_expert,
                    (uint32_t)expert,
                    gate_offset, up_offset, down_offset,
                    gate_expert_bytes, down_expert_bytes);
#endif
            if (!copied_from_host_cache) copied_from_host_cache =
                cuda_ds_prefetch_copy_expert_to_device(
                    g_stream_selected_cache.gate_ptr + gate_dst,
                    g_stream_selected_cache.up_ptr + gate_dst,
                    g_stream_selected_cache.down_ptr + down_dst,
                    model_map, gate_src, up_src, down_src,
                    gate_expert_bytes, down_expert_bytes);
            if (copied_from_host_cache < 0) {
                cuda_stream_selected_cache_invalidate();
                DS4_SELECTED_RETURN(strict_failure ? 0 : 1);
            }
            if (copied_from_host_cache > 0) direct_loads++;
            cuda_stream_host_expert_cache *host_cache =
                !copied_from_host_cache && cache_eligible ?
                cuda_stream_host_expert_cache_prepare(gate_expert_bytes,
                                                      down_expert_bytes,
                                                      configured_cache_budget) : NULL;
            /* [DIAG 2026-08-16] Accounting for the ~15 s of `load` that is NOT DirectStorage.
             * Per-batch tracing showed DS runs at ~16.7 GiB/s and accounts for only ~11 s of the
             * 26.5 s load phase, so the remainder is here: host-cache probe + H2D copy. Time the
             * two separately - the pinned-host-cache win (+98% prefill) came from exactly this
             * path, so it is the one lever already proven responsive. */
            /* [2026-08-16 PERF FIX] This was a bare getenv() inside the PER-EXPERT loop - roughly
             * 24,000 calls per layer-batch during prefill and ~66,000 across a 256-token decode.
             * Measured cost: decode fell to 6.14 / 7.33 t/s against a 10.4-10.9 history, i.e. the
             * diagnostics I added to chase the chunk limits regressed decode ~35%. getenv() is not
             * free on Windows. Cache it in a static - evaluated once per process.
             *
             * [2026-08-18 ATTRIBUTION CORRECTED - read this before hunting getenv calls elsewhere]
             * getenv() was NOT what cost the 35%. Measured directly on this box
             * (.planning/benchmarks/getenv_cost.c in the RTX_ACCELERATED_MAC_PREFILL_LLAMA repo):
             * a full-environment MISS costs 1.546 us with a 106-variable / 7213-byte environment, so
             * the ~66,000 calls above come to 0.102 s against a ~25 s decode = 0.41%, not 35%.
             * The regression came from what the getenv GATED - a clock read and an fprintf per expert -
             * not from the lookup. Caching is still right (it is free, and it removes the gated work
             * from the hot path), but the lesson is "do not put DIAGNOSTICS in a per-expert loop",
             * NOT "getenv is expensive". For scale: 20 bare getenv calls per layer x 43 layers x 256
             * tokens = 220,160 calls = 1.3% of a token - real, worth fixing, and far too small to
             * explain a host-bound decode. */
            static const bool ds_copy_trace = getenv("DS4_CUDA_COPY_TRACE") != NULL;
            const double copy_t0 = ds_copy_trace ? cuda_decode_profile_now_ms() : 0.0;
            long long traced_host_slot = -1;   /* [DIAG] host_slot is scoped inside the if below */
            if (host_cache) {
                int was_hit = 0;
                const int host_slot =
                    cuda_stream_host_expert_cache_get_slot(host_cache,
                                                           model_map,
                                                           model_size,
                                                           layer,
                                                           n_total_expert,
                                                           (uint32_t)expert,
                                                           gate_offset,
                                                           up_offset,
                                                           down_offset,
                                                           gate_expert_bytes,
                                                           down_expert_bytes,
                                                           &was_hit);
                if (host_slot >= 0) {
                    traced_host_slot = (long long)host_slot;   /* [DIAG] for the source-run ratio */
                    /* Accumulate instead of copying. The run extends only when BOTH ends stay
                     * contiguous; otherwise flush what we have and start a new run. */
                    const int extends =
                        run_len != 0 && run_cache == host_cache &&
                        (uint32_t)host_slot == run_first_host + run_len &&
                        gate_dst == run_first_gate_dst + (uint64_t)run_len * gate_expert_bytes &&
                        down_dst == run_first_down_dst + (uint64_t)run_len * down_expert_bytes;
                    if (extends) {
                        run_len++;
                        copied_from_host_cache = 1;
                    } else if (DS4_FLUSH_HOST_RUN()) {
                        run_cache          = host_cache;
                        run_first_host     = (uint32_t)host_slot;
                        run_first_gate_dst = gate_dst;
                        run_first_down_dst = down_dst;
                        run_len            = 1;
                        copied_from_host_cache = 1;
                    } else {
                        copied_from_host_cache = 0;
                    }
                    if (was_hit) host_cache_hits++;
                    else host_cache_misses++;
                }
            }

            if (ds_copy_trace) {
                /* [DIAG 2026-08-16] Accumulate BYTES as well as ms, so aggregate GiB/s is measured
                 * rather than inferred. The earlier ~13 GiB/s figure divided this path's time by
                 * DirectStorage's byte count - two different populations, the same mistake that
                 * produced a meaningless "1% host hit rate". A copy moves gate + up + down. */
                static double   host_ms    = 0.0;
                static uint64_t host_n     = 0;
                static uint64_t host_bytes = 0;
                /* [DIAG 2026-08-16] Source-run length decides the merge design. Destinations are
                 * provably contiguous (gate_dst = compact_slot * gate_expert_bytes), but a single
                 * transfer needs BOTH ends contiguous and the host slot is allocated independently.
                 * Count how often this copy's host_slot continues the previous one: long runs ->
                 * plain merged copies; runs of ~1 -> needs a gather kernel or compact-order host
                 * slot allocation. Two different implementations, so measure before writing either. */
                static long long prev_host_slot = -1;
                static uint64_t  contig_n       = 0;
                if (traced_host_slot >= 0) {
                    if (prev_host_slot >= 0 && traced_host_slot == prev_host_slot + 1) contig_n++;
                    prev_host_slot = traced_host_slot;
                }
                host_ms += cuda_decode_profile_now_ms() - copy_t0;
                host_n++;
                host_bytes += (uint64_t)gate_expert_bytes * 2ull + (uint64_t)down_expert_bytes;
                if ((host_n % 2000ull) == 0ull) {
                    const double gib = (double)host_bytes / (1024.0 * 1024.0 * 1024.0);
                    fprintf(stderr,
                            "ds4: COPYTRACE host_path n=%llu total_ms=%.1f gib=%.2f gib_s=%.2f "
                            "contig=%llu (%.1f%%) mean_run=%.2f\n",
                            (unsigned long long)host_n, host_ms, gib,
                            host_ms > 0.0 ? gib / (host_ms / 1000.0) : 0.0,
                            (unsigned long long)contig_n,
                            100.0 * (double)contig_n / (double)host_n,
                            (double)host_n / (double)(host_n - contig_n ? host_n - contig_n : 1));
                }
            }
            if (!copied_from_host_cache) {
                copied_from_host_cache = cuda_ds_prefetch_copy_expert_to_device(
                    g_stream_selected_cache.gate_ptr + gate_dst,
                    g_stream_selected_cache.up_ptr + gate_dst,
                    g_stream_selected_cache.down_ptr + down_dst,
                    model_map, gate_src, up_src, down_src,
                    gate_expert_bytes, down_expert_bytes, 1);
                if (copied_from_host_cache < 0) {
                    cuda_stream_selected_cache_invalidate();
                    DS4_SELECTED_RETURN(strict_failure ? 0 : 1);
                }
                if (copied_from_host_cache) direct_loads++;
            }
            if (!copied_from_host_cache) {
                uint64_t streamed_chunks = 0;
                direct_loads++;
                if (!cuda_model_copy_to_device_streamed(g_stream_selected_cache.gate_ptr + gate_dst,
                                                        model_map,
                                                        model_size,
                                                        gate_src,
                                                        gate_expert_bytes,
                                                        "selected moe_gate", streamed_chunks) ||
                    !cuda_model_copy_to_device_streamed(g_stream_selected_cache.up_ptr + gate_dst,
                                                        model_map,
                                                        model_size,
                                                        up_src,
                                                        gate_expert_bytes,
                                                        "selected moe_up", streamed_chunks) ||
                    !cuda_model_copy_to_device_streamed(g_stream_selected_cache.down_ptr + down_dst,
                                                        model_map,
                                                        model_size,
                                                        down_src,
                                                        down_expert_bytes,
                                                        "selected moe_down", streamed_chunks)) {
                    /* (d) the serial-copy fallback's failure exit, INSIDE the loop. Found by auditing every
                     * return between submit and drain rather than assuming the count - the first pass of
                     * this change missed it, and a batch left outstanding here desynchronises the FIFO ring
                     * for every later layer. */
                    cuda_stream_selected_cache_invalidate();
                    DS4_SELECTED_RETURN(strict_failure ? 0 : 1);
                }
            }
        }
    }
    }   /* end of the two-pass wrapper: pass 0 = VRAM-resident experts, pass 1 = fetched misses */

    /* (c) DRAIN BEFORE THE FLUSH, and therefore before the arena is retired.
     *
     * Placed here rather than beside cuda_ds_prefetch_reset() so it also covers the flush's strict_failure
     * return below. It does NOT cover the in-loop exits - those carry their own drains at (b) and (d);
     * an earlier version of this comment wrongly claimed it covered them all. Ordering is load-bearing:
     * drain must come BEFORE the flush (the flush reads host-cache staging that the fetch is still
     * filling) and before the reset (which retires the arena the fetch writes into). A layer whose experts
     * were ALL cache hits leaves nothing outstanding, and the drain is idempotent, so this costs nothing
     * in that case. */
    cuda_ds_expert_fetch_drain();

    /* [2026-08-16] Flush the final merged run BEFORE the arena is retired below. A deferred run
     * reads from host-cache staging, so flushing after cuda_ds_prefetch_reset() would copy data
     * that has since been overwritten - silent corruption, not a crash. */
    if (!DS4_FLUSH_HOST_RUN()) {
        cuda_stream_selected_cache_invalidate();
        DS4_SELECTED_RETURN(strict_failure ? 0 : 1);
    }
#undef DS4_FLUSH_HOST_RUN

#if defined(_WIN32)
    /* Keep the immutable token-wide hot prefix, but retire this layer's routed
     * miss tail before another layer can overwrite it. Without a token batch,
     * preserve the original full reset. */
    {
        cuda_ds_phase_scope retire_scope(&g_ds_decode_bandwidth.phase_retire_ms);
        if (hot_prefetch_match) cuda_ds_prefetch_reset_transient();
        else cuda_ds_prefetch_reset();
    }
#endif

    if (!cuda_ok(cudaMemcpy(g_stream_selected_cache.slot_selected_ptr,
                            slot_ids,
                            (size_t)slot_count * sizeof(slot_ids[0]),
                            cudaMemcpyHostToDevice),
                 "streaming selected slot upload")) {
        cuda_stream_selected_cache_invalidate();
        return strict_failure ? 0 : 1;
    }
    }

    /* [merge 2026-08-16] ROOT CAUSE of "CUDA streaming selected experts are unavailable for layer 0".
     *
     * `logical_tier` is a field UPSTREAM added to cuda_stream_selected_cache for tensor parallelism.
     * Upstream's own population site sets it (~29501); this HEAD-side streaming site never did,
     * because HEAD's struct had no such field. The two sites are otherwise line-for-line parallel --
     * this was the single missing assignment.
     *
     * Upstream then added a consumer (~27207) that requires
     *     g_stream_selected_cache.logical_tier == ds4_tensor_device_idx(out)
     * before it will use the streaming cache. With this field left at the -1 that
     * cuda_stream_selected_cache_release() writes (line ~261), and ds4_tensor_device_idx() returning
     * 0 on a single-GPU box, that check could NEVER pass -- so every layer reported "unavailable"
     * and prefill died at layer 0. Verified absent from the pre-merge tree: both that message and
     * this field are new with the merge.
     *
     * ⚠️ Store the LOGICAL tier, not a physical ordinal. My first attempt used cudaGetDevice(), which
     * happens to work here only because both are 0 on a single visible GPU -- but this field is
     * compared against ds4_tensor_device_idx(), a LOGICAL tensor tier. A future multi-device
     * streaming path must map cudaGetDevice()'s physical result back through g_gpu[t].device_id
     * rather than storing the ordinal directly. This SSD-streaming path is single-tier today
     * (cuda_use_mmq() and the streaming design both assume g_n_gpus == 1), so tier 0 is correct and
     * honest; anything else would be a guess dressed up as generality. */
    g_stream_selected_cache.logical_tier = 0;
    g_stream_selected_cache.slot_selected_tensor.device_id = 0;
    g_stream_selected_cache.model_map = model_map;
    g_stream_selected_cache.layer = layer;
    g_stream_selected_cache.n_total_expert = n_total_expert;
    /* [merge 2026-08-15] `.n_selected = slot_count;` removed. `n_selected` is a HEAD-era field that
     * upstream's cuda_stream_selected_cache (the struct that won this merge) does not have -- it
     * carries `slot_count` instead. The assignment was written once and read nowhere, and the very
     * next line already stores the identical value, so dropping it is behaviour-preserving. */
    g_stream_selected_cache.slot_count = slot_count;
    g_stream_selected_cache.compact_count = compact_count;
    g_stream_selected_cache.gate_offset = gate_offset;
    g_stream_selected_cache.up_offset = up_offset;
    g_stream_selected_cache.down_offset = down_offset;
    g_stream_selected_cache.gate_expert_bytes = gate_expert_bytes;
    g_stream_selected_cache.down_expert_bytes = down_expert_bytes;
    g_stream_selected_cache.slot_selected_tensor.ptr =
        g_stream_selected_cache.slot_selected_ptr;
    g_stream_selected_cache.slot_selected_tensor.bytes =
        (uint64_t)slot_count * sizeof(int32_t);
    g_stream_selected_cache.slot_selected_tensor.owner = 0;
    g_stream_selected_cache.valid = 1;

#if defined(_WIN32)
    cuda_ds_decode_pipeline_advance(layer);
    cuda_ds_hash_pipeline_advance(layer);
#endif

    const uint64_t misses = use_global_cache ?
        (uint64_t)cache_misses : (uint64_t)compact_count;
    if (decode_profile || g_stream_expert_cache_phase_decode) {
        /* Cheap existing counters also quantify resident DSpark verification;
         * no profiling synchronization or timer is needed for exact fetches. */
        g_decode_profile.cache_hits += cache_hits;
        g_decode_profile.cache_misses += misses;
    }
    if (decode_profile) {
        g_decode_profile.expert_layers++;
        if (misses == 0) g_decode_profile.clean_layers++;
        g_decode_profile.expert_plan_ms +=
            cuda_decode_profile_now_ms() - decode_profile_t0;
    }

    /* [2026-08-18] ROUTE DUMP, for the ONE question that decides whether layer-ahead prefetch can work
     * in any form.  MEASURED: the current predictor (global hotlist rank inside the RAM band) hits
     * 1.4-1.5% against a 6/256 = 2.34% chance baseline - i.e. WORSE than guessing, because that band is
     * defined to exclude the hottest experts.  Router-ahead cannot rescue it: the router consumes this
     * layer's own post-attention logits, so L+1's expert set is not knowable before L+1's attention
     * (except for the 3 hash-routed layers, which select on the token id alone).
     *
     * That leaves exactly one untried predictor: THE EXPERTS THIS LAYER USED FOR THE PREVIOUS TOKEN.
     * MoE routing has strong temporal locality, last token's selection is already known, and remembering
     * it costs ~1 KB (43 layers x 6 ids).  Before building anything, MEASURE the locality: dump the
     * per-layer selected ids and compute the overlap between token t and t+1 for the same layer.
     *   overlap >> 2.34%  -> wire this predictor into the promotion path, which is ALREADY correctly
     *                        placed (it starts before the layer's attention and router).
     *   overlap ~ 2.34%   -> layer-ahead prefetch is dead in every form; say so plainly.
     * Gated OFF by default: this is ~43 lines per token, for one diagnostic run only. */
    {
        static int trace_route = -1;
        if (trace_route < 0) trace_route = getenv("DS4_TRACE_ROUTE") != NULL;
        if (trace_route && compact_ids && compact_count > 0) {
            fprintf(stderr, "ds4: route layer=%u n=%u ids=", layer, compact_count);
            for (uint32_t ri = 0; ri < compact_count; ri++) {
                fprintf(stderr, "%s%d", ri ? "," : "", (int)compact_ids[ri]);
            }
            fprintf(stderr, "\n");
        }
    }
    if (getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_VERBOSE") || decode_profile) {
        cuda_model_load_progress_finish();
        fprintf(stderr,
                "ds4: CUDA streaming selected layer=%u slots=%u compact=%u global_budget=%u before=%u after=%u hits=%u misses=%u host_hits=%u host_misses=%u direct=%u gate/up %.2f MiB down %.2f MiB\n",
                layer,
                slot_count,
                compact_count,
                expert_cache && expert_cache->valid ? expert_cache->capacity : 0,
                cache_count_before,
                expert_cache && expert_cache->valid ? expert_cache->count : 0,
                cache_hits,
                cache_misses,
                (uint32_t)(g_expert_host_hits - host_hits_before),
                (uint32_t)(g_expert_host_misses - host_misses_before),
                direct_loads,
                (double)compact_gate_bytes / 1048576.0,
                (double)compact_down_bytes / 1048576.0);
    }
#undef DS4_SELECTED_RETURN
    return 1;
}

extern "C" int ds4_gpu_stream_expert_cache_begin_selected_load(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *selected_ids,
        uint32_t                           n_selected) {
    if (!g_ssd_streaming_mode) return 1;
    if (!table || !selected_ids || n_selected == 0) return 0;
#if defined(_WIN32)
    /* One aggregate scope per selected layer (43 on the shipped model), not per
     * expert. Nested plan/copy/retire/wait/submit phases are subtracted. */
    cuda_ds_phase_scope bookkeeping_scope(
        &g_ds_decode_bandwidth.phase_bookkeeping_ms);
#endif
    /* This is the per-token decode entry. Save the completed router selection
     * for the same layer's pre-router promotion on the next token. */
    cuda_route_previous_note(table->layer, selected_ids, n_selected);
    cuda_route_hotness_note(table->layer, selected_ids, n_selected,
                            table->expert_tiers, table->model_identity,
                            table->model_size, table->n_total_expert);
    const void *model_map = table->model_map;
    const uint64_t model_size = table->model_size;
    const uint32_t layer = table->layer;
    const uint32_t n_total_expert = table->n_total_expert;
    const uint64_t gate_offset = table->gate_offset;
    const uint64_t up_offset = table->up_offset;
    const uint64_t down_offset = table->down_offset;
    const uint64_t gate_expert_bytes = table->gate_expert_bytes;
    const uint64_t down_expert_bytes = table->down_expert_bytes;

    std::vector<int32_t> expert_to_slot(n_total_expert, -1);
    std::vector<int32_t> compact_ids;
    std::vector<int32_t> slot_ids(n_selected);
    compact_ids.reserve(n_selected);
    for (uint32_t i = 0; i < n_selected; i++) {
        const int32_t expert_i = selected_ids[i];
        if (expert_i < 0 || (uint32_t)expert_i >= n_total_expert) {
            fprintf(stderr,
                    "ds4: CUDA streaming selected expert id %d is outside 0..%u at layer %u\n",
                    expert_i,
                    n_total_expert,
                    layer);
            return 0;
        }
        expert_to_slot[(uint32_t)expert_i] = -2;
    }
    for (uint32_t e = 0; e < n_total_expert; e++) {
        if (expert_to_slot[e] != -2) continue;
        expert_to_slot[e] = (int32_t)compact_ids.size();
        compact_ids.push_back((int32_t)e);
    }
    for (uint32_t i = 0; i < n_selected; i++) {
        slot_ids[i] = expert_to_slot[(uint32_t)selected_ids[i]];
    }
    if (compact_ids.empty() || compact_ids.size() > UINT32_MAX) return 0;
    return cuda_stream_selected_cache_begin_compact_load(
            model_map,
            model_size,
            layer,
            compact_ids.data(),
            slot_ids.data(),
            n_total_expert,
            (uint32_t)compact_ids.size(),
            n_selected,
            gate_offset,
            up_offset,
            down_offset,
            gate_expert_bytes,
            down_expert_bytes,
            0,
            1,
            table->expert_tiers,
            table->expert_ranks);
}

extern "C" int ds4_gpu_stream_expert_cache_prepare_selected_batch(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *selected_ids,
        uint32_t                           n_tokens,
        uint32_t                           n_selected) {
    if (!g_ssd_streaming_mode) return 1;
    if (!table ||
        !selected_ids ||
        table->n_total_expert == 0 ||
        n_selected == 0 ||
        n_tokens == 0 ||
        (uint64_t)n_tokens > UINT32_MAX / (uint64_t)n_selected) {
        return 0;
    }
    /* Route-hotness virtual cache: this is the PREFILL entry (the whole chunk's selections at once),
     * where begin_selected_load is the per-token DECODE entry. Both must be counted or the record
     * only sees half the workload - the first version hooked only the decode entry and a one-shot CLI
     * run produced NO report at all. */
    cuda_route_hotness_note(table->layer, selected_ids,
                            n_tokens * n_selected, table->expert_tiers,
                            table->model_identity, table->model_size,
                            table->n_total_expert);
    const void *model_map = table->model_map;
    const uint64_t model_size = table->model_size;
    const uint32_t layer = table->layer;
    const uint32_t n_total_expert = table->n_total_expert;
    const uint64_t gate_offset = table->gate_offset;
    const uint64_t up_offset = table->up_offset;
    const uint64_t down_offset = table->down_offset;
    const uint64_t gate_expert_bytes = table->gate_expert_bytes;
    const uint64_t down_expert_bytes = table->down_expert_bytes;

    std::vector<int32_t> expert_to_slot(n_total_expert, -1);
    std::vector<int32_t> compact_ids;
    const uint32_t slot_count = n_tokens * n_selected;
    std::vector<int32_t> slot_ids(slot_count);
    compact_ids.reserve(slot_count < n_total_expert ? slot_count : n_total_expert);

    for (uint32_t i = 0; i < slot_count; i++) {
        const int32_t expert_i = selected_ids[i];
        if (expert_i < 0 || (uint32_t)expert_i >= n_total_expert) {
            fprintf(stderr,
                    "ds4: CUDA streaming batch selected expert id %d is outside 0..%u at layer %u\n",
                    expert_i,
                    n_total_expert,
                    layer);
            return 0;
        }
        expert_to_slot[(uint32_t)expert_i] = -2;
    }
    for (uint32_t e = 0; e < n_total_expert; e++) {
        if (expert_to_slot[e] != -2) continue;
        expert_to_slot[e] = (int32_t)compact_ids.size();
        compact_ids.push_back((int32_t)e);
    }
    for (uint32_t i = 0; i < slot_count; i++) {
        slot_ids[i] = expert_to_slot[(uint32_t)selected_ids[i]];
    }

    if (compact_ids.empty() || compact_ids.size() > UINT32_MAX) return 0;
    return cuda_stream_selected_cache_begin_compact_load(
            model_map,
            model_size,
            layer,
            compact_ids.data(),
            slot_ids.data(),
            n_total_expert,
            (uint32_t)compact_ids.size(),
            slot_count,
            gate_offset,
            up_offset,
            down_offset,
            gate_expert_bytes,
            down_expert_bytes,
            1,
            /* A speculative verify is decode. Keep the existing target cache;
             * ordinary prefill retains its prior release-all behavior. */
            g_stream_expert_cache_phase_decode && n_tokens<=16u && n_total_expert==384u &&
                model_map!=g_support_host_base && getenv("DS4_CUDA_DSPARK_RESIDENT") &&
                !strcmp(getenv("DS4_CUDA_DSPARK_RESIDENT"),"1"),
            table->expert_tiers,
            table->expert_ranks);
}

extern "C" int ds4_gpu_stream_expert_cache_seed_experts(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *expert_ids,
        const uint32_t                    *expert_priorities,
        uint32_t                           n_experts) {
    if (!g_ssd_streaming_mode) return 1;
    if (!table) return 0;
    const void *model_map = table->model_map;
    const uint64_t model_size = table->model_size;
    const uint32_t layer = table->layer;
    const uint32_t n_total_expert = table->n_total_expert;
    const uint64_t gate_offset = table->gate_offset;
    const uint64_t up_offset = table->up_offset;
    const uint64_t down_offset = table->down_offset;
    const uint64_t gate_expert_bytes = table->gate_expert_bytes;
    const uint64_t down_expert_bytes = table->down_expert_bytes;
    if (!model_map || !expert_ids || n_experts == 0 ||
        !cuda_stream_layer_expert_ranges_valid(model_size,
                                               n_total_expert,
                                               gate_offset,
                                               up_offset,
                                               down_offset,
                                               gate_expert_bytes,
                                               down_expert_bytes,
                                               "seed hotlist")) {
        return 0;
    }

    cuda_stream_expert_cache *cache =
        cuda_stream_expert_cache_prepare(gate_expert_bytes,
                                         down_expert_bytes,
                                         n_experts);
    if (!cache || cache->capacity == 0) return 1;

    const uint32_t layer_seed_cap =
        n_experts < cache->capacity ? n_experts : cache->capacity;
    std::vector<uint32_t> chosen;
    try {
        chosen.reserve(layer_seed_cap);
    } catch (...) {
        return 1;
    }

    for (uint32_t i = 0; i < n_experts; i++) {
        const int32_t expert = expert_ids[i];
        if (expert < 0 || (uint32_t)expert >= n_total_expert) {
            fprintf(stderr,
                    "ds4: CUDA streaming hotlist seed expert id %d is outside 0..%u at layer %u\n",
                    expert,
                    n_total_expert,
                    layer);
            return 0;
        }
        if (table->expert_tiers &&
            table->expert_tiers[(uint32_t)expert] !=
                DS4_STREAM_EXPERT_TIER_CACHE) {
            continue;
        }
        const uint32_t priority =
            expert_priorities ? expert_priorities[i] : (n_experts - i);
        uint32_t pos = 0;
        while (pos < chosen.size()) {
            const uint32_t other = chosen[pos];
            const uint32_t other_priority =
                expert_priorities ? expert_priorities[other] :
                                    (n_experts - other);
            if (priority > other_priority) break;
            pos++;
        }
        if (chosen.size() < layer_seed_cap) {
            chosen.insert(chosen.begin() + pos, i);
        } else if (pos < chosen.size()) {
            chosen.insert(chosen.begin() + pos, i);
            chosen.pop_back();
        }
    }

    const uint32_t n = (uint32_t)chosen.size();
    for (uint32_t ri = 0; ri < n; ri++) {
        const uint32_t i = chosen[n - 1u - ri];
        if (!cuda_stream_expert_cache_seed_one(cache,
                                               model_map,
                                               model_size,
                                               layer,
                                               n_total_expert,
                                               (uint32_t)expert_ids[i],
                                               table->expert_ranks,
                                               gate_offset,
                                               up_offset,
                                               down_offset,
                                               gate_expert_bytes,
                                               down_expert_bytes)) {
            cuda_stream_expert_cache_invalidate(cache);
            return 1;
        }
    }
    if (getenv("DS4_CUDA_STREAMING_EXPERT_CACHE_VERBOSE")) {
        fprintf(stderr,
                "ds4: CUDA streaming hotlist seeded layer=%u requested=%u cached=%u cap=%u\n",
                layer,
                n_experts,
                n,
                cache->capacity);
    }
    return 1;
}

extern "C" int ds4_gpu_stream_host_expert_cache_seed_experts(
        const ds4_gpu_stream_expert_table *table,
        const int32_t                     *expert_ids,
        uint32_t                           n_experts) {
    if (!g_ssd_streaming_mode || !cuda_stream_host_expert_cache_enabled()) {
        return 1;
    }
    if (!table || !expert_ids || n_experts == 0) return 0;
    const void *model_map = table->model_map;
    const uint64_t model_size = table->model_size;
    const uint32_t layer = table->layer;
    const uint32_t n_total_expert = table->n_total_expert;
    const uint64_t gate_offset = table->gate_offset;
    const uint64_t up_offset = table->up_offset;
    const uint64_t down_offset = table->down_offset;
    const uint64_t gate_expert_bytes = table->gate_expert_bytes;
    const uint64_t down_expert_bytes = table->down_expert_bytes;
    if (!model_map ||
        !cuda_stream_layer_expert_ranges_valid(model_size,
                                               n_total_expert,
                                               gate_offset,
                                               up_offset,
                                               down_offset,
                                               gate_expert_bytes,
                                               down_expert_bytes,
                                               "RAM preload")) {
        return 0;
    }

    cuda_stream_host_expert_cache *cache =
        cuda_stream_host_expert_cache_prepare(gate_expert_bytes,
                                              down_expert_bytes,
                                              0);
    if (!cache || cache->capacity == 0) return 1;

    uint32_t hits = 0;
    uint32_t misses = 0;
    for (uint32_t i = 0; i < n_experts; i++) {
        const int32_t expert_i = expert_ids[i];
        if (expert_i < 0 || (uint32_t)expert_i >= n_total_expert) {
            fprintf(stderr,
                    "ds4: CUDA RAM expert cache preload expert id %d is outside 0..%u at layer %u\n",
                    expert_i,
                    n_total_expert,
                    layer);
            return 0;
        }
        int was_hit = 0;
        const int slot =
            cuda_stream_host_expert_cache_get_slot(cache,
                                                   model_map,
                                                   model_size,
                                                   layer,
                                                   n_total_expert,
                                                   (uint32_t)expert_i,
                                                   gate_offset,
                                                   up_offset,
                                                   down_offset,
                                                   gate_expert_bytes,
                                                   down_expert_bytes,
                                                   &was_hit);
        if (slot < 0) return 0;
        if (was_hit) hits++;
        else misses++;
    }
    /* Global band selection happens in ds4.c before these per-layer lists are
     * formed.  Report only quantities whose units are valid here; cache->count
     * is global for the size class and must not be presented as a layer rank. */
    fprintf(stderr,
            "ds4: CUDA RAM expert cache seeded layer=%u source_entries=%u "
            "resident_total=%u/%u\n",
            layer,
            n_experts,
            cache->count,
            cache->capacity);
    if (getenv("DS4_CUDA_STREAMING_HOST_CACHE_VERBOSE")) {
        fprintf(stderr,
                "ds4: CUDA RAM expert cache preloaded layer=%u experts=%u hits=%u misses=%u count=%u/%u\n",
                layer,
                n_experts,
                hits,
                misses,
                cache->count,
                cache->capacity);
    }
    return 1;
}

__global__ static void embed_token_hc_kernel(float *out, const unsigned short *w, uint32_t token, uint32_t n_embd, uint32_t n_hc) {
    uint32_t i = blockIdx.x * blockDim.x + threadIdx.x;
    uint32_t n = n_embd * n_hc;
    if (i >= n) return;
    uint32_t e = i % n_embd;
    out[i] = __half2float(reinterpret_cast<const __half *>(w)[(uint64_t)token * n_embd + e]);
}

__global__ static void embed_tokens_hc_kernel(
        float *out,
        const int32_t *tokens,
        const __half *w,
        uint32_t n_vocab,
        uint32_t n_tokens,
        uint32_t n_embd,
        uint32_t n_hc) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * n_hc * n_embd;
    if (gid >= n) return;
    uint32_t d = gid % n_embd;
    uint64_t tmp = gid / n_embd;
    uint32_t t = tmp / n_hc;
    int32_t tok_i = tokens[t];
    uint32_t tok = tok_i < 0 ? 0u : (uint32_t)tok_i;
    if (tok >= n_vocab) tok = 0;
    out[gid] = __half2float(w[(uint64_t)tok * n_embd + d]);
}

__global__ static void matmul_f16_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;

    float sum = 0.0f;
    const __half *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = threadIdx.x; i < in_dim; i += blockDim.x) {
        sum += __half2float(wr[i]) * xr[i];
    }

    __shared__ float partial[256];
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) out[tok * out_dim + row] = partial[0];
}

__global__ static void matmul_f16_serial_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok || threadIdx.x != 0) return;

    float sum = 0.0f;
    const __half *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = 0; i < in_dim; i++) {
        sum += __half2float(wr[i]) * xr[i];
    }
    out[tok * out_dim + row] = sum;
}

__global__ static void matmul_f16_ordered_chunks_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;

    __shared__ float partial[32];
    const uint32_t tid = threadIdx.x;
    float sum = 0.0f;
    const uint64_t chunk = (in_dim + 31u) / 32u;
    const uint64_t k0 = (uint64_t)tid * chunk;
    uint64_t k1 = k0 + chunk;
    if (k1 > in_dim) k1 = in_dim;
    const __half *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = k0; i < k1; i++) {
        sum += __half2float(wr[i]) * xr[i];
    }
    partial[tid] = sum;
    __syncthreads();
    if (tid == 0) {
        float total = 0.0f;
        for (uint32_t i = 0; i < 32u; i++) total += partial[i];
        out[tok * out_dim + row] = total;
    }
}

__global__ static void matmul_f16_small_out_hx_ordered_chunks_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim) {
    uint64_t row = (uint64_t)blockIdx.x;
    if (row >= out_dim) return;

    __shared__ float partial[32];
    const uint32_t tid = threadIdx.x;
    float sum = 0.0f;
    const uint64_t chunk = (in_dim + 31u) / 32u;
    const uint64_t k0 = (uint64_t)tid * chunk;
    uint64_t k1 = k0 + chunk;
    if (k1 > in_dim) k1 = in_dim;
    const __half *wr = w + row * in_dim;
    for (uint64_t i = k0; i < k1; i++) {
        const float xv = __half2float(__float2half(x[i]));
        sum += __half2float(wr[i]) * xv;
    }
    partial[tid] = sum;
    __syncthreads();
    if (tid == 0) {
        float total = 0.0f;
        for (uint32_t i = 0; i < 32u; i++) total += partial[i];
        out[row] = total;
    }
}

__global__ static void matmul_f16_small_out_batch_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    const uint64_t tok = (uint64_t)blockIdx.x;
    const uint32_t tid = threadIdx.x;
    if (tok >= n_tok || out_dim > 32u || blockDim.x != 256u) return;

    float acc[32];
    #pragma unroll
    for (uint32_t r = 0; r < 32u; r++) acc[r] = 0.0f;

    const float *xr = x + tok * in_dim;
    for (uint64_t i = tid; i < in_dim; i += 256u) {
        const float xv = xr[i];
        #pragma unroll
        for (uint32_t r = 0; r < 32u; r++) {
            if (r < out_dim) {
                acc[r] += __half2float(w[(uint64_t)r * in_dim + i]) * xv;
            }
        }
    }

    __shared__ float partial[32 * 256];
    #pragma unroll
    for (uint32_t r = 0; r < 32u; r++) {
        if (r < out_dim) partial[r * 256u + tid] = acc[r];
    }
    __syncthreads();

    for (uint32_t stride = 128u; stride > 0u; stride >>= 1u) {
        if (tid < stride) {
            #pragma unroll
            for (uint32_t r = 0; r < 32u; r++) {
                if (r < out_dim) {
                    partial[r * 256u + tid] += partial[r * 256u + tid + stride];
                }
            }
        }
        __syncthreads();
    }

    if (tid == 0) {
        #pragma unroll
        for (uint32_t r = 0; r < 32u; r++) {
            if (r < out_dim) out[tok * out_dim + r] = partial[r * 256u];
        }
    }
}

__global__ static void matmul_f16_pair_ordered_chunks_kernel(
        float *out0,
        float *out1,
        const __half *w0,
        const __half *w1,
        const float *x,
        uint64_t in_dim,
        uint64_t out0_dim,
        uint64_t out1_dim) {
    uint64_t row = (uint64_t)blockIdx.x;
    if (row >= out0_dim && row >= out1_dim) return;

    __shared__ float partial0[32];
    __shared__ float partial1[32];
    const uint32_t tid = threadIdx.x;
    float sum0 = 0.0f;
    float sum1 = 0.0f;
    const uint64_t chunk = (in_dim + 31u) / 32u;
    const uint64_t k0 = (uint64_t)tid * chunk;
    uint64_t k1 = k0 + chunk;
    if (k1 > in_dim) k1 = in_dim;
    const __half *wr0 = row < out0_dim ? w0 + row * in_dim : w0;
    const __half *wr1 = row < out1_dim ? w1 + row * in_dim : w1;
    for (uint64_t i = k0; i < k1; i++) {
        const float xv = x[i];
        if (row < out0_dim) sum0 += __half2float(wr0[i]) * xv;
        if (row < out1_dim) sum1 += __half2float(wr1[i]) * xv;
    }
    partial0[tid] = sum0;
    partial1[tid] = sum1;
    __syncthreads();
    if (tid == 0) {
        float total0 = 0.0f;
        float total1 = 0.0f;
        for (uint32_t i = 0; i < 32u; i++) {
            total0 += partial0[i];
            total1 += partial1[i];
        }
        if (row < out0_dim) out0[row] = total0;
        if (row < out1_dim) out1[row] = total1;
    }
}

/* Preserve the 256-thread halving tree: combine the eight warp partials
 * before reducing within the first warp. Only two block barriers are needed. */
__device__ __forceinline__ static float block_sum_f32_256(float v, float *partial) {
    const uint32_t t = threadIdx.x;
    partial[t] = v;
    __syncthreads();
    if (t < 32u) {
        v = ((partial[t] + partial[t + 128u]) +
             (partial[t + 64u] + partial[t + 192u])) +
            ((partial[t + 32u] + partial[t + 160u]) +
             (partial[t + 96u] + partial[t + 224u]));
        for (uint32_t s = 16u; s; s >>= 1u)
            v += __shfl_down_sync(0xffffffffu, v, s);
        if (t == 0u) partial[0] = v;
    }
    __syncthreads();
    return partial[0];
}

__global__ static void matmul_f32_kernel(
        float *out,
        const float *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;

    float sum = 0.0f;
    const float *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = threadIdx.x; i < in_dim; i += blockDim.x) {
        sum += wr[i] * xr[i];
    }

    __shared__ float partial[256];
    sum = block_sum_f32_256(sum, partial);
    if (threadIdx.x == 0) out[tok * out_dim + row] = sum;
}

__global__ static void repeat_hc_kernel(float *out, const float *row, uint32_t n_embd, uint32_t n_hc) {
    uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_embd * n_hc;
    if (i >= n) return;
    out[i] = row[i % n_embd];
}

__global__ static void repeat_hc_rows_kernel(float *out, const float *rows, uint32_t n_tokens, uint32_t n_embd, uint32_t n_hc) {
    uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * n_hc * n_embd;
    if (i >= n) return;

    uint64_t hc_row = (uint64_t)n_hc * n_embd;
    uint64_t tok = i / hc_row;
    uint64_t embd = i % n_embd;
    out[i] = rows[tok * n_embd + embd];
}

__global__ static void pack_slot_rows_f32_kernel(float *out, const float *slots, uint32_t n_rows, uint32_t width, uint32_t n_slots, uint32_t slot_cap) {
    uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_rows * n_slots * width;
    if (i >= n) return;

    uint64_t col = i % width;
    uint64_t slot = (i / width) % n_slots;
    uint64_t row = i / ((uint64_t)n_slots * width);
    out[i] = slots[((slot * slot_cap) + row) * width + col];
}

__global__ static void f32_to_f16_kernel(__half *out, const float *x, uint64_t n) {
    uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) out[i] = __float2half(x[i]);
}

__global__ static void f16_to_f32_kernel(float *out, const __half *x, uint64_t n) {
    uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) out[i] = __half2float(x[i]);
}

__global__ static void f32_rows_to_q8_kv_kernel(
        char *dst,
        const float *src,
        uint32_t rows,
        uint32_t head_dim,
        uint64_t dst_row_bytes) {
    uint32_t row = blockIdx.x;
    if (row >= rows || head_dim == 0) return;
    __shared__ float partial[256];
    float local_max = 0.0f;
    const float *src_row = src + (uint64_t)row * head_dim;
    for (uint32_t d = threadIdx.x; d < head_dim; d += blockDim.x) {
        local_max = fmaxf(local_max, fabsf(src_row[d]));
    }
    partial[threadIdx.x] = local_max;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            partial[threadIdx.x] = fmaxf(partial[threadIdx.x],
                                         partial[threadIdx.x + stride]);
        }
        __syncthreads();
    }
    char *dst_row = dst + (uint64_t)row * dst_row_bytes;
    float scale = partial[0] > 0.0f ? partial[0] / 127.0f : 1.0f;
    if (threadIdx.x == 0) {
        *((float *)dst_row) = scale;
    }
    __syncthreads();
    int8_t *q = (int8_t *)(dst_row + sizeof(float));
    const float inv_scale = 1.0f / scale;
    for (uint32_t d = threadIdx.x; d < head_dim; d += blockDim.x) {
        int v = __float2int_rn(src_row[d] * inv_scale);
        if (v > 127) v = 127;
        if (v < -127) v = -127;
        q[d] = (int8_t)v;
    }
}

__global__ static void q8_kv_to_f32_kernel(
        float *out,
        const char *src,
        uint32_t rows,
        uint32_t head_dim,
        uint64_t src_row_bytes) {
    uint64_t idx = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)rows * head_dim;
    if (idx >= n || head_dim == 0) return;
    uint32_t row = (uint32_t)(idx / head_dim);
    uint32_t d = (uint32_t)(idx - (uint64_t)row * head_dim);
    const char *src_row = src + (uint64_t)row * src_row_bytes;
    const float scale = *((const float *)src_row);
    const int8_t q = ((const int8_t *)(src_row + sizeof(float)))[d];
    out[idx] = scale * (float)q;
}

static uint64_t cuda_comp_kv_row_bytes(uint32_t format, uint32_t head_dim) {
    if (format == DS4_GPU_COMP_KV_FORMAT_F16) {
        return (uint64_t)head_dim * sizeof(__half);
    }
    if (format == DS4_GPU_COMP_KV_FORMAT_Q8) {
        return sizeof(float) + (uint64_t)head_dim * sizeof(int8_t);
    }
    return (uint64_t)head_dim * sizeof(float);
}

static ds4_gpu_tensor *cuda_comp_kv_to_f32_tensor(
        const ds4_gpu_tensor *comp_kv,
        uint32_t format,
        uint32_t n_comp,
        uint32_t head_dim,
        const char *what) {
    if (!comp_kv || n_comp == 0 || head_dim == 0) return NULL;
    const uint64_t count = (uint64_t)n_comp * head_dim;
    if (count / head_dim != (uint64_t)n_comp ||
        count > UINT64_MAX / sizeof(float)) {
        fprintf(stderr,
                "ds4: CUDA compressed KV expansion overflow for %s\n",
                what ? what : "attention");
        return NULL;
    }
    const uint64_t src_row_bytes = cuda_comp_kv_row_bytes(format, head_dim);
    if ((uint64_t)n_comp > UINT64_MAX / src_row_bytes) return NULL;
    const uint64_t src_bytes = (uint64_t)n_comp * src_row_bytes;
    const uint64_t dst_bytes = count * sizeof(float);
    if (comp_kv->bytes < src_bytes) {
        fprintf(stderr,
                "ds4: CUDA compressed KV buffer too small for %s (%llu < %llu)\n",
                what ? what : "attention",
                (unsigned long long)comp_kv->bytes,
                (unsigned long long)src_bytes);
        return NULL;
    }
    ds4_gpu_tensor *f32 = ds4_gpu_tensor_alloc(dst_bytes);
    if (!f32) return NULL;
    if (format == DS4_GPU_COMP_KV_FORMAT_F16) {
        f16_to_f32_kernel<<<(count + 255u) / 256u, 256>>>(
                (float *)f32->ptr,
                (const __half *)comp_kv->ptr,
                count);
    } else if (format == DS4_GPU_COMP_KV_FORMAT_Q8) {
        q8_kv_to_f32_kernel<<<(count + 255u) / 256u, 256>>>(
                (float *)f32->ptr,
                (const char *)comp_kv->ptr,
                n_comp,
                head_dim,
                src_row_bytes);
    } else {
        ds4_gpu_tensor_free(f32);
        return NULL;
    }
    if (!cuda_ok(cudaGetLastError(),
                 what ? what : "compressed KV to f32 launch")) {
        ds4_gpu_tensor_free(f32);
        return NULL;
    }
    if (getenv("DS4_CUDA_KV_CACHE_VERBOSE")) {
        fprintf(stderr,
                "ds4: CUDA expanded %s compressed KV for %s: rows=%u dim=%u bytes %.2f MiB -> %.2f MiB\n",
                format == DS4_GPU_COMP_KV_FORMAT_Q8 ? "Q8" : "FP16",
                what ? what : "attention",
                n_comp,
                head_dim,
                (double)src_bytes / 1048576.0,
                (double)dst_bytes / 1048576.0);
    }
    return f32;
}

__device__ static float warp_sum_f32(float v) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(0xffffffffu, v, offset);
    }
    return v;
}

__device__ static float warp_max_f32(float v) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        v = fmaxf(v, __shfl_down_sync(0xffffffffu, v, offset));
    }
    return v;
}

__device__ static float dot4_f32(float4 a, float4 b) {
    return a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
}

template <uint32_t COMP_FORMAT>
__device__ __forceinline__ static float cuda_comp_kv_load_scalar(
        const void *comp_kv,
        uint64_t row,
        uint32_t d,
        uint32_t head_dim) {
    if (COMP_FORMAT == DS4_GPU_COMP_KV_FORMAT_F16) {
        return __half2float(((const __half *)comp_kv)[row * (uint64_t)head_dim + d]);
    }
    if (COMP_FORMAT == DS4_GPU_COMP_KV_FORMAT_Q8) {
        const char *row_ptr = (const char *)comp_kv +
            row * (sizeof(float) + (uint64_t)head_dim * sizeof(int8_t));
        const float scale = *((const float *)row_ptr);
        const int8_t q = ((const int8_t *)(row_ptr + sizeof(float)))[d];
        return scale * (float)q;
    }
    return ((const float *)comp_kv)[row * (uint64_t)head_dim + d];
}

template <uint32_t COMP_FORMAT>
__device__ __forceinline__ static float4 cuda_comp_kv_load4(
        const void *comp_kv,
        uint64_t row,
        uint32_t c4,
        uint32_t head_dim) {
    const uint64_t base = row * (uint64_t)head_dim + (uint64_t)c4 * 4u;
    if (COMP_FORMAT == DS4_GPU_COMP_KV_FORMAT_F16) {
        const __half *h = (const __half *)comp_kv + base;
        return make_float4(__half2float(h[0]),
                           __half2float(h[1]),
                           __half2float(h[2]),
                           __half2float(h[3]));
    }
    if (COMP_FORMAT == DS4_GPU_COMP_KV_FORMAT_Q8) {
        const char *row_ptr = (const char *)comp_kv +
            row * (sizeof(float) + (uint64_t)head_dim * sizeof(int8_t));
        const float scale = *((const float *)row_ptr);
        const int8_t *q = (const int8_t *)(row_ptr + sizeof(float)) + (uint64_t)c4 * 4u;
        return make_float4(scale * (float)q[0],
                           scale * (float)q[1],
                           scale * (float)q[2],
                           scale * (float)q[3]);
    }
    return ((const float4 *)((const float *)comp_kv + row * (uint64_t)head_dim))[c4];
}

__device__ __forceinline__ static int32_t load_i8x4_i32_aligned(const int8_t *p) {
    return *(const int32_t *)p;
}

__device__ __forceinline__ static int32_t load_i8x4_i32_unaligned(const int8_t *p) {
    /* Raw Q8_0 blocks have a 34-byte stride: two-byte, not four-byte,
     * alignment. Both loads stay inside the requested four weight bytes. */
    const uint16_t *u = (const uint16_t *)p;
    return (int32_t)((uint32_t)u[0] | ((uint32_t)u[1] << 16));
}

__device__ __forceinline__ static int32_t dot_i8x32_dp4a(const int8_t *a, const int8_t *b) {
    int32_t dot = 0;
#pragma unroll
    for (uint32_t i = 0; i < 32u; i += 4u) {
        dot = __dp4a(load_i8x4_i32_unaligned(a + i), load_i8x4_i32_aligned(b + i), dot);
    }
    return dot;
}

__device__ __forceinline__ static int32_t dot_i8_block(const int8_t *a, const int8_t *b, uint64_t n, int use_dp4a) {
    if (use_dp4a && n == 32u) return dot_i8x32_dp4a(a, b);
    int32_t dot = 0;
    for (uint64_t i = 0; i < n; i++) dot += (int32_t)a[i] * (int32_t)b[i];
    return dot;
}

__global__ static void quantize_q8_0_f32_kernel(
        int8_t *xq,
        float *xscale,
        const float *x,
        uint64_t in_dim,
        uint64_t blocks) {
    uint64_t b = blockIdx.x;
    uint64_t tok = blockIdx.y;
    if (b >= blocks) return;
    uint64_t i0 = b * 32;
    uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
    const float *xr = x + tok * in_dim + i0;

    float a = 0.0f;
    if (threadIdx.x < bn) a = fabsf(xr[threadIdx.x]);
    __shared__ float vals[32];
    vals[threadIdx.x] = a;
    __syncthreads();
    for (uint32_t stride = 16; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) vals[threadIdx.x] = fmaxf(vals[threadIdx.x], vals[threadIdx.x + stride]);
        __syncthreads();
    }
    const float d = vals[0] / 127.0f;
    const float id = d != 0.0f ? 1.0f / d : 0.0f;
    if (threadIdx.x == 0) xscale[tok * blocks + b] = d;
    int8_t *dst = xq + (tok * blocks + b) * 32;
    if (threadIdx.x < bn) {
        int v = (int)lrintf(xr[threadIdx.x] * id);
        v = v > 127 ? 127 : (v < -128 ? -128 : v);
        dst[threadIdx.x] = (int8_t)v;
    } else {
        dst[threadIdx.x] = 0;
    }
}

__global__ static void quantize_q8_0_group_slice_rows_kernel(
        int8_t *xq,
        float *xscale,
        const float *x,
        uint64_t group_dim,
        uint64_t blocks,
        uint32_t n_groups_total,
        uint32_t group0,
        uint32_t group_cnt) {
    const uint64_t b = blockIdx.x;
    const uint64_t packed_row = blockIdx.y;
    if (b >= blocks) return;
    const uint64_t token = packed_row / group_cnt;
    const uint64_t group = group0 + packed_row - token * group_cnt;
    const uint64_t i0 = b * 32u;
    const uint64_t bn = group_dim - i0 < 32u ? group_dim - i0 : 32u;
    const float *xr = x +
        (token * n_groups_total + group) * group_dim + i0;

    float a = 0.0f;
    if (threadIdx.x < bn) a = fabsf(xr[threadIdx.x]);
    __shared__ float vals[32];
    vals[threadIdx.x] = a;
    __syncthreads();
    for (uint32_t stride = 16u; stride > 0u; stride >>= 1u) {
        if (threadIdx.x < stride) {
            vals[threadIdx.x] =
                fmaxf(vals[threadIdx.x], vals[threadIdx.x + stride]);
        }
        __syncthreads();
    }
    const float d = vals[0] / 127.0f;
    const float id = d != 0.0f ? 1.0f / d : 0.0f;
    if (threadIdx.x == 0u) xscale[packed_row * blocks + b] = d;
    int8_t *dst = xq + (packed_row * blocks + b) * 32u;
    if (threadIdx.x < bn) {
        int v = (int)lrintf(xr[threadIdx.x] * id);
        v = v > 127 ? 127 : (v < -128 ? -128 : v);
        dst[threadIdx.x] = (int8_t)v;
    } else {
        dst[threadIdx.x] = 0;
    }
}

__global__ static void matmul_q8_0_preq_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok,
        uint64_t blocks,
        int use_dp4a) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;
    const unsigned char *wr = w + row * blocks * 34;
    const int8_t *xqr = xq + tok * blocks * 32;
    const float *xsr = xscale + tok * blocks;
    float acc = 0.0f;
    for (uint64_t b = threadIdx.x; b < blocks; b += blockDim.x) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xqr + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xsr[b] * (float)dot;
    }
    __shared__ float partial[256];
    partial[threadIdx.x] = acc;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) out[tok * out_dim + row] = partial[0];
}

__global__ static void matmul_q8_0_preq_warp8_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        int use_dp4a) {
    uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint64_t tok = (uint64_t)blockIdx.y;
    uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim) return;
    const unsigned char *wr = w + row * blocks * 34;
    const int8_t *xqr = xq + tok * blocks * 32u;
    const float *xsr = xscale + tok * blocks;
    float acc = 0.0f;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xqr + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xsr[b] * (float)dot;
    }
    acc = warp_sum_f32(acc);
    if (lane == 0) out[tok * out_dim + row] = acc;
}

__device__ __forceinline__ static uint32_t q8_top1_float_ordered_key(float v) {
    const uint32_t u = __float_as_uint(v);
    return (u & 0x80000000u) ? ~u : (u ^ 0x80000000u);
}

__device__ __forceinline__ static uint64_t q8_top1_pack_key(float v, uint32_t idx) {
    return ((uint64_t)q8_top1_float_ordered_key(v) << 32u) |
           (uint64_t)(0xffffffffu - idx);
}

__device__ __forceinline__ static float q8_top1_unpack_value(uint32_t ordered) {
    const uint32_t u = (ordered & 0x80000000u)
        ? (ordered ^ 0x80000000u)
        : ~ordered;
    return __uint_as_float(u);
}

__global__ static void matmul_q8_0_top1_preq_warp8_kernel(
        unsigned long long *best_key,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        uint32_t index_offset,
        int use_dp4a) {
    const uint32_t warp = threadIdx.x >> 5u;
    const uint32_t lane = threadIdx.x & 31u;
    const uint64_t row = (uint64_t)blockIdx.x * 8u + warp;
    const bool valid = row < out_dim;
    float acc = 0.0f;

    if (valid) {
        const unsigned char *wr = w + row * blocks * 34;
        for (uint64_t b = lane; b < blocks; b += 32u) {
            uint64_t i0 = b * 32;
            uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
            const __half *scale_h = (const __half *)(wr + b * 34);
            const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
            const int8_t *xqb = xq + b * 32;
            int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc += __half2float(*scale_h) * xscale[b] * (float)dot;
        }
    }
    acc = warp_sum_f32(acc);

    __shared__ unsigned long long keys[8];
    if (lane == 0u) {
        keys[warp] = valid
            ? (unsigned long long)q8_top1_pack_key(acc, index_offset + (uint32_t)row)
            : 0ull;
    }
    __syncthreads();

    if (threadIdx.x == 0u) {
        unsigned long long block_best = keys[0];
        #pragma unroll
        for (uint32_t i = 1u; i < 8u; i++) {
            if (keys[i] > block_best) block_best = keys[i];
        }
        (void)atomicMax(best_key, block_best);
    }
}

__global__ static void matmul_q8_0_top1_unpack_kernel(
        uint32_t *selected,
        float *values,
        const unsigned long long *best_key) {
    if (threadIdx.x != 0u || blockIdx.x != 0u) return;
    const uint64_t key = (uint64_t)best_key[0];
    const uint32_t ordered = (uint32_t)(key >> 32u);
    const uint32_t idx = 0xffffffffu - (uint32_t)key;
    selected[0] = idx;
    values[0] = q8_top1_unpack_value(ordered);
}

__global__ static void matmul_q8_0_kslice_preq_warp8_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t slice_dim,
        uint64_t out_dim,
        uint64_t full_blocks,
        uint64_t block_start,
        uint64_t slice_blocks,
        int use_dp4a) {
    const uint64_t row =
        (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint64_t tok = blockIdx.y;
    const uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim) return;
    out += tok * out_dim;
    xq += tok * slice_blocks * 32u;
    xscale += tok * slice_blocks;
    const unsigned char *wr =
        w + row * full_blocks * 34u + block_start * 34u;
    float acc = 0.0f;
    for (uint64_t b = lane; b < slice_blocks; b += 32u) {
        uint64_t i0 = b * 32u;
        uint64_t bn = slice_dim - i0 < 32u ? slice_dim - i0 : 32u;
        const __half *scale_h = (const __half *)(wr + b * 34u);
        const int8_t *qs = (const int8_t *)(wr + b * 34u + 2u);
        const int8_t *xqb = xq + b * 32u;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xscale[b] * (float)dot;
    }
    acc = warp_sum_f32(acc);
    if (lane == 0) out[row] = acc;
}

__global__ static void matmul_q8_0_pair_preq_warp8_kernel(
        float *out0,
        float *out1,
        const unsigned char *w0,
        const unsigned char *w1,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out0_dim,
        uint64_t out1_dim,
        uint64_t blocks,
        int use_dp4a) {
    uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint64_t tok = (uint64_t)blockIdx.y;
    uint32_t lane = threadIdx.x & 31u;
    if (row >= out0_dim && row >= out1_dim) return;
    float acc0 = 0.0f;
    float acc1 = 0.0f;
    const unsigned char *wr0 = row < out0_dim ? w0 + row * blocks * 34 : NULL;
    const unsigned char *wr1 = row < out1_dim ? w1 + row * blocks * 34 : NULL;
    const int8_t *xqr = xq + tok * blocks * 32u;
    const float *xsr = xscale + tok * blocks;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const int8_t *xqb = xqr + b * 32;
        const float xs = xsr[b];
        if (wr0) {
            const __half *scale_h = (const __half *)(wr0 + b * 34);
            const int8_t *qs = (const int8_t *)(wr0 + b * 34 + 2);
            int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc0 += __half2float(*scale_h) * xs * (float)dot;
        }
        if (wr1) {
            const __half *scale_h = (const __half *)(wr1 + b * 34);
            const int8_t *qs = (const int8_t *)(wr1 + b * 34 + 2);
            int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc1 += __half2float(*scale_h) * xs * (float)dot;
        }
    }
    acc0 = warp_sum_f32(acc0);
    acc1 = warp_sum_f32(acc1);
    if (lane == 0) {
        if (row < out0_dim) out0[tok * out0_dim + row] = acc0;
        if (row < out1_dim) out1[tok * out1_dim + row] = acc1;
    }
}

__global__ static void shared_mid_q8_0_preq_warp8_exact_kernel(
        float *mid,
        const unsigned char *gate_w,
        const unsigned char *up_w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        float clamp,
        const int32_t *selected,
        uint32_t expert_split,
        bool home_rank,
        int use_dp4a) {
    const uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim) return;
    if (selected) {
        /* Complementary predicates select exactly one writer; ties stay on
         * the home rank to avoid an unnecessary peer store. */
        uint32_t home_count = 0u;
        uint32_t peer_count = 0u;
        #pragma unroll
        for (uint32_t i = 0; i < 6u; i++) {
            const int32_t expert = selected[i];
            if (expert >= 0 && (uint32_t)expert < expert_split) {
                home_count++;
            } else if (expert >= 0 &&
                       (uint32_t)expert < 2u * expert_split) {
                peer_count++;
            }
        }
        const bool assigned = home_rank
            ? home_count <= peer_count : peer_count < home_count;
        if (!assigned) return;
    }
    const unsigned char *gate_row = gate_w + row * blocks * 34u;
    const unsigned char *up_row = up_w + row * blocks * 34u;
    float gate = 0.0f;
    float up = 0.0f;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        const uint64_t i0 = b * 32u;
        const uint64_t bn = in_dim - i0 < 32u ? in_dim - i0 : 32u;
        const int8_t *xqb = xq + b * 32u;
        const float xs = xscale[b];
        const unsigned char *gb = gate_row + b * 34u;
        const unsigned char *ub = up_row + b * 34u;
        gate += __half2float(*(const __half *)gb) * xs *
                (float)dot_i8_block((const int8_t *)(gb + 2u), xqb, bn,
                                    use_dp4a);
        up += __half2float(*(const __half *)ub) * xs *
              (float)dot_i8_block((const int8_t *)(ub + 2u), xqb, bn,
                                  use_dp4a);
    }
    gate = warp_sum_f32(gate);
    up = warp_sum_f32(up);
    if (lane == 0u) {
        if (clamp > 1.0e-6f) {
            gate = fminf(gate, clamp);
            up = fminf(fmaxf(up, -clamp), clamp);
        }
        const float silu = gate / (1.0f + expf(-gate));
        mid[row] = silu * up * 1.0f;
    }
}

__global__ static void matmul_q8_0_pair_preq_batch_kernel(
        float *out0,
        float *out1,
        const unsigned char *w0,
        const unsigned char *w1,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out0_dim,
        uint64_t out1_dim,
        uint64_t n_tok,
        uint64_t blocks,
        int use_dp4a) {
    const uint64_t row = (uint64_t)blockIdx.x;
    const uint64_t tok = (uint64_t)blockIdx.y;
    if (tok >= n_tok) return;
    const int has0 = row < out0_dim;
    const int has1 = row < out1_dim;
    if (!has0 && !has1) return;

    const unsigned char *wr0 = has0 ? w0 + row * blocks * 34u : NULL;
    const unsigned char *wr1 = has1 ? w1 + row * blocks * 34u : NULL;
    const int8_t *xqr = xq + tok * blocks * 32u;
    const float *xsr = xscale + tok * blocks;
    float acc0 = 0.0f;
    float acc1 = 0.0f;

    for (uint64_t b = threadIdx.x; b < blocks; b += blockDim.x) {
        const uint64_t i0 = b * 32u;
        const uint64_t bn = in_dim - i0 < 32u ? in_dim - i0 : 32u;
        const int8_t *xqb = xqr + b * 32u;
        const float xs = xsr[b];
        if (has0) {
            const __half *scale_h = (const __half *)(wr0 + b * 34u);
            const int8_t *qs = (const int8_t *)(wr0 + b * 34u + 2u);
            const int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc0 += __half2float(*scale_h) * xs * (float)dot;
        }
        if (has1) {
            const __half *scale_h = (const __half *)(wr1 + b * 34u);
            const int8_t *qs = (const int8_t *)(wr1 + b * 34u + 2u);
            const int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc1 += __half2float(*scale_h) * xs * (float)dot;
        }
    }

    __shared__ float partial0[256];
    __shared__ float partial1[256];
    partial0[threadIdx.x] = acc0;
    partial1[threadIdx.x] = acc1;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1u; stride > 0u; stride >>= 1u) {
        if (threadIdx.x < stride) {
            partial0[threadIdx.x] += partial0[threadIdx.x + stride];
            partial1[threadIdx.x] += partial1[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        if (has0) out0[tok * out0_dim + row] = partial0[0];
        if (has1) out1[tok * out1_dim + row] = partial1[0];
    }
}

__global__ static void matmul_q8_0_pair_preq_batch_tok2_exact_kernel(
        float *out0,
        float *out1,
        const unsigned char *w0,
        const unsigned char *w1,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out0_dim,
        uint64_t out1_dim,
        uint64_t n_tok,
        uint64_t blocks,
        int use_dp4a) {
    const uint64_t row = (uint64_t)blockIdx.x;
    const uint64_t tok0 = (uint64_t)blockIdx.y * 2u;
    if (tok0 >= n_tok) return;
    const int has0 = row < out0_dim;
    const int has1 = row < out1_dim;
    if (!has0 && !has1) return;
    const int valid1 = tok0 + 1u < n_tok;

    const unsigned char *wr0 = has0 ? w0 + row * blocks * 34u : NULL;
    const unsigned char *wr1 = has1 ? w1 + row * blocks * 34u : NULL;
    const int8_t *xqr0 = xq + tok0 * blocks * 32u;
    const int8_t *xqr1 = valid1 ? xqr0 + blocks * 32u : xqr0;
    const float *xsr0 = xscale + tok0 * blocks;
    const float *xsr1 = valid1 ? xsr0 + blocks : xsr0;
    float acc00 = 0.0f;
    float acc01 = 0.0f;
    float acc10 = 0.0f;
    float acc11 = 0.0f;

    for (uint64_t b = threadIdx.x; b < blocks; b += blockDim.x) {
        const uint64_t i0 = b * 32u;
        const uint64_t bn = in_dim - i0 < 32u ? in_dim - i0 : 32u;
        const int8_t *xqb0 = xqr0 + b * 32u;
        const int8_t *xqb1 = xqr1 + b * 32u;
        const float xs0 = xsr0[b];
        const float xs1 = valid1 ? xsr1[b] : 0.0f;
        if (has0) {
            const __half *scale_h = (const __half *)(wr0 + b * 34u);
            const int8_t *qs = (const int8_t *)(wr0 + b * 34u + 2u);
            const int dot0 = dot_i8_block(qs, xqb0, bn, use_dp4a);
            int dot1 = 0;
            if (valid1) dot1 = dot_i8_block(qs, xqb1, bn, use_dp4a);
            const float ws = __half2float(*scale_h);
            acc00 += ws * xs0 * (float)dot0;
            if (valid1) acc01 += ws * xs1 * (float)dot1;
        }
        if (has1) {
            const __half *scale_h = (const __half *)(wr1 + b * 34u);
            const int8_t *qs = (const int8_t *)(wr1 + b * 34u + 2u);
            const int dot0 = dot_i8_block(qs, xqb0, bn, use_dp4a);
            int dot1 = 0;
            if (valid1) dot1 = dot_i8_block(qs, xqb1, bn, use_dp4a);
            const float ws = __half2float(*scale_h);
            acc10 += ws * xs0 * (float)dot0;
            if (valid1) acc11 += ws * xs1 * (float)dot1;
        }
    }

    __shared__ float partial00[256];
    __shared__ float partial01[256];
    __shared__ float partial10[256];
    __shared__ float partial11[256];
    partial00[threadIdx.x] = acc00;
    partial01[threadIdx.x] = acc01;
    partial10[threadIdx.x] = acc10;
    partial11[threadIdx.x] = acc11;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1u; stride > 0u; stride >>= 1u) {
        if (threadIdx.x < stride) {
            partial00[threadIdx.x] += partial00[threadIdx.x + stride];
            partial01[threadIdx.x] += partial01[threadIdx.x + stride];
            partial10[threadIdx.x] += partial10[threadIdx.x + stride];
            partial11[threadIdx.x] += partial11[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        if (has0) {
            out0[tok0 * out0_dim + row] = partial00[0];
            if (valid1) out0[(tok0 + 1u) * out0_dim + row] = partial01[0];
        }
        if (has1) {
            out1[tok0 * out1_dim + row] = partial10[0];
            if (valid1) out1[(tok0 + 1u) * out1_dim + row] = partial11[0];
        }
    }
}

__device__ static float moe_owned_packed_combine_row(
        const float *home_slots,
        const float *peer_packed,
        const int32_t *selected,
        uint32_t row,
        uint32_t out_dim,
        uint32_t expert_split);

__global__ static void matmul_q8_0_hc_expand_preq_warp8_kernel(
        float *out_hc,
        float *block_out,
        const float *block_add,
        const float *block_add2,
        const float *owned_home_slots,
        const float *owned_peer_packed,
        const int32_t *owned_selected,
        const float *residual_hc,
        const float *split,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint32_t n_embd,
        uint32_t n_hc,
        uint64_t blocks,
        int has_add,
        int has_add2,
        int has_owned_slots,
        uint32_t owned_expert_split,
        int use_dp4a) {
    const uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim) return;
    const unsigned char *wr = w + row * blocks * 34;
    float acc = 0.0f;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        const uint64_t i0 = b * 32;
        const uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xq + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xscale[b] * (float)dot;
    }
    acc = warp_sum_f32(acc);
    if (lane == 0) {
        const uint32_t d = (uint32_t)row;
        block_out[d] = acc;
        float block_v = acc;
        if (has_owned_slots) {
            const float routed = moe_owned_packed_combine_row(
                    owned_home_slots,
                    owned_peer_packed,
                    owned_selected,
                    d,
                    (uint32_t)out_dim,
                    owned_expert_split);
            block_v = __fadd_rn(block_v, routed);
        } else if (has_add) {
            float add_v = block_add[d];
            if (has_add2) add_v += block_add2[d];
            block_v += add_v;
        }
        const float *post = split + n_hc;
        const float *comb = split + 2u * n_hc;
        for (uint32_t dst_hc = 0; dst_hc < n_hc; dst_hc++) {
            float hc_acc = block_v * post[dst_hc];
            for (uint32_t src_hc = 0; src_hc < n_hc; src_hc++) {
                const float comb_v = comb[dst_hc + (uint64_t)src_hc * n_hc];
                const float res_v = residual_hc[(uint64_t)src_hc * n_embd + d];
                hc_acc += comb_v * res_v;
            }
            out_hc[(uint64_t)dst_hc * n_embd + d] = hc_acc;
        }
    }
}

__global__ static void matmul_q8_0_kslice_hc_expand_add_preq_warp8_kernel(
        float *out_hc,
        float *block_out,
        const float *block_add,
        const float *residual_hc,
        const float *split,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t slice_dim,
        uint64_t out_dim,
        uint64_t full_blocks,
        uint64_t block_start,
        uint64_t slice_blocks,
        uint32_t n_embd,
        uint32_t n_hc,
        int use_dp4a) {
    const uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim) return;
    const unsigned char *wr = w + row * full_blocks * 34u + block_start * 34u;
    float acc = 0.0f;
    for (uint64_t b = lane; b < slice_blocks; b += 32u) {
        const uint64_t i0 = b * 32u;
        const uint64_t bn = slice_dim - i0 < 32u ? slice_dim - i0 : 32u;
        const __half *scale_h = (const __half *)(wr + b * 34u);
        const int8_t *qs = (const int8_t *)(wr + b * 34u + 2u);
        const int8_t *xqb = xq + b * 32u;
        const int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xscale[b] * (float)dot;
    }
    acc = warp_sum_f32(acc);
    if (lane == 0) {
        const uint32_t d = (uint32_t)row;
        block_out[d] = acc;
        const float block_v = acc + block_add[d];
        const float *post = split + n_hc;
        const float *comb = split + 2u * n_hc;
        for (uint32_t dst_hc = 0; dst_hc < n_hc; dst_hc++) {
            float hc_acc = block_v * post[dst_hc];
            for (uint32_t src_hc = 0; src_hc < n_hc; src_hc++) {
                const float comb_v = comb[dst_hc + (uint64_t)src_hc * n_hc];
                const float res_v = residual_hc[(uint64_t)src_hc * n_embd + d];
                hc_acc += comb_v * res_v;
            }
            out_hc[(uint64_t)dst_hc * n_embd + d] = hc_acc;
        }
    }
}

__global__ static void matmul_q8_0_preq_batch_warp8_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok,
        uint64_t blocks,
        int use_dp4a) {
    const uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint64_t tok = (uint64_t)blockIdx.y;
    const uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim || tok >= n_tok) return;

    const unsigned char *wr = w + row * blocks * 34;
    const int8_t *xqr = xq + tok * blocks * 32;
    const float *xsr = xscale + tok * blocks;
    float acc = 0.0f;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        const uint64_t i0 = b * 32;
        const uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xqr + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xsr[b] * (float)dot;
    }
    acc = warp_sum_f32(acc);
    if (lane == 0) out[tok * out_dim + row] = acc;
}

__global__ static void matmul_q8_0_preq_batch_warp8_tok2_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        int use_dp4a) {
    const uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    const uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim) return;

    const unsigned char *wr = w + row * blocks * 34u;
    const int8_t *xqr0 = xq;
    const int8_t *xqr1 = xq + blocks * 32u;
    const float *xsr0 = xscale;
    const float *xsr1 = xscale + blocks;
    float acc0 = 0.0f;
    float acc1 = 0.0f;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        const uint64_t i0 = b * 32u;
        const uint64_t bn = in_dim - i0 < 32u ? in_dim - i0 : 32u;
        const __half *scale_h = (const __half *)(wr + b * 34u);
        const int8_t *qs = (const int8_t *)(wr + b * 34u + 2u);
        const int8_t *xqb0 = xqr0 + b * 32u;
        const int8_t *xqb1 = xqr1 + b * 32u;
        int dot0 = 0;
        int dot1 = 0;
        if (use_dp4a && bn == 32u) {
#pragma unroll
            for (uint32_t i = 0; i < 32u; i += 4u) {
                const int32_t w4 = load_i8x4_i32_unaligned(qs + i);
                dot0 = __dp4a(w4, load_i8x4_i32_aligned(xqb0 + i), dot0);
                dot1 = __dp4a(w4, load_i8x4_i32_aligned(xqb1 + i), dot1);
            }
        } else {
            dot0 = dot_i8_block(qs, xqb0, bn, use_dp4a);
            dot1 = dot_i8_block(qs, xqb1, bn, use_dp4a);
        }
        const float ws = __half2float(*scale_h);
        acc0 += ws * xsr0[b] * (float)dot0;
        acc1 += ws * xsr1[b] * (float)dot1;
    }
    acc0 = warp_sum_f32(acc0);
    acc1 = warp_sum_f32(acc1);
    if (lane == 0) {
        out[row] = acc0;
        out[out_dim + row] = acc1;
    }
}

__global__ static void matmul_q8_0_preq_batch_warp8_tok4_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
