#include "ds4_cache_affinity_background.cuh"
#include "ds4_expert_restore_async.cuh"

extern "C" int ds4_gpu_cache_affinity_router_tensor(
    ds4_gpu_tensor *selected, ds4_gpu_tensor *weights, const ds4_gpu_tensor *probs,
    const void *model_map, uint64_t model_size, uint64_t bias_offset, bool has_bias,
    uint32_t layer, uint32_t position, uint32_t layers, uint32_t experts, uint32_t used,
    uint32_t rows, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset,
    uint64_t gate_bytes, uint64_t down_bytes, float scale, float lambda) {
    if (!g_stream_expert_cache_phase_decode || rows!=1u) return 1;
    if (g_affinity_anchor == 0.0f && g_affinity_calibrate_path.empty() && !getenv("DS4_CACHE_AFFINITY_PROFILE")) return 1;
    lambda=g_affinity_verify_active && g_affinity_verify_mean>=0 ? g_affinity_verify_mean : g_affinity_mean;
    const bool hard_verify=g_affinity_verify_active && g_affinity_verify_hard && cuda_affinity_ramp_factor(g_affinity_decoded)>=1.0f;
#ifdef DS4_EXTERNAL_DECODE
    const bool external = g_ds4x_external_mode != 0;
#else
    const bool external = false;
#endif
    if ((!g_ssd_streaming_mode && !external) || !selected || !weights || !probs || !model_map ||
        (experts != 256u && experts != 384u) || used != 6u || !rows || !layers || layer >= layers ||
        !isfinite(lambda) || lambda < 0.0f || lambda > 3.0f ||
        selected->bytes < (uint64_t)rows * used * 4u || weights->bytes < (uint64_t)rows * used * 4u ||
        probs->bytes < (uint64_t)rows * experts * 4u) return 0;
    if(layers>128u || !cuda_affinity_model(model_map,model_size,experts,layers)) return 0;
    const uint64_t decode_step=g_affinity_decoded;
    lambda *= cuda_affinity_ramp_factor(decode_step)*g_affinity_factor[layer];
    if(g_affinity_verify_active && g_affinity_verify_mean>=0)
        fprintf(stderr,"ds4: verify-only-bias position=%u layer=%u decode_mean=%.6g verify_mean=%.6g delta=%.6g\n",position,layer,g_affinity_mean,g_affinity_verify_mean,lambda);
    g_affinity_current_biased=lambda>0.0f;
    const int tier = ds4_tensor_device_idx(selected);
    cuda_router_residency residency = {};
#ifdef DS4_EXTERNAL_DECODE
    /* RAMFIX: external decode prices a RAM-resident expert between VRAM and storage.
     * LLAMADECODE_RAM_ROUTE_COST in [0,1] is its share of the miss penalty (0 = old
     * boolean residency). Selection only; combine weights stay the original probabilities. */
    static const float ram_route_cost = [] {
        const char *v = getenv("LLAMADECODE_RAM_ROUTE_COST"); char *end = nullptr;
        const float c = v && *v ? strtof(v, &end) : 0.5f;
        if (v && *v && (!end || *end || !(c >= 0.0f && c <= 1.0f))) { fprintf(stderr, "ds4: LLAMADECODE_RAM_ROUTE_COST must be in [0,1]\n"); return -1.0f; }
        fprintf(stderr, "LLAMADECODE_RAM_ROUTE_COST=%.3f\n", c); return c; }();
    if (ram_route_cost < 0.0f) return 0;
    if (external) residency.ram_cost = ram_route_cost;
    if (external) {
        if (!g_ds4x_residency_hook || !g_ds4x_residency_hook(g_ds4x_residency_user, layer, residency.tier, experts)) {
            fprintf(stderr, "LLAMADECODE_DS4X_RESIDENCY_FAILED layer=%u\n", layer); return 0;
        }
    }
#endif
    cuda_stream_expert_cache *v = &g_stream_expert_caches[
        cuda_stream_expert_cache_class_index(gate_bytes, down_bytes)];
    cuda_stream_host_expert_cache *h = &g_stream_host_expert_caches[
        cuda_stream_host_expert_cache_class_index(gate_bytes, down_bytes)];
    /* Snapshot existing slots once, using the point lookup's exact predicate. */
    for (uint32_t i = 0; !external && h->valid && i < h->capacity; i++) {
        const auto &slot = h->slots[i];
        if (slot.expert < experts && cuda_stream_expert_slot_matches(slot, model_map,
                model_size, layer, experts, slot.expert, gate_offset, up_offset,
                down_offset, gate_bytes, down_bytes)) residency.tier[slot.expert] = 2;
    }
    for (uint32_t i = 0; !external && v->valid && i < v->capacity; i++) {
        const auto &slot = v->slots[i];
        if (slot.expert < experts && cuda_stream_expert_slot_matches(slot, model_map,
                model_size, layer, experts, slot.expert, gate_offset, up_offset,
                down_offset, gate_bytes, down_bytes)) residency.tier[slot.expert] = 1;
    }
    const float *bias = NULL;
    if (has_bias) {
        if (bias_offset > model_size || model_size - bias_offset < experts * sizeof(float)) return 0;
        bias = (const float *)cuda_resolve_weight_ptr(model_map, bias_offset,
                    experts * sizeof(float), tier, "cache_affinity_router_bias");
        if (!bias) return 0;
    }
    cuda_router_affinity_metrics *device_metrics = (cuda_router_affinity_metrics *)
        cuda_tmp_alloc_on(tier, (uint64_t)rows * sizeof(*device_metrics), "cache affinity metrics");
    if (!device_metrics) return 0;
    ds4_affinity_confidence *device_confidence=NULL;
    std::vector<ds4_affinity_confidence> confidence_rows;
    ds4_affinity_resident_decision *device_hard=NULL;
    std::vector<ds4_affinity_resident_decision> hard_rows;
    if(hard_verify) {
        device_hard=(ds4_affinity_resident_decision *)cuda_tmp_alloc_on(tier,rows*sizeof(*device_hard),"verify hard resident metrics");
        if(!device_hard)return 0;
        hard_rows.resize(rows);
        cache_affinity_hard_resident_kernel<<<rows,1,0,cuda_decode_stream()>>>(
            (int32_t *)selected->ptr,(float *)weights->ptr,(const float *)probs->ptr,
            bias,residency,lambda,experts,used,scale,rows,device_metrics,device_hard);
    } else if(g_affinity_router_confidence) {
        device_confidence=(ds4_affinity_confidence *)cuda_tmp_alloc_on(tier,
            (uint64_t)rows*sizeof(*device_confidence),"router confidence metrics");
        if(!device_confidence)return 0;
        confidence_rows.resize(rows);
        cache_affinity_confidence_kernel<<<rows, 1, 0, cuda_decode_stream()>>>(
            (int32_t *)selected->ptr, (float *)weights->ptr, (const float *)probs->ptr,
            bias, residency, lambda, experts, used, scale, rows, device_metrics, device_confidence);
    } else if(g_affinity_warp_topk && lambda>0.0f) {
        cache_affinity_warp_kernel<<<rows, 32, 0, cuda_decode_stream()>>>(
            (int32_t *)selected->ptr, (float *)weights->ptr, (const float *)probs->ptr,
            bias, residency, lambda, experts, used, scale, rows, device_metrics);
    } else {
        cache_affinity_rerank_kernel<<<rows, 1, 0, cuda_decode_stream()>>>(
            (int32_t *)selected->ptr, (float *)weights->ptr, (const float *)probs->ptr,
            bias, residency, lambda, experts, used, scale, rows, device_metrics);
    }
    if (!cuda_ok(cudaGetLastError(), "cache affinity rerank")) return 0;
    static const bool external_log = getenv("LLAMADECODE_DS4X_AFFINITY_LOG") != NULL;
    /* External decode with no calibration, log or verify consumer: the
     * metrics have no reader (the host owns admission), so skip their
     * readback and its per-layer stream synchronization. */
    const bool metrics_unread = external && !external_log && g_affinity_calibrate_path.empty() &&
        !hard_verify && !g_affinity_router_confidence;
    std::vector<cuda_router_affinity_metrics> metrics(metrics_unread ? 0u : rows);
    if (!metrics_unread && (!cuda_ok(cudaMemcpyAsync(metrics.data(), device_metrics, rows * sizeof(*device_metrics),
            cudaMemcpyDeviceToHost, cuda_decode_stream()), "cache affinity metrics copy") ||
        (!hard_verify && g_affinity_router_confidence && !cuda_ok(cudaMemcpyAsync(confidence_rows.data(),
            device_confidence,rows*sizeof(*device_confidence),cudaMemcpyDeviceToHost,
            cuda_decode_stream()),"router confidence metrics copy")) ||
        (hard_verify && !cuda_ok(cudaMemcpyAsync(hard_rows.data(),device_hard,rows*sizeof(*device_hard),
            cudaMemcpyDeviceToHost,cuda_decode_stream()),"verify hard resident metrics copy")) ||
        !cuda_ok(cudaStreamSynchronize(cuda_decode_stream()), "cache affinity metrics sync"))) return 0;
    /* External: the host owns admission; ds4's own background promotion has no cache here. */
    if(!external && !cuda_affinity_background_prepare(gate_bytes,down_bytes))return 0;
    for (uint32_t t = 0; !metrics_unread && t < rows; t++) {
        const auto &m = metrics[t];
        if(!external) cuda_affinity_background_note(m,residency,model_map,model_size,layer,experts,
            gate_offset,up_offset,down_offset,gate_bytes,down_bytes);
        if(!g_affinity_calibrate_path.empty() && g_affinity_calibration[layer].size()<64u) {
            if(!isfinite(m.spread) || m.spread<0.0f) {fprintf(stderr,"ds4: invalid calibration score readback\n");return 0;}
            g_affinity_calibration[layer].push_back(m.spread);
        }
        if (!external || external_log) fprintf(stderr, "ds4: cache-affinity token=%u decode_step=%llu layer=%u mean=%.6g delta=%.6g stage=%s vram_hits=%u ram_hits=%u selections=%u vram_hit_rate=%.6f changed=%u spread=%.9g\n",
            position+t,(unsigned long long)decode_step,layer,g_affinity_mean,lambda,
            g_affinity_mean==0.0f?"off":decode_step<g_affinity_warmup?"warmup":cuda_affinity_ramp_factor(decode_step)<1.0f?"ramp":"biased",
            m.vram,m.ram,m.selections,(double)m.vram/m.selections,m.changed,m.spread);
        if(hard_verify)
            fprintf(stderr,"ds4: verify-resident decode_step=%llu layer=%u applied=%u protected_top=%u insufficient=%u residents=%u width=%.9g alternative=%.9g\n",
                (unsigned long long)decode_step,layer,hard_rows[t].applied,hard_rows[t].protected_top,
                hard_rows[t].insufficient_resident,hard_rows[t].resident_count,hard_rows[t].width,hard_rows[t].alternative);
        if(!hard_verify && g_affinity_router_confidence)
            fprintf(stderr,"ds4: router-confidence decode_step=%llu layer=%u replacement=%.9g width=%.9g min_delta=%.9g max_delta=%.9g protected=%u\n",
                (unsigned long long)decode_step,layer,confidence_rows[t].replacement,confidence_rows[t].width,
                confidence_rows[t].min_delta,confidence_rows[t].max_delta,confidence_rows[t].protected_count);
    }
    /* Protect the current selected demand set before choosing any upload victim.
     * Observe old residency before publication, avoiding false same-step churn. */
    if(!external && !cuda_affinity_background_harvest())return 0;
    if(layer+1u==layers) {
#if defined(_WIN32)
        if(g_affinity_cap && (g_affinity_decoded+1u)%32u==0u)
            for(uint32_t l=0;l<layers;l++)for(uint32_t e=0;e<experts;e++)g_affinity_displaced[l][e]/=2u;
#endif
        g_affinity_decoded++;
    }
    return 1;
}

extern "C" int ds4_gpu_router_select_tensor(ds4_gpu_tensor *selected, ds4_gpu_tensor *weights, ds4_gpu_tensor *probs, const void *model_map, uint64_t model_size, uint64_t bias_offset, uint64_t hash_offset, uint32_t hash_rows, uint32_t token, uint32_t n_expert, uint32_t n_expert_used, float expert_weight_scale, uint32_t n_expert_groups, uint32_t n_group_used, bool has_bias, bool hash_mode, const ds4_gpu_tensor *logits) {
    if (!selected || !weights || !probs || !logits || !model_map || n_expert_groups > 1u || n_group_used > 0u) return 0;
    if ((n_expert != 256u && n_expert != 384u) || n_expert_used != 6u || fabsf(expert_weight_scale - 1.5f) > 1.0e-6f ||
        logits->bytes < n_expert * sizeof(float) || probs->bytes < n_expert * sizeof(float) ||
        selected->bytes < 6u * sizeof(int32_t) || weights->bytes < 6u * sizeof(float)) return 0;
    int32_t tok = (int32_t)token;
    int ok = 1;
    const float *bias = NULL;
    const int32_t *hash = NULL;
    const int logical_tier = ds4_tensor_device_idx(selected);
    if (ok && has_bias && !hash_mode) {
        if (bias_offset > model_size || model_size - bias_offset < n_expert * sizeof(float)) ok = 0;
        else bias = (const float *)cuda_resolve_weight_ptr(model_map, bias_offset, n_expert * sizeof(float), logical_tier, "router_bias");
        if (!bias) ok = 0;
    }
    if (ok && hash_mode) {
        const uint64_t hash_bytes = (uint64_t)hash_rows * 6u * sizeof(int32_t);
        if (hash_offset > model_size || hash_bytes > model_size - hash_offset) ok = 0;
        else hash = (const int32_t *)cuda_resolve_weight_ptr(model_map, hash_offset, hash_bytes, logical_tier, "router_hash");
        if (!hash) ok = 0;
    }
    if (ok) {
        if (n_expert == 384u) {
            router_select_warp_topk_kernel<384><<<1, dim3(32, 4), 0, cuda_decode_stream()>>>(
                (int32_t *)selected->ptr, (float *)weights->ptr, (float *)probs->ptr,
                bias, hash, (const float *)logits->ptr, NULL, tok, hash_rows, 1,
                has_bias && !hash_mode, hash_mode);
        } else if (getenv("DS4_CUDA_NO_WARP_ROUTER_SELECT") == NULL &&
            getenv("DS4_CUDA_NO_PARALLEL_ROUTER_SELECT") == NULL) {
            dim3 block(32, 4, 1);
            router_select_warp_topk_kernel<<<1, block, 0, cuda_decode_stream()>>>((int32_t *)selected->ptr, (float *)weights->ptr, (float *)probs->ptr,
                                                         bias, hash, (const float *)logits->ptr, NULL, tok, hash_rows, 1,
                                                         has_bias && !hash_mode, hash_mode);
        } else if (getenv("DS4_CUDA_NO_PARALLEL_ROUTER_SELECT") == NULL) {
            router_select_parallel_kernel<<<1, 256, 0, cuda_decode_stream()>>>((int32_t *)selected->ptr, (float *)weights->ptr, (float *)probs->ptr,
                                                      bias, hash, (const float *)logits->ptr, NULL, tok, hash_rows, 1,
                                                      has_bias && !hash_mode, hash_mode);
        } else {
            router_select_kernel<<<1, 1, 0, cuda_decode_stream()>>>((int32_t *)selected->ptr, (float *)weights->ptr, (float *)probs->ptr,
                                          bias, hash, (const float *)logits->ptr, NULL, tok, hash_rows, 1,
                                          has_bias && !hash_mode, hash_mode);
        }
        ok = cuda_ok(cudaGetLastError(), "router_select launch");
    }
    return ok;
}
extern "C" int ds4_gpu_router_select_batch_tensor(ds4_gpu_tensor *selected, ds4_gpu_tensor *weights, ds4_gpu_tensor *probs, const void *model_map, uint64_t model_size, uint64_t bias_offset, uint64_t hash_offset, uint32_t hash_rows, uint32_t n_expert_groups, uint32_t n_group_used, bool has_bias, bool hash_mode, const ds4_gpu_tensor *logits, const ds4_gpu_tensor *tokens, uint32_t n_expert, uint32_t n_expert_used, float expert_weight_scale, uint32_t n_tokens) {
    const bool draft = n_expert == 128u && n_expert_used == 3u && !hash_mode;
    if ((!draft && ((n_expert != 256u && n_expert != 384u) || n_expert_used != 6u)) ||
        fabsf(expert_weight_scale - 1.5f) > 1.0e-6f) return 0;
    if (!selected || !weights || !probs || !logits || !tokens || !model_map || n_tokens == 0 ||
        n_expert_groups > 1u || n_group_used > 0u ||
        logits->bytes < (uint64_t)n_tokens * n_expert * sizeof(float) ||
        probs->bytes < (uint64_t)n_tokens * n_expert * sizeof(float) ||
        tokens->bytes < (uint64_t)n_tokens * sizeof(int32_t) ||
        selected->bytes < (uint64_t)n_tokens * n_expert_used * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_tokens * n_expert_used * sizeof(float)) {
        return 0;
    }
    const float *bias = NULL;
    const int32_t *hash = NULL;
    const int logical_tier = ds4_tensor_device_idx(selected);
    if (has_bias && !hash_mode) {
        if (bias_offset > model_size || model_size - bias_offset < n_expert * sizeof(float)) return 0;
        bias = (const float *)cuda_resolve_weight_ptr(model_map, bias_offset, n_expert * sizeof(float), logical_tier, "router_bias");
        if (!bias) return 0;
    }
    if (hash_mode) {
        const uint64_t hash_bytes = (uint64_t)hash_rows * 6u * sizeof(int32_t);
        if (hash_offset > model_size || hash_bytes > model_size - hash_offset) return 0;
        hash = (const int32_t *)cuda_resolve_weight_ptr(model_map, hash_offset, hash_bytes, logical_tier, "router_hash");
        if (!hash) return 0;
    }
    if (draft) {
        router_select_warp_topk_kernel<128,3><<<(n_tokens + 3u) / 4u, dim3(32,4), 0, cuda_decode_stream()>>>(
            (int32_t *)selected->ptr, (float *)weights->ptr, (float *)probs->ptr,
            bias, NULL, (const float *)logits->ptr, (const int32_t *)tokens->ptr,
            0, 0, n_tokens, has_bias, false);
    } else if (n_expert == 384u) {
        router_select_warp_topk_kernel<384><<<(n_tokens + 3u) / 4u, dim3(32, 4), 0, cuda_decode_stream()>>>(
            (int32_t *)selected->ptr, (float *)weights->ptr, (float *)probs->ptr,
            bias, hash, (const float *)logits->ptr, (const int32_t *)tokens->ptr,
            0, hash_rows, n_tokens, has_bias && !hash_mode, hash_mode);
    } else if (getenv("DS4_CUDA_NO_WARP_ROUTER_SELECT") == NULL &&
        getenv("DS4_CUDA_NO_PARALLEL_ROUTER_SELECT") == NULL) {
        dim3 block(32, 4, 1);
        router_select_warp_topk_kernel<<<(n_tokens + 3u) / 4u, block>>>((int32_t *)selected->ptr,
                                                                        (float *)weights->ptr,
                                                                        (float *)probs->ptr,
                                                                        bias,
                                                                        hash,
                                                                        (const float *)logits->ptr,
                                                                        (const int32_t *)tokens->ptr,
                                                                        0,
                                                                        hash_rows,
                                                                        n_tokens,
                                                                        has_bias && !hash_mode,
                                                                        hash_mode);
    } else if (getenv("DS4_CUDA_NO_PARALLEL_ROUTER_SELECT") == NULL) {
        router_select_parallel_kernel<<<n_tokens, 256>>>((int32_t *)selected->ptr,
                                                         (float *)weights->ptr,
                                                         (float *)probs->ptr,
                                                         bias,
                                                         hash,
                                                         (const float *)logits->ptr,
                                                         (const int32_t *)tokens->ptr,
                                                         0,
                                                         hash_rows,
                                                         n_tokens,
                                                         has_bias && !hash_mode,
                                                         hash_mode);
    } else {
        router_select_kernel<<<n_tokens, 1>>>((int32_t *)selected->ptr,
                                              (float *)weights->ptr,
                                              (float *)probs->ptr,
                                              bias,
                                              hash,
                                              (const float *)logits->ptr,
                                              (const int32_t *)tokens->ptr,
                                              0,
                                              hash_rows,
                                              n_tokens,
                                              has_bias && !hash_mode,
                                              hash_mode);
    }
    return cuda_ok(cudaGetLastError(), "router_select launch");
}

extern "C" int ds4_gpu_router_select_batch_visual_tensor(
        ds4_gpu_tensor *selected,
        ds4_gpu_tensor *weights,
        ds4_gpu_tensor *probs,
        const void *model_map,
        uint64_t model_size,
        uint64_t bias_offset,
        uint64_t hash_offset,
        uint32_t hash_rows,
        bool has_bias,
        bool hash_mode,
        const void *vision_map,
        uint64_t vision_size,
        uint64_t visual_bias_offset,
        const ds4_gpu_tensor *logits,
        const ds4_gpu_tensor *tokens,
        uint32_t vocab_size,
        uint32_t n_expert,
        uint32_t n_expert_used,
        float expert_weight_scale,
        uint32_t n_tokens) {
    if (!selected || !weights || !probs || !logits || !tokens ||
        !model_map || !vision_map || n_tokens == 0 || vocab_size == 0 ||
        n_expert != 256u || n_expert_used != 6u ||
        fabsf(expert_weight_scale - 1.5f) > 1.0e-6f ||
        logits->bytes < (uint64_t)n_tokens * 256u * sizeof(float) ||
        probs->bytes < (uint64_t)n_tokens * 256u * sizeof(float) ||
        selected->bytes < (uint64_t)n_tokens * 6u * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_tokens * 6u * sizeof(float) ||
        tokens->bytes < (uint64_t)n_tokens * sizeof(int32_t)) return 0;

    const int logical_tier = ds4_tensor_device_idx(selected);
    const float *bias = NULL;
    const int32_t *hash = NULL;
    if (has_bias && !hash_mode) {
        if (bias_offset > model_size || model_size - bias_offset < 256u * sizeof(float)) return 0;
        bias = (const float *)cuda_resolve_weight_ptr(
                model_map, bias_offset, 256u * sizeof(float),
                logical_tier, "router_bias");
        if (!bias) return 0;
    }
    if (hash_mode) {
        const uint64_t hash_bytes = (uint64_t)hash_rows * 6u * sizeof(int32_t);
        if (hash_offset > model_size || model_size - hash_offset < hash_bytes) return 0;
        hash = (const int32_t *)cuda_resolve_weight_ptr(
                model_map, hash_offset, hash_bytes,
                logical_tier, "router_hash");
        if (!hash) return 0;
    }
    if (visual_bias_offset > vision_size ||
        vision_size - visual_bias_offset < 256u * sizeof(float)) return 0;
    const float *visual_bias = (const float *)cuda_resolve_weight_ptr(
            vision_map, visual_bias_offset, 256u * sizeof(float),
            logical_tier, "visual_router_bias");
    if (!visual_bias) return 0;

    router_select_visual_parallel_kernel<<<n_tokens, 256>>>(
            (int32_t *)selected->ptr,
            (float *)weights->ptr,
            (float *)probs->ptr,
            bias,
            visual_bias,
            hash,
            (const float *)logits->ptr,
            (const int32_t *)tokens->ptr,
            hash_rows,
            vocab_size,
            n_tokens,
            has_bias && !hash_mode,
            hash_mode);
    return cuda_ok(cudaGetLastError(), "visual router select launch");
}

__device__ static float dev_f16_to_f32(uint16_t v) {
    return __half2float(*reinterpret_cast<const __half *>(&v));
}

__device__ __forceinline__ static uint32_t dev_unpack_iq2_signs(uint32_t v) {
    const uint32_t p = __popc(v) & 1u;
    const uint32_t s = v ^ (p << 7u);
    return s * 0x01010101u;
}

__device__ __forceinline__ static int32_t dev_iq2_dp4a_8(uint64_t grid, uint32_t sign, const int8_t *q8, int32_t acc) {
    const uint32_t signs = dev_unpack_iq2_signs(sign);
    const int32_t sm0 = __vcmpne4(signs & 0x08040201u, 0);
    const int32_t sm1 = __vcmpne4(signs & 0x80402010u, 0);
    const int32_t g0 = __vsub4((int32_t)(uint32_t)grid ^ sm0, sm0);
    const int32_t g1 = __vsub4((int32_t)(uint32_t)(grid >> 32) ^ sm1, sm1);
    acc = __dp4a(g0, *(const int32_t *)(q8 + 0), acc);
    acc = __dp4a(g1, *(const int32_t *)(q8 + 4), acc);
    return acc;
}

__device__ static int32_t dev_dot_q2_16(const uint8_t *q2, const int8_t *q8, int shift) {
    int32_t sum = 0;
    #pragma unroll
    for (uint32_t i = 0; i < 16; i += 4) {
        const int32_t v = (*(const int32_t *)(q2 + i) >> shift) & 0x03030303;
        sum = __dp4a(v, *(const int32_t *)(q8 + i), sum);
    }
    return sum;
}

__device__ static int32_t dev_dot_iq2_pair_16(uint8_t grid0, uint32_t sign0, uint8_t grid1, uint32_t sign1, const int8_t *q8) {
    int32_t sum = 0;
    sum = dev_iq2_dp4a_8(cuda_iq2xxs_grid[grid0], cuda_ksigns_iq2xs[sign0], q8, sum);
    sum = dev_iq2_dp4a_8(cuda_iq2xxs_grid[grid1], cuda_ksigns_iq2xs[sign1], q8 + 8, sum);
    return sum;
}

__device__ __forceinline__ static void dev_iq2_i8x8_lut(
        const uint64_t *grid,
        const uint8_t *signs,
        uint8_t grid_idx,
        uint32_t sign_idx,
        int32_t *w0,
        int32_t *w1) {
    const uint32_t s = dev_unpack_iq2_signs(signs[sign_idx]);
    const int32_t sm0 = __vcmpne4(s & 0x08040201u, 0);
    const int32_t sm1 = __vcmpne4(s & 0x80402010u, 0);
    const uint64_t g = grid[grid_idx];
    *w0 = __vsub4((int32_t)(uint32_t)g ^ sm0, sm0);
    *w1 = __vsub4((int32_t)(uint32_t)(g >> 32) ^ sm1, sm1);
}

__device__ static float dev_dot_iq2_xxs_q8_K_block_lut(
        const cuda_block_iq2_xxs *x,
        const cuda_block_q8_K *y,
        const uint64_t *grid,
        const uint8_t *signs) {
    const float xd = dev_f16_to_f32(x->d);
    const uint16_t *q2 = x->qs;
    const int8_t *q8 = y->qs;
    int32_t bsum = 0;
    for (int ib32 = 0; ib32 < CUDA_QK_K / 32; ib32++) {
        const uint32_t aux0 = (uint32_t)q2[0] | ((uint32_t)q2[1] << 16);
        const uint32_t aux1 = (uint32_t)q2[2] | ((uint32_t)q2[3] << 16);
        q2 += 4;
        const int32_t ls = (int32_t)(2u * (aux1 >> 28) + 1u);
        int32_t w[8];
        dev_iq2_i8x8_lut(grid, signs, (uint8_t)(aux0 & 0xffu),           (aux1 >> 0)  & 127u, &w[0], &w[1]);
        dev_iq2_i8x8_lut(grid, signs, (uint8_t)((aux0 >> 8)  & 0xffu),   (aux1 >> 7)  & 127u, &w[2], &w[3]);
        dev_iq2_i8x8_lut(grid, signs, (uint8_t)((aux0 >> 16) & 0xffu),   (aux1 >> 14) & 127u, &w[4], &w[5]);
        dev_iq2_i8x8_lut(grid, signs, (uint8_t)((aux0 >> 24) & 0xffu),   (aux1 >> 21) & 127u, &w[6], &w[7]);
        int32_t sumi = 0;
        sumi = __dp4a(w[0], *(const int32_t *)(q8 + ib32 * 32u + 0),  sumi);
        sumi = __dp4a(w[1], *(const int32_t *)(q8 + ib32 * 32u + 4),  sumi);
        sumi = __dp4a(w[2], *(const int32_t *)(q8 + ib32 * 32u + 8),  sumi);
        sumi = __dp4a(w[3], *(const int32_t *)(q8 + ib32 * 32u + 12), sumi);
        sumi = __dp4a(w[4], *(const int32_t *)(q8 + ib32 * 32u + 16), sumi);
        sumi = __dp4a(w[5], *(const int32_t *)(q8 + ib32 * 32u + 20), sumi);
        sumi = __dp4a(w[6], *(const int32_t *)(q8 + ib32 * 32u + 24), sumi);
        sumi = __dp4a(w[7], *(const int32_t *)(q8 + ib32 * 32u + 28), sumi);
        bsum += sumi * ls;
    }
    return 0.125f * xd * y->d * (float)bsum;
}

__device__ static float dev_dot_iq2_xxs_q8_K_block(const cuda_block_iq2_xxs *x, const cuda_block_q8_K *y) {
    const float d = dev_f16_to_f32(x->d) * y->d;
    const uint16_t *q2 = x->qs;
    const int8_t *q8 = y->qs;
    int32_t bsum = 0;
    for (int ib32 = 0; ib32 < CUDA_QK_K / 32; ib32++) {
        const uint32_t aux0 = (uint32_t)q2[0] | ((uint32_t)q2[1] << 16);
        const uint32_t aux1 = (uint32_t)q2[2] | ((uint32_t)q2[3] << 16);
        q2 += 4;
        const uint32_t ls = 2u * (aux1 >> 28) + 1u;
        const uint8_t a0 = (uint8_t)(aux0 & 0xffu);
        const uint8_t a1 = (uint8_t)((aux0 >> 8) & 0xffu);
        const uint8_t a2 = (uint8_t)((aux0 >> 16) & 0xffu);
        const uint8_t a3 = (uint8_t)((aux0 >> 24) & 0xffu);
        int32_t sumi = 0;
        sumi += dev_dot_iq2_pair_16(a0, (aux1 >> 0) & 127u, a1, (aux1 >> 7) & 127u, q8);
        q8 += 16;
        sumi += dev_dot_iq2_pair_16(a2, (aux1 >> 14) & 127u, a3, (aux1 >> 21) & 127u, q8);
        q8 += 16;
        bsum += sumi * (int32_t)ls;
    }
    return 0.125f * d * (float)bsum;
}

__device__ static void dev_dot_iq2_xxs_q8_K_block8_deq_lut(
        const cuda_block_iq2_xxs *x,
        const cuda_block_q8_K *y0,
        const cuda_block_q8_K *y1,
        const cuda_block_q8_K *y2,
        const cuda_block_q8_K *y3,
        const cuda_block_q8_K *y4,
        const cuda_block_q8_K *y5,
        const cuda_block_q8_K *y6,
        const cuda_block_q8_K *y7,
        uint32_t n,
        float acc[8],
        const uint64_t *grid,
        const uint8_t *signs) {
    const float xd = dev_f16_to_f32(x->d);
    const uint16_t *q2 = x->qs;
    int32_t bsum[8] = {0, 0, 0, 0, 0, 0, 0, 0};
    const int8_t *q8[8] = {
        y0 ? y0->qs : NULL, y1 ? y1->qs : NULL, y2 ? y2->qs : NULL, y3 ? y3->qs : NULL,
        y4 ? y4->qs : NULL, y5 ? y5->qs : NULL, y6 ? y6->qs : NULL, y7 ? y7->qs : NULL,
    };
    for (int ib32 = 0; ib32 < CUDA_QK_K / 32; ib32++) {
        const uint32_t aux0 = (uint32_t)q2[0] | ((uint32_t)q2[1] << 16);
        const uint32_t aux1 = (uint32_t)q2[2] | ((uint32_t)q2[3] << 16);
        q2 += 4;
        const int32_t ls = (int32_t)(2u * (aux1 >> 28) + 1u);
        int32_t w[8];
        dev_iq2_i8x8_lut(grid, signs, (uint8_t)(aux0 & 0xffu),           (aux1 >> 0)  & 127u, &w[0], &w[1]);
        dev_iq2_i8x8_lut(grid, signs, (uint8_t)((aux0 >> 8)  & 0xffu),   (aux1 >> 7)  & 127u, &w[2], &w[3]);
        dev_iq2_i8x8_lut(grid, signs, (uint8_t)((aux0 >> 16) & 0xffu),   (aux1 >> 14) & 127u, &w[4], &w[5]);
        dev_iq2_i8x8_lut(grid, signs, (uint8_t)((aux0 >> 24) & 0xffu),   (aux1 >> 21) & 127u, &w[6], &w[7]);
        for (uint32_t p = 0; p < n; p++) {
            const int8_t *q = q8[p] + ib32 * 32;
            int32_t sumi = 0;
            sumi = __dp4a(w[0], *(const int32_t *)(q + 0),  sumi);
            sumi = __dp4a(w[1], *(const int32_t *)(q + 4),  sumi);
            sumi = __dp4a(w[2], *(const int32_t *)(q + 8),  sumi);
            sumi = __dp4a(w[3], *(const int32_t *)(q + 12), sumi);
            sumi = __dp4a(w[4], *(const int32_t *)(q + 16), sumi);
            sumi = __dp4a(w[5], *(const int32_t *)(q + 20), sumi);
            sumi = __dp4a(w[6], *(const int32_t *)(q + 24), sumi);
            sumi = __dp4a(w[7], *(const int32_t *)(q + 28), sumi);
            bsum[p] += sumi * ls;
        }
    }
    const cuda_block_q8_K *ys[8] = { y0, y1, y2, y3, y4, y5, y6, y7 };
    for (uint32_t p = 0; p < n; p++) acc[p] += 0.125f * xd * ys[p]->d * (float)bsum[p];
}

__device__ static void dev_dot_iq2_xxs_q8_K_block4(
        const cuda_block_iq2_xxs *x,
