    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(down_base + (uint64_t)(uint32_t)expert_i * down_expert_bytes + (uint64_t)row * down_row_bytes);
    const cuda_block_q8_K *xq = midq + (uint64_t)pair * midq_blocks;
    float acc = 0.0f;
    for (uint32_t b = lane; b < midq_blocks; b += 8u) acc += dev_dot_q2_K_q8_K_block(wr + b, xq + b);
    acc = quarter_warp_sum_f32(acc, lane);
    if (lane == 0) down_out[(uint64_t)pair * out_dim + row] = acc;
}

__global__ static void moe_sum_kernel(float *out, const float *down, uint32_t out_dim, uint32_t n_expert, uint32_t n_tokens) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * out_dim;
    if (gid >= n) return;
    uint32_t tok = gid / out_dim;
    uint32_t row = gid - (uint64_t)tok * out_dim;
    float acc = 0.0f;
    for (uint32_t e = 0; e < n_expert; e++) acc += down[((uint64_t)tok * n_expert + e) * out_dim + row];
    out[gid] = acc;
}

__global__ static void moe_sum_owned_kernel(
        float *out,
        const float *down,
        const int32_t *selected,
        uint32_t out_dim,
        uint32_t n_expert,
        uint32_t n_tokens) {
    const uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const uint64_t n = (uint64_t)n_tokens * out_dim;
    if (gid >= n) return;
    const uint32_t tok = (uint32_t)(gid / out_dim);
    const uint32_t row = (uint32_t)(gid - (uint64_t)tok * out_dim);
    float acc = 0.0f;
    #pragma unroll
    for (uint32_t slot = 0; slot < 6u; slot++) {
        if (slot >= n_expert) break;
        const uint64_t pair = (uint64_t)tok * n_expert + slot;
        const float value = selected[pair] >= 0
            ? down[pair * out_dim + row] : 0.0f;
        acc = __fadd_rn(acc, value);
    }
    out[gid] = acc;
}

__device__ static float dev_iq2_xxs_dot_f32(const cuda_block_iq2_xxs *row, const float *x, uint32_t nb) {
    float acc = 0.0f;
    for (uint32_t b = 0; b < nb; b++) {
        const cuda_block_iq2_xxs *xb = row + b;
        const float d = dev_f16_to_f32(xb->d);
        const uint16_t *q2 = xb->qs;
        const float *xf = x + (uint64_t)b * CUDA_QK_K;
        for (uint32_t ib32 = 0; ib32 < CUDA_QK_K / 32; ib32++) {
            const uint32_t aux_g = (uint32_t)q2[0] | ((uint32_t)q2[1] << 16);
            const uint32_t aux_s = (uint32_t)q2[2] | ((uint32_t)q2[3] << 16);
            q2 += 4;
            const float dl = d * (0.5f + (float)(aux_s >> 28)) * 0.25f;
            const uint8_t grids[4] = {
                (uint8_t)(aux_g & 0xffu),
                (uint8_t)((aux_g >> 8) & 0xffu),
                (uint8_t)((aux_g >> 16) & 0xffu),
                (uint8_t)((aux_g >> 24) & 0xffu),
            };
            for (uint32_t half = 0; half < 2; half++) {
                for (uint32_t g = 0; g < 2; g++) {
                    const uint32_t gi = half * 2 + g;
                    const uint64_t grid = cuda_iq2xxs_grid[grids[gi]];
                    const uint8_t signs = cuda_ksigns_iq2xs[(aux_s >> (14u * half + 7u * g)) & 127u];
                    for (uint32_t i = 0; i < 8; i++) {
                        float w = (float)((grid >> (8u * i)) & 0xffu);
                        if (signs & (1u << i)) w = -w;
                        acc += dl * w * xf[ib32 * 32u + half * 16u + g * 8u + i];
                    }
                }
            }
        }
    }
    return acc;
}

__device__ static float dev_q2_K_dot_f32(const cuda_block_q2_K *row, const float *x, uint32_t nb) {
    float acc = 0.0f;
    for (uint32_t b = 0; b < nb; b++) {
        const cuda_block_q2_K *xb = row + b;
        const float d = dev_f16_to_f32(xb->d);
        const float dmin = dev_f16_to_f32(xb->dmin);
        for (uint32_t il = 0; il < 16; il++) {
            const uint32_t chunk = il / 8u;
            const uint32_t pair = il & 1u;
            const uint32_t shift = ((il / 2u) & 3u) * 2u;
            const uint8_t sc = xb->scales[il];
            const float dl = d * (float)(sc & 0x0fu);
            const float ml = dmin * (float)(sc >> 4);
            const uint8_t *q = xb->qs + 32u * chunk + 16u * pair;
            const float *xf = x + (uint64_t)b * CUDA_QK_K + chunk * 128u + ((il % 8u) / 2u) * 32u + pair * 16u;
            for (uint32_t i = 0; i < 16; i++) {
                const float w = dl * (float)((q[i] >> shift) & 3u) - ml;
                acc += w * xf[i];
            }
        }
    }
    return acc;
}

__global__ static void moe_gate_up_mid_f32_kernel(
        float *gate_out,
        float *up_out,
        float *mid_out,
        const char *gate_base,
        const char *up_base,
        const float *x,
        const int32_t *selected,
        const float *weights,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t n_expert,
        float clamp) {
    uint32_t row = blockIdx.x;
    uint32_t pair = blockIdx.y;
    if (row >= expert_mid_dim) return;
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    uint32_t expert = (uint32_t)expert_i;
    const uint32_t nb = expert_in_dim / CUDA_QK_K;
    const cuda_block_iq2_xxs *gr = (const cuda_block_iq2_xxs *)(gate_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
    const cuda_block_iq2_xxs *ur = (const cuda_block_iq2_xxs *)(up_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
    const float *xr = x + (uint64_t)tok * expert_in_dim;
    float gate = 0.0f;
    float up = 0.0f;
    for (uint32_t b = threadIdx.x; b < nb; b += blockDim.x) {
        gate += dev_iq2_xxs_dot_f32(gr + b, xr + (uint64_t)b * CUDA_QK_K, 1);
        up += dev_iq2_xxs_dot_f32(ur + b, xr + (uint64_t)b * CUDA_QK_K, 1);
    }
    __shared__ float partial_gate[256];
    __shared__ float partial_up[256];
    partial_gate[threadIdx.x] = gate;
    partial_up[threadIdx.x] = up;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            partial_gate[threadIdx.x] += partial_gate[threadIdx.x + stride];
            partial_up[threadIdx.x] += partial_up[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        gate = partial_gate[0];
        up = partial_up[0];
        if (clamp > 1.0e-6f) {
            if (gate > clamp) gate = clamp;
            if (up > clamp) up = clamp;
            if (up < -clamp) up = -clamp;
        }
        const uint64_t off = (uint64_t)pair * expert_mid_dim + row;
        gate_out[off] = gate;
        up_out[off] = up;
        mid_out[off] = (gate / (1.0f + expf(-gate))) * up * weights[(uint64_t)tok * n_expert + slot];
    }
}

__global__ static void moe_down_f32_kernel(
        float *down_out,
        const char *down_base,
        const float *mid,
        const int32_t *selected,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        uint32_t n_expert) {
    uint32_t row = blockIdx.x;
    uint32_t pair = blockIdx.y;
    if (row >= out_dim) return;
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    const uint32_t nb = expert_mid_dim / CUDA_QK_K;
    const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(down_base + (uint64_t)(uint32_t)expert_i * down_expert_bytes + (uint64_t)row * down_row_bytes);
    const float *xr = mid + (uint64_t)pair * expert_mid_dim;
    float acc = 0.0f;
    for (uint32_t b = threadIdx.x; b < nb; b += blockDim.x) acc += dev_q2_K_dot_f32(wr + b, xr + (uint64_t)b * CUDA_QK_K, 1);
    __shared__ float partial[256];
    partial[threadIdx.x] = acc;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) down_out[(uint64_t)pair * out_dim + row] = partial[0];
}

#include "ds4_cuda_dspark_lowbit.cuh"

/* streaming-llama's native-half expert graph rounds the weighted SwiGLU product to F16
 * before the down projection (llama-dsv41-ffn.cpp). */
__global__ static void moe_round_f16_kernel(float *x, uint64_t n) {
    const uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) x[i] = __half2float(__float2half_rn(x[i]));
}

/* Set at model open when deepseek41.expert_layout names the kernel-native
 * packed FP4 expert layout (external decode only). */
static int g_ds4_fp4_packed_experts = 0;
extern "C" void ds4_gpu_set_fp4_packed_experts(int on) { g_ds4_fp4_packed_experts = on ? 1 : 0; }

/* DS4X_STAGE_PROFILE=1 decode attribution. Marks are CUDA events on the
 * legacy stream; the interval ending at mark k is charged to stage k, so a
 * host stall (expert hook, synchronous reads) shows in the stage it delays. */
static int g_stage_profile = -1;
static cudaEvent_t g_stage_events[4096];
static int g_stage_ids[4096];
static int g_stage_count = 0;
static double g_stage_total[16];
static uint64_t g_stage_tokens = 0;
extern "C" int ds4_gpu_stage_mark(int id) {
    if (g_stage_profile < 0) {
        const char *v = getenv("DS4X_STAGE_PROFILE");
        g_stage_profile = v && v[0] == '1' && !v[1];
    }
    if (!g_stage_profile || g_stage_count >= 4096 || id < 0 || id > 15) return 1;
    if (!g_stage_events[g_stage_count] && cudaEventCreate(&g_stage_events[g_stage_count]) != cudaSuccess) return 1;
    if (cudaEventRecord(g_stage_events[g_stage_count], 0) != cudaSuccess) return 1;
    g_stage_ids[g_stage_count++] = id;
    return 1;
}
extern "C" void ds4_pool_call_stats(uint64_t *calls, double *ms);
/* Prefetched router selection (ds4_gpu_prefetch_selected). */
static int32_t *g_prefetch_ids = nullptr;
static cudaEvent_t g_prefetch_event = nullptr;
static const void *g_prefetch_src = nullptr;
static uint32_t g_prefetch_count = 0;
extern "C" int ds4_gpu_prefetch_selected(const ds4_gpu_tensor *selected, uint32_t count) {
    g_prefetch_src = nullptr;
#ifndef DS4_EXTERNAL_DECODE
    (void)selected; (void)count; return 1;
#else
    static const bool on = [] { const char *v = getenv("DS4X_PREFETCH_SELECTED"); return v && v[0] == '1' && !v[1]; }();
    if (!on || !g_ds4x_expert_hook || !selected || !selected->ptr || !count || count > 64u ||
        selected->bytes < (uint64_t)count * sizeof(int32_t)) return 1;
    if (!g_prefetch_ids) {
        if (cudaHostAlloc((void **)&g_prefetch_ids, 64u * sizeof(int32_t), cudaHostAllocDefault) != cudaSuccess ||
            cudaEventCreateWithFlags(&g_prefetch_event, cudaEventDisableTiming) != cudaSuccess) {
            fprintf(stderr, "ds4: router selection prefetch setup failed\n"); return 0;
        }
    }
    if (cudaMemcpyAsync(g_prefetch_ids, selected->ptr, (size_t)count * sizeof(int32_t), cudaMemcpyDeviceToHost, cuda_decode_stream()) != cudaSuccess ||
        cudaEventRecord(g_prefetch_event, cuda_decode_stream()) != cudaSuccess) return 0;
    g_prefetch_src = selected->ptr; g_prefetch_count = count;
    return 1;
#endif
}
static double g_stage_host_ms[3];
static uint64_t g_stage_pool_calls0 = 0;
static double g_stage_pool_ms0 = 0.0;
static double g_stage_launch_ms = 0.0;
static void ds4_gpu_stage_host(double read_ms, double hook_ms, double write_ms) {
    if (g_stage_profile != 1) return;
    g_stage_host_ms[0] += read_ms; g_stage_host_ms[1] += hook_ms; g_stage_host_ms[2] += write_ms;
}
extern "C" void ds4_gpu_stage_flush(uint32_t position) {
    if (g_stage_profile != 1 || g_stage_count < 2) { g_stage_count = 0; return; }
    (void)cudaEventSynchronize(g_stage_events[g_stage_count - 1]);
    double per[16] = {};
    for (int i = 1; i < g_stage_count; ++i) {
        float ms = 0.0f;
        if (cudaEventElapsedTime(&ms, g_stage_events[i - 1], g_stage_events[i]) == cudaSuccess) per[g_stage_ids[i]] += ms;
    }
    g_stage_count = 0;
    uint64_t pool_calls = 0; double pool_ms = 0.0;
    ds4_pool_call_stats(&pool_calls, &pool_ms);
    double total = 0.0;
    for (int i = 0; i < 16; ++i) { g_stage_total[i] += per[i]; total += per[i]; }
    ++g_stage_tokens;
    fprintf(stderr, "DS4X_STAGE position=%u total_ms=%.3f hc_pre=%.3f attention=%.3f hc_mix=%.3f router_shared=%.3f "
            "expert_hook=%.3f routed_experts=%.3f after_moe=%.3f between_layers=%.3f head=%.3f "
            "host_ids_read=%.3f host_cache_hook=%.3f host_slot_write=%.3f host_fp4_launch=%.3f pool_calls=%llu pool_ms=%.3f "
            "attn_project=%.3f attn_rope_store=%.3f attn_select=%.3f attn_core=%.3f\n",
            position, total, per[1], per[2], per[3], per[6], per[7], per[4], per[5], per[0], per[8],
            g_stage_host_ms[0], g_stage_host_ms[1], g_stage_host_ms[2], g_stage_launch_ms,
            (unsigned long long) (pool_calls - g_stage_pool_calls0), pool_ms - g_stage_pool_ms0,
            per[10], per[11], per[12], per[13]);
    g_stage_pool_calls0 = pool_calls; g_stage_pool_ms0 = pool_ms;
    g_stage_host_ms[0] = g_stage_host_ms[1] = g_stage_host_ms[2] = 0.0; g_stage_launch_ms = 0.0;
}
#include "ds4_external_host_compute.inc"
#ifdef DS4_EXTERNAL_DECODE
/* FP4 CPU lane (ds4_external_host_compute_wrapper.inc): ids read together
 * with the activation, CPU experts marked -2 for the packed kernels, and the
 * join callback that the packed launcher runs before the down projection. */
static const void *g_fp4_pre_ids_src = nullptr;
static int32_t g_fp4_pre_ids[6];
static bool g_fp4_cpu_active = false;
static float *g_fp4_cpu_acc_dev = nullptr;
static int external_fp4_cpu_join(void *ctx, cudaStream_t stream);
static double g_last_hook_ms = 0.0;
#endif

static int routed_moe_launch(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *model_map,
        uint64_t model_size,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint32_t gate_type,
        uint32_t down_type,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_total_expert,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x,
        uint32_t layer_index,
        uint32_t n_tokens,
        int allow_streaming,
        int owned_filtered);

static int routed_moe_launch_impl(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *model_map,
        uint64_t model_size,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint32_t gate_type,
        uint32_t down_type,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_total_expert,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x,
        uint32_t layer_index,
        uint32_t n_tokens,
        int allow_streaming,
        int owned_filtered) {
    if (!out || !gate || !up || !mid || !down || !model_map || !selected || !weights || !x ||
        n_tokens == 0 || n_total_expert == 0 || n_expert == 0 ||
        expert_in_dim % CUDA_QK_K != 0 || expert_mid_dim % CUDA_QK_K != 0 ||
        gate_offset > model_size || up_offset > model_size || down_offset > model_size ||
        x->bytes < (uint64_t)n_tokens * expert_in_dim * sizeof(float) ||
        selected->bytes < (uint64_t)n_tokens * n_expert * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_tokens * n_expert * sizeof(float) ||
        gate->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        up->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        mid->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        down->bytes < (uint64_t)n_tokens * n_expert * out_dim * sizeof(float) ||
        out->bytes < (uint64_t)n_tokens * out_dim * sizeof(float)) {
        return 0;
    }
    if(model_map==g_support_host_base && n_total_expert==128u && n_expert==3u && gate_type==down_type && (gate_type==10u || gate_type==11u))
        return dspark_lowbit_launch(out,gate,up,mid,down,model_map,model_size,gate_offset,up_offset,
            down_offset,gate_type,gate_expert_bytes,gate_row_bytes,down_expert_bytes,down_row_bytes,
            expert_in_dim,expert_mid_dim,out_dim,selected,weights,n_total_expert,n_expert,clamp,x,n_tokens);
    const int q4k_path = (gate_type == 12u && down_type == 12u);
    const int iq2_path = (gate_type == 16u && down_type == 10u);
    const int mxfp4_path = (gate_type == 39u && down_type == 39u);
    if (!q4k_path && !iq2_path && !mxfp4_path) return 0;

    const char *external_gate = nullptr, *external_up = nullptr, *external_down = nullptr;
    const char *external_l2[3] = {nullptr, nullptr, nullptr};
    uint64_t external_l2_stride[3] = {0, 0, 0};
    uint32_t external_l1_slots = 0;
#ifdef DS4_EXTERNAL_DECODE
    if (g_ds4x_expert_hook) {
        /* The caller's expert cache supplies the routed experts' bytes: the
         * rows' ids become slots in its pool, read with the original strides.
         * A multi-row call (ds4x_prefill) asks for the union of its rows' experts
         * at once; a union above the group cap is split into row halves, each a
         * call of its own (the id read below orders it after the previous half). */
        const uint32_t assignments = n_tokens * n_expert;
        std::vector<int32_t> ids(assignments), unique, slots;
        if (n_tokens == 1u) (void)ds4_gpu_stage_mark(6);
        const auto hook_t0 = std::chrono::steady_clock::now();
        if (g_fp4_pre_ids_src && g_fp4_pre_ids_src == selected->ptr && assignments == 6u) {
            g_fp4_pre_ids_src = nullptr;
            std::memcpy(ids.data(), g_fp4_pre_ids, 6u * sizeof(int32_t));
        } else if (g_prefetch_src && g_prefetch_src == selected->ptr && g_prefetch_count == assignments) {
            g_prefetch_src = nullptr;
            if (cudaEventSynchronize(g_prefetch_event) != cudaSuccess) return 0;
            std::memcpy(ids.data(), g_prefetch_ids, (size_t)assignments * sizeof(int32_t));
        } else if (!ds4_gpu_tensor_read(selected, 0, ids.data(), (uint64_t)assignments * sizeof(int32_t))) return 0;
        const auto hook_t1 = std::chrono::steady_clock::now();
        for (const int32_t id : ids) {
            if (id < 0 || (uint32_t)id >= n_total_expert) return 0;
            if(std::find(g_external_cpu_ids.begin(),g_external_cpu_ids.end(),id)!=g_external_cpu_ids.end())continue;
            if (std::find(unique.begin(), unique.end(), id) == unique.end()) unique.push_back(id);
        }
        static const uint32_t group_cap = [] {
            const char *v = getenv("LLAMADECODE_DS4X_MOE_GROUP_EXPERTS");
            const long n = v && *v ? strtol(v, nullptr, 10) : 192;
            return (uint32_t)(n < 16 ? 16 : n > 384 ? 384 : n);
        }();
        if (n_tokens > 1u && unique.size() > group_cap) {
            const uint32_t first = n_tokens / 2u, rest = n_tokens - first;
            ds4_gpu_tensor *v[8] = {};
            auto view = [](const ds4_gpu_tensor *t, uint64_t row, uint64_t width, uint64_t rows) {
                return ds4_gpu_tensor_view(t, row * width * 4u, rows * width * 4u); };
            v[0] = view(out, 0, out_dim, first); v[1] = view(out, first, out_dim, rest);
            v[2] = view(x, 0, expert_in_dim, first); v[3] = view(x, first, expert_in_dim, rest);
            v[4] = view(selected, 0, n_expert, first); v[5] = view(selected, first, n_expert, rest);
            v[6] = view(weights, 0, n_expert, first); v[7] = view(weights, first, n_expert, rest);
            int ok = 1;
            for (auto *t : v) ok &= t != nullptr;
            for (uint32_t h = 0; ok && h < 2u; h++)
                ok = routed_moe_launch(v[h], gate, up, mid, down, model_map, model_size, gate_offset, up_offset,
                    down_offset, gate_type, down_type, gate_expert_bytes, gate_row_bytes, down_expert_bytes,
                    down_row_bytes, expert_in_dim, expert_mid_dim, out_dim, v[4 + h], v[6 + h], n_total_expert,
                    n_expert, clamp, v[2 + h], layer_index, h ? rest : first, allow_streaming, owned_filtered);
            for (auto *t : v) ds4_gpu_tensor_free(t);
            return ok;
        }
        slots.assign(unique.size(), -1);uint32_t n_slots = 0;
        const auto hook_t2 = std::chrono::steady_clock::now();
        if (g_ds4x_expert_hook_l2 && mxfp4_path && g_ds4_fp4_packed_experts) {
            const char *bases[6] = {};
            if (!g_ds4x_expert_hook_l2(g_ds4x_expert_user_l2, layer_index, unique.data(), (uint32_t)unique.size(), slots.data(),
                                       bases, external_l2_stride, &external_l1_slots, &n_slots) ||
                external_l1_slots > n_slots || (n_slots > external_l1_slots && (!bases[3] || !bases[4] || !bases[5]))) {
                fprintf(stderr, "LLAMADECODE_DS4X_EXPERT_HOOK_FAILED layer=%u rows=%u experts=%zu direct_l2=1\n", layer_index, n_tokens, unique.size());
                return 0;
            }
            external_gate = bases[0]; external_up = bases[1]; external_down = bases[2];
            for (int k = 0; k < 3; ++k) external_l2[k] = bases[3 + k];
        } else if (!g_ds4x_expert_hook(g_ds4x_expert_user, layer_index, unique.data(), (uint32_t)unique.size(), slots.data(),
                                &external_gate, &external_up, &external_down, &n_slots) ||
            !external_gate || !external_up || !external_down || !n_slots) {
            fprintf(stderr, "LLAMADECODE_DS4X_EXPERT_HOOK_FAILED layer=%u rows=%u experts=%zu\n", layer_index, n_tokens, unique.size());
            return 0;
        }
        const auto hook_t3 = std::chrono::steady_clock::now();
        if (n_tokens == 1u) g_last_hook_ms = std::chrono::duration<double, std::milli>(hook_t3 - hook_t2).count();
        for (const int32_t slot : slots) if (slot < 0 || (uint32_t)slot >= n_slots) return 0;
        for (int32_t &id : ids){
            const auto at=std::find(unique.begin(),unique.end(),id);
            id=at==unique.end()?(g_fp4_cpu_active?-2:-1):slots[size_t(at-unique.begin())];
        }
        if (g_ds4x_slot_tensor.bytes < (uint64_t)assignments * sizeof(int32_t)) {
            if (g_ds4x_slot_tensor.ptr) { (void)cudaFree(g_ds4x_slot_tensor.ptr); g_ds4x_slot_tensor = {}; }
            const uint64_t bytes = (uint64_t)(assignments > 64u ? assignments : 64u) * sizeof(int32_t);
            void *ptr = nullptr;
            if (cudaMalloc(&ptr, bytes) != cudaSuccess) return 0;
            g_ds4x_slot_tensor.ptr = ptr; g_ds4x_slot_tensor.bytes = bytes;
            g_ds4x_slot_tensor.owner = 0; g_ds4x_slot_tensor.device_id = -1;
        }
        if (!ds4_gpu_tensor_write(&g_ds4x_slot_tensor, 0, ids.data(), (uint64_t)assignments * sizeof(int32_t))) return 0;
        if (n_tokens == 1u) {
            (void)ds4_gpu_stage_mark(7);
            const auto hook_t4 = std::chrono::steady_clock::now();
            auto ms = [](auto a, auto b) { return std::chrono::duration<double, std::milli>(b - a).count(); };
            ds4_gpu_stage_host(ms(hook_t0, hook_t1), ms(hook_t2, hook_t3), ms(hook_t3, hook_t4));
        }
