        n_total_expert = n_slots;
        allow_streaming = 0;
    }
#endif
    const bool resident_draft=g_ssd_streaming_mode && model_map==g_support_host_base &&
        getenv("DS4_CUDA_DSPARK_RESIDENT") && !strcmp(getenv("DS4_CUDA_DSPARK_RESIDENT"),"1");
    if(resident_draft)allow_streaming=0;
    if (g_ssd_streaming_mode && !owned_filtered && !resident_draft) {
        const ds4_gpu_stream_expert_table table = {
            model_map, model_size, 0u, layer_index, n_total_expert,
            gate_offset, up_offset, down_offset, gate_expert_bytes, down_expert_bytes,
            nullptr, nullptr};
        if ((uint64_t)n_tokens * n_expert > UINT32_MAX) return 0;
#if defined(_WIN32)
        /* V4.1 scalar rows must use the Windows VRAM/RAM/DirectStorage
         * hierarchy too. The upstream compact loader has a separate LRU and
         * bypasses the host cache and DirectStorage accounting entirely. */
        /* A borrowed layer sweep can end a layer on a one-row chunk (the
         * decoder suffix keeps only the last row at layer 39; a short sweep's
         * last tile can be one row). Those rows must use the borrowed loader:
         * the decode-tier path below would re-prepare the released tier inside
         * the borrow and stage its compact experts into the loader's slots. */
        if (n_tokens == 1u && expert_in_dim == 5120u && expert_mid_dim == 2304u &&
            !g_stream_prefill_borrow_slots) {
            std::vector<int32_t> ids(n_expert);
            if (!ds4_gpu_tensor_read(selected, 0, ids.data(), n_expert * sizeof(int32_t)) ||
                !ds4_gpu_stream_expert_cache_begin_selected_load(&table, ids.data(), n_expert)) return 0;
        } else if(allow_streaming && n_tokens>1u && n_total_expert==384u &&
            expert_in_dim==5120u && expert_mid_dim==2304u &&
            getenv("DS4_CUDA_DSPARK_RESIDENT") && !strcmp(getenv("DS4_CUDA_DSPARK_RESIDENT"),"1")) {
            std::vector<int32_t> ids((size_t)n_tokens*n_expert);
            if(!ds4_gpu_tensor_read(selected,0,ids.data(),ids.size()*sizeof(int32_t)) ||
               !ds4_gpu_stream_expert_cache_prepare_selected_batch(&table,ids.data(),n_tokens,n_expert))return 0;
        } else
#endif
        if (!ds4_gpu_glm_stream_expert_cache_begin_selected_load_tensor(
                &table, selected, n_tokens * n_expert)) return 0;
        allow_streaming = 1;
    }

    /* The aligned artifacts replace the raw expert tensors on integrated
     * CUDA systems.  Route both prefill and decode before resolving a raw
     * pointer, otherwise the fallback cache would duplicate tens of GiB. */
    if (iq2_path && !external_gate && !g_ssd_streaming_mode &&
        cuda_aligned_iq2_enabled() && cuda_aligned_q2k_enabled()) {
        const uint64_t gate_total = (uint64_t)n_total_expert * gate_expert_bytes;
        const uint64_t down_total = (uint64_t)n_total_expert * down_expert_bytes;
        const uint64_t gate_aligned_bytes = ds4_mmq_iq2_xxs_aligned_bytes(
            (int)expert_mid_dim, (int)expert_in_dim, (int)n_total_expert);
        const uint64_t down_aligned_bytes = ds4_mmq_q2_k_aligned_bytes(
            (int)out_dim, (int)expert_mid_dim, (int)n_total_expert);
        const char *gate_aligned = cuda_derived_weight_ptr(
            model_map, gate_offset, gate_total,
            CUDA_DERIVED_IQ2_XXS_ALIGNED_MOE,
            expert_in_dim, expert_mid_dim, n_total_expert,
            gate_aligned_bytes);
        const char *up_aligned = cuda_derived_weight_ptr(
            model_map, up_offset, gate_total,
            CUDA_DERIVED_IQ2_XXS_ALIGNED_MOE,
            expert_in_dim, expert_mid_dim, n_total_expert,
            gate_aligned_bytes);
        const char *down_aligned = cuda_derived_weight_ptr(
            model_map, down_offset, down_total,
            CUDA_DERIVED_Q2_K_ALIGNED_MOE,
            expert_mid_dim, out_dim, n_total_expert,
            down_aligned_bytes);
        if (gate_aligned && up_aligned && down_aligned) {
            const cudaStream_t aligned_stream =
                n_tokens == 1u ? cuda_decode_stream() : (cudaStream_t)0;
            if (owned_filtered && n_tokens <= 8u && (n_expert == 3u || n_expert == 6u)) {
                /* Keep TP decode and short appends on their Q8_K arithmetic.
                 * Only the lossless weight layout changes here. */
                const uint32_t xb = expert_in_dim / CUDA_QK_K;
                const uint32_t mb = expert_mid_dim / CUDA_QK_K;
                if (down->bytes < (uint64_t)n_tokens * xb * sizeof(cuda_block_q8_K) ||
                    gate->bytes < (uint64_t)n_tokens * n_expert * mb * sizeof(cuda_block_q8_K)) return 0;
                auto *xq = (cuda_block_q8_K *)down->ptr;
                auto *mq = (cuda_block_q8_K *)gate->ptr;
                const uint64_t scales = ((uint64_t)n_total_expert * expert_mid_dim * xb * 2u + 63u) & ~63ull;
                q8_K_quantize_kernel<<<dim3(xb, n_tokens), 256, 0, aligned_stream>>>(
                    xq, (const float *)x->ptr, expert_in_dim, n_tokens);
                if (!cuda_ok(cudaGetLastError(), "aligned owned x quantize")) return 0;
                moe_gate_up_mid_aligned_q8k_kernel<<<
                    dim3((expert_mid_dim + 7u) / 8u, n_tokens * n_expert), 256, 0, aligned_stream>>>(
                    (float *)mid->ptr, gate_aligned, up_aligned, xq,
                    (const int32_t *)selected->ptr, (const float *)weights->ptr,
                    xb, expert_mid_dim, n_expert, scales, clamp);
                if (!cuda_ok(cudaGetLastError(), "aligned owned gate/up")) return 0;
                q8_K_quantize_owned_kernel<<<dim3(mb, n_tokens * n_expert), 256, 0, aligned_stream>>>(
                    mq, (const float *)mid->ptr, (const int32_t *)selected->ptr,
                    expert_mid_dim, n_tokens * n_expert, 0, n_total_expert);
                if (!cuda_ok(cudaGetLastError(), "aligned owned mid quantize")) return 0;
                const dim3 grid((out_dim + 31u) / 32u, n_tokens);
                if (n_expert == 6u) {
                    moe_down_sum_qwarp32_kernel<6, true><<<grid, 256, 0, aligned_stream>>>(
                        (float *)out->ptr, down_aligned, mq, (const int32_t *)selected->ptr,
