template <typename CT>
__device__ __forceinline__ static float2 glm_cache_rope_pair_f16_dev(
        const CT *rope_cache, uint64_t rope_base, uint32_t r,
        uint32_t row, uint32_t qk_rope, float freq_base, float freq_scale,
        float ext_factor, float attn_factor, const float corr_dims[2]) {
    const float theta_base = (float)row;
    const float inv_ndims = -1.0f / (float)qk_rope;
    const float theta = theta_base * powf(freq_base, inv_ndims * (float)r);
    float ct, st;
    glm_rope_yarn_dev(theta, freq_scale, corr_dims, (int)r,
                      ext_factor, attn_factor, &ct, &st);
    const float x0 = (float)rope_cache[rope_base + r];
    const float x1 = (float)rope_cache[rope_base + r + 1u];
    return make_float2(x0 * ct - x1 * st, x0 * st + x1 * ct);
}

__global__ static void glm_dense_attn_pack_q_f16_kernel(
        __half *packed,
        const float *q,
        uint32_t n_q,
        uint32_t n_head,
        uint32_t head0,
        uint32_t group_heads,
        uint32_t dim) {
    const uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const uint64_t count = (uint64_t)group_heads * n_q * dim;
    if (i >= count) return;
    const uint32_t d = (uint32_t)(i % dim);
    const uint64_t row = i / dim;
    const uint32_t token = (uint32_t)(row % n_q);
    const uint32_t head = head0 + (uint32_t)(row / n_q);
    packed[i] = __float2half(q[((uint64_t)token * n_head + head) * dim + d]);
}

__global__ static void glm_dense_attn_causal_softmax_f16_kernel(
        __half *prob,
        const float *scores,
        uint32_t n_q,
        uint32_t n_kv,
        uint32_t q_row0,
        float scale) {
    const uint32_t token = blockIdx.x;
    const uint32_t group_head = blockIdx.y;
    if (token >= n_q) return;
    const uint32_t visible = min(n_kv, q_row0 + token + 1u);
    const uint64_t row = ((uint64_t)group_head * n_q + token) * n_kv;

    float local_max = -FLT_MAX;
    for (uint32_t col = threadIdx.x; col < visible; col += blockDim.x) {
        local_max = fmaxf(local_max, scores[row + col] * scale);
    }
    __shared__ float reduce[256];
    reduce[threadIdx.x] = local_max;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1u; stride > 0u; stride >>= 1u) {
        if (threadIdx.x < stride) {
            reduce[threadIdx.x] = fmaxf(reduce[threadIdx.x],
                                         reduce[threadIdx.x + stride]);
        }
        __syncthreads();
    }
    const float max_score = reduce[0];
    __syncthreads();

    float local_sum = 0.0f;
    for (uint32_t col = threadIdx.x; col < visible; col += blockDim.x) {
        local_sum += expf(scores[row + col] * scale - max_score);
    }
    reduce[threadIdx.x] = local_sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1u; stride > 0u; stride >>= 1u) {
        if (threadIdx.x < stride) {
            reduce[threadIdx.x] += reduce[threadIdx.x + stride];
        }
        __syncthreads();
    }
    const float inv_sum = reduce[0] > 0.0f ? 1.0f / reduce[0] : 0.0f;
    for (uint32_t col = threadIdx.x; col < n_kv; col += blockDim.x) {
        const float p = col < visible
            ? expf(scores[row + col] * scale - max_score) * inv_sum : 0.0f;
        prob[row + col] = __float2half(p);
    }
}

__global__ static void glm_dense_attn_unpack_f32_kernel(
        float *out,
        const float *packed,
        uint32_t n_q,
        uint32_t n_head,
        uint32_t head0,
        uint32_t group_heads,
        uint32_t dim) {
    const uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const uint64_t count = (uint64_t)group_heads * n_q * dim;
    if (i >= count) return;
    const uint32_t d = (uint32_t)(i % dim);
    const uint64_t row = i / dim;
    const uint32_t token = (uint32_t)(row % n_q);
    const uint32_t head = head0 + (uint32_t)(row / n_q);
    out[((uint64_t)token * n_head + head) * dim + d] = packed[i];
}

extern "C" int ds4_gpu_glm_attention_dense_compact_lora_causal_tensor(
        ds4_gpu_tensor       *lora_out,
        const ds4_gpu_tensor *qk_low,
        const ds4_gpu_tensor *kv_lora_cache,
        uint32_t              q_row0,
        uint32_t              n_q,
        uint32_t              n_kv,
        uint32_t              cache_cap,
        bool                  cache_f16,
        uint32_t              n_head,
        uint32_t              kv_lora_dim,
        uint32_t              qk_dim) {
    if (!lora_out || !qk_low || !kv_lora_cache || !g_cublas_ready ||
        g_n_gpus != 1 || n_q == 0u || n_kv == 0u || n_kv > cache_cap ||
        q_row0 >= n_kv || n_q > n_kv - q_row0 || !cache_f16 ||
        n_q > INT_MAX || n_kv > INT_MAX || n_head == 0u ||
        kv_lora_dim != 512u || qk_dim == 0u ||
        qk_low->bytes < (uint64_t)n_q * n_head * kv_lora_dim * sizeof(float) ||
        kv_lora_cache->bytes < (uint64_t)cache_cap * kv_lora_dim * sizeof(__half) ||
        lora_out->bytes < (uint64_t)n_q * n_head * kv_lora_dim * sizeof(float)) {
        return 0;
    }

    const uint32_t visible_kv = min(n_kv, q_row0 + n_q);
    const uint32_t max_group_heads = min(n_head, 8u);
    if ((uint64_t)n_q > UINT64_MAX / max_group_heads / visible_kv) {
        return 0;
    }
    const uint64_t q_count =
        (uint64_t)max_group_heads * n_q * kv_lora_dim;
    const uint64_t score_count =
        (uint64_t)max_group_heads * n_q * visible_kv;
    const uint64_t q_bytes = q_count * sizeof(__half);
    const uint64_t score_off = (q_bytes + 255u) & ~255ull;
    const uint64_t score_bytes = score_count * sizeof(float);
    const uint64_t prob_off = (score_off + score_bytes + 255u) & ~255ull;
    const uint64_t prob_bytes = score_count * sizeof(__half);
    const uint64_t out_off = (prob_off + prob_bytes + 255u) & ~255ull;
    const uint64_t out_bytes = q_count * sizeof(float);
    if (score_off < q_bytes || prob_off < score_off || out_off < prob_off ||
        out_off > UINT64_MAX - out_bytes) {
        return 0;
    }
    unsigned char *scratch = (unsigned char *)cuda_tmp_alloc_on(
        0, out_off + out_bytes, "GLM dense compact attention");
    if (!scratch) return 0;
    __half *q_half = (__half *)scratch;
    float *scores = (float *)(scratch + score_off);
    __half *prob = (__half *)(scratch + prob_off);
    float *packed_out = (float *)(scratch + out_off);
    const __half *kv = (const __half *)kv_lora_cache->ptr;
    const float attn_scale = 1.0f / sqrtf((float)qk_dim);
    cublasHandle_t handle = cuda_cublas_for_tier(0);
    const float alpha = 1.0f;
    const float beta = 0.0f;

    for (uint32_t head0 = 0; head0 < n_head; head0 += max_group_heads) {
        const uint32_t group_heads = min(max_group_heads, n_head - head0);
        const uint64_t group_q_count =
            (uint64_t)group_heads * n_q * kv_lora_dim;
        glm_dense_attn_pack_q_f16_kernel<<<
            (group_q_count + 255u) / 256u, 256, 0, cuda_decode_stream()>>>(
                q_half, (const float *)qk_low->ptr, n_q, n_head, head0,
                group_heads, kv_lora_dim);
        if (!cuda_ok(cudaGetLastError(),
                     "GLM dense attention Q pack launch")) return 0;

        cublasStatus_t st = cublasGemmStridedBatchedEx(
            handle,
            CUBLAS_OP_T, CUBLAS_OP_N,
            (int)visible_kv, (int)n_q, (int)kv_lora_dim,
            &alpha,
            kv, CUDA_R_16F, (int)kv_lora_dim, 0,
            q_half, CUDA_R_16F, (int)kv_lora_dim,
            (long long)n_q * kv_lora_dim,
            &beta,
            scores, CUDA_R_32F, (int)visible_kv,
            (long long)n_q * visible_kv,
            (int)group_heads,
            CUBLAS_COMPUTE_32F,
            CUBLAS_GEMM_DEFAULT);
        if (!cublas_ok(st, "GLM dense attention score GEMM")) return 0;

        dim3 softmax_grid(n_q, group_heads, 1u);
        glm_dense_attn_causal_softmax_f16_kernel<<<
            softmax_grid, 256, 0, cuda_decode_stream()>>>(
                prob, scores, n_q, visible_kv, q_row0, attn_scale);
        if (!cuda_ok(cudaGetLastError(),
                     "GLM dense attention softmax launch")) return 0;

        st = cublasGemmStridedBatchedEx(
            handle,
            CUBLAS_OP_N, CUBLAS_OP_N,
            (int)kv_lora_dim, (int)n_q, (int)visible_kv,
            &alpha,
            kv, CUDA_R_16F, (int)kv_lora_dim, 0,
            prob, CUDA_R_16F, (int)visible_kv,
            (long long)n_q * visible_kv,
            &beta,
            packed_out, CUDA_R_32F, (int)kv_lora_dim,
            (long long)n_q * kv_lora_dim,
            (int)group_heads,
            CUBLAS_COMPUTE_32F,
            CUBLAS_GEMM_DEFAULT);
        if (!cublas_ok(st, "GLM dense attention value GEMM")) return 0;

        glm_dense_attn_unpack_f32_kernel<<<
            (group_q_count + 255u) / 256u, 256, 0, cuda_decode_stream()>>>(
                (float *)lora_out->ptr, packed_out, n_q, n_head, head0,
                group_heads, kv_lora_dim);
        if (!cuda_ok(cudaGetLastError(),
                     "GLM dense attention output unpack launch")) return 0;
    }
    return 1;
}

/* Scalar-correct MLA attention: one warp per head, grid
 * (ceil(n_head/8), n_tokens). The row loop handles either a contiguous
 * causal range or an explicit selected-row list and mirrors the Metal online
 * softmax so numerics stay comparable. */
template <typename CT, bool selected_rows>
__global__ static void glm_attention_lora_causal_kernel(
        float *lora_out,
        const float *q,
        const float *qk_low,
        const CT *kv_lora_cache,
        const CT *k_rope_cache,
        const uint32_t *selected,
        uint32_t cache_cap,
        uint32_t n_tokens,
        uint32_t pos0,
        uint32_t n_selected,
        uint32_t n_head,
        uint32_t kv_lora_dim,
        uint32_t qk_nope,
        uint32_t qk_rope,
        uint32_t n_ctx_orig,
        float freq_base,
        float freq_scale,
        float ext_factor,
        float attn_factor,
        float beta_fast,
        float beta_slow,
        float scale) {
    const uint32_t token = blockIdx.y;
    const uint32_t warp = threadIdx.x >> 5;
    const uint32_t lane = threadIdx.x & 31u;
    const uint32_t head = blockIdx.x * 8u + warp;
    if (token >= n_tokens || head >= n_head || kv_lora_dim != 512u ||
        (qk_rope != 0u && qk_rope != 64u)) {
        return;
    }
    const uint32_t visible = selected_rows
        ? n_selected : min(n_selected, pos0 + token + 1u);
    if (visible == 0u) return;

    const uint32_t qk_dim = qk_nope + qk_rope;
    const float *qh = q + (uint64_t)token * n_head * qk_dim +
                      (uint64_t)head * qk_dim;
    const float4 *low4 = (const float4 *)(qk_low +
        (uint64_t)token * n_head * kv_lora_dim +
        (uint64_t)head * kv_lora_dim);

    float4 low0 = low4[lane];
    float4 low1 = low4[lane + 32u];
    float4 low2 = low4[lane + 64u];
    float4 low3 = low4[lane + 96u];
    float4 qrope = make_float4(0.f, 0.f, 0.f, 0.f);
    const uint32_t rope_vecs = qk_rope >> 2;   /* 16 */
    if (lane < rope_vecs) {
        qrope = *((const float4 *)(qh + qk_nope + lane * 4u));
    }

    float corr_dims[2] = {0.0f, 0.0f};
    if (qk_rope != 0u && ext_factor != 0.0f) {
        corr_dims[0] = fmaxf(0.0f,
            floorf(glm_rope_yarn_corr_factor_dev((int)qk_rope, (int)n_ctx_orig,
                                                 beta_fast, freq_base)));
        corr_dims[1] = fminf((float)qk_rope - 1.0f,
            ceilf(glm_rope_yarn_corr_factor_dev((int)qk_rope, (int)n_ctx_orig,
                                                beta_slow, freq_base)));
    }

    float M = -FLT_MAX / 2.0f;
    float S = 0.0f;
    float4 o0 = make_float4(0.f,0.f,0.f,0.f);
    float4 o1 = o0, o2 = o0, o3 = o0;

    for (uint32_t ri = 0u; ri < visible; ri++) {
        const uint32_t row = selected_rows
            ? selected[(uint64_t)token * n_selected + ri] : ri;
        if (row >= cache_cap) continue;
        const CT *kvrow = kv_lora_cache + (uint64_t)row * kv_lora_dim;
        float partial = 0.0f;
        {
            const float4 k0 = make_float4(
                (float)(kvrow[lane*4u+0u]), (float)(kvrow[lane*4u+1u]),
                (float)(kvrow[lane*4u+2u]), (float)(kvrow[lane*4u+3u]));
            const float4 k1 = make_float4(
                (float)(kvrow[(lane+32u)*4u+0u]), (float)(kvrow[(lane+32u)*4u+1u]),
                (float)(kvrow[(lane+32u)*4u+2u]), (float)(kvrow[(lane+32u)*4u+3u]));
            const float4 k2 = make_float4(
                (float)(kvrow[(lane+64u)*4u+0u]), (float)(kvrow[(lane+64u)*4u+1u]),
                (float)(kvrow[(lane+64u)*4u+2u]), (float)(kvrow[(lane+64u)*4u+3u]));
            const float4 k3 = make_float4(
                (float)(kvrow[(lane+96u)*4u+0u]), (float)(kvrow[(lane+96u)*4u+1u]),
                (float)(kvrow[(lane+96u)*4u+2u]), (float)(kvrow[(lane+96u)*4u+3u]));
            partial += low0.x*k0.x + low0.y*k0.y + low0.z*k0.z + low0.w*k0.w;
            partial += low1.x*k1.x + low1.y*k1.y + low1.z*k1.z + low1.w*k1.w;
            partial += low2.x*k2.x + low2.y*k2.y + low2.z*k2.z + low2.w*k2.w;
            partial += low3.x*k3.x + low3.y*k3.y + low3.z*k3.z + low3.w*k3.w;
            if (lane < rope_vecs) {
                const uint64_t rope_base = (uint64_t)row * qk_rope;
                const uint32_t r = lane * 4u;
                const float2 y0 = glm_cache_rope_pair_f16_dev(
                        k_rope_cache, rope_base, r, row, qk_rope, freq_base,
                        freq_scale, ext_factor, attn_factor, corr_dims);
                const float2 y1 = glm_cache_rope_pair_f16_dev(
                        k_rope_cache, rope_base, r + 2u, row, qk_rope,
                        freq_base, freq_scale, ext_factor, attn_factor,
                        corr_dims);
                partial += qrope.x*y0.x + qrope.y*y0.y +
                           qrope.z*y1.x + qrope.w*y1.y;
            }
            for (uint32_t off = 16u; off > 0u; off >>= 1u) {
                partial += __shfl_xor_sync(0xffffffffu, partial, off);
            }
            const float score = partial * scale;
            const float new_m = fmaxf(M, score);
            const float old_scale = expf(M - new_m);
            const float row_scale = expf(score - new_m);
            o0.x = o0.x*old_scale + k0.x*row_scale; o0.y = o0.y*old_scale + k0.y*row_scale;
            o0.z = o0.z*old_scale + k0.z*row_scale; o0.w = o0.w*old_scale + k0.w*row_scale;
            o1.x = o1.x*old_scale + k1.x*row_scale; o1.y = o1.y*old_scale + k1.y*row_scale;
            o1.z = o1.z*old_scale + k1.z*row_scale; o1.w = o1.w*old_scale + k1.w*row_scale;
            o2.x = o2.x*old_scale + k2.x*row_scale; o2.y = o2.y*old_scale + k2.y*row_scale;
            o2.z = o2.z*old_scale + k2.z*row_scale; o2.w = o2.w*old_scale + k2.w*row_scale;
            o3.x = o3.x*old_scale + k3.x*row_scale; o3.y = o3.y*old_scale + k3.y*row_scale;
            o3.z = o3.z*old_scale + k3.z*row_scale; o3.w = o3.w*old_scale + k3.w*row_scale;
            S = S*old_scale + row_scale;
            M = new_m;
        }
    }

    const float inv_s = S > 0.0f ? 1.0f / S : 0.0f;
    float4 *out4 = (float4 *)(lora_out +
        ((uint64_t)token * n_head + head) * kv_lora_dim);
    o0.x*=inv_s; o0.y*=inv_s; o0.z*=inv_s; o0.w*=inv_s;
    o1.x*=inv_s; o1.y*=inv_s; o1.z*=inv_s; o1.w*=inv_s;
    o2.x*=inv_s; o2.y*=inv_s; o2.z*=inv_s; o2.w*=inv_s;
    o3.x*=inv_s; o3.y*=inv_s; o3.z*=inv_s; o3.w*=inv_s;
    out4[lane] = o0;
    out4[lane + 32u] = o1;
    out4[lane + 64u] = o2;
    out4[lane + 96u] = o3;
}

extern "C" int ds4_gpu_glm_attention_indexed_batch_lora_causal_tensor(
        ds4_gpu_tensor       *lora_out,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *qk_low,
        const ds4_gpu_tensor *kv_lora_cache,
        const ds4_gpu_tensor *k_rope_cache,
        uint32_t              n_tokens,
        uint32_t              pos0,
        uint32_t              n_selected,
        uint32_t              cache_cap,
        bool                  cache_f16,
        uint32_t              n_head,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_rope,
        uint32_t              n_ctx_orig,
        float                 freq_base,
        float                 freq_scale,
        float                 ext_factor,
        float                 attn_factor,
        float                 beta_fast,
        float                 beta_slow) {
    if (!lora_out || !q || !qk_low || !kv_lora_cache || !k_rope_cache ||
        n_tokens == 0 || n_head == 0 || kv_lora_dim != 512u ||
        (qk_rope != 0u && qk_rope != 64u)) {
        fprintf(stderr, "ds4: glm attn lora causal: unsupported config "
                "(n_tok=%u head=%u lora=%u rope=%u f16=%d)\n",
                n_tokens, n_head, kv_lora_dim, qk_rope, (int)cache_f16);
        return 0;
    }
    const float scale = 1.0f / sqrtf((float)(qk_nope + qk_rope));
    dim3 grid((n_head + 7u) / 8u, n_tokens, 1);
    if (cache_f16) {
        glm_attention_lora_causal_kernel<__half, false><<<grid, 256>>>(
                (float *)lora_out->ptr,
                (const float *)q->ptr,
                (const float *)qk_low->ptr,
                (const __half *)kv_lora_cache->ptr,
                (const __half *)k_rope_cache->ptr,
                NULL, cache_cap,
                n_tokens, pos0, n_selected, n_head, kv_lora_dim, qk_nope,
                qk_rope, n_ctx_orig, freq_base, freq_scale, ext_factor,
                attn_factor, beta_fast, beta_slow, scale);
    } else {
        glm_attention_lora_causal_kernel<float, false><<<grid, 256>>>(
                (float *)lora_out->ptr,
                (const float *)q->ptr,
                (const float *)qk_low->ptr,
                (const float *)kv_lora_cache->ptr,
                (const float *)k_rope_cache->ptr,
                NULL, cache_cap,
                n_tokens, pos0, n_selected, n_head, kv_lora_dim, qk_nope,
                qk_rope, n_ctx_orig, freq_base, freq_scale, ext_factor,
                attn_factor, beta_fast, beta_slow, scale);
    }
    return cuda_ok(cudaGetLastError(), "glm attn lora causal launch");
}

