__device__ __forceinline__ static float glm_q8_0_dot_row_dev(
        const char *row, const float *x, uint32_t n_cols) {
    float acc = 0.0f;
    const uint32_t nb = n_cols >> 5;
    for (uint32_t b = 0; b < nb; b++) {
        const char *blk = row + (uint64_t)b * 34u;
        const float d = __half2float(*(const __half *)blk);
        const int8_t *q = (const int8_t *)(blk + 2);
        float s = 0.0f;
        #pragma unroll 8
        for (uint32_t k = 0; k < 32u; k++) s += (float)q[k] * x[b * 32u + k];
        acc += d * s;
    }
    return acc;
}

template <typename CT>
__device__ __forceinline__ static float2 glm_cache_value_pair_dev(
        const CT *p) {
    return make_float2((float)p[0], (float)p[1]);
}

template <>
__device__ __forceinline__ float2 glm_cache_value_pair_dev<__half>(
        const __half *p) {
    return __half22float2(*(const __half2 *)p);
}

template <>
__device__ __forceinline__ float2 glm_cache_value_pair_dev<float>(
        const float *p) {
    return *(const float2 *)p;
}

/* Exact staged decode attention. The original fused kernel owns one block per
 * head, which leaves more than half of an L40S idle. These stages preserve the
 * fused kernel's arithmetic order for every score, softmax lane, lora output,
 * and value-projection row while exposing independent rows/dimensions as
 * separate blocks. */
template <typename CT, bool RANGE_TOK2 = false>
__global__ static void glm_attention_decode_weights_staged_kernel(
        float *weights,
        float *denom,
        const float *q,
        const float *qk_low,
        const CT *kv_lora_cache,
        const CT *k_rope_cache,
        const uint32_t *selected,
        uint32_t n_selected,
        uint32_t cache_cap,
        uint32_t n_head,
        uint32_t kv_lora_dim,
        uint32_t qk_nope,
        uint32_t qk_rope,
        float scale,
        uint32_t n_ctx_orig,
        float freq_base,
        float freq_scale,
        float ext_factor,
        float attn_factor,
        float beta_fast,
        float beta_slow,
        bool score_vec2) {
    const uint32_t head = blockIdx.x;
    const uint32_t token = RANGE_TOK2 ? blockIdx.y : 0u;
    const uint32_t row_count = n_selected + (RANGE_TOK2 ? token : 0u);
    const uint32_t score_stride = n_selected + (RANGE_TOK2 ? 1u : 0u);
    const uint32_t tid = threadIdx.x;
    const uint32_t nth = blockDim.x;
    if (head >= n_head || row_count == 0u) return;
    const uint32_t qk_dim = qk_nope + qk_rope;
    extern __shared__ float glm_dec_stage_sh[];
    float *red = glm_dec_stage_sh;
    float *scores = glm_dec_stage_sh + 256u;
    const float *qh = q +
        ((uint64_t)token * n_head + head) * qk_dim;
    const float *low = qk_low +
        ((uint64_t)token * n_head + head) * kv_lora_dim;

    float corr_dims[2] = {0.0f, 0.0f};
    if (qk_rope != 0u && ext_factor != 0.0f) {
        corr_dims[0] = fmaxf(0.0f,
            floorf(glm_rope_yarn_corr_factor_dev((int)qk_rope,
                    (int)n_ctx_orig, beta_fast, freq_base)));
        corr_dims[1] = fminf((float)qk_rope - 1.0f,
            ceilf(glm_rope_yarn_corr_factor_dev((int)qk_rope,
                    (int)n_ctx_orig, beta_slow, freq_base)));
    }

    float local_max = -FLT_MAX;
    for (uint32_t s = tid; s < row_count; s += nth) {
        const uint32_t row = RANGE_TOK2 ? s : selected[s];
        float score = -FLT_MAX;
        if (row < cache_cap) {
            float dotv = 0.0f;
            const uint64_t lora_base = (uint64_t)row * kv_lora_dim;
            if (score_vec2) {
                for (uint32_t j = 0; j < kv_lora_dim; j += 2u) {
                    const float2 x = *(const float2 *)(low + j);
                    const float2 y = glm_cache_value_pair_dev(
                            kv_lora_cache + lora_base + j);
                    dotv += x.x * y.x;
                    dotv += x.y * y.y;
                }
            } else {
                for (uint32_t j = 0; j < kv_lora_dim; j++) {
                    dotv += low[j] * (float)kv_lora_cache[lora_base + j];
                }
            }
            const uint64_t rope_base = (uint64_t)row * qk_rope;
            for (uint32_t r = 0; r < qk_rope; r += 2u) {
                const float2 y = glm_cache_rope_pair_f16_dev<CT>(
                        k_rope_cache, rope_base, r, row, qk_rope,
                        freq_base, freq_scale, ext_factor, attn_factor,
                        corr_dims);
                dotv += qh[qk_nope + r] * y.x +
                        qh[qk_nope + r + 1u] * y.y;
            }
            score = dotv * scale;
        }
        scores[s] = score;
        local_max = fmaxf(local_max, score);
    }
    red[tid] = local_max;
    __syncthreads();
    for (uint32_t step = nth >> 1; step > 0; step >>= 1) {
        if (tid < step) red[tid] = fmaxf(red[tid], red[tid + step]);
        __syncthreads();
    }
    const float max_score = red[0];
    __syncthreads();

    float local_sum = 0.0f;
    for (uint32_t s = tid; s < row_count; s += nth) {
        const float w = expf(scores[s] - max_score);
        scores[s] = w;
        local_sum += w;
    }
    red[tid] = local_sum;
    __syncthreads();
    for (uint32_t step = nth >> 1; step > 0; step >>= 1) {
        if (tid < step) red[tid] += red[tid + step];
        __syncthreads();
    }
    const uint64_t head_index = (uint64_t)token * n_head + head;
    if (tid == 0u) denom[head_index] = fmaxf(red[0], 1.0e-20f);
    float *head_weights = weights + head_index * score_stride;
    for (uint32_t s = tid; s < row_count; s += nth) {
        head_weights[s] = scores[s];
    }
}

template <typename CT, bool RANGE_TOK2 = false>
__global__ static void glm_attention_decode_lora_staged_kernel(
        float *lora_sum,
        const float *scores,
        const float *denom,
        const CT *kv_lora_cache,
        const uint32_t *selected,
        uint32_t n_selected,
        uint32_t cache_cap,
        uint32_t n_head,
        uint32_t kv_lora_dim) {
    const uint32_t head = blockIdx.y;
    const uint32_t token = RANGE_TOK2 ? blockIdx.z : 0u;
    const uint32_t row_count = n_selected + (RANGE_TOK2 ? token : 0u);
    const uint32_t score_stride = n_selected + (RANGE_TOK2 ? 1u : 0u);
    const uint32_t pair = blockIdx.x * blockDim.x + threadIdx.x;
    const uint32_t j = pair * 2u;
    if (head >= n_head || j >= kv_lora_dim) return;
    const uint64_t head_index = (uint64_t)token * n_head + head;
    const float *head_scores = scores + head_index * score_stride;
    float acc0 = 0.0f;
    float acc1 = 0.0f;
    for (uint32_t s = 0; s < row_count; s++) {
        const uint32_t row = RANGE_TOK2 ? s : selected[s];
        if (row < cache_cap) {
            const float2 v = glm_cache_value_pair_dev(
                    kv_lora_cache + (uint64_t)row * kv_lora_dim + j);
            const float w = head_scores[s];
            acc0 += w * v.x;
            acc1 += w * v.y;
        }
    }
    float *out = lora_sum + head_index * kv_lora_dim + j;
    out[0] = acc0 / denom[head_index];
    out[1] = acc1 / denom[head_index];
}

template <bool TOK2 = false>
__global__ static void glm_attention_decode_value_staged_kernel(
        float *heads,
        const float *lora_sum,
        const char *value_weight,
        uint32_t n_head,
        uint32_t kv_lora_dim,
        uint32_t value_dim,
        uint32_t value_row_bytes) {
    const uint32_t head = blockIdx.y;
    const uint32_t token = TOK2 ? blockIdx.z : 0u;
    const uint32_t warp = threadIdx.x >> 5;
    const uint32_t lane = threadIdx.x & 31u;
    const uint32_t nwarps = blockDim.x >> 5;
    const uint32_t out_warp = blockIdx.x * nwarps + warp;
    const uint32_t total_warps = gridDim.x * nwarps;
    if (head >= n_head) return;
    const float *low = lora_sum +
        ((uint64_t)token * n_head + head) * kv_lora_dim;
    float *out = heads +
        ((uint64_t)token * n_head + head) * value_dim;
    const uint32_t nblk = kv_lora_dim >> 5;
    for (uint32_t d = out_warp; d < value_dim; d += total_warps) {
        const char *row = value_weight +
            ((uint64_t)head * value_dim + d) * value_row_bytes;
        float acc = 0.0f;
        for (uint32_t blk = lane >> 1; blk < nblk; blk += 16u) {
            const char *b = row + (uint64_t)blk * 34u;
            const float dscale = __half2float(*(const __half *)b);
            const int8_t *q = (const int8_t *)(b + 2) + (lane & 1u) * 16u;
            const float *xs = low + blk * 32u + (lane & 1u) * 16u;
            float s = 0.0f;
            #pragma unroll
            for (int k = 0; k < 16; k++) s += (float)q[k] * xs[k];
            acc += dscale * s;
        }
        for (int off = 16; off > 0; off >>= 1) {
            acc += __shfl_down_sync(0xffffffffu, acc, off);
        }
        if (lane == 0u) out[d] = acc;
    }
}

/* Single-token indexed MLA decode attention, one block per head.
 * Fuses score (qk_low . kv_lora + q_rope . rope(k_rope@row)), softmax over
 * the indexer-selected rows, the weighted kv_lora sum, and the per-head
 * value projection (q8_0). Dynamic shared: red[256] + scores[n_selected] +
 * lora_sum[kv_lora_dim]. */
template <typename CT, bool RANGE_TOK2 = false>
__global__ static void glm_attention_indexed_decode_kernel(
        float *heads,
        const float *q,
        const float *qk_low,
        const CT *kv_lora_cache,
        const CT *k_rope_cache,
        const char *value_weight,
        const uint32_t *selected,
        uint32_t n_selected,
        uint32_t cache_cap,
        uint32_t n_head,
        uint32_t kv_lora_dim,
        uint32_t qk_nope,
        uint32_t qk_rope,
        uint32_t value_dim,
        uint32_t value_row_bytes,
        bool lora_vec2,
        bool score_vec2,
        float scale,
        uint32_t n_ctx_orig,
        float freq_base,
        float freq_scale,
        float ext_factor,
        float attn_factor,
        float beta_fast,
        float beta_slow) {
    const uint32_t head = blockIdx.x;
    const uint32_t token = RANGE_TOK2 ? blockIdx.y : 0u;
    const uint32_t row_count = n_selected + (RANGE_TOK2 ? token : 0u);
    const uint32_t tid = threadIdx.x;
    const uint32_t nth = blockDim.x;
    if (head >= n_head || row_count == 0u) return;
    const uint32_t qk_dim = qk_nope + qk_rope;

    extern __shared__ float glm_dec_sh[];
    float *red = glm_dec_sh;
    float *scores = glm_dec_sh + 256u;
    float *lora_sum = scores + row_count;

    const float *qh = q +
        ((uint64_t)token * n_head + head) * qk_dim;
    const float *low = qk_low +
        ((uint64_t)token * n_head + head) * kv_lora_dim;

    float corr_dims[2] = {0.0f, 0.0f};
    if (qk_rope != 0u && ext_factor != 0.0f) {
        corr_dims[0] = fmaxf(0.0f,
            floorf(glm_rope_yarn_corr_factor_dev((int)qk_rope,
                    (int)n_ctx_orig, beta_fast, freq_base)));
        corr_dims[1] = fminf((float)qk_rope - 1.0f,
            ceilf(glm_rope_yarn_corr_factor_dev((int)qk_rope,
                    (int)n_ctx_orig, beta_slow, freq_base)));
    }

    float local_max = -FLT_MAX;
    for (uint32_t s = tid; s < row_count; s += nth) {
        const uint32_t row = RANGE_TOK2 ? s : selected[s];
        float score = -FLT_MAX;
        if (row < cache_cap) {
            float dotv = 0.0f;
            const uint64_t lora_base = (uint64_t)row * kv_lora_dim;
            if (score_vec2) {
                for (uint32_t j = 0; j < kv_lora_dim; j += 2u) {
                    const float2 x = *(const float2 *)(low + j);
                    const float2 y = glm_cache_value_pair_dev(
                            kv_lora_cache + lora_base + j);
                    dotv += x.x * y.x;
                    dotv += x.y * y.y;
                }
            } else {
                for (uint32_t j = 0; j < kv_lora_dim; j++) {
                    dotv += low[j] * (float)kv_lora_cache[lora_base + j];
                }
            }
            const uint64_t rope_base = (uint64_t)row * qk_rope;
            for (uint32_t r = 0; r < qk_rope; r += 2u) {
                const float2 y = glm_cache_rope_pair_f16_dev<CT>(
                        k_rope_cache, rope_base, r, row, qk_rope,
                        freq_base, freq_scale, ext_factor, attn_factor,
                        corr_dims);
                dotv += qh[qk_nope + r] * y.x + qh[qk_nope + r + 1u] * y.y;
            }
            score = dotv * scale;
        }
        scores[s] = score;
        local_max = fmaxf(local_max, score);
    }
    red[tid] = local_max;
    __syncthreads();
    for (uint32_t step = nth >> 1; step > 0; step >>= 1) {
        if (tid < step) red[tid] = fmaxf(red[tid], red[tid + step]);
        __syncthreads();
    }
    const float max_score = red[0];
    __syncthreads();

    float local_sum = 0.0f;
    for (uint32_t s = tid; s < row_count; s += nth) {
        const float w = expf(scores[s] - max_score);
        scores[s] = w;
        local_sum += w;
    }
    red[tid] = local_sum;
    __syncthreads();
    for (uint32_t step = nth >> 1; step > 0; step >>= 1) {
        if (tid < step) red[tid] += red[tid + step];
        __syncthreads();
    }
    const float denom = fmaxf(red[0], 1.0e-20f);
    __syncthreads();

    if (lora_vec2) {
        for (uint32_t j = tid * 2u; j < kv_lora_dim; j += nth * 2u) {
            float acc0 = 0.0f;
            float acc1 = 0.0f;
            for (uint32_t s = 0; s < row_count; s++) {
                const uint32_t row = RANGE_TOK2 ? s : selected[s];
                if (row < cache_cap) {
                    const float2 v = glm_cache_value_pair_dev(
                            kv_lora_cache + (uint64_t)row * kv_lora_dim + j);
                    const float w = scores[s];
                    acc0 += w * v.x;
                    acc1 += w * v.y;
                }
            }
            lora_sum[j] = acc0 / denom;
            lora_sum[j + 1u] = acc1 / denom;
        }
    } else {
        for (uint32_t j = tid; j < kv_lora_dim; j += nth) {
            float acc = 0.0f;
            for (uint32_t s = 0; s < row_count; s++) {
                const uint32_t row = RANGE_TOK2 ? s : selected[s];
                if (row < cache_cap) {
                    acc += scores[s] *
                           (float)kv_lora_cache[(uint64_t)row * kv_lora_dim + j];
                }
            }
            lora_sum[j] = acc / denom;
        }
    }
    __syncthreads();

    float *out = heads +
        ((uint64_t)token * n_head + head) * value_dim;
    /* Warp-cooperative value projection: one warp per output dim, two
     * lanes per q8_0 block (16 cols each). */
    const uint32_t nwarps = nth >> 5;
    const uint32_t warp = tid >> 5;
    const uint32_t lane = tid & 31u;
    const uint32_t nblk = kv_lora_dim >> 5;
    for (uint32_t d = warp; d < value_dim; d += nwarps) {
        const char *row = value_weight +
            ((uint64_t)head * value_dim + d) * value_row_bytes;
        float acc = 0.0f;
        for (uint32_t blk = lane >> 1; blk < nblk; blk += 16u) {
            const char *b = row + (uint64_t)blk * 34u;
            const float dscale = __half2float(*(const __half *)b);
            const int8_t *q = (const int8_t *)(b + 2) + (lane & 1u) * 16u;
            const float *xs = lora_sum + blk * 32u + (lane & 1u) * 16u;
            float s = 0.0f;
            #pragma unroll
            for (int k = 0; k < 16; k++) s += (float)q[k] * xs[k];
            acc += dscale * s;
        }
        for (int off = 16; off > 0; off >>= 1) {
            acc += __shfl_down_sync(0xffffffffu, acc, off);
        }
        if (lane == 0u) out[d] = acc;
    }
}

extern "C" int ds4_gpu_glm_attention_indexed_decode_typed_tensor(
        ds4_gpu_tensor       *heads,
        const ds4_gpu_tensor *q,
        const ds4_gpu_tensor *qk_low,
        const ds4_gpu_tensor *kv_lora_cache,
        const ds4_gpu_tensor *k_rope_cache,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              value_weight_offset,
        uint32_t              value_weight_type,
        const ds4_gpu_tensor *selected,
        uint32_t              n_selected,
        uint32_t              cache_cap,
        bool                  cache_f16,
        uint32_t              n_head,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_rope,
        uint32_t              value_dim,
        uint32_t              n_ctx_orig,
        float                 freq_base,
        float                 freq_scale,
        float                 ext_factor,
        float                 attn_factor,
        float                 beta_fast,
        float                 beta_slow) {
    const uint32_t qk_dim = qk_nope + qk_rope;
    if (!heads || !q || !qk_low || !kv_lora_cache || !k_rope_cache ||
        !model_map || !selected ||
        n_selected == 0 || cache_cap == 0 || n_selected > cache_cap ||
        n_head == 0 || kv_lora_dim == 0 || (kv_lora_dim & 31u) != 0u ||
        qk_nope == 0 || (qk_rope & 1u) != 0u ||
        value_dim == 0) {
        return 0;
    }
    if (value_weight_type != 8u) {   /* DS4_TENSOR_Q8_0 */
        fprintf(stderr,
            "ds4: glm indexed decode attention: unsupported value type %u\n",
            value_weight_type);
        return 0;
    }
    const uint64_t value_row_bytes = ((uint64_t)kv_lora_dim / 32u) * 34u;
    const uint64_t value_weight_bytes =
        (uint64_t)n_head * value_dim * value_row_bytes;
    if (value_weight_offset > model_size ||
        value_weight_bytes > model_size - value_weight_offset) {
        return 0;
    }
    const uint64_t cache_elem = cache_f16 ? 2u : 4u;
    if (heads->bytes < (uint64_t)n_head * value_dim * sizeof(float) ||
        q->bytes < (uint64_t)n_head * qk_dim * sizeof(float) ||
        qk_low->bytes < (uint64_t)n_head * kv_lora_dim * sizeof(float) ||
        kv_lora_cache->bytes < (uint64_t)cache_cap * kv_lora_dim * cache_elem ||
        k_rope_cache->bytes < (uint64_t)cache_cap * qk_rope * cache_elem ||
        selected->bytes < (uint64_t)n_selected * sizeof(uint32_t)) {
        return 0;
    }
    const int logical_tier = cuda_current_tier();
    const char *vw = cuda_resolve_weight_ptr(model_map, value_weight_offset,
            value_weight_bytes, logical_tier, "glm_v_b_decode");
    if (!vw) return 0;
    const float scale = 1.0f / sqrtf((float)qk_dim);
    const bool score_vec2 = getenv("DS4_GLM_ATTN_NO_SCORE_VEC2") == NULL;
    const bool range_tok2 =
        g_glm_mtp_verify_mode &&
        getenv("DS4_GLM_MTP_NO_ATTN_TOK2") == NULL &&
        n_selected < cache_cap &&
        heads->bytes >= 2u * (uint64_t)n_head * value_dim * sizeof(float) &&
        q->bytes >= 2u * (uint64_t)n_head * qk_dim * sizeof(float) &&
        qk_low->bytes >=
            2u * (uint64_t)n_head * kv_lora_dim * sizeof(float);
    if (range_tok2 && n_selected < 512u) {
        const bool lora_vec2 =
            getenv("DS4_GLM_ATTN_NO_LORA_VEC2") == NULL;
        const uint32_t shmem =
            (256u + n_selected + 1u + kv_lora_dim) *
            (uint32_t)sizeof(float);
        const dim3 grid(n_head, 2u, 1u);
        if (cache_f16) {
            glm_attention_indexed_decode_kernel<__half, true>
                    <<<grid, 256, shmem>>>(
                    (float *)heads->ptr, (const float *)q->ptr,
                    (const float *)qk_low->ptr,
                    (const __half *)kv_lora_cache->ptr,
                    (const __half *)k_rope_cache->ptr,
                    vw, (const uint32_t *)selected->ptr,
                    n_selected, cache_cap, n_head, kv_lora_dim,
                    qk_nope, qk_rope, value_dim,
                    (uint32_t)value_row_bytes,
                    lora_vec2, score_vec2, scale, n_ctx_orig,
                    freq_base, freq_scale, ext_factor, attn_factor,
                    beta_fast, beta_slow);
        } else {
            glm_attention_indexed_decode_kernel<float, true>
                    <<<grid, 256, shmem>>>(
                    (float *)heads->ptr, (const float *)q->ptr,
                    (const float *)qk_low->ptr,
                    (const float *)kv_lora_cache->ptr,
                    (const float *)k_rope_cache->ptr,
                    vw, (const uint32_t *)selected->ptr,
                    n_selected, cache_cap, n_head, kv_lora_dim,
                    qk_nope, qk_rope, value_dim,
                    (uint32_t)value_row_bytes,
                    lora_vec2, score_vec2, scale, n_ctx_orig,
                    freq_base, freq_scale, ext_factor, attn_factor,
                    beta_fast, beta_slow);
        }
        return cuda_ok(cudaGetLastError(),
                       "glm indexed decode attention tok2 range");
    }
    if (n_selected >= 512u &&
        getenv("DS4_GLM_ATTN_NO_STAGED_DECODE") == NULL) {
        const uint32_t token_count = range_tok2 ? 2u : 1u;
        const uint32_t score_stride = n_selected + (range_tok2 ? 1u : 0u);
        const uint64_t head_count = (uint64_t)token_count * n_head;
        if (head_count > UINT64_MAX / score_stride ||
            head_count > UINT64_MAX / kv_lora_dim) {
            return 0;
        }
        const uint64_t score_count = head_count * score_stride;
        const uint64_t lora_count = head_count * kv_lora_dim;
        if (score_count > UINT64_MAX - head_count - lora_count ||
            score_count + head_count + lora_count >
                UINT64_MAX / sizeof(float)) {
            return 0;
        }
        const uint64_t scratch_bytes =
            (score_count + head_count + lora_count) * sizeof(float);
        float *scratch = (float *)cuda_tmp_alloc_on(
                ds4_tensor_device_idx(heads), scratch_bytes,
                "glm staged decode attention");
        if (!scratch) return 0;
        float *softmax_denom = scratch + score_count;
        float *lora_sum = softmax_denom + head_count;
        const uint32_t weight_shmem =
            (256u + score_stride) * (uint32_t)sizeof(float);
        const dim3 weight_grid(n_head, token_count, 1u);
        if (cache_f16 && range_tok2) {
            glm_attention_decode_weights_staged_kernel<__half, true>
                    <<<weight_grid, 256, weight_shmem>>>(
                    scratch, softmax_denom, (const float *)q->ptr,
                    (const float *)qk_low->ptr,
                    (const __half *)kv_lora_cache->ptr,
                    (const __half *)k_rope_cache->ptr,
                    (const uint32_t *)selected->ptr,
                    n_selected, cache_cap, n_head, kv_lora_dim,
                    qk_nope, qk_rope, scale, n_ctx_orig, freq_base,
                    freq_scale, ext_factor, attn_factor, beta_fast,
                    beta_slow, score_vec2);
        } else if (cache_f16) {
            glm_attention_decode_weights_staged_kernel<__half>
                    <<<weight_grid, 256, weight_shmem>>>(
                    scratch, softmax_denom, (const float *)q->ptr,
                    (const float *)qk_low->ptr,
                    (const __half *)kv_lora_cache->ptr,
                    (const __half *)k_rope_cache->ptr,
                    (const uint32_t *)selected->ptr,
                    n_selected, cache_cap, n_head, kv_lora_dim,
                    qk_nope, qk_rope, scale, n_ctx_orig, freq_base,
                    freq_scale, ext_factor, attn_factor, beta_fast,
                    beta_slow, score_vec2);
        } else if (range_tok2) {
            glm_attention_decode_weights_staged_kernel<float, true>
                    <<<weight_grid, 256, weight_shmem>>>(
                    scratch, softmax_denom, (const float *)q->ptr,
                    (const float *)qk_low->ptr,
                    (const float *)kv_lora_cache->ptr,
                    (const float *)k_rope_cache->ptr,
                    (const uint32_t *)selected->ptr,
                    n_selected, cache_cap, n_head, kv_lora_dim,
                    qk_nope, qk_rope, scale, n_ctx_orig, freq_base,
                    freq_scale, ext_factor, attn_factor, beta_fast,
                    beta_slow, score_vec2);
        } else {
            glm_attention_decode_weights_staged_kernel<float>
                    <<<weight_grid, 256, weight_shmem>>>(
                    scratch, softmax_denom, (const float *)q->ptr,
                    (const float *)qk_low->ptr,
                    (const float *)kv_lora_cache->ptr,
                    (const float *)k_rope_cache->ptr,
                    (const uint32_t *)selected->ptr,
                    n_selected, cache_cap, n_head, kv_lora_dim,
                    qk_nope, qk_rope, scale, n_ctx_orig, freq_base,
                    freq_scale, ext_factor, attn_factor, beta_fast,
                    beta_slow, score_vec2);
        }
        if (!cuda_ok(cudaGetLastError(),
                     "glm staged decode weights launch")) {
            return 0;
        }
        dim3 lora_grid((kv_lora_dim / 2u + 63u) / 64u,
                       n_head, token_count);
        if (cache_f16 && range_tok2) {
            glm_attention_decode_lora_staged_kernel<__half, true>
                    <<<lora_grid, 64>>>(
                    lora_sum, scratch, softmax_denom,
                    (const __half *)kv_lora_cache->ptr,
                    (const uint32_t *)selected->ptr,
                    n_selected, cache_cap, n_head, kv_lora_dim);
        } else if (cache_f16) {
            glm_attention_decode_lora_staged_kernel<__half>
                    <<<lora_grid, 64>>>(
                    lora_sum, scratch, softmax_denom,
                    (const __half *)kv_lora_cache->ptr,
                    (const uint32_t *)selected->ptr,
                    n_selected, cache_cap, n_head, kv_lora_dim);
        } else if (range_tok2) {
            glm_attention_decode_lora_staged_kernel<float, true>
                    <<<lora_grid, 64>>>(
                    lora_sum, scratch, softmax_denom,
                    (const float *)kv_lora_cache->ptr,
                    (const uint32_t *)selected->ptr,
                    n_selected, cache_cap, n_head, kv_lora_dim);
        } else {
            glm_attention_decode_lora_staged_kernel<float>
                    <<<lora_grid, 64>>>(
                    lora_sum, scratch, softmax_denom,
                    (const float *)kv_lora_cache->ptr,
                    (const uint32_t *)selected->ptr,
                    n_selected, cache_cap, n_head, kv_lora_dim);
        }
        if (!cuda_ok(cudaGetLastError(),
                     "glm staged decode lora launch")) {
            return 0;
        }
        dim3 value_grid((value_dim + 127u) / 128u,
                        n_head, token_count);
        if (range_tok2) {
            glm_attention_decode_value_staged_kernel<true>
                    <<<value_grid, 128>>>(
                    (float *)heads->ptr, lora_sum, vw,
                    n_head, kv_lora_dim, value_dim,
                    (uint32_t)value_row_bytes);
        } else {
            glm_attention_decode_value_staged_kernel<false>
                    <<<value_grid, 128>>>(
                    (float *)heads->ptr, lora_sum, vw,
                    n_head, kv_lora_dim, value_dim,
                    (uint32_t)value_row_bytes);
        }
        return cuda_ok(cudaGetLastError(),
                       "glm staged decode value launch");
    }
    const bool lora_vec2 = getenv("DS4_GLM_ATTN_NO_LORA_VEC2") == NULL;
    const uint32_t shmem =
        (256u + n_selected + kv_lora_dim) * (uint32_t)sizeof(float);
    if (cache_f16) {
        glm_attention_indexed_decode_kernel<__half><<<n_head, 256, shmem>>>(
                (float *)heads->ptr, (const float *)q->ptr,
                (const float *)qk_low->ptr,
                (const __half *)kv_lora_cache->ptr,
                (const __half *)k_rope_cache->ptr,
                vw, (const uint32_t *)selected->ptr,
                n_selected, cache_cap, n_head, kv_lora_dim,
                qk_nope, qk_rope, value_dim, (uint32_t)value_row_bytes,
                lora_vec2, score_vec2, scale, n_ctx_orig, freq_base, freq_scale,
                ext_factor, attn_factor, beta_fast, beta_slow);
    } else {
        glm_attention_indexed_decode_kernel<float><<<n_head, 256, shmem>>>(
                (float *)heads->ptr, (const float *)q->ptr,
                (const float *)qk_low->ptr,
                (const float *)kv_lora_cache->ptr,
                (const float *)k_rope_cache->ptr,
                vw, (const uint32_t *)selected->ptr,
                n_selected, cache_cap, n_head, kv_lora_dim,
                qk_nope, qk_rope, value_dim, (uint32_t)value_row_bytes,
                lora_vec2, score_vec2, scale, n_ctx_orig, freq_base, freq_scale,
                ext_factor, attn_factor, beta_fast, beta_slow);
    }
    return cuda_ok(cudaGetLastError(), "glm indexed decode attention");
}

__global__ static void glm53_indexer_pool_update_kernel(
        void *pool_cache,
        float *tail,
        const float *raw_k,
        const float *gate,
        const float *norm_weight,
        const float *norm_bias,
        const uint16_t *ape,
        uint32_t pos0,
        uint32_t n_tokens,
        uint32_t cache_cap,
        uint32_t head_dim,
        uint32_t pool_size,
        float eps,
        bool cache_f16) {
    const uint32_t tid = threadIdx.x;
    if (head_dim == 0u || pool_size == 0u || tid >= head_dim ||
        n_tokens == 0u) {
        return;
    }
    float *const tail_k = tail;
    float *const tail_gate = tail + (uint64_t)pool_size * head_dim;
    extern __shared__ float shared[];
    float *rows = shared;
    float *mean = rows + (uint64_t)pool_size * head_dim;
    float *inv = mean + pool_size;
    const uint32_t pool = pos0 / pool_size + blockIdx.x;
    const uint32_t pool_start = pool * pool_size;
    const uint32_t input_end = pos0 + n_tokens;
    if (pool_start >= input_end || pool_start + pool_size <= pos0) return;
    const bool complete = pool_start + pool_size <= input_end;

    for (uint32_t r = 0; r < pool_size; r++) {
        const uint32_t pos = pool_start + r;
        float k_value = 0.0f;
        float gate_value = 0.0f;
        if (pos >= pos0 && pos < input_end) {
            const uint32_t src_row = pos - pos0;
            k_value = raw_k[(uint64_t)src_row * head_dim + tid];
            gate_value = gate[(uint64_t)src_row * head_dim + tid];
            if (!complete) {
                tail_k[(uint64_t)r * head_dim + tid] = k_value;
                tail_gate[(uint64_t)r * head_dim + tid] = gate_value;
            }
        } else {
            k_value = tail_k[(uint64_t)r * head_dim + tid];
            gate_value = tail_gate[(uint64_t)r * head_dim + tid];
        }
        rows[(uint64_t)r * head_dim + tid] = k_value;
    }
    __syncthreads();
    if (!complete || pool >= (cache_cap + pool_size - 1u) / pool_size) {
        return;
    }

    if (tid < pool_size) {
        const uint32_t r = tid;
        float sum = 0.0f;
        for (uint32_t d = 0; d < head_dim; d++) {
            sum += rows[(uint64_t)r * head_dim + d];
        }
        const float m = sum / (float)head_dim;
        float ss = 0.0f;
        for (uint32_t d = 0; d < head_dim; d++) {
            const float delta = rows[(uint64_t)r * head_dim + d] - m;
            ss = fmaf(delta, delta, ss);
        }
        mean[r] = m;
        inv[r] = rsqrtf(ss / (float)head_dim + eps);
    }
    __syncthreads();

    float max_logit = -INFINITY;
    float logits[4];
    for (uint32_t r = 0; r < pool_size; r++) {
        const uint32_t pos = pool_start + r;
        const float gate_value = pos >= pos0
            ? gate[(uint64_t)(pos - pos0) * head_dim + tid]
            : tail_gate[(uint64_t)r * head_dim + tid];
        const float ape_value = __uint_as_float(
            (uint32_t)ape[(uint64_t)r * head_dim + tid] << 16);
        logits[r] = gate_value + ape_value;
        max_logit = fmaxf(max_logit, logits[r]);
    }
    float denom = 0.0f;
    for (uint32_t r = 0; r < pool_size; r++) {
        logits[r] = expf(logits[r] - max_logit);
        denom += logits[r];
    }
    float pooled = 0.0f;
    for (uint32_t r = 0; r < pool_size; r++) {
        const float normalized =
            (rows[(uint64_t)r * head_dim + tid] - mean[r]) * inv[r] *
            norm_weight[tid] + norm_bias[tid];
        pooled = fmaf(logits[r] / denom, normalized, pooled);
    }
    const uint64_t dst_index = (uint64_t)pool * head_dim + tid;
    if (cache_f16) {
        ((__half *)pool_cache)[dst_index] = __float2half(pooled);
    } else {
        ((float *)pool_cache)[dst_index] = pooled;
    }
}

extern "C" int ds4_gpu_glm53_indexer_pool_update_tensor(
        ds4_gpu_tensor       *pool_cache,
        ds4_gpu_tensor       *tail_k,
        ds4_gpu_tensor       *tail_gate,
        const ds4_gpu_tensor *raw_k,
        const ds4_gpu_tensor *gate,
        const void           *model_map,
        uint64_t              model_size,
        uint64_t              norm_weight_offset,
        uint64_t              norm_bias_offset,
        uint64_t              ape_offset,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              head_dim,
        uint32_t              pool_size,
        float                 eps,
        bool                  cache_f16) {
    if (!pool_cache || !tail_k || !tail_gate || !raw_k || !gate ||
        !model_map || n_tokens == 0u || cache_cap == 0u || head_dim == 0u ||
        head_dim > 1024u || pool_size != 4u || !isfinite(eps) || eps <= 0.0f ||
        pos0 > cache_cap || n_tokens > cache_cap - pos0) {
        return 0;
    }
    const uint64_t pool_cap =
        ((uint64_t)cache_cap + pool_size - 1u) / pool_size;
    const uint64_t cache_elem_size = cache_f16 ? sizeof(__half) : sizeof(float);
    if (!glm53_cuda_tensor_has(pool_cache, pool_cap * head_dim,
                               cache_elem_size) ||
        !glm53_cuda_tensor_has(tail_k, 2u * (uint64_t)pool_size * head_dim,
                               sizeof(float)) ||
        !glm53_cuda_tensor_has(tail_gate, (uint64_t)pool_size * head_dim,
                               sizeof(float)) ||
        (char *)tail_gate->ptr !=
            (char *)tail_k->ptr +
                (uint64_t)pool_size * head_dim * sizeof(float) ||
        !glm53_cuda_tensor_has(raw_k, (uint64_t)n_tokens * head_dim,
                               sizeof(float)) ||
        !glm53_cuda_tensor_has(gate, (uint64_t)n_tokens * head_dim,
                               sizeof(float))) {
        fprintf(stderr, "ds4: GLM-5.3 indexer pool received invalid buffers\n");
        return 0;
    }
    const int tier = ds4_tensor_device_idx(pool_cache);
    const float *norm_weight = glm53_cuda_weight_f32(
        model_map, model_size, norm_weight_offset, head_dim, tier,
        "indexer pool norm weight");
    const float *norm_bias = glm53_cuda_weight_f32(
        model_map, model_size, norm_bias_offset, head_dim, tier,
        "indexer pool norm bias");
    const uint64_t ape_bytes =
        (uint64_t)pool_size * head_dim * sizeof(uint16_t);
    if (ape_offset > model_size || ape_bytes > model_size - ape_offset) {
        fprintf(stderr, "ds4: GLM-5.3 indexer pool APE range is invalid\n");
        return 0;
    }
    const uint16_t *ape = (const uint16_t *)cuda_resolve_weight_ptr(
        model_map, ape_offset, ape_bytes, tier, "indexer pool APE");
    if (!norm_weight || !norm_bias || !ape) return 0;

    const uint64_t shared_bytes =
        ((uint64_t)pool_size * head_dim + 2u * pool_size) * sizeof(float);
    uint32_t done = 0u;
    const uint32_t leading = pos0 % pool_size;
    if (leading != 0u) {
        uint32_t chunk = pool_size - leading;
        if (chunk > n_tokens) chunk = n_tokens;
        glm53_indexer_pool_update_kernel<<<1u, head_dim, shared_bytes,
            cuda_decode_stream()>>>(
                pool_cache->ptr, (float *)tail_k->ptr,
                (const float *)raw_k->ptr,
                (const float *)gate->ptr, norm_weight, norm_bias, ape,
                pos0, chunk, cache_cap, head_dim, pool_size, eps, cache_f16);
        if (!cuda_ok(cudaGetLastError(),
                     "GLM-5.3 leading indexer pool update launch")) {
            return 0;
        }
        done = chunk;
    }
    const uint32_t remaining = n_tokens - done;
    const uint32_t full_tokens = remaining - remaining % pool_size;
    if (full_tokens != 0u) {
        const uint32_t groups = full_tokens / pool_size;
        glm53_indexer_pool_update_kernel<<<groups, head_dim, shared_bytes,
            cuda_decode_stream()>>>(
                pool_cache->ptr, (float *)tail_k->ptr,
                (const float *)raw_k->ptr + (uint64_t)done * head_dim,
                (const float *)gate->ptr + (uint64_t)done * head_dim,
                norm_weight, norm_bias, ape, pos0 + done, full_tokens, cache_cap,
                head_dim, pool_size, eps, cache_f16);
        if (!cuda_ok(cudaGetLastError(),
                     "GLM-5.3 full indexer pool update launch")) {
            return 0;
        }
        done += full_tokens;
    }
    if (done < n_tokens) {
        const uint32_t tail_tokens = n_tokens - done;
        glm53_indexer_pool_update_kernel<<<1u, head_dim, shared_bytes,
            cuda_decode_stream()>>>(
                pool_cache->ptr, (float *)tail_k->ptr,
                (const float *)raw_k->ptr + (uint64_t)done * head_dim,
                (const float *)gate->ptr + (uint64_t)done * head_dim,
                norm_weight, norm_bias, ape, pos0 + done, tail_tokens,
                cache_cap, head_dim, pool_size, eps, cache_f16);
        if (!cuda_ok(cudaGetLastError(),
                     "GLM-5.3 trailing indexer pool update launch")) {
            return 0;
        }
    }
    return 1;
}

__global__ static void glm53_expand_pool_selection_kernel(
        uint32_t *raw_selected,
        const uint32_t *pool_selected,
        uint32_t n_tokens,
        uint32_t pos0,
        uint32_t selected_pools,
        uint32_t index_topk,
        uint32_t pool_size,
        uint32_t output_width) {
    const uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    const uint64_t total = (uint64_t)n_tokens * output_width;
    if (gid >= total || output_width == 0u || pool_size == 0u) return;
    const uint32_t token = (uint32_t)(gid / output_width);
    const uint32_t slot = (uint32_t)(gid - (uint64_t)token * output_width);
    uint32_t value = UINT32_MAX;
    if (slot < index_topk) {
        const uint32_t pool_slot = slot / pool_size;
        if (pool_slot < selected_pools) {
            const uint32_t pool = pool_selected[
                (uint64_t)token * selected_pools + pool_slot];
            value = pool * pool_size + slot % pool_size;
        }
    } else {
        const uint32_t tail_slot = slot - index_topk;
        const uint32_t visible = pos0 + token + 1u;
        const uint32_t tail_count = visible % pool_size;
        if (tail_slot < tail_count) {
            value = visible - tail_count + tail_slot;
        }
    }
    raw_selected[gid] = value;
}

extern "C" int ds4_gpu_glm53_expand_pool_selection_tensor(
        ds4_gpu_tensor       *raw_selected,
        const ds4_gpu_tensor *pool_selected,
        uint32_t              n_tokens,
        uint32_t              pos0,
        uint32_t              selected_pools,
        uint32_t              index_topk,
        uint32_t              pool_size,
        uint32_t              output_width) {
    if (!raw_selected || !pool_selected || n_tokens == 0u ||
        selected_pools == 0u || index_topk == 0u || pool_size == 0u ||
        selected_pools > index_topk / pool_size ||
        output_width < index_topk + pool_size - 1u ||
        !glm53_cuda_tensor_has(raw_selected,
            (uint64_t)n_tokens * output_width, sizeof(uint32_t)) ||
        !glm53_cuda_tensor_has(pool_selected,
            (uint64_t)n_tokens * selected_pools, sizeof(uint32_t))) {
        return 0;
    }
    const uint64_t total = (uint64_t)n_tokens * output_width;
    glm53_expand_pool_selection_kernel<<<
        (unsigned)((total + 255u) / 256u), 256u, 0,
        cuda_decode_stream()>>>(
            (uint32_t *)raw_selected->ptr,
            (const uint32_t *)pool_selected->ptr, n_tokens, pos0,
            selected_pools, index_topk, pool_size, output_width);
    return cuda_ok(cudaGetLastError(),
                   "GLM-5.3 pool selection expansion launch");
}

template <typename CT>
__device__ __forceinline__ static CT glm_cache_cast(float value) {
    return (CT)value;
}

template <>
__device__ __forceinline__ __half glm_cache_cast<__half>(float value) {
    return __float2half(value);
}

template <typename CT>
__global__ static void glm_build_kv_cache_kernel(
        CT *key_cache,
        CT *value_cache,
        const float *kv_raw,
        const float *k_nope,
        const float *value,
        uint32_t pos0,
        uint32_t n_tokens,
        uint32_t n_head,
        uint32_t kv_raw_dim,
        uint32_t kv_lora_dim,
        uint32_t qk_nope,
        uint32_t qk_rope,
        uint32_t value_dim,
        uint32_t n_ctx_orig,
        float freq_base,
        float freq_scale,
        float ext_factor,
        float attn_factor,
        float beta_fast,
        float beta_slow) {
    const uint32_t token = blockIdx.x;
    const uint32_t head = blockIdx.y;
    const uint32_t tid = threadIdx.x;
    if (token >= n_tokens || head >= n_head) return;
    const uint32_t qk_dim = qk_nope + qk_rope;
    const uint32_t pos = pos0 + token;
    const float *raw = kv_raw + (uint64_t)token * kv_raw_dim;
    const float *kn = k_nope +
        ((uint64_t)token * n_head + head) * qk_nope;
    const float *val = value +
        ((uint64_t)token * n_head + head) * value_dim;
    const uint64_t kbase = ((uint64_t)pos * n_head + head) * qk_dim;
    const uint64_t vbase = ((uint64_t)pos * n_head + head) * value_dim;

    for (uint32_t i = tid; i < qk_nope; i += blockDim.x) {
        key_cache[kbase + i] = glm_cache_cast<CT>(kn[i]);
    }
    float corr_dims[2] = {0.0f, 0.0f};
    if (qk_rope != 0u && ext_factor != 0.0f) {
        corr_dims[0] = fmaxf(0.0f,
            floorf(glm_rope_yarn_corr_factor_dev(
                (int)qk_rope, (int)n_ctx_orig, beta_fast, freq_base)));
        corr_dims[1] = fminf((float)qk_rope - 1.0f,
            ceilf(glm_rope_yarn_corr_factor_dev(
                (int)qk_rope, (int)n_ctx_orig, beta_slow, freq_base)));
    }
    const float inv_dims = qk_rope != 0u ? -1.0f / (float)qk_rope : 0.0f;
    for (uint32_t r = tid * 2u; r < qk_rope; r += blockDim.x * 2u) {
        const float theta = (float)pos *
            powf(freq_base, inv_dims * (float)r);
        float cos_theta = 0.0f;
        float sin_theta = 0.0f;
        glm_rope_yarn_dev(theta, freq_scale, corr_dims, (int)r,
                          ext_factor, attn_factor,
                          &cos_theta, &sin_theta);
        const float x0 = raw[kv_lora_dim + r];
        const float x1 = raw[kv_lora_dim + r + 1u];
        key_cache[kbase + qk_nope + r] = glm_cache_cast<CT>(
            x0 * cos_theta - x1 * sin_theta);
        key_cache[kbase + qk_nope + r + 1u] = glm_cache_cast<CT>(
            x0 * sin_theta + x1 * cos_theta);
    }
    for (uint32_t i = tid; i < value_dim; i += blockDim.x) {
        value_cache[vbase + i] = glm_cache_cast<CT>(val[i]);
    }
}

static int glm_build_kv_cache_launch(
        ds4_gpu_tensor       *key_cache,
        ds4_gpu_tensor       *value_cache,
        const ds4_gpu_tensor *kv_raw,
        const ds4_gpu_tensor *k_nope,
        const ds4_gpu_tensor *value,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              kv_raw_dim,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_rope,
        uint32_t              value_dim,
        uint32_t              n_ctx_orig,
        float                 freq_base,
        float                 freq_scale,
        float                 ext_factor,
        float                 attn_factor,
        float                 beta_fast,
        float                 beta_slow,
        bool                  cache_f16) {
    const uint32_t qk_dim = qk_nope + qk_rope;
    const uint64_t cache_elem = cache_f16 ? sizeof(__half) : sizeof(float);
    if (!key_cache || !value_cache || !kv_raw || !k_nope || !value ||
        n_tokens == 0u || cache_cap == 0u || n_head == 0u ||
        kv_raw_dim == 0u || kv_lora_dim == 0u || qk_nope == 0u ||
        value_dim == 0u || kv_lora_dim > kv_raw_dim ||
        qk_rope > kv_raw_dim - kv_lora_dim || qk_dim < qk_nope ||
        (qk_rope & 1u) != 0u || pos0 > cache_cap ||
        n_tokens > cache_cap - pos0 ||
        (qk_rope != 0u && (!isfinite(freq_base) || freq_base <= 0.0f)) ||
        (qk_rope != 0u && (!isfinite(freq_scale) || freq_scale <= 0.0f)) ||
        !isfinite(ext_factor) || !isfinite(attn_factor) ||
        !isfinite(beta_fast) || !isfinite(beta_slow) ||
        key_cache->bytes <
            (uint64_t)cache_cap * n_head * qk_dim * cache_elem ||
        value_cache->bytes <
            (uint64_t)cache_cap * n_head * value_dim * cache_elem ||
        kv_raw->bytes <
            (uint64_t)n_tokens * kv_raw_dim * sizeof(float) ||
        k_nope->bytes <
            (uint64_t)n_tokens * n_head * qk_nope * sizeof(float) ||
        value->bytes <
            (uint64_t)n_tokens * n_head * value_dim * sizeof(float)) {
        return 0;
    }
    const dim3 grid(n_tokens, n_head, 1u);
    if (cache_f16) {
        glm_build_kv_cache_kernel<__half><<<grid, 256u, 0,
            cuda_decode_stream()>>>(
                (__half *)key_cache->ptr, (__half *)value_cache->ptr,
                (const float *)kv_raw->ptr, (const float *)k_nope->ptr,
                (const float *)value->ptr, pos0, n_tokens, n_head,
                kv_raw_dim, kv_lora_dim, qk_nope, qk_rope, value_dim,
                n_ctx_orig, freq_base, freq_scale, ext_factor, attn_factor,
                beta_fast, beta_slow);
    } else {
        glm_build_kv_cache_kernel<float><<<grid, 256u, 0,
            cuda_decode_stream()>>>(
                (float *)key_cache->ptr, (float *)value_cache->ptr,
                (const float *)kv_raw->ptr, (const float *)k_nope->ptr,
                (const float *)value->ptr, pos0, n_tokens, n_head,
                kv_raw_dim, kv_lora_dim, qk_nope, qk_rope, value_dim,
                n_ctx_orig, freq_base, freq_scale, ext_factor, attn_factor,
                beta_fast, beta_slow);
    }
    return cuda_ok(cudaGetLastError(), "GLM KV cache build launch");
}

extern "C" int ds4_gpu_glm_build_kv_cache_flash_tensor(
        ds4_gpu_tensor       *key_cache,
        ds4_gpu_tensor       *value_cache,
        const ds4_gpu_tensor *kv_raw,
        const ds4_gpu_tensor *k_nope,
        const ds4_gpu_tensor *value,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              kv_raw_dim,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_rope,
        uint32_t              value_dim,
        uint32_t              n_ctx_orig,
        float                 freq_base,
        float                 freq_scale,
        float                 ext_factor,
        float                 attn_factor,
        float                 beta_fast,
        float                 beta_slow,
        bool                  cache_f16) {
    if (pos0 != 0u) return 0;
    return glm_build_kv_cache_launch(
        key_cache, value_cache, kv_raw, k_nope, value, pos0, n_tokens,
        cache_cap, n_head, kv_raw_dim, kv_lora_dim, qk_nope, qk_rope,
        value_dim, n_ctx_orig, freq_base, freq_scale, ext_factor,
        attn_factor, beta_fast, beta_slow, cache_f16);
}

extern "C" int ds4_gpu_glm_build_kv_cache_tensor(
        ds4_gpu_tensor       *key_cache,
        ds4_gpu_tensor       *value_cache,
        const ds4_gpu_tensor *kv_raw,
        const ds4_gpu_tensor *k_nope,
        const ds4_gpu_tensor *value,
        uint32_t              pos0,
        uint32_t              n_tokens,
        uint32_t              cache_cap,
        uint32_t              n_head,
        uint32_t              kv_raw_dim,
        uint32_t              kv_lora_dim,
        uint32_t              qk_nope,
        uint32_t              qk_rope,
        uint32_t              value_dim,
        uint32_t              n_ctx_orig,
        float                 freq_base,
        float                 freq_scale,
        float                 ext_factor,
        float                 attn_factor,
        float                 beta_fast,
        float                 beta_slow,
        bool                  cache_f16) {
    return glm_build_kv_cache_launch(
        key_cache, value_cache, kv_raw, k_nope, value, pos0, n_tokens,
        cache_cap, n_head, kv_raw_dim, kv_lora_dim, qk_nope, qk_rope,
        value_dim, n_ctx_orig, freq_base, freq_scale, ext_factor,
        attn_factor, beta_fast, beta_slow, cache_f16);
}

__global__ static void glm_fill_selected_range_batch_kernel(
        uint32_t *selected,
        uint32_t n_tokens,
        uint32_t pos0,
        uint32_t n_selected,
        uint32_t pad_row) {
    uint32_t gid = blockIdx.x * blockDim.x + threadIdx.x;
    const uint32_t total = n_tokens * n_selected;
    if (gid >= total || n_selected == 0u) return;
    const uint32_t token = gid / n_selected;
    const uint32_t slot = gid - token * n_selected;
    const uint32_t visible = pos0 + token + 1u;
    selected[gid] = slot < visible ? slot : pad_row;
}

extern "C" int ds4_gpu_glm_fill_selected_range_batch_tensor(
        ds4_gpu_tensor *selected,
        uint32_t        n_tokens,
        uint32_t        pos0,
        uint32_t        n_selected,
        uint32_t        pad_row) {
    if (!selected || n_tokens == 0 || n_selected == 0 ||
        selected->bytes < (uint64_t)n_tokens * n_selected * sizeof(uint32_t)) {
        return 0;
    }
    const uint64_t total = (uint64_t)n_tokens * n_selected;
    glm_fill_selected_range_batch_kernel<<<(unsigned)((total + 255) / 256), 256>>>(
            (uint32_t *)selected->ptr, n_tokens, pos0, n_selected, pad_row);
    return cuda_ok(cudaGetLastError(), "glm fill selected batch launch");
}

__global__ static void glm_fill_selected_range_kernel(
        uint32_t *selected, uint32_t n_selected) {
    uint32_t gid = blockIdx.x * blockDim.x + threadIdx.x;
    if (gid < n_selected) selected[gid] = gid;
}

extern "C" int ds4_gpu_glm_fill_selected_range_tensor(
        ds4_gpu_tensor *selected,
        uint32_t        n_selected) {
    if (!selected || n_selected == 0 ||
        selected->bytes < (uint64_t)n_selected * sizeof(uint32_t)) {
        return 0;
    }
    glm_fill_selected_range_kernel<<<(n_selected + 255) / 256, 256>>>(
            (uint32_t *)selected->ptr, n_selected);
    return cuda_ok(cudaGetLastError(), "glm fill selected launch");
}

